(function(){var m=window.SITE_DATA_BY_DOMAIN=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]=m["coding"]||{};d["theory"]=[{"id":"th-roofline-code-decode","title":"代码推理的 Roofline 界","direction":"dir-repo-context-kv","prereq":[],"plain":"解码阶段每生成一个 token 只做一次权重读取和一次 KV 读取，算术强度极低，性能被 HBM 带宽而非 Tensor Core 算力钉死；预填阶段则相反，长上下文下算术强度随序列长度线性上升，最终撞上算力屋顶。","definition":"解码阶段每生成一个 token 只做一次权重读取和一次 KV 读取，算术强度极低，性能被 HBM 带宽而非 Tensor Core 算力钉死；预填阶段则相反，长上下文下算术强度随序列长度线性上升，最终撞上算力屋顶。","formula":"$$\\text{Attainable}=\\min\\left(\\pi_{\\text{peak}},\\;\\frac{\\beta_{\\text{HBM}}}{I}\\right),\\quad I_{\\text{decode}}\\approx\\frac{2N_{\\text{active}}}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}},\\quad I_{\\text{prefill}}\\approx\\frac{2N_{\\text{active}}S}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,S}$$","variables":[{"sym":"\\pi_{\\text{peak}}","meaning":"GPU 峰值算力（如 B200 FP8 稠密约 4.5 PFLOPS，SM100 双 die 合计）"},{"sym":"\\beta_{\\text{HBM}}","meaning":"HBM3e 有效带宽（B200 约 8 TB/s，GB200 NVL72 单 GPU 同量级）"},{"sym":"I","meaning":"算术强度，单位 FLOP/Byte"},{"sym":"N_{\\text{active}}","meaning":"每 token 参与计算的激活参数量"},{"sym":"L","meaning":"Transformer 层数"},{"sym":"d_{\\text{kv}}","meaning":"每层 KV 头维度（head_dim × kv_heads）"},{"sym":"n_{\\text{kv}}","meaning":"KV 头数（GQA/MQA 下远小于 Q 头数）"},{"sym":"S","meaning":"预填序列长度（仓库级上下文可达 10^5 token 量级）"}],"derivation":"解码算术强度 $$I_{\\text{decode}}\\approx\\frac{2N_{\\text{active}}}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}}$$ 的分子是每 token 的权重乘加 FLOP，分母是权重字节加 KV 字节；$N_{\\text{active}}$ 为每 token 激活参数量，$L$ 为层数，$d_{\\text{kv}}$ 为每层 KV 头维度，$n_{\\text{kv}}$ 为 KV 头数（GQA/MQA 下远小于 Q 头数）。","example":"推导的关键一步是把每 token 的 FLOP 与字节数分别写出再相除：解码时权重字节固定而 KV 字节随批与序列增长，预填时 attention 的 FLOP 随 $S$ 平方增长而 KV 字节随 $S$ 线性增长，因此两条曲线的斜率不同，决定了何时从带宽受限切换到算力受限。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设权重与 KV 均从 HBM 读取且无片上复用；若采用权重量化（FP8/INT4）或 KV 分块驻留 SMEM，则 I 与 β 的有效值需重算，公式给出的是上界而非实测值","仅适用于稠密 Transformer 单卡/单 rank 视角；MoE 的激活参数 N_active 随 token 路由变化，专家并行引入跨卡 all-to-all 后带宽项需替换为互联带宽","未刻画 kernel launch 与调度开销，当 batch=1 且序列极短（代码补全单行场景）时，实际时延由固定开销主导，roofline 预测偏乐观"],"system_note":"适用边界是稠密 Transformer 单卡/单 rank 视角且权重与 KV 均从 HBM 读取、无片上复用；失效条件包括权重量化（FP8/INT4）或 KV 分块驻留 SMEM 时 $I$ 与 $\\beta$ 的有效值需重算，公式只给上界；MoE 的 $N_{\\text{active}}$ 随 token 路由变化，专家并行引入跨卡 all-to-all 后带宽项需替换为互联带宽；batch=1 且序列极短（代码补全单行场景）时实际时延由 kernel launch 与调度固定开销主导，roofline 预测偏乐观。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["解码阶段每生成一个 token，只做一次权重读取和一次 KV 读取，算术强度极低，性能被 HBM 带宽而非 Tensor Core 算力钉死；预填阶段则相反，长上下文下算术强度随序列长度线性上升，最终撞上算力屋顶。","公式 $$\\text{Attainable}=\\min\\left(\\pi_{\\text{peak}},\\;\\frac{\\beta_{\\text{HBM}}}{I}\\right)$$ 中，$\\pi_{\\text{peak}}$ 是 GPU 峰值算力（B200 FP8 稠密约 4.5 PFLOPS，SM100 双 die 合计），$\\beta_{\\text{HBM}}$ 是 HBM3e 有效带宽（B200 约 8 TB/s），$I$ 是算术强度（FLOP/Byte），取两者较小值即为可达性能上界。","解码算术强度 $$I_{\\text{decode}}\\approx\\frac{2N_{\\text{active}}}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}}$$ 的分子是每 token 的权重乘加 FLOP，分母是权重字节加 KV 字节；$N_{\\text{active}}$ 为每 token 激活参数量，$L$ 为层数，$d_{\\text{kv}}$ 为每层 KV 头维度，$n_{\\text{kv}}$ 为 KV 头数（GQA/MQA 下远小于 Q 头数）。","预填算术强度 $$I_{\\text{prefill}}\\approx\\frac{2N_{\\text{active}}S}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,S}$$ 中 $S$ 为预填序列长度，仓库级上下文可达 $10^5$ token 量级；分母的 KV 项随 $S$ 线性增长，分子随 $S$ 线性增长，故 $I$ 随 $S$ 上升并最终撞上算力屋顶。","推导的关键一步是把每 token 的 FLOP 与字节数分别写出再相除：解码时权重字节固定而 KV 字节随批与序列增长，预填时 attention 的 FLOP 随 $S$ 平方增长而 KV 字节随 $S$ 线性增长，因此两条曲线的斜率不同，决定了何时从带宽受限切换到算力受限。","适用边界是稠密 Transformer 单卡/单 rank 视角且权重与 KV 均从 HBM 读取、无片上复用；失效条件包括权重量化（FP8/INT4）或 KV 分块驻留 SMEM 时 $I$ 与 $\\beta$ 的有效值需重算，公式只给上界；MoE 的 $N_{\\text{active}}$ 随 token 路由变化，专家并行引入跨卡 all-to-all 后带宽项需替换为互联带宽；batch=1 且序列极短（代码补全单行场景）时实际时延由 kernel launch 与调度固定开销主导，roofline 预测偏乐观。","在推理性能或容量决策中，该界用于判断某工作负载处于带宽受限还是算力受限区间：代码补全的低延迟场景落在解码带宽受限区，应优先做权重量化与 KV 压缩；仓库级长上下文预填落在算力受限区，应优先做 chunked prefill 与并行切分，而非继续压带宽。","常见误用是把公式给出的上界当作实测吞吐，忽略 kernel launch、调度与框架开销；另一误用是在 MoE 或专家并行部署中仍用单卡 HBM 带宽代入，导致对 all-to-all 互联瓶颈的低估；还有误用是未按量化后的有效字节重算 $I$，把 FP8 权重的收益误判为线性提升。"],"anchors":["4.5 PFLOPS","8 TB/s","192 GB","10^5"],"pitfalls":["把 roofline 上界当实测吞吐：batch=1 单行补全时固定开销主导，预测偏乐观导致 SLO 承诺无法兑现。","在 MoE 专家并行部署中沿用单卡 HBM 带宽项，忽略跨卡 all-to-all 互联带宽，容量规划严重高估。","权重量化后未重算算术强度与有效带宽，把 FP8/INT4 的收益误判为等比例吞吐提升。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-1\">一 · 一句话直觉与它背后的物理</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-2\">二 · 严格定义：两个强度、一个 min</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-3\">三 · 为什么需要这个界：它决定优化投向</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-4\">四 · 常见误解之一：把上界当实测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-5\">五 · 常见误解之二：量化收益线性、MoE 沿用单卡带宽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-6\">六 · 定义落地：把界写成可执行的判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-7\">七 · 上界不是承诺：Roofline 在代码推理里的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-8\">八 · 逐项拆解：分子分母各是什么字节</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-9\">九 · 推导关键步：先写 FLOP 再写字节，最后相除</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-10\">十 · 离散化与近似落在哪三处</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-11\">十一 · 量化后必须重算，不能线性外推</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-12\">十二 · 失效条件的工程含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-13\">十三 · 边界在哪里：从&quot;上界&quot;到&quot;实测&quot;的三处断点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-14\">十四 · 公式成立的前提，以及它在哪里先崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-15\">十五 · 上界不是实测：固定开销吃掉的那一段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-16\">十六 · 量化改变的是 I 和 β 的有效值，不是线性收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-17\">十七 · 稠密单卡假设在 MoE 与专家并行下失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-18\">十八 · 预填的 S 平方项与 chunked prefill 的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-19\">十九 · 规模上限：公式在什么尺度上停止有效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-20\">二十 · 当公式开始说谎：Roofline 界的假设、失效与规模天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-21\">二十一 · 当 roofline 让位于固定开销与互联瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-22\">二十二 · 从界到决策变量：把 roofline 反解成配置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-23\">二十三 · 定并行度：切分改变的是哪一项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-24\">二十四 · 定 KV 预算：精度与分块如何改写分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-25\">二十五 · 定 SLO：把界翻译成可承诺的数字</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-26\">二十六 · 算例：一次完整的反解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-27\">二十七 · 把上界换算成配置：批大小、并行度、KV 预算与 SLO 的反解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-28\">二十八 · 把上界换算成容量：批大小、并行度与 KV 预算的取整规则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-29\">二十九 · 把上界当实测：batch=1 单行补全的固定开销陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-30\">三十 · MoE 与专家并行：沿用单卡 HBM 带宽项的容量高估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-31\">三十一 · 量化后不重算：把 FP8/INT4 收益误判为等比例提升</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-32\">三十二 · 反例：仓库级预填误按解码带宽受限规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-33\">三十三 · 识别清单：三个判据与一条纪律</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-34\">三十四 · 误用解剖：把上界当承诺、把单卡带宽当互联带宽、把量化当线性加速</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-roofline-code-decode-sec-35\">三十五 · 误用三连：上界当实测、单卡带宽套 MoE、量化后不重算 I</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:544px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 544.5 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"462.5\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"462.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：解码阶段每生成一个 token 只做一次权重读取和一次 KV 读取…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"462.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\text{Attainable}=\\min\\left(\\pi…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"462.5\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设权重与 KV 均从 HBM 读取且无片上复用；若采用权重量化（…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-roofline-code-decode-sec-1\">一 · 一句话直觉与它背后的物理</h3>\n<p>把解码器的一次前向拆到最粗的粒度：生成一个 token，要把全部激活权重从 HBM 搬进 SM 一遍，再把该 token 需要的历史 KV 搬一遍，然后做一次乘加。搬运的字节数以 GB 计，而算术只有每权重两个 FLOP。Tensor Core 在等数据，HBM 在供数据，前者空转，后者满载。这就是“解码被带宽钉死”的全部直觉：不是算不动，是喂不饱。B200 的 FP8 稠密算力约 4.5 PFLOPS（SM100 双 die 合计），HBM3e 有效带宽约 8 TB/s，两者相除得到该机器的“脊点”算术强度——只有当工作负载的 FLOP/Byte 超过这个比值，算力才成为约束；解码的实测强度远在其下，于是可达性能退化为 β_HBM/I。</p>\n<p>这条直觉必须被写成可计算的量，否则它只是口号。Roofline 界的作用是把“喂不饱”翻译成一个可代入参数的上界，让工程判断从“感觉带宽不够”变成“给定 N_active、L、d_kv、n_kv，我的天花板在哪，离它多远”。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-2\">二 · 严格定义：两个强度、一个 min</h3>\n<p>定义算术强度 I 为每字节 HBM 流量所对应的浮点运算数，单位 FLOP/Byte。可达性能上界取算力屋顶与带宽屋顶的较小者：</p>\n<div class=\"formula\">$$\\text{Attainable}=\\min\\left(\\pi_{\\text{peak}},\\;\\frac{\\beta_{\\text{HBM}}}{I}\\right)$$</div>\n<p>解码与预填的 I 表达式不同，因为分子分母随规模变化的斜率不同：</p>\n<div class=\"formula\">$$I_{\\text{decode}}\\approx\\frac{2N_{\\text{active}}}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}},\\quad I_{\\text{prefill}}\\approx\\frac{2N_{\\text{active}}S}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,S}$$</div>\n<p>解码式的分子是每 token 的权重乘加 FLOP，分母是权重字节加该 token 的 KV 字节；两者都与 batch 无关地写成了“每 token”口径，因此 batch 增大时 KV 项按 batch 摊薄、权重项不变，I 缓慢上升但仍远低于脊点。预填式的分子随 S 线性增长，分母中权重项固定、KV 项随 S 线性增长，因此 I 随 S 单调上升并趋于饱和值 2N_active/(2L d_kv n_kv) 量级之外的算力屋顶——这正是“长上下文预填撞上算力屋顶”的解析来源。注意预填中 attention 的 FLOP 实际随 S 平方增长，而 KV 字节随 S 线性增长，两条曲线斜率不同，这是从带宽受限切换到算力受限的判据所在；上式是每 token 摊薄后的写法，用于快速估算而非精确刻画平方项。</p>\n<p>变量口径必须钉死：N_active 是每 token 参与计算的激活参数量；L 是层数；d_kv 是每层 KV 头维度（head_dim × kv_heads）；n_kv 是 KV 头数，GQA/MQA 下远小于 Q 头数；S 是预填序列长度，仓库级上下文可达 10^5 token 量级。π_peak 与 β_HBM 取目标机器的实测有效值，而非 datasheet 峰值。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-3\">三 · 为什么需要这个界：它决定优化投向</h3>\n<p>没有这个界，工程团队会在错误的维度上投入。代码补全的低延迟场景落在解码带宽受限区：batch 小、序列短，I 极低，可达性能由 β_HBM/I 给出，此时提升算力利用率毫无意义，正确动作是压缩每 token 必须搬运的字节——权重量化到 FP8/INT4、KV 压缩、GQA 已经是既成事实的架构选择。反过来，仓库级长上下文预填落在算力受限区：S 达到 10^5 量级时 I 已越过脊点，可达性能被 π_peak 截断，此时继续压带宽收益递减，正确动作是 chunked prefill 切分、并行切分与算子融合，把 Tensor Core 喂满。</p>\n<p>这个界还是容量规划的第一道筛子。给定 SLO 的 token/s 目标，先用 roofline 算出该工作负载的理论天花板，再乘以一个由 kernel 效率与调度开销决定的经验折扣，得到可承诺的容量。若天花板本身就低于 SLO，问题不在调优而在选型或重构（更小的 N_active、更强的量化、分离式部署）。它把“能不能做到”与“怎么做到”分成两个阶段，避免在物理上不可能的目标上烧工程时间。</p>\n<p>第三个用途是归因。实测吞吐与 roofline 上界的比值就是“效率缺口”，缺口大意味着实现层面有浪费（kernel launch、无效搬运、片上复用不足），缺口小意味着已接近物理极限、应转向算法层（更激进的量化、更小的激活参数、MoE 路由）。这把性能分析从“猜”变成“算”。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-4\">四 · 常见误解之一：把上界当实测</h3>\n<p>公式给的是上界，不是吞吐。它假设权重与 KV 全部从 HBM 读取且无片上复用，未刻画 kernel launch 与调度开销。当 batch=1 且序列极短——代码补全单行场景——实际时延由固定开销主导，roofline 预测偏乐观。工程后果很具体：按上界做 SLO 承诺，上线后发现单行补全的 P99 被 launch 开销吃掉，承诺无法兑现。正确做法是把上界乘以一个随 batch 与序列长度变化的效率因子，短序列区间该因子显著小于 1，长序列、大 batch 区间才趋近 1。判断某个部署是否已进入“roofline 可信区”，看两个信号：batch 是否足够大以摊薄固定开销，序列是否足够长以使搬运量远超 launch 成本。</p>\n<p>另一个同源误解是把 min 里的两项当成可加。它们是取小，不是相加；带宽屋顶与算力屋顶不会叠加成更高性能。当 I 恰好落在脊点附近时，两项接近相等，此时任何一端的抖动（HBM 频率、SM 占用率）都会让实际性能在两侧摆动，容量规划应留出余量而非贴着脊点设计。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-5\">五 · 常见误解之二：量化收益线性、MoE 沿用单卡带宽</h3>\n<p>权重量化后必须重算 I 与 β 的有效值。FP8 把权重字节减半，分母变小、I 变大，带宽屋顶 β/I 上升，但上升不是等比例的：KV 字节未变，分母中固定项与 KV 项的比例改变，且量化后的有效带宽 β 本身受反量化开销与访问模式影响。把 FP8 的收益误判为“吞吐翻倍”是典型错误；正确动作是代入量化后的字节数重算 I，再取 min，看新的瓶颈落在哪一侧。若量化后 I 越过脊点，收益就从带宽侧转移到算力侧，此时继续量化权重不再提升吞吐，反而可能因反量化指令占用 SM 而降低有效算力。</p>\n<p>MoE 与专家并行部署中沿用单卡 HBM 带宽项是更危险的误用。MoE 的 N_active 随 token 路由变化，每 token 激活的专家集合不同，激活参数量是随机变量而非常数；专家并行引入跨卡 all-to-all 后，带宽项必须替换为互联带宽（NVLink 5 与 NCCL 集合通信的有效带宽），而非单卡 HBM 带宽。容量规划若仍用 8 TB/s 代入，会系统性低估 all-to-all 瓶颈，高估可支撑的并发与吞吐。判断是否落入此陷阱的信号：部署拓扑跨节点、路由分布偏斜、all-to-all 时间占比在 profile 中不可忽略。此时 roofline 的带宽项应写成互联带宽与 HBM 带宽的加权组合，权重由路由的跨卡比例决定。</p>\n<p>还有一个边界条件常被忽略：公式仅适用于稠密 Transformer 单卡/单 rank 视角。KV 分块驻留 SMEM 时，KV 字节不再全部走 HBM，分母的有效值需重算，公式退化为上界；此时真实性能可能超过朴素 roofline 预测，因为片上复用改变了 I 的定义域。工程上应把“是否启用 SMEM 驻留 KV”作为是否信任该界的前置判断。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-6\">六 · 定义落地：把界写成可执行的判据</h3>\n<p>把上面的定义落成三步判据，用于每次容量评审。第一步，按目标机器的 π_peak 与 β_HBM 算出脊点强度 I_ridge = π_peak/β_HBM；B200 上该比值由 4.5 PFLOPS 与 8 TB/s 给出，量级在数百 FLOP/Byte。第二步，按工作负载的 N_active、L、d_kv、n_kv、S 与 batch 代入两个 I 表达式，与 I_ridge 比较：低于脊点判为带宽受限，高于脊点判为算力受限。第三步，在判定的受限侧选优化动作，并用“实测吞吐 / min 上界”作为效率缺口持续跟踪，缺口收敛即停止调优、转向算法层。</p>\n<p>这套判据的价值在于它把“快不快”变成“在哪一侧、离顶多远、缺口多大”三个可回答的问题。代码补全的单行场景会被第一步判为带宽受限、第二步判为固定开销主导区，于是优化动作锁定在权重量化与 KV 压缩，且明确知道上界偏乐观、SLO 需留余量；仓库级 10^5 token 预填会被判为算力受限，优化动作锁定在 chunked prefill 与并行切分。判据本身不产生性能，但它阻止把工程预算投到物理上不产生收益的一侧——这是 roofline 界在推理系统里最硬的用处。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-7\">七 · 上界不是承诺：Roofline 在代码推理里的失效边界</h3>\n<p>把 roofline 用在代码推理上，第一件要纠正的事是它的身份：$\\text{Attainable}=\\min(\\pi_{\\text{peak}},\\beta_{\\text{HBM}}/I)$ 给出的是<b>可达性能的上界</b>，不是吞吐预测值。这个上界成立的前提相当窄——权重与 KV 全部从 HBM 读取、无片上复用、稠密 Transformer、单卡或单 rank 视角。一旦权重量化到 FP8/INT4，或把 KV 分块驻留 SMEM，分母里的字节数就变了，$I$ 与 $\\beta$ 的有效值必须重算，原公式只剩“上界”这一层意义。工程上更危险的是把上界当承诺：代码补全的典型负载是 batch=1、序列极短（单行或函数体级别），此时每 token 的权重读取量虽大，但 kernel launch、调度与框架开销占据时延的主要份额，roofline 预测系统性偏乐观，按它去签 SLO 会直接违约。判断标准很简单：当固定开销与理论传输时间同量级时，roofline 已退出适用区，应改用实测的端到端时延模型。</p>\n<p>第二个失效点是带宽项的替换。公式默认 $\\beta_{\\text{HBM}}$ 为单卡 HBM3e 有效带宽（B200 约 8 TB/s，GB200 NVL72 单 GPU 同量级），这在稠密模型单 rank 部署下成立。但 MoE 的 $N_{\\text{active}}$ 随 token 路由逐 token 变化，算术强度不再是常数而是一个分布；专家并行把权重读取拆到多卡后，瓶颈从 HBM 转移到跨卡 all-to-all，带宽项必须换成互联带宽（NVLink 5 域内与跨域 InfiniBand 是两套数量级），否则容量规划会把互联瓶颈整体低估。同理，权重量化后若不按有效字节重算 $I$，会把 FP8 的收益误判为等比例吞吐提升——实际上解码仍受 KV 字节与固定开销牵制，收益远非线性。</p>\n<p>第三个边界来自预填与解码的斜率差异。预填时分子随 $S$ 线性增长、分母的 KV 项也随 $S$ 线性增长，但 attention 的 FLOP 随 $S$ 平方增长，两条曲线斜率不同，决定了从带宽受限切换到算力受限的拐点；仓库级上下文 $S$ 可达 $10^5$ 量级，此时已深入算力受限区。反过来，解码侧 $I_{\\text{decode}}\\approx 2N_{\\text{active}}/(2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}})$ 在 GQA/MQA 下 $n_{\\text{kv}}$ 远小于 Q 头数，KV 项被压小，$I$ 停留在低位，性能被带宽钉死。这意味着同一套 roofline 不能同时服务两类负载的决策：补全场景应优先权重量化与 KV 压缩，长上下文预填应优先 chunked prefill 与并行切分，继续压带宽对后者几乎无效。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>受限侧</th><th>roofline 可信度</th><th>首要优化</th></tr></thead><tbody><tr><td>单行补全 batch=1</td><td>固定开销主导</td><td>偏乐观，不宜作 SLO 依据</td><td>降低 launch 与调度开销</td></tr><tr><td>解码（GQA，中等 batch）</td><td>HBM 带宽</td><td>较高，需按量化后字节重算</td><td>权重量化、KV 压缩</td></tr><tr><td>仓库级预填 $S\\sim10^5$</td><td>算力</td><td>较高，撞 $\\pi_{\\text{peak}}$ 屋顶</td><td>chunked prefill、并行切分</td></tr><tr><td>MoE 专家并行</td><td>互联带宽</td><td>需替换 $\\beta$ 项</td><td>all-to-all 拓扑与重叠</td></tr></tbody></table>\n<p>把这三类失效条件写成检查清单，比记住公式本身更有用：先问字节是否真从 HBM 来（量化、SMEM 驻留都会改写分母），再问带宽项是否还是单卡 HBM（MoE 与专家并行必须换），最后问固定开销是否已与传输时间同量级（短序列补全必然如此）。三项中任一不满足，公式输出的就只是一个乐观上界，而不是可以拿去排容量、签延迟承诺的数字。</p>\n<h3 id=\"th-roofline-code-decode-sec-8\">八 · 逐项拆解：分子分母各是什么字节</h3>\n<p>把 $\\text{Attainable}=\\min\\left(\\pi_{\\text{peak}},\\;\\beta_{\\text{HBM}}/I\\right)$ 拆开看，真正决定结果的是 $I$ 的量纲对齐：分子必须是 FLOP，分母必须是 Byte，且两者统计的是同一个 token 的同一段工作。解码式 $I_{\\text{decode}}\\approx\\frac{2N_{\\text{active}}}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}}$ 的分子是每 token 一次前向的权重乘加 FLOP，系数 2 来自乘加各计一次；分母第一项是权重字节（每参数按 2 字节 FP16/BF16 计），第二项是 KV 字节，$L\\,d_{\\text{kv}}\\,n_{\\text{kv}}$ 是每 token 需要读到的 KV 元素总数，再乘 2 字节。这里有一个容易被忽略的对齐点：分母的权重项与 $N_{\\text{active}}$ 同源，而 KV 项与 $N_{\\text{active}}$ 无关，只随层数、KV 头维度、头数增长。因此 GQA/MQA 把 $n_{\\text{kv}}$ 压到 Q 头数的几分之一，直接缩小分母第二项，抬高 $I$，把解码从带宽受限往算力受限方向推——但推不远，因为权重项本身已经占满分母。</p>\n<p>预填式 $I_{\\text{prefill}}\\approx\\frac{2N_{\\text{active}}S}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,S}$ 的差别只在分母的 KV 项乘了 $S$：一次预填要读入整段上下文的 KV，而权重只读一次。分子同样乘 $S$，因为每个 token 都要过一遍权重。于是 $S$ 在分子上是线性的、在分母的 KV 项上也是线性的，但分母还有不随 $S$ 变的权重项，所以 $I_{\\text{prefill}}$ 随 $S$ 单调上升并趋于饱和值 $\\frac{2N_{\\text{active}}}{2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}}$——这个饱和值就是预填的算术强度天花板，也是它撞上 $\\pi_{\\text{peak}}$ 屋顶的位置。仓库级上下文 $S$ 到 $10^5$ 量级时，KV 项早已远大于权重项，$I$ 基本贴着饱和值走。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-9\">九 · 推导关键步：先写 FLOP 再写字节，最后相除</h3>\n<p>推导没有捷径，就是把每 token 的 FLOP 与字节分别写出再相除。第一步写 FLOP：稠密 Transformer 每 token 前向的乘加次数约等于 $2N_{\\text{active}}$，$N_{\\text{active}}$ 是参与该 token 计算的激活参数量，对稠密模型即全部参数。第二步写字节：权重必须从 HBM 读一遍，字节数为 $2N_{\\text{active}}$（按 2 字节/参数）；KV 必须读当前上下文对应的缓存，字节数为 $2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}$（解码，单 token 视角）或 $2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,S$（预填，整段上下文）。第三步相除，得到两个 $I$ 表达式。关键判断发生在第三步之后：解码时分母的权重项是常数、KV 项随批与序列增长，所以增大 batch 会让分母变大、$I$ 变小，解码更牢固地锁在带宽受限区；预填时分母的 KV 项随 $S$ 线性增长而分子也随 $S$ 线性增长，但分母的权重项不随 $S$ 变，所以 $S$ 越大 $I$ 越大，预填往算力受限区滑。</p>\n<p>还有一步常被跳过但必须点明：attention 的 FLOP 随 $S$ 平方增长，而 KV 字节随 $S$ 线性增长，两条曲线斜率不同。上面的 $I_{\\text{prefill}}$ 只统计了权重乘加与 KV 读取，没有把 attention 的 $S^2$ 项写进分子；一旦把 $S^2$ 项计入，$I_{\\text{prefill}}$ 在长上下文下会比该式给出的更高，更快撞上 $\\pi_{\\text{peak}}$。这就是为什么仓库级预填的瓶颈判断不能只看权重项，必须把 attention 的二次项单独估一遍。工程上这意味着：$S$ 从 $10^3$ 涨到 $10^5$，KV 字节涨 100 倍，attention FLOP 涨 10^4 倍，算术强度的实际上升比线性式更陡。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-10\">十 · 离散化与近似落在哪三处</h3>\n<p>公式是连续近似，落地时有三个离散化断点。第一处是“每 token 一次权重读取”的假设：真实 kernel 按 tile 分块，权重在 SMEM 与寄存器间有片上复用，实际 HBM 流量小于 $2N_{\\text{active}}$，所以公式给的是上界而非实测。第二处是 KV 读取的粒度：分页 KV cache 按 block 取，block 边界不对齐时实际读取字节大于理论值；KV 分块驻留 SMEM 时，部分 KV 不再走 HBM，$\\beta_{\\text{HBM}}$ 的有效值要重算。第三处是 batch 维度的离散化：解码式写的是单 token 视角，连续批处理把 $B$ 个 token 的权重读取合并为一次，分母权重项不变而分子乘 $B$，$I$ 随 $B$ 上升——这与“增大 batch 让 $I$ 变小”并不矛盾，前者是权重复用带来的分子增益，后者是 KV 字节随批增长带来的分母膨胀，两者谁占上风取决于 $B$ 与 KV 长度的比值。工程判断就落在这个比值上：短序列、大 batch 时权重复用占优，解码可以短暂离开带宽受限区；长序列、小 batch 时 KV 字节占优，回到带宽受限。</p>\n<div class=\"formula\">$$I_{\\text{decode}}(B)\\approx\\frac{2N_{\\text{active}}B}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,B}$$</div>\n<p>这个带 $B$ 的写法不是新公式，只是把离散化的 batch 维度显式写出来，用来判断权重复用与 KV 膨胀的交叉点。交叉点满足 $2N_{\\text{active}}\\approx 2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,B$，即 $B\\approx N_{\\text{active}}/(L\\,d_{\\text{kv}}\\,n_{\\text{kv}})$。超过这个 $B$，KV 字节主导分母，$I$ 趋近饱和值 $\\frac{2N_{\\text{active}}}{2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}}$，解码彻底锁死在带宽受限区。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-11\">十一 · 量化后必须重算，不能线性外推</h3>\n<p>权重量化改变的是分母第一项的字节数，不是分子。FP8 把权重字节从 2 降到 1，INT4 降到 0.5，$I$ 随之上升，但上升不是线性的：分母里还有 KV 项，KV 项不因权重量化而缩小。以解码为例，权重项与 KV 项在分母中的占比决定了量化收益的上限——当 KV 项已经占分母大头时，把权重压到 FP8 只能带来有限提升，因为瓶颈字节已经转移到 KV。这正是“把 FP8 收益误判为等比例吞吐提升”的失效模式：$I$ 上升了，但 $\\beta_{\\text{HBM}}/I$ 的改善被 KV 项稀释。KV 量化（FP8/INT8 KV cache）才是解码带宽受限区更直接的杠杆，因为它直接缩小分母第二项。</p>\n<p>量化还会改变 $\\beta_{\\text{HBM}}$ 的有效值：反量化在 SMEM 或寄存器里做，额外指令与数据搬运会吃掉一部分带宽，有效带宽低于标称 8 TB/s。所以重算 $I$ 时必须同时重算 $\\beta$ 的有效值，两个量一起动，不能只改一个。B200 的 192 GB HBM3e 容量决定了 KV 能驻留多少，容量与带宽是两个独立约束：容量不够时 KV 被迫换出，带宽项之外又多一次 HBM 往返，roofline 预测进一步偏乐观。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-12\">十二 · 失效条件的工程含义</h3>\n<p>公式的适用边界是稠密 Transformer、单卡/单 rank 视角、权重与 KV 均从 HBM 读取且无片上复用。四条失效条件各有明确的工程后果。其一，MoE 的 $N_{\\text{active}}$ 随 token 路由变化，每 token 激活参数不是常数，$I$ 变成随机量，只能用期望激活参数代入，且专家并行引入跨卡 all-to-all 后，分母的带宽项必须替换为互联带宽而非单卡 HBM 带宽——沿用 8 TB/s 会严重高估容量。其二，batch=1 且序列极短（代码补全单行场景）时，kernel launch 与调度固定开销主导时延，roofline 预测偏乐观，此时 SLO 承诺不能按 $\\beta_{\\text{HBM}}/I$ 推。其三，权重量化或 KV 分块驻留 SMEM 时 $I$ 与 $\\beta$ 的有效值需重算，公式只给上界。其四，公式未刻画 kernel launch 与调度开销，长上下文预填的 chunked prefill 切分本身带来调度开销，切得越细开销占比越高。</p>\n<p>把上界当实测吞吐是最常见的误用。B200 的 4.5 PFLOPS FP8 与 8 TB/s 是两个标称屋顶，实际可达性能是两者的较小值再打折。代码补全的低延迟场景落在解码带宽受限区，应优先做权重量化与 KV 压缩；仓库级长上下文预填落在算力受限区，应优先做 chunked prefill 与并行切分，而非继续压带宽。这个判断的方向由 $I$ 与 $\\pi_{\\text{peak}}/\\beta_{\\text{HBM}}$ 的比较决定：$I$ 小于该比值时带宽受限，大于时算力受限。B200 上该比值约为 $4.5\\times10^{15}/8\\times10^{12}\\approx 560$ FLOP/Byte，解码的 $I$ 远低于此，预填在 $S$ 到 $10^5$ 时逼近此值——这就是两条曲线切换区间的定量锚点。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-13\">十三 · 边界在哪里：从\"上界\"到\"实测\"的三处断点</h3>\n<p>把 <span class=\"formula\">$$\\text{Attainable}=\\min\\left(\\pi_{\\text{peak}},\\;\\frac{\\beta_{\\text{HBM}}}{I}\\right)$$</span> 当成容量规划的输入之前，必须先承认它是一张<em>上界</em>而非一张<em>预测</em>。这个上界的推导只用了两个假设：权重与 KV 全部从 HBM 取，且片上没有复用。真实 kernel 里这两条都不成立——tcgen05 的 MMA 会把权重块搬进 SMEM 与 TMEM 反复使用，KV 分块驻留 SMEM 后同一份 KV 字节可服务多个 query tile。此时公式里的 β 不再是 HBM 有效带宽，而是\"每字节 HBM 流量能支撑多少次 MMA\"的折算值；I 也不再是朴素比值。工程上正确的做法是把 β 换成 β_eff = β_HBM × (1 + 复用倍数)，把 I 换成按量化后有效字节重算的值，再取 min。若跳过这一步，FP8 权重量化带来的字节减半会被误读为吞吐等比例翻倍，而实际上受限于 kernel 的 tile 形状与 TMEM 容量，收益往往落在 1.3–1.6 倍区间而非 2 倍。</p>\n<p>第二个断点在离散化。公式把每 token 的 FLOP 写成 2N_active，把字节写成权重字节加 KV 字节，这是把连续的张量运算拍扁成一次\"读—算—写\"的粗粒度模型。真实执行被切成以层为单位的 kernel 序列，每层之间有一次 launch 与一次全局同步。当 batch=1、序列只有一行代码补全长度时，单次 kernel 的执行时间可能短于 launch 与调度开销，此时时延由固定开销主导，roofline 预测的\"带宽受限\"结论虽然方向正确，但绝对数值偏乐观——它算的是稳态带宽时间，没算排队与启动。判断阈值很直接：若单 kernel 的 HBM 传输时间低于 launch 开销的量级，就该把这一层从 roofline 模型里摘出来单独按固定开销估算，而不是继续用 β/I 推。</p>\n<p>第三个断点是并行视角。公式默认单卡单 rank，MoE 部署下 N_active 随 token 路由浮动，同一 batch 内不同 token 激活的专家集合不同，算术强度不再是一个常数而是一个分布；更关键的是专家并行引入跨卡 all-to-all 后，分母里的带宽项必须从 β_HBM 换成互联带宽 β_NVLink。此时瓶颈从\"卡内 HBM 读权重\"迁移到\"卡间搬激活\"，roofline 曲线的斜率整体改变。用 8 TB/s 的 HBM 数字去套一个 all-to-all 主导的 MoE 解码，会把互联瓶颈系统性低估，容量规划随之高估。下表把三种典型工作负载的受限区间与应优先动的杠杆并列，便于在决策时快速定位：</p>\n<table class=\"mini\"><thead><tr><th>工作负载</th><th>主导项</th><th>受限区间</th><th>优先杠杆</th><th>公式失效点</th></tr></thead><tbody><tr><td>单行代码补全（batch=1，短序列）</td><td>固定开销</td><td>非稳态，roofline 偏乐观</td><td>降低 launch 次数、算子融合</td><td>未刻画调度开销</td></tr><tr><td>仓库级长上下文预填（S 达 10^5 量级）</td><td>π_peak</td><td>算力受限</td><td>chunked prefill、并行切分</td><td>KV 字节随 S 线性、FLOP 随 S 平方的斜率差被忽略</td></tr><tr><td>MoE 专家并行解码</td><td>β_NVLink</td><td>互联受限</td><td>专家放置、all-to-all 聚合</td><td>沿用单卡 HBM 带宽项</td></tr></tbody></table>\n<p>还有一处容易被忽略的近似：预填公式里 attention 的 FLOP 实际随 S 平方增长，而分母的 KV 字节只随 S 线性增长，两者斜率不同正是\"从带宽受限切到算力受限\"的根源。但公式把分子写成 2N_active·S，只保留了线性项，平方项被吸收进常数里。这在 S 较小时无伤大雅，在 S 逼近 10^5 时会让算力受限的拐点位置偏移——真实拐点比公式给出的更早到来。因此把该界用于 SLO 承诺时，应把它当作\"乐观下界的时间\"来反推容量冗余，而不是当作\"预期吞吐\"直接写进合同；一旦 batch=1 短序列或 MoE 跨卡场景落入表中前两行的失效点，就必须用实测的 kernel 级 profile 替换公式输出，否则承诺的时延目标会在固定开销与互联瓶颈处双双落空。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-14\">十四 · 公式成立的前提，以及它在哪里先崩</h3>\n<p>这套 roofline 的推导链条其实很短：把每 token 的 FLOP 与字节分别写出再相除，得到 $I$，再代入 $\\text{Attainable}=\\min(\\pi_{\\text{peak}},\\beta_{\\text{HBM}}/I)$ 取较小值。关键步在于分母的构成——解码时分母是权重字节 $2N_{\\text{active}}$ 加上 KV 字节 $2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}$，权重项固定而 KV 项随批与序列增长；预填时分母的 KV 项乘上 $S$，分子也乘上 $S$，于是 $I_{\\text{prefill}}$ 随 $S$ 上升并最终撞上算力屋顶。两条曲线斜率不同，正是带宽受限向算力受限切换的判据。但这条链条的每一环都预设了“权重与 KV 均从 HBM 读取、无片上复用”，一旦这个假设被工程手段打破，公式给出的就只是上界而非实测值。</p>\n<p>最先失效的是量化与驻留。权重压到 FP8/INT4 后，分母的权重字节项缩小，$I$ 上升，$\\beta_{\\text{HBM}}$ 的有效值也随之改变（读的是压缩后的字节），必须按量化后的有效字节重算，否则会把 FP8 的收益误判为等比例吞吐提升。KV 分块驻留 SMEM 同理：被复用的 KV 不再计入 HBM 流量，分母被人为压低，roofline 预测会偏保守而非偏乐观。这两类改动都不改变公式形式，只改变代入值，误用往往就发生在“忘了改代入值”这一步。</p>\n<p>第二类失效来自并行形态。MoE 的 $N_{\\text{active}}$ 随 token 路由逐 token 变化，单条 $I$ 曲线不再成立；专家并行引入跨卡 all-to-all 后，带宽项必须从单卡 HBM 带宽替换为互联带宽（NVLink 5 域内与跨域 InfiniBand 量级差一个数量级以上），沿用 $\\beta_{\\text{HBM}}$ 代入会系统性低估互联瓶颈，容量规划严重高估。公式本身只对稠密 Transformer 的单卡/单 rank 视角成立，这是它的适用边界，不是可以外推的近似。</p>\n<p>第三类是固定开销。batch=1、序列极短的代码补全单行场景，实际时延由 kernel launch 与调度开销主导，roofline 完全不刻画这部分，预测偏乐观，直接拿它做 SLO 承诺会兑现不了。工程判断上，这条界只该用来判断工作负载落在哪个区间：低延迟补全落在解码带宽受限区，优先权重量化与 KV 压缩；仓库级长上下文预填（$S$ 可达 $10^5$ 量级）落在算力受限区，优先 chunked prefill 与并行切分，而不是继续压带宽。</p>\n<table class=\"mini\"><thead><tr><th>失效来源</th><th>被破坏的假设</th><th>系统代价表现</th></tr></thead><tbody><tr><td>FP8/INT4 权重量化</td><td>权重字节固定</td><td>未重算 $I$，吞吐收益被高估</td></tr><tr><td>KV 驻留 SMEM</td><td>KV 全走 HBM</td><td>分母虚高，预测偏保守</td></tr><tr><td>MoE 专家并行</td><td>单卡 HBM 带宽项</td><td>all-to-all 互联瓶颈被低估</td></tr><tr><td>batch=1 短序列</td><td>无固定开销</td><td>launch/调度主导，SLO 失守</td></tr></tbody></table>\n<h3 id=\"th-roofline-code-decode-sec-15\">十五 · 上界不是实测：固定开销吃掉的那一段</h3>\n<p>公式给出的是<strong>可达性能上界</strong>，而不是吞吐承诺。它的推导把一次 token 生成抽象成“读一遍权重、读一遍 KV、算一遍乘加”，但真实推理路径上还叠着 kernel launch、图调度、采样、框架侧的批拼装与结果回传。这些开销在长序列、大批量下被摊薄到可以忽略，在短序列、小批量下却是主导项。代码补全的单行场景正是后者：batch=1、上下文只有几十到几百 token，解码循环里每个 token 要走数十层、每层数个 kernel，单次 launch 的固定代价乘以层数乘以 kernel 数，累加起来可能已经与 HBM 读取权重的时间同量级。</p>\n<p>把固定开销写成可加项，roofline 预测的时延应当修正为：</p>\n<div class=\"formula\">$$T_{\\text{token}}\\;\\ge\\;\\max\\!\\left(\\frac{B_{\\text{weight}}+B_{\\text{kv}}}{\\beta_{\\text{HBM}}},\\;\\frac{F}{I\\cdot\\beta_{\\text{HBM}}}\\right)\\;+\\;T_{\\text{fixed}}$$</div>\n<p>其中 $T_{\\text{fixed}}$ 涵盖 launch、调度与采样，$B_{\\text{weight}}$ 是单 token 需读的权重字节。当 $T_{\\text{fixed}}$ 与带宽项同量级时，公式预测的“带宽受限”结论依然成立，但绝对数值偏乐观——它描述的是下界，而不是可达时延。工程判断是：对 batch=1 的补全型负载，先测 $T_{\\text{fixed}}$ 的实际占比，再决定是否值得为压带宽投入量化与 KV 压缩；若固定开销占主导，优化方向应是 CUDA Graph 捕获、kernel 融合与减少每 token 的 launch 次数，而不是继续压 HBM 字节。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-16\">十六 · 量化改变的是 I 和 β 的有效值，不是线性收益</h3>\n<p>公式中 $I$ 的分子是 FLOP、分母是字节。权重量化到 FP8 或 INT4 后，权重字节按位宽比例缩小，$I$ 随之上升；但 $I$ 上升并不意味着吞吐等比例提升，因为可达性能取 $\\min(\\pi_{\\text{peak}},\\beta_{\\text{HBM}}/I)$——一旦 $I$ 越过拐点，瓶颈从带宽切换到算力，继续压字节不再带来收益。更关键的是 $\\beta_{\\text{HBM}}$ 本身也要重算：量化权重需要反量化或混合精度乘加，实际有效带宽受反量化指令吞吐、scale 因子读取、以及 dequant 与 MMA 的重叠程度影响，未必等于标称的 8 TB/s。</p>\n<p>以 B200 的锚点做一次定性推演：$\\pi_{\\text{peak}}$ 约 4.5 PFLOPS（FP8 稠密），$\\beta_{\\text{HBM}}$ 约 8 TB/s，拐点算术强度在 $4.5\\times10^{15}/8\\times10^{12}\\approx 5.6\\times10^{2}$ FLOP/Byte 量级。解码阶段 $I_{\\text{decode}}$ 的典型值远低于此，因此解码牢牢落在带宽受限区；把权重从 FP16 压到 FP8，$I$ 大致翻倍，但只要仍低于拐点，吞吐提升就接近字节缩减比例——这恰恰是“误判为线性提升”容易成立的地方。一旦量化把 $I$ 推过拐点，收益立刻饱和。KV 分块驻留 SMEM 是另一条路径：它把 KV 字节从 HBM 分母中移出，$I$ 的有效值上升，但受 SMEM 容量与 bank 冲突约束，可驻留的 KV 块有限，公式给出的仍是上界。</p>\n<p>代价侧要一起看：INT4 权重带来反量化开销与精度损失，KV 压缩带来额外的元数据读取与重建成本。这些都不在公式里，却直接吃掉量化省下的带宽。工程上应把量化收益写成“字节缩减比例 × 落在带宽受限区的比例”，而不是单一倍数。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-17\">十七 · 稠密单卡假设在 MoE 与专家并行下失效</h3>\n<p>公式的 $N_{\\text{active}}$ 假设每 token 参与计算的参数量是固定的，这在稠密 Transformer 下成立，在 MoE 下不成立：$N_{\\text{active}}$ 随 token 的路由结果变化，不同 token 激活的专家不同，单 token 的权重读取字节因此是随机变量而非定值。更严重的是专家并行——专家分散在多卡上，token 需要经 all-to-all 送到持有对应专家的 rank，此时带宽项不再是单卡 HBM 带宽 $\\beta_{\\text{HBM}}$，而应替换为互联带宽（NVLink 5 的链路带宽与 all-to-all 的有效吞吐）。</p>\n<p>把这一层写进分母，解码算术强度变为：</p>\n<div class=\"formula\">$$I_{\\text{decode}}^{\\text{MoE}}\\approx\\frac{2\\bar{N}_{\\text{active}}}{2\\bar{N}_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}+\\;B_{\\text{a2a}}\\cdot n_{\\text{rank}}}$$</div>\n<p>其中 $\\bar{N}_{\\text{active}}$ 是路由后的期望激活参数量，$B_{\\text{a2a}}$ 是每 token 经 all-to-all 搬运的字节，$n_{\\text{rank}}$ 是参与并行的 rank 数。分母多出的互联项会把 $I$ 进一步压低，使系统更深地落入带宽受限区——但这里的“带宽”是互联带宽，不是 HBM 带宽。容量规划若沿用单卡 HBM 带宽代入，会系统性高估可达吞吐：实际瓶颈在跨卡链路上，扩容加卡未必线性提升，反而可能因 all-to-all 的拓扑跳数增加而恶化。GB200 NVL72 的机架级互联把这一项从 PCIe 级抬到 NVLink 级，但公式的适用边界要求把 $\\beta$ 换成对应层级的有效带宽，而不是继续用 8 TB/s。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-18\">十八 · 预填的 S 平方项与 chunked prefill 的边界</h3>\n<p>预填公式的分母里 KV 项随 $S$ 线性增长，分子随 $S$ 线性增长，因此 $I_{\\text{prefill}}$ 随 $S$ 上升并最终撞上算力屋顶——这是公式的结论。但推导里还有一步没写进简化式：attention 的 FLOP 随 $S$ 平方增长，而 KV 字节随 $S$ 线性增长，两条曲线斜率不同，决定了从带宽受限切换到算力受限的拐点位置。仓库级上下文可达 $10^5$ token 量级，此时 $S$ 平方项主导，预填牢牢落在算力受限区。</p>\n<p>chunked prefill 改变的是这条曲线的形状：把长序列切成若干 chunk 分批送入，单 chunk 的 $S$ 变小，$I$ 随之下降，系统从算力受限区回落到带宽受限区，代价是 chunk 间的调度开销与 KV 的重复读写。公式在这里的适用边界是：它描述的是单次前向的稳态算术强度，chunked prefill 下每个 chunk 有自己的 $I$，整段预填的可达性能是各 chunk 的加权结果，而不是把总 $S$ 代入一次。工程判断是：当 $S$ 达到 $10^5$ 量级、算力受限时，优先做并行切分与 chunked prefill；当 chunk 切得过小、$I$ 掉回带宽区，则预填收益被调度开销抵消，需要重新找 chunk 大小的平衡点。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-19\">十九 · 规模上限：公式在什么尺度上停止有效</h3>\n<p>公式的适用边界可以归纳为三条尺度约束。第一，<strong>序列尺度</strong>：$S$ 极短时固定开销主导，$S$ 极长时 attention 的平方项使简化式的线性假设失效，中间段才是公式的稳态有效区。第二，<strong>并行尺度</strong>：单卡/单 rank 视角下 $\\beta_{\\text{HBM}}$ 是唯一带宽项；一旦引入张量并行、专家并行或分离式部署，通信项进入分母，公式需按互联层级重写。第三，<strong>精度尺度</strong>：FP8/INT4 量化与 KV 分块驻留 SMEM 都改变 $I$ 与 $\\beta$ 的有效值，公式给出的是上界，实测值需按有效字节与有效带宽重算。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>失效条件</th><th>需替换的项</th><th>系统代价</th></tr></thead><tbody><tr><td>权重与 KV 均从 HBM 读、无片上复用</td><td>KV 分块驻留 SMEM、权重常驻</td><td>$I$ 的有效值、$\\beta$ 的有效值</td><td>SMEM 容量约束、bank 冲突</td></tr><tr><td>稠密 Transformer、$N_{\\text{active}}$ 固定</td><td>MoE 路由、专家并行</td><td>$\\bar{N}_{\\text{active}}$、互联带宽项</td><td>all-to-all 时延、拓扑跳数</td></tr><tr><td>单卡/单 rank 视角</td><td>张量并行、分离式预填/解码</td><td>$\\beta_{\\text{HBM}}\\to\\beta_{\\text{link}}$</td><td>跨卡通信、KV 传输</td></tr><tr><td>稳态解码循环</td><td>batch=1、单行补全</td><td>加 $T_{\\text{fixed}}$ 项</td><td>launch 与调度开销</td></tr></tbody></table>\n<p>规模上限的工程含义是：公式用于<strong>判断区间</strong>而非<strong>预测数值</strong>。它告诉你代码补全的低延迟场景落在解码带宽受限区、仓库级长上下文预填落在算力受限区，从而决定优化方向是压字节还是切并行；但它不告诉你具体的 token/s，因为 $T_{\\text{fixed}}$、反量化开销、all-to-all 有效带宽都不在式子里。把上界当实测吞吐去承诺 SLO，是这套公式最常见的失败模式——预测偏乐观，承诺无法兑现。反过来，在 MoE 专家并行部署中沿用单卡 8 TB/s 代入，会低估互联瓶颈，容量规划严重高估。正确用法是：先用公式定位区间，再用实测的有效 $\\beta$ 与 $T_{\\text{fixed}}$ 回填，得到可承诺的容量数字。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-20\">二十 · 当公式开始说谎：Roofline 界的假设、失效与规模天花板</h3>\n<p>这套界的第一条隐含假设是“权重与 KV 全部从 HBM 读出、片上无复用”。一旦工程上打破这条假设，公式给出的就不再是可达性能，而只是一个未经修正的上界。最典型的是权重量化：把权重从 FP16 压到 FP8 或 INT4，分子里的乘加 FLOP 不变，分母里的权重字节按位宽比例缩小，$I$ 随之上升，$\\beta_{\\text{HBM}}/I$ 项变大，界向右上方移动。但收益绝不是线性的——量化后必须按<em>有效字节</em>重算 $I$，同时反量化、scale 广播、混合精度累加会引入额外指令与寄存器压力，$\\beta_{\\text{HBM}}$ 的有效值也要按实际可达带宽打折。把 FP8 当成“吞吐翻倍”来承诺 SLO，是把上界误读成实测的经典翻车点。同理，KV 分块驻留 SMEM、以 chunked prefill 复用片上缓存时，分母中的 KV 字节项被部分消掉，公式必须重写，否则会系统性低估预填吞吐。</p>\n<p>第二条边界是“稠密 Transformer、单卡/单 rank 视角”。MoE 直接击穿它：$N_{\\text{active}}$ 不再是常量，而随 token 路由逐 token 变化，$I_{\\text{decode}}$ 的分子变成随机变量，roofline 只能给期望意义上的界；更严重的是专家并行把原本的 HBM 带宽项替换为跨卡互联带宽，此时瓶颈从 $\\beta_{\\text{HBM}}$ 变成 all-to-all 的有效吞吐。容量规划若仍代入单卡 8 TB/s，会严重高估可承载的并发——互联带宽通常比 HBM 低一个量级，且受拓扑与拥塞影响。可写成修正形式：</p>\n<div class=\"formula\">$$\\text{Attainable}_{\\text{MoE}}=\\min\\left(\\pi_{\\text{peak}},\\;\\frac{\\beta_{\\text{link}}}{I_{\\text{decode}}^{\\text{eff}}}\\right),\\quad \\beta_{\\text{link}}=\\min\\left(\\beta_{\\text{HBM}},\\;\\beta_{\\text{all2all}}\\right)$$</div>\n<p>其中 $\\beta_{\\text{all2all}}$ 由 NVLink 5 拓扑、NCCL/NIXL 传输路径与专家分布共同决定，必须实测而非查表。</p>\n<p>第三条是规模上限与固定开销。公式完全未刻画 kernel launch、调度与框架开销，而这些在 batch=1、序列极短的代码补全单行场景里是主导项。设单 token 固定开销为 $t_0$，则实际时延近似 $t\\approx\\max\\left(\\frac{\\text{Bytes}}{\\beta_{\\text{HBM}}},\\frac{\\text{FLOP}}{\\pi_{\\text{peak}}}\\right)+t_0$，当 $t_0$ 与带宽项同量级时，roofline 预测偏乐观，SLO 承诺无法兑现。反过来，预填侧的上限由 $S$ 决定：仓库级上下文可达 $10^5$ token，$I_{\\text{prefill}}$ 随 $S$ 上升并撞上 $\\pi_{\\text{peak}}$ 屋顶，此时继续压带宽毫无意义，应转向 chunked prefill 与并行切分；而 192 GB 的 HBM 容量决定了 KV 能驻留多长的上下文，容量而非带宽成为硬约束。工程判断很简单：先用有效字节与有效带宽重算 $I$，确认自己落在哪一侧，再决定优化方向——把界当上界用，而不是当承诺用。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-21\">二十一 · 当 roofline 让位于固定开销与互联瓶颈</h3>\n<p>公式成立的前提是权重与 KV 全部从 HBM 搬运且无片上复用，因此它给出的是上界而非实测值。一旦权重量化到 FP8/INT4 或把 KV 分块驻留 SMEM，分母的字节项被改写，$I$ 与 $\\beta_{\\text{HBM}}$ 的有效值都必须重算；此时若仍用原始 $I$ 代入 $\\min(\\pi_{\\text{peak}},\\beta/I)$，就会把量化收益误判为等比例吞吐提升。以 B200 的 8 TB/s 与 4.5 PFLOPS FP8 为锚点，解码 $I_{\\text{decode}}$ 的分子 $2N_{\\text{active}}$ 固定、分母随 $L\\,d_{\\text{kv}}\\,n_{\\text{kv}}$ 增长，量化只压缩权重字节而不改变 KV 项，收益因此是分段的而非线性的。</p>\n<p>规模上限首先体现在 batch=1 且序列极短的代码补全单行场景：此时每 token 的搬运量小到让 kernel launch 与调度开销占据主导，roofline 预测偏乐观，SLO 承诺容易落空。可用一个修正判据刻画失效边界：</p>\n<div class=\"formula\">$$\\text{有效吞吐}\\approx\\frac{1}{\\max\\!\\left(\\dfrac{I}{\\min(\\pi_{\\text{peak}},\\beta_{\\text{HBM}}/I)},\\;t_{\\text{fixed}}\\right)}$$</div>\n<p>其中 $t_{\\text{fixed}}$ 为单次前向的固定开销，当 $I$ 对应的理想时延低于 $t_{\\text{fixed}}$ 时，公式让位于调度开销，这正是低延迟补全场景必须单独建模的原因。</p>\n<p>第二个失效条件是部署形态。MoE 的 $N_{\\text{active}}$ 随 token 路由逐次变化，专家并行把权重读取替换为跨卡 all-to-all，带宽项须换成 NVLink 5 互联带宽而非单卡 HBM 带宽；沿用 8 TB/s 代入会系统性低估互联瓶颈，容量规划严重高估。下表给出三类负载的适用性判断：</p>\n<table class=\"mini\"><thead><tr><th>负载</th><th>主导项</th><th>公式是否可信</th></tr></thead><tbody><tr><td>单行补全，batch=1</td><td>固定开销</td><td>偏乐观，需加 $t_{\\text{fixed}}$</td></tr><tr><td>仓库级预填，$S\\sim10^5$</td><td>算力屋顶</td><td>可信，优先 chunked prefill</td></tr><tr><td>MoE 专家并行解码</td><td>互联带宽</td><td>须替换 $\\beta$ 项</td></tr></tbody></table>\n<p>预填侧的边界在于 $S$ 的量级：仓库级上下文达 $10^5$ token 时 $I_{\\text{prefill}}$ 已撞上 $\\pi_{\\text{peak}}$，继续压带宽无收益，应转向并行切分与 chunked prefill；而在 $S$ 尚小的中等上下文，KV 项仍占分母主导，此时切分反而增加通信代价。判断切换点的工程做法是解 $\\beta_{\\text{HBM}}/I_{\\text{prefill}}(S)=\\pi_{\\text{peak}}$ 得到临界序列长度，超过它才进入算力受限区。</p>\n<h3 id=\"th-roofline-code-decode-sec-22\">二十二 · 从界到决策变量：把 roofline 反解成配置</h3>\n<p>前两部分给出的是正向映射：给定 $N_{\\text{active}}$、$L$、$d_{\\text{kv}}$、$n_{\\text{kv}}$、$S$，算出 $I$ 与可达性能上界。工程决策要的是反向映射——给定工作负载形态与 SLO，反解出批大小、并行度、KV 预算。做法是把 $\\text{Attainable}=\\min(\\pi_{\\text{peak}},\\beta_{\\text{HBM}}/I)$ 改写成对配置变量的约束不等式，再逐条取可行域交集。</p>\n<p>关键是把 $I$ 里的批维度显式化。解码时权重字节对 batch 不变，KV 字节随 batch 线性增长，故 batch=$B$、上下文长度 $C$ 时</p>\n<div class=\"formula\">$$I_{\\text{decode}}(B,C)\\approx\\frac{2N_{\\text{active}}B}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,B\\,C}$$</div>\n<p>分母第二项随 $B\\cdot C$ 增长，$I$ 随批增大而单调下降，意味着增大 batch 会把工作负载更深地推入带宽受限区——但总吞吐仍上升，因为每步搬运的权重被更多 token 摊薄。真正的约束来自两处：KV 显存容量（$B\\cdot C$ 不得超过 KV 预算）与 SLO 的 TPOT 上限。于是批大小决策变成：在 KV 预算内取最大 $B$，使单步解码时间 $T_{\\text{step}}\\approx(2N_{\\text{active}}+2L d_{\\text{kv}}n_{\\text{kv}}BC)/\\beta_{\\text{HBM}}$ 满足 TPOT 约束。注意这里用的是字节数除以带宽，而不是 FLOP 除以算力——因为在带宽受限区，后者给出的是永远达不到的乐观值。</p>\n<p>代价判断很直接：B200 的 8 TB/s 带宽与 192 GB HBM 是硬边界。若某模型的权重在 FP8 下占 $W$ 字节，则 KV 预算为 $192\\text{ GB}-W$ 再扣激活与框架开销；把该预算除以每 token 的 KV 字节 $2L d_{\\text{kv}}n_{\\text{kv}}$（按 KV 精度折算），得到单序列最大上下文，再除以目标并发数即得每序列可用上下文。这一步是容量规划里最容易被跳过、也最容易翻车的地方。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-23\">二十三 · 定并行度：切分改变的是哪一项</h3>\n<p>张量并行不改变 $I$ 的分子结构，但改变分母里的带宽项。把权重切到 $P$ 个 rank 后，每 rank 每步读取 $2N_{\\text{active}}/P$ 字节权重，同时引入 all-reduce 通信量。对解码这种每步只搬一次权重的场景，通信量与计算量同阶，因此有效带宽必须替换为 $\\beta_{\\text{eff}}=\\min(\\beta_{\\text{HBM}},\\beta_{\\text{link}}\\cdot\\eta)$，其中 $\\beta_{\\text{link}}$ 是 NVLink 5 的单向带宽量级，$\\eta$ 是 all-reduce 的环状算法效率因子。这一步的正确写法是：先判断单卡 roofline 落在哪个区，再判断切分后互联是否成为新瓶颈。</p>\n<p>具体机制上，解码的 all-reduce 发生在每层 attention 输出与 MLP 输出之后，每 token 每层两次，故通信字节约为 $2\\cdot 2N_{\\text{active}}/P\\cdot(P-1)/P$ 量级；当 $P$ 增大，单卡计算量下降而通信次数不变，通信占比上升。因此并行度的选择不是越大越好：存在一个 $P^\\*$，使单卡计算时间与 all-reduce 时间相等，超过它则 roofline 的带宽项被互联带宽接管，吞吐不再线性扩展。</p>\n<p>算例：设某稠密模型 $N_{\\text{active}}=30\\text{B}$、$L=60$、$d_{\\text{kv}}n_{\\text{kv}}$ 使每 token KV 字节为 $2\\times60\\times d_{\\text{kv}}n_{\\text{kv}}$，在 FP8 下权重约 30 GB。单卡 B200 上权重读取 30 GB 需约 $30/8000\\approx3.75\\text{ ms}$（按 8 TB/s 计），这是 batch=1 解码的单步下界。若目标 TPOT 为 20 ms，则留给 KV 读取与调度的余量为 16 ms 量级，据此可反推可承受的 $B\\cdot C$ 乘积。若把模型切到 4 卡，单卡权重读取降至 7.5 GB、约 0.94 ms，但每层两次 all-reduce 的时延开始与计算同阶，此时应转而评估 NVLink 域内是否仍满足 TPOT，而不是继续加卡。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-24\">二十四 · 定 KV 预算：精度与分块如何改写分母</h3>\n<p>KV 预算是容量决策的核心，但 roofline 视角下的 KV 不只是显存占用，它同时是解码带宽分母的一项。压缩 KV 有两个独立收益：显存上允许更大 $B\\cdot C$，带宽上降低每步读取字节从而抬高 $I$。两者不可混为一谈——前者改善容量，后者改善时延。工程上常见的错误是把 KV 量化当成纯容量手段，忽略它对 $I$ 的抬升，从而低估时延改善。</p>\n<p>机制上，若 KV 从 BF16 降到 FP8，每 token KV 字节减半，$I_{\\text{decode}}$ 的分母第二项减半，$I$ 上升；若进一步做 KV 分块驻留 SMEM，则公式假设的“KV 均从 HBM 读取”失效，$\\beta_{\\text{HBM}}$ 的有效值需按实际 HBM 流量重算，公式退化为上界。此时正确的做法是把分母拆成 HBM 字节与 SMEM 复用字节两部分，前者除以 $\\beta_{\\text{HBM}}$、后者不计入带宽项，得到修正后的 $I'$。</p>\n<p>代价侧：192 GB 的 B200 在 FP8 权重下留给 KV 的空间有限，仓库级上下文 $S$ 达 $10^5$ 量级时，单序列 KV 字节可能吃掉相当比例的预算，直接压缩并发数。决策规则是：先按 SLO 定出目标并发 $B$ 与目标上下文 $C$，算出所需 KV 字节，与预算比较；若超支，优先降 KV 精度（容量与带宽双收益），其次降 $C$（仅容量收益），最后才降 $B$（直接损失吞吐）。这个优先级顺序来自 roofline 的结构，而不是经验拍脑袋。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-25\">二十五 · 定 SLO：把界翻译成可承诺的数字</h3>\n<p>SLO 的两个常用指标是 TTFT 与 TPOT。预填阶段的 roofline 落在算力受限区（长上下文下 $I_{\\text{prefill}}$ 随 $S$ 上升直至撞上 $\\pi_{\\text{peak}}$），因此 TTFT 的下界由 $\\pi_{\\text{peak}}$ 决定：$T_{\\text{prefill}}\\gtrsim 2N_{\\text{active}}S/\\pi_{\\text{peak}}$。以 B200 的 4.5 PFLOPS 计，$S=10^5$ 时分子是 $2\\times N_{\\text{active}}\\times10^5$ FLOP 量级，这一项决定了仓库级预填不可能靠加带宽解决，只能靠 chunked prefill 与并行切分把工作分摊到多卡、并与解码错峰。</p>\n<p>解码侧则相反，TPOT 下界由 $\\beta_{\\text{HBM}}$ 决定：$T_{\\text{decode}}\\gtrsim(2N_{\\text{active}}+2L d_{\\text{kv}}n_{\\text{kv}}BC)/\\beta_{\\text{HBM}}$。把 SLO 的 TPOT 上限代入，得到对 $B\\cdot C$ 的硬约束。这一步的工程价值在于：它把“能不能承诺 20 ms TPOT 下 32 路并发”变成一个可计算的不等式，而不是靠压测试探。</p>\n<p>失效条件必须写进 SLO 文档：batch=1 且序列极短（代码补全单行场景）时，固定开销主导，roofline 预测偏乐观，承诺值需留出 kernel launch 与调度余量；MoE 部署中 $N_{\\text{active}}$ 随路由变化，且专家并行的 all-to-all 使带宽项须替换为互联带宽，单卡 HBM 代入会严重高估容量。这两条是容量规划翻车的高频原因。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-26\">二十六 · 算例：一次完整的反解</h3>\n<p>设工作负载为代码补全 + 仓库级问答混合。补全侧：单行、上下文短、$B$ 小，落在解码带宽受限区；问答侧：$S$ 达 $10^5$ 量级，落在预填算力受限区。两段共享同一批 GPU，决策需分别做。</p>\n<p>补全侧反解：以 FP8 权重、$N_{\\text{active}}$ 给定，单步权重读取字节固定，$T_{\\text{step}}$ 主要由权重字节除以 8 TB/s 决定；由于 $B$ 小、$C$ 短，KV 项占比低，$I$ 接近上界 $\\beta_{\\text{HBM}}/I$ 给出的带宽受限值。此时提升吞吐的唯一有效手段是增大 $B$（摊薄权重读取）与降 KV 精度（减小分母），而非加并行度——加卡反而引入 all-reduce 固定开销，在 batch=1 场景下净损失。</p>\n<p>问答侧反解：$S=10^5$ 使 $I_{\\text{prefill}}$ 撞上 $\\pi_{\\text{peak}}$，预填时间由算力决定，与带宽无关。此时应做 chunked prefill 把长预填切成块与解码交错，避免单次长预填阻塞 TPOT；并行切分应优先切预填而非解码，因为预填在算力受限区、切分收益线性。KV 预算上，$10^5$ 上下文的单序列 KV 字节会显著压缩并发，需按第三节的优先级先降 KV 精度。</p>\n<p>合并判断：两段工作负载的 roofline 区间不同，混部时若用同一套并行度与批策略，必然一端受损。工程上应做区间感知的调度——补全请求优先走低并行、大批、KV 压缩路径；问答请求走 chunked prefill 加预填切分路径。这正是把 roofline 从“解释性能”变成“分配资源”的用法：界不是用来事后归因的，而是用来在部署前把配置变量钉在可行域内。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-27\">二十七 · 把上界换算成配置：批大小、并行度、KV 预算与 SLO 的反解</h3>\n\n<p>容量决策的正确用法不是拿公式去预测吞吐，而是把它反解成配置约束。给定 SLO 要求的单 token 时延上限 $t_{\\text{slo}}$，解码阶段每步至少要搬运 $2N_{\\text{active}}$ 字节权重加 $2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,B$ 字节 KV（$B$ 为并发批），于是单步时间下界为 $\\max\\left(\\frac{2N_{\\text{active}}+2L d_{\\text{kv}} n_{\\text{kv}} B}{\\beta_{\\text{HBM}}},\\ \\frac{2N_{\\text{active}}B}{\\pi_{\\text{peak}}}\\right)$。以 B200 的 8 TB/s 与 4.5 PFLOPS 代入，权重项在 $B$ 较小时完全支配分母，批增大只线性增加 KV 字节而几乎不增加算力压力——这正是解码区间的可用杠杆：把 $B$ 推到 KV 项与权重项同量级之前，吞吐近似线性增长而时延几乎不变；越过该点后每 token 时延开始随 $B$ 上升，SLO 被击穿。工程上应解出使 KV 字节等于权重字节的临界批 $B^\\*=\\frac{N_{\\text{active}}}{L\\,d_{\\text{kv}}\\,n_{\\text{kv}}}$，把它作为连续批处理的上界参考，而不是凭经验拍一个 256 或 512。</p>\n\n<p>KV 预算的定法同理，但要把 192 GB 的账算清。权重占用 $2N_{\\text{active}}$ 字节（FP8 下减半），剩余显存除以每 token KV 字节 $2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}$ 得到可容纳的 token 总数，再除以目标并发即得每请求可用上下文长度。这里的关键判断是：GQA/MQA 把 $n_{\\text{kv}}$ 压到远小于 Q 头数，直接线性放大可服务 token 数，因此 KV 预算紧张时应优先确认 $n_{\\text{kv}}$ 是否已压到架构下限，其次才是分页与前缀复用。反过来，若把 FP8 权重当成等比例吞吐提升，就会在权重字节减半后仍沿用旧 $I$ 值，误判系统已进入算力受限区而盲目加并行度——实际有效带宽与有效 $I$ 必须按量化后的字节重算，公式给的始终是上界。</p>\n\n<p>预填侧的决策逻辑完全不同。$I_{\\text{prefill}}$ 随 $S$ 上升，仓库级 $10^5$ token 上下文会把工作负载推入算力受限区，此时压带宽收益趋零，应转向 chunked prefill 把长预填切块与解码交错、以及张量/序列并行切分来分摊算力。但切分本身有代价：跨卡切分把权重与 KV 读取换成互联带宽项，NVLink 5 的域内带宽虽高，跨 rank 的 all-to-all 与集合通信延迟仍会吃掉切分收益，尤其在 MoE 专家并行下 $N_{\\text{active}}$ 随路由逐 token 变化，单卡 HBM 带宽代入会系统性高估容量。可用的判断表如下：</p>\n\n<table class=\"mini\"><thead><tr><th>决策项</th><th>受限区判据</th><th>首选手段</th><th>系统代价</th></tr></thead><tbody><tr><td>批大小</td><td>KV 字节 < 权重字节</td><td>增大连续批</td><td>越过 $B^*$ 后时延线性上升</td></tr><tr><td>KV 预算</td><td>显存余量 / 每 token KV 字节</td><td>压 $n_{\\text{kv}}$、分页复用</td><td>上下文变长挤占并发</td></tr><tr><td>并行度</td><td>$I_{\\text{prefill}}$ 撞算力屋顶</td><td>chunked prefill、切分</td><td>互联带宽与通信延迟</td></tr><tr><td>SLO 承诺</td><td>batch=1 短序列</td><td>不以 roofline 定价</td><td>固定开销主导，预测偏乐观</td></tr></tbody></table>\n\n<p>最后一条边界必须写进容量模型：代码补全单行场景下 batch=1、序列极短，kernel launch 与调度固定开销主导实际时延，roofline 给出的下界与实测之间的差距不可忽略，用它去承诺 SLO 会直接违约。因此该界适合做区间划分与杠杆排序，不适合做单点吞吐报价；一旦工作负载落在固定开销区或跨卡互联区，就必须把带宽项替换为对应层级的有效带宽并叠加调度开销项，否则公式的乐观偏差会沿着容量规划一路放大。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-28\">二十八 · 把上界换算成容量：批大小、并行度与 KV 预算的取整规则</h3>\n<p>决策时把 roofline 当约束方程而非预测器：先由 SLO 定每 token 时延上限 <span class=\"inline-math\">t_max</span>，反解允许的最大批 <span class=\"inline-math\">B</span>。解码每步耗时下界近似 <span class=\"inline-math\">t_step ≥ (2N_active·w_bytes + B·2L·d_kv·n_kv·kv_bytes)/β_HBM</span>，其中 <span class=\"inline-math\">w_bytes</span> 是量化后每参数字节。权重项与 <span class=\"inline-math\">B</span> 无关，是固定税；KV 项随 <span class=\"inline-math\">B</span> 线性涨。因此 <span class=\"inline-math\">B_max ≈ (t_max·β_HBM − 2N_active·w_bytes)/(2L·d_kv·n_kv·kv_bytes)</span>。若算出 <span class=\"inline-math\">B_max &lt; 1</span>，说明连 batch=1 都撑不住该 SLO——此时唯一出路是压 <span class=\"inline-math\">w_bytes</span>（FP8/INT4）或减 KV 字节（GQA、KV 量化），而不是加卡。这是把公式用于定批大小的正确姿势：先看权重税占了多少时延预算。</p>\n<p>并行度不能靠 roofline 直接给出，但它能判定切分方向是否有意义。预填阶段 <span class=\"inline-math\">I_prefill</span> 随 <span class=\"inline-math\">S</span> 上升并撞上 <span class=\"inline-math\">π_peak</span>，一旦进入算力受限区，增加 TP/EP 切分才换来近线性收益；反之若仍在带宽受限区，切分只是把同一份权重字节摊到多卡、每卡带宽项不变，收益被互联通信吃掉。判断阈值：当 <span class=\"inline-math\">β_HBM/I_prefill &lt; π_peak</span> 时切分无效。仓库级 <span class=\"inline-math\">S≈10^5</span> 的预填显然落在算力侧，故 chunked prefill 与序列并行优先；而代码补全单行解码落在带宽侧，加卡无益。</p>\n<p>KV 预算同样由上界反推：给定 <span class=\"inline-math\">B</span> 与目标上下文 <span class=\"inline-math\">S</span>，KV 占用 <span class=\"inline-math\">≈ B·S·2L·d_kv·n_kv·kv_bytes</span>，须塞进 192 GB 减去权重后的余量。若超了，roofline 告诉你压缩 KV 字节直接抬升 <span class=\"inline-math\">B_max</span>，而扩卡只扩容量不扩带宽。下表给出决策映射（定性，不含实测）：</p>\n<table class=\"mini\"><thead><tr><th>工作负载</th><th>受限区间</th><th>优先手段</th><th>roofline 失效点</th></tr></thead><tbody><tr><td>单行补全 batch=1</td><td>带宽+固定开销</td><td>权重量化、KV 压缩</td><td>launch/调度开销主导，预测偏乐观</td></tr><tr><td>仓库级预填 S≈10^5</td><td>算力</td><td>chunked prefill、序列并行</td><td>忽略 attention 的 S² 项细节</td></tr><tr><td>MoE 专家并行</td><td>互联带宽</td><td>all-to-all 拓扑优化</td><td>沿用单卡 β_HBM 严重高估</td></tr></tbody></table>\n<p>边界必须写进容量模型：公式假设权重与 KV 全从 HBM 读、无片上复用，量化或 KV 驻留 SMEM 后 <span class=\"inline-math\">I</span> 与 <span class=\"inline-math\">β</span> 有效值需重算，给出的是上界；MoE 的 <span class=\"inline-math\">N_active</span> 随路由抖动且带宽项应换成互联带宽；batch=1 短序列时固定开销主导。把上界当实测吞吐去承诺 SLO，或在专家并行里沿用单卡带宽做规划，是两类会把容量算错的典型误用。</p>\n<h3 id=\"th-roofline-code-decode-sec-29\">二十九 · 把上界当实测：batch=1 单行补全的固定开销陷阱</h3>\n<p>最普遍的一类误用，是把 <span class=\"formula\">$$\\text{Attainable}=\\min\\left(\\pi_{\\text{peak}},\\;\\frac{\\beta_{\\text{HBM}}}{I}\\right)$$</span> 算出来的数直接当成服务能交付的吞吐或时延写进 SLO。这个式子的量纲是「稳态下的可达性能上界」，它默认了足够长的执行窗口，使 kernel 内部的数据搬运可以摊薄一切非计算开销。而代码补全的真实工作负载恰恰相反：batch=1、序列极短（单行或数十 token），每次解码步的 HBM 搬运量只有权重加极小 KV，绝对时间落在微秒级，与 kernel launch、调度器派发、框架前后处理处于同一数量级。</p>\n<p>识别方法很直接：算一下 roofline 预测的单步时间 <span class=\"formula\">$$t_{\\text{roof}}=\\frac{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}}{\\beta_{\\text{HBM}}}$$</span>，再与实际端到端 token 间隔对比。若实测间隔显著大于 $t_{\\text{roof}}$ 且随 batch 增大而收敛，说明固定开销在主导，此时 roofline 给出的是下界时间而非可达时间。后果是容量规划按上界反推并发数，上线后单请求延迟打不满承诺，SLO 违约。工程判断：对 batch=1 短序列场景，roofline 只用来判断「带宽受限还是算力受限」的方向，不用来定绝对数值；绝对数值必须由实测的固定开销项修正。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-30\">三十 · MoE 与专家并行：沿用单卡 HBM 带宽项的容量高估</h3>\n<p>公式的适用边界写明是稠密 Transformer 单卡/单 rank 视角，权重与 KV 均从 HBM 读取。MoE 部署打破了这个前提的两处：其一，$N_{\\text{active}}$ 随 token 路由变化，同一 batch 内不同 token 激活的专家集合不同，算术强度不再是一个稳定标量，而是随路由分布的随机量；其二，专家并行把权重分散到多卡，每 token 的专家计算需要跨卡 all-to-all 交换激活，带宽项从 $\\beta_{\\text{HBM}}$ 变成了互联带宽（NVLink 5 域内或跨域 fabric），量级与 HBM 不同。</p>\n<p>误用形态是：规划时仍用 8 TB/s 的 HBM 带宽代入 $\\beta$，得到一条漂亮的带宽受限曲线，据此估算单 GPU 可承载的 token/s，再乘以 GPU 数得到集群容量。真实瓶颈却在 all-to-all：每层每个 token 要经历一次 dispatch 与 combine，通信量与激活维度、top-k 专家数、EP 度数相关，且 all-to-all 的有效带宽远低于 HBM 且对拓扑敏感。识别信号是压测中 GPU 的 HBM 带宽利用率上不去、SM 空转等待通信，而 NCCL/NIXL 的链路吞吐已接近饱和。修正方式是把分母的字节项替换为「本地权重字节 + 跨卡交换字节」，$\\beta$ 换成互联有效带宽，重算 $I$ 与可达性能；容量规划必须以互联带宽为约束重新做，而不是在单卡公式上乘卡数。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-31\">三十一 · 量化后不重算：把 FP8/INT4 收益误判为等比例提升</h3>\n<p>第三个高频误用出现在权重量化之后。公式的失效条件明确指出：采用 FP8/INT4 量化或 KV 分块驻留 SMEM 时，$I$ 与 $\\beta$ 的有效值需重算，公式给出的是上界而非实测值。原因在于算术强度的分母是字节数，权重从 BF16 压到 FP8 分母减半，$I$ 近似翻倍，带宽受限区间的可达性能随之抬升——但抬升不是线性的，因为同时出现了新的约束：反量化开销、scale 因子的额外读取、以及某些 kernel 在低比特下无法打满 HBM 带宽。</p>\n<p>误判的典型表述是「权重减半，吞吐翻倍」。实际推演：设原 BF16 下 $I_{\\text{decode}}$ 落在带宽受限区，量化后 $I$ 上升，可达性能按 $\\beta/I$ 提升，但只要 $I$ 仍低于 $\\pi_{\\text{peak}}/\\beta$ 的拐点，提升幅度就受限于有效带宽是否真的翻倍。若量化 kernel 的实际有效带宽只提高了部分比例（受反量化指令吞吐与访存模式影响），则吞吐提升小于字节缩减比例。识别方法：分别测量量化前后的实测有效带宽与 kernel 时间，用实测 $\\beta_{\\text{eff}}$ 重算 $I$，而不是用标称 8 TB/s。工程判断：量化收益要用「重算后的 $I$ 落在哪个区间」来评估，落在带宽受限区则收益接近字节缩减比，落在算力受限区则收益被 $\\pi_{\\text{peak}}$ 截断，两种情况的容量结论完全不同。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-32\">三十二 · 反例：仓库级预填误按解码带宽受限规划</h3>\n<p>给一个完整的反例。某代码推理服务要支持仓库级上下文，$S$ 达 $10^5$ token 量级，同时保留低延迟单行补全通道。规划者用解码公式 <span class=\"formula\">$$I_{\\text{decode}}\\approx\\frac{2N_{\\text{active}}}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}}$$</span> 算出算术强度极低、判定全局带宽受限，于是把预算全部投在权重量化与 KV 压缩上，预填侧只做了最朴素的整段前向。</p>\n<p>错误在于把两个阶段的区间判断混为一谈。预填的算术强度是 <span class=\"formula\">$$I_{\\text{prefill}}\\approx\\frac{2N_{\\text{active}}S}{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}\\,S}$$</span>，分子随 $S$ 线性增长，分母中 KV 项也随 $S$ 线性增长但权重项固定，故 $I$ 随 $S$ 上升并最终撞上算力屋顶。$S=10^5$ 时该请求早已进入算力受限区，瓶颈是 Tensor Core 的 $\\pi_{\\text{peak}}$（B200 FP8 稠密约 4.5 PFLOPS），不是 HBM 带宽。此时继续压带宽对预填时延几乎无贡献，而正确手段是 chunked prefill 把长序列切块与解码请求交错、以及并行切分把单请求摊到多卡。</p>\n<p>后果是可量化的：预填请求独占 SM 长时间运行，阻塞同批次解码请求，TTFT 与 TPOT 同时恶化；而权重量化带来的带宽收益在算力受限的预填段被 $\\pi_{\\text{peak}}$ 截断，投入产出比极低。识别信号是预填阶段 SM 的 Tensor Core 利用率接近饱和、HBM 带宽利用率反而有余量——这与解码段的信号正好相反。修正路径：先用 $I_{\\text{prefill}}$ 与拐点 $\\pi_{\\text{peak}}/\\beta_{\\text{HBM}}$ 比较，确认落在算力受限区，再把优化预算从量化转向 chunked prefill 与并行切分；量化预算留给真正带宽受限的解码通道。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-33\">三十三 · 识别清单：三个判据与一条纪律</h3>\n<p>把上述误用收敛成可操作的判据。判据一，看区间：先用 $I$ 与 $\\pi_{\\text{peak}}/\\beta$ 的拐点比较，确认工作负载落在带宽受限还是算力受限，再决定优化方向；跨阶段的混合负载必须分段判断，不能用一个 $I$ 覆盖预填与解码。判据二，看分母：检查字节项是否与部署形态一致——稠密单卡用 HBM 字节，MoE 专家并行必须加入跨卡交换字节并把 $\\beta$ 换成互联有效带宽；量化后必须用实测有效带宽与量化后字节重算。判据三，看窗口：batch=1 且序列极短时，先估固定开销占比，若与 $t_{\\text{roof}}$ 同量级则 roofline 只作方向判断。</p>\n<p>一条纪律贯穿全部：这个公式给出的是上界，任何写进容量规划与 SLO 的数字都必须经过实测修正项。上界的价值在于排序——告诉你先压带宽还是先加算力、先做量化还是先做切分——而不在于给出可承诺的绝对值。把上界当承诺，就是把排序工具误用成了预测工具，这正是三类误用的共同根源。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-34\">三十四 · 误用解剖：把上界当承诺、把单卡带宽当互联带宽、把量化当线性加速</h3>\n\n<p>第一种误用最普遍：把 <span class=\"formula\">$$\\text{Attainable}=\\min\\left(\\pi_{\\text{peak}},\\;\\frac{\\beta_{\\text{HBM}}}{I}\\right)$$</span> 算出的数值直接抄进 SLO 文档，当作可交付的吞吐。这个式子的本质是<strong>上界</strong>，它假设权重与 KV 全部从 HBM 读取且没有任何片上复用，也完全没有刻画 kernel launch、调度、框架 Python 开销与批组装延迟。在代码补全的单行场景里，batch=1、序列极短，每步真实耗时被固定开销主导——一次解码 step 的 wall time 可能数倍于纯带宽搬运时间，roofline 给出的数字在纸面上漂亮，落到线上却兑现不了。识别方法很直接：把实测 step latency 与 <span class=\"formula\">$$\\frac{2N_{\\text{active}}+2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}}{\\beta_{\\text{HBM}}}$$</span> 的比值画出来，若小 batch 区间比值显著大于 1 且随 batch 增大而收敛，就说明你处在固定开销区而非带宽区，此时该做的是合并 step、放大 batch 或上 CUDA Graph，而不是继续压权重字节。</p>\n\n<p>第二种误用出现在 MoE 与专家并行部署中：容量规划仍沿用单卡 HBM 带宽 <span class=\"formula\">$$\\beta_{\\text{HBM}}$$</span>（B200 约 8 TB/s）代入分母，却忘了专家并行后每个 token 的激活参数 <span class=\"formula\">$$N_{\\text{active}}$$</span> 随路由变化，且专家权重分散在多卡，跨卡 all-to-all 的互联带宽才是真正的瓶颈项。此时正确的分母应替换为互联带宽而非 HBM 带宽，否则算出的可达性能会系统性高估，上线后 all-to-all 排队把 TPOT 拖垮。识别信号是：单卡 profile 显示带宽利用率不高，但端到端吞吐上不去，且 NCCL/all-to-all kernel 占用显著——这就是带宽项写错了位置。</p>\n\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>上界当实测吞吐</td><td>SLO 承诺无法兑现</td><td>小 batch 下实测/理论比值远大于 1</td></tr><tr><td>MoE 沿用单卡 HBM 带宽</td><td>容量规划严重高估</td><td>all-to-all kernel 占比高、HBM 利用率低</td></tr><tr><td>量化后不重算 I 与 β</td><td>把 FP8/INT4 当等比例加速</td><td>量化后实测提升远小于字节缩减比例</td></tr></tbody></table>\n\n<p>第三种误用最隐蔽：权重量化到 FP8 或 INT4 后，仍拿原始 <span class=\"formula\">$$I$$</span> 与 <span class=\"formula\">$$\\beta_{\\text{HBM}}$$</span> 代回公式，得出“字节减半、吞吐翻倍”的线性结论。实际上量化改变了有效字节数与有效带宽利用率，<span class=\"formula\">$$I$$</span> 必须按量化后的权重字节重算，而 <span class=\"formula\">$$\\beta_{\\text{HBM}}$$</span> 的有效值还受反量化开销、KV 仍为高精度、以及 SMEM 分块驻留带来的片上复用影响——公式给出的只是上界，不是实测值。一个具体反例：某代码补全服务把权重压到 FP8 后按公式预期吞吐翻倍，实际只提升有限，因为解码阶段的 KV 读取字节并未缩减，分母里的 KV 项 <span class=\"formula\">$$2L\\,d_{\\text{kv}}\\,n_{\\text{kv}}$$</span> 在长上下文下占比上升，权重缩减的收益被稀释；同时反量化在 SM 上引入额外指令，进一步吃掉带宽红利。工程判断应落在：量化收益要用“量化后字节占比”而非“权重压缩比”来估算，先确认分母中权重项是否仍是主导项，再决定是否值得投入量化管线。</p>\n\n<h3 id=\"th-roofline-code-decode-sec-35\">三十五 · 误用三连：上界当实测、单卡带宽套 MoE、量化后不重算 I</h3>\n<p>最普遍的误用是把 <span class=\"formula\">$$\\text{Attainable}=\\min\\left(\\pi_{\\text{peak}},\\;\\frac{\\beta_{\\text{HBM}}}{I}\\right)$$</span> 算出的值直接写进 SLO 承诺。这个式子描述的是稳态下带宽与算力两条屋顶的较小者，它不含 kernel launch、调度、框架 Python 开销与批内气泡。代码补全的单行场景恰恰是固定开销主导的区间：batch=1、序列极短，每 token 的 HBM 搬运量小到无法摊薄一次前向的启动成本，实测时延显著高于 roofline 预测。识别方法很直接——把实测 tokens/s 与 <span class=\"formula\">$$\\beta_{\\text{HBM}}/B_{\\text{per-token}}$$</span> 的上界并排看，若实测只有上界的很小一部分且随 batch 增大而迅速抬升，说明瓶颈在固定开销而非带宽，此时该做的是合批与减少 launch 次数，而不是继续压权重字节。</p>\n<p>第二个反例出现在 MoE 专家并行部署：工程师沿用单卡 HBM 带宽 β 代入公式，得到一条漂亮的带宽屋顶，却忽略了路由后专家权重分散在多卡、每个 token 需经 all-to-all 交换激活。此时分母中的字节项不再是本地 HBM 流量，而应替换为互联带宽项，屋顶整体下移。容量规划若按单卡 β 估算，会严重高估可承载的并发与吞吐。识别信号是：实测吞吐对 batch 不敏感、却对 EP 并行度与 NVLink 拓扑敏感，且 all-to-all kernel 占据可观时间比例——这就是带宽项写错了位置。</p>\n<p>第三个误用是权重量化后不重算算术强度。FP8/INT4 把权重字节减半或再减半，分母变小、I 上升，屋顶从带宽侧向算力侧移动；但有效 β 与真实可达算力也随之变化，收益绝非等比例。把 FP8 的字节缩减直接换算成吞吐翻倍，是把上界当成了线性缩放。正确做法是按量化后的有效字节重算 I，再取 min，并对照实测确认是否真的越过了屋顶切换点。下表给出三种误用的判别特征。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>判别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>上界当实测</td><td>batch=1 实测远低于上界，随 batch 抬升</td><td>低延迟 SLO 无法兑现</td></tr><tr><td>单卡 β 套 MoE</td><td>吞吐对 EP 度与拓扑敏感</td><td>容量规划高估、显存与互联预算错配</td></tr><tr><td>量化后不重算 I</td><td>实测未随字节缩减线性提升</td><td>误判屋顶区间，优化方向跑偏</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\pi_{\\text{peak}}</td><td>GPU 峰值算力（如 B200 FP8 稠密约 4.5 PFLOPS，SM100 双 die 合计）</td></tr><tr><td>\\beta_{\\text{HBM}}</td><td>HBM3e 有效带宽（B200 约 8 TB/s，GB200 NVL72 单 GPU 同量级）</td></tr><tr><td>I</td><td>算术强度，单位 FLOP/Byte</td></tr><tr><td>N_{\\text{active}}</td><td>每 token 参与计算的激活参数量</td></tr><tr><td>L</td><td>Transformer 层数</td></tr><tr><td>d_{\\text{kv}}</td><td>每层 KV 头维度（head_dim × kv_heads）</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-roofline-code-decode · 共 5 个片段</p>\n"},{"id":"th-kv-cache-capacity","title":"KV Cache 显存与并发容量","direction":"dir-spec-decode-code","prereq":[],"plain":"KV cache 字节数等于 2×层数×KV头数×头维×序列长×批大小×每元素字节；仓库级长上下文下它迅速超过权重显存，成为并发上限的唯一约束，分页与 GQA/MQA 是把这个乘积压下去的两把刀。","definition":"KV cache 字节数等于 2×层数×KV头数×头维×序列长×批大小×每元素字节；仓库级长上下文下它迅速超过权重显存，成为并发上限的唯一约束，分页与 GQA/MQA 是把这个乘积压下去的两把刀。","formula":"$$M_{\\text{KV}}=2\\,L\\,n_{\\text{kv}}\\,d_{\\text{h}}\\,S\\,B\\,\\frac{b}{8},\\qquad B_{\\max}=\\left\\lfloor\\frac{M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}}{M_{\\text{KV}}(S)}\right\\rfloor$$","variables":[{"sym":"M_{\\text{KV}}","meaning":"单请求 KV cache 显存占用（字节）"},{"sym":"L","meaning":"层数"},{"sym":"n_{\\text{kv}}","meaning":"KV 头数"},{"sym":"d_{\\text{h}}","meaning":"每头维度"},{"sym":"S","meaning":"上下文长度（含前缀缓存命中的共享部分）"},{"sym":"B","meaning":"并发批大小"},{"sym":"b","meaning":"KV 元素位宽（FP16=16，FP8=8，INT4=4）"},{"sym":"M_{\\text{GPU}}","meaning":"单卡可用显存（B200 为 192 GB HBM3e）"}],"derivation":"并发上界 $$B_{\\max}=\\left\\lfloor\\frac{M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}}{M_{\\text{KV}}(S)}\\right\\rfloor$$ 中 $M_{\\text{GPU}}$ 为单卡可用显存（B200 为 192 GB HBM3e），分子扣除权重与激活后剩余空间除以单请求 KV 占用，即为理论最大并发批。","example":"适用边界是 KV 无压缩、无跨请求共享的独占情形；失效条件包括前缀缓存命中时实际占用按共享前缀折算，公式给出最坏独占上界；分页分配（PagedAttention）存在块内碎片与预留块开销，$B_{\\max}$ 需乘以有效利用率 $\\eta$（典型 0.9 左右）否则高估并发；未计入 CUDA Graph、通信缓冲、临时 workspace 与框架元数据；NVL72 多卡 TP 时每卡只存 $1/TP$ 的 KV 但需额外通信缓冲。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设 KV 无压缩、无跨请求共享；前缀缓存命中时实际占用按共享前缀折算，公式给出的是最坏独占情形","分页分配（PagedAttention）下存在块内碎片与预留块开销，B_max 需乘以有效利用率 η（典型 0.9 左右），否则高估并发","未计入 CUDA Graph、通信缓冲、临时 workspace 与框架元数据；NVL72 多卡 TP 时每卡只存 1/TP 的 KV，但需额外通信缓冲"],"system_note":"在容量决策中，该公式用于反推给定 $S$ 与目标并发下的最小显存需求，或给定显存反推可支撑的上下文长度；工程上先按 $\\eta\\approx0.9$ 折算再留出权重与 workspace 余量，可避免上线后因碎片与元数据导致并发骤降。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["KV cache 字节数等于 $2\\times$ 层数 $\\times$ KV 头数 $\\times$ 头维 $\\times$ 序列长 $\\times$ 批大小 $\\times$ 每元素字节；仓库级长上下文下它迅速超过权重显存，成为并发上限的唯一约束。","公式 $$M_{\\text{KV}}=2\\,L\\,n_{\\text{kv}}\\,d_{\\text{h}}\\,S\\,B\\,\\frac{b}{8}$$ 中系数 2 对应 K 与 V 两份张量，$L$ 为层数，$n_{\\text{kv}}$ 为 KV 头数，$d_{\\text{h}}$ 为每头维度，$S$ 为上下文长度（含前缀缓存命中的共享部分），$B$ 为并发批大小，$b$ 为 KV 元素位宽（FP16=16，FP8=8，INT4=4）。","并发上界 $$B_{\\max}=\\left\\lfloor\\frac{M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}}{M_{\\text{KV}}(S)}\\right\\rfloor$$ 中 $M_{\\text{GPU}}$ 为单卡可用显存（B200 为 192 GB HBM3e），分子扣除权重与激活后剩余空间除以单请求 KV 占用，即为理论最大并发批。","推导的关键一步是把 KV 占用写成与 $S$ 和 $B$ 的乘积成正比：$S$ 从数千涨到 $10^5$ 量级时 KV 项线性膨胀，而权重显存固定，因此长上下文场景下 $B_{\\max}$ 由 KV 而非权重决定；GQA/MQA 通过缩小 $n_{\\text{kv}}$ 直接压低该乘积。","适用边界是 KV 无压缩、无跨请求共享的独占情形；失效条件包括前缀缓存命中时实际占用按共享前缀折算，公式给出最坏独占上界；分页分配（PagedAttention）存在块内碎片与预留块开销，$B_{\\max}$ 需乘以有效利用率 $\\eta$（典型 0.9 左右）否则高估并发；未计入 CUDA Graph、通信缓冲、临时 workspace 与框架元数据；NVL72 多卡 TP 时每卡只存 $1/TP$ 的 KV 但需额外通信缓冲。","在容量决策中，该公式用于反推给定 $S$ 与目标并发下的最小显存需求，或给定显存反推可支撑的上下文长度；工程上先按 $\\eta\\approx0.9$ 折算再留出权重与 workspace 余量，可避免上线后因碎片与元数据导致并发骤降。","常见误用是直接用 $M_{\\text{GPU}}$ 减权重后除以 $M_{\\text{KV}}$ 得到并发数而不乘利用率 $\\eta$，上线后因分页碎片与预留块使实际并发低于规划；另一误用是前缀缓存命中时仍按独占 KV 计费，导致容量被严重高估；还有误用是忽略 TP 分片后每卡 KV 缩小但通信缓冲增加的事实。"],"anchors":["192 GB","0.9","10^5"],"pitfalls":["不乘分页有效利用率 η 直接算并发，上线后块内碎片与预留块使实际并发低于规划值。","前缀缓存命中时仍按独占 KV 计费，容量被高估，长上下文仓库场景下并发承诺无法兑现。","忽略 CUDA Graph、通信缓冲与临时 workspace，显存预算被权重与 KV 吃满后触发 OOM 或被迫降批。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-1\">一 · 一句话直觉：KV cache 是“按 token 计费的显存”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-2\">二 · 严格定义：从张量形状到字节数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-3\">三 · 为什么需要它：没有 KV cache 的解码代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-4\">四 · 常见误解之一：拿总算力除，不乘分页利用率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-5\">五 · 常见误解之二：前缀命中仍按独占计费，以及漏项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-6\">六 · KV 容量公式的适用边界：它算的是什么，不算什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-7\">七 · 容量公式的适用边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-8\">八 · 系数 2 与位宽项：字节数从哪来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-9\">九 · 推导关键步：从单 token 到批上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-10\">十 · 离散化与近似：三处必须打折的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-11\">十一 · 反推与预算：公式在容量决策中的两种用法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-12\">十二 · 误用清单与判断准则</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-13\">十三 · 公式的失效边界：从最坏独占上界到可兑现并发</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-14\">十四 · 公式成立所需的三个隐含假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-15\">十五 · 前缀缓存命中：$\\alpha$ 让公式从最坏界变成保守界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-16\">十六 · 分页与碎片：$\\eta$ 与预留块把上界打折</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-17\">十七 · 被公式漏掉的显存项：CUDA Graph、通信缓冲与 workspace</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-18\">十八 · 规模上限：TP 分片改变的是分母，不是问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-19\">十九 · 公式在什么条件下不再成立：η、共享前缀与隐藏显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-20\">二十 · 把容量公式变成可执行的预算表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-21\">二十一 · 由 SLO 反推批大小与并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-22\">二十二 · KV 预算的分档与预留策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-23\">二十三 · 失效条件的量化修正与上线校验</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-24\">二十四 · 容量决策的联动：位宽、GQA 与分离式部署</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-25\">二十五 · 误用一：把 $B_{\\max}$ 当成算术除法，跳过分页有效利用率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-26\">二十六 · 误用二：前缀缓存命中仍按独占 KV 计费</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-27\">二十七 · 误用三：忽略 CUDA Graph、通信缓冲与临时 workspace</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-28\">二十八 · 反例：一次仓库级代码助手的并发规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-29\">二十九 · 误用的共同结构：把上界当承诺</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-30\">三十 · 误用与反例：把 B_max 当承诺值时，最先崩的是哪一条假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-kv-cache-capacity-sec-31\">三十一 · 并发上界的三笔漏账：η、前缀共享与框架常驻</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:574px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 573.8 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"491.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"491.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：KV cache 字节数等于 2×层数×KV头数×头维×序列长×批…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"491.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$M_{\\text{KV}}=2\\,L\\,n_{\\text{kv…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"491.8\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设 KV 无压缩、无跨请求共享；前缀缓存命中时实际占用按共享前缀…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-kv-cache-capacity-sec-1\">一 · 一句话直觉：KV cache 是“按 token 计费的显存”</h3>\n<p>把自回归解码想成一条不断变长的账本：每生成一个 token，模型都要回看此前所有 token 的 Key 与 Value，而这两份张量一旦算过就不再改变，于是被留在显存里复用。KV cache 的本质就是这笔“历史账”：它不随权重变化，只随“看多长”和“同时看多少人”线性增长。一句话直觉可以写成——<strong>KV cache 的显存开销，等于层数、KV 头数、头维、上下文长度、并发批大小与元素位宽六者的乘积再乘 2</strong>。这个乘积里没有任何一项会因为“模型已经加载完了”而停止增长，所以它是推理系统里唯一一个随负载而非随模型固定的显存项。</p>\n<p>与之对照，权重显存是一次性买断的固定资产：模型确定，权重字节数就确定。KV cache 则是流式账单：上下文从数千涨到 $10^5$ 量级时，账单按同一比例膨胀。工程直觉因此非常直接——短上下文时你几乎感觉不到 KV 的存在，长上下文时它不是“一部分开销”，而是决定你能同时服务几个请求的那道墙。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-2\">二 · 严格定义：从张量形状到字节数</h3>\n<p>严格地说，KV cache 是每一层、每一个 KV 头上缓存的 Key 张量与 Value 张量，形状为 $[S, d_h]$，按批维堆叠后为 $[B, S, n_{\\text{kv}}, d_h]$。系数 2 对应 K 与 V 两份张量，$L$ 为层数，$n_{\\text{kv}}$ 为 KV 头数（GQA/MQA 下小于注意力头数），$d_h$ 为每头维度，$S$ 为上下文长度（含前缀缓存命中的共享部分），$B$ 为并发批大小，$b$ 为 KV 元素位宽。写成字节数：</p>\n<div class=\"formula\">$$M_{\\text{KV}}=2\\,L\\,n_{\\text{kv}}\\,d_{\\text{h}}\\,S\\,B\\,\\frac{b}{8},\\qquad B_{\\max}=\\left\\lfloor\\frac{M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}}{M_{\\text{KV}}(S)}\\right\\rfloor$$</div>\n<p>第二个式子把容量问题变成一次除法：分子是单卡可用显存（B200 为 192 GB HBM3e）扣掉权重与激活后的剩余空间，分母是单请求在长度 $S$ 下的 KV 占用，商向下取整即理论最大并发批。定义的关键不在公式本身，而在“$S$ 与 $B$ 以乘积形式出现”这一结构：权重项固定，KV 项线性，于是存在一个交叉点，越过它之后 $B_{\\max}$ 完全由 KV 而非权重决定。仓库级长上下文正是越过该交叉点的典型场景。</p>\n<p>定义里还有一处容易被忽略：$S$ 是“含前缀缓存命中的共享部分”的逻辑长度，而不是物理独占字节。逻辑长度决定注意力要读多少历史，物理字节决定显存要放多少副本——两者在前缀共享时分叉，这正是后面所有容量误判的源头。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-3\">三 · 为什么需要它：没有 KV cache 的解码代价</h3>\n<p>若不留缓存，每生成一个 token 都要把整段历史重新做一遍 K/V 投影，计算量随 $S$ 线性重做，解码从“读一遍缓存”退化为“算一遍前缀”。解码阶段的 roofline 由带宽界主导（该界在别处展开），而重算前缀会把本已受限于 HBM 带宽的步骤再叠上一层矩阵乘，延迟随上下文长度近似线性上升。KV cache 用显存换掉了这部分重算：一次投影、多次读取，把解码的每步代价压到“按 $S$ 读一遍 KV”的量级。</p>\n<p>代价也随之转移。以 B200 的 192 GB 为例，权重与激活占去一部分后，剩余空间全部由 $M_{\\text{KV}}(S)$ 切分。设某模型在 $S=10^5$ 时单请求 KV 占用已达到数十 GB 量级，则剩余空间只够容纳个位数并发——此时系统的吞吐上限不是算力，而是显存里能塞下几份账本。工程上的判断因此变成：<em>你要么缩短 $S$，要么压低每个 token 的字节数，要么让多个请求共享同一段前缀</em>。GQA/MQA 缩小 $n_{\\text{kv}}$、FP8/INT4 压低 $b$、前缀缓存摊薄 $S$ 的独占部分，这三把刀砍的都是同一个乘积。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-4\">四 · 常见误解之一：拿总算力除，不乘分页利用率</h3>\n<p>最常见的误用是直接用 $M_{\\text{GPU}}$ 减权重再除以 $M_{\\text{KV}}$ 得到并发数，而不乘有效利用率 $\\eta$。分页分配（PagedAttention）以块为单位管理 KV，块内存在碎片，运行时还要预留块以应对生成长度不确定，因此物理占用高于逻辑字节。工程上先按 $\\eta\\approx0.9$ 折算，再留出权重与 workspace 余量，才能避免上线后并发骤降。</p>\n<p>这个误解的代价是可观测的：规划时算出 32 路并发，上线后因块内碎片与预留块只能稳定跑在二十几路，SLO 里的尾延迟指标随之漂移。它不是公式错了，而是公式给的是“逻辑字节的上界”，而调度器管理的是“物理块的下界”。把 $\\eta$ 写进容量表，比事后调参便宜得多。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-5\">五 · 常见误解之二：前缀命中仍按独占计费，以及漏项</h3>\n<p>第二类误解发生在前缀缓存命中时仍按独占 KV 计费。仓库级长上下文场景中，大量请求共享同一段系统提示或代码库前缀，实际占用应按共享前缀折算，而 $M_{\\text{KV}}$ 给出的是最坏独占情形。若把最坏情形当作常态去承诺并发，容量会被严重高估，长上下文仓库场景下的并发承诺无法兑现。正确做法是把 $S$ 拆成“共享前缀 + 独占后缀”，只对独占部分计费，共享部分按引用计数摊薄。</p>\n<p>第三类误解是漏项。公式未计入 CUDA Graph、通信缓冲、临时 workspace 与框架元数据；NVL72 多卡 TP 时每卡只存 $1/TP$ 的 KV，但需额外通信缓冲。显存预算被权重与 KV 吃满后，这些漏项会直接触发 OOM 或迫使系统降批。一个具体的工程动作是：在容量表里为每卡固定扣除一块 workspace 与通信缓冲额度，再用剩余空间跑 $B_{\\max}$，而不是把 $M_{\\text{GPU}}$ 全额当作可用分母。</p>\n<table class=\"mini\"><thead><tr><th>误解</th><th>机制后果</th><th>工程动作</th></tr></thead><tbody><tr><td>不乘 $\\eta$</td><td>块内碎片与预留块使实际并发低于规划</td><td>按 $\\eta\\approx0.9$ 折算后再留余量</td></tr><tr><td>前缀命中按独占计费</td><td>容量被高估，长上下文并发承诺落空</td><td>$S$ 拆共享/独占，只计独占部分</td></tr><tr><td>漏算 Graph/通信/workspace</td><td>预算吃满后 OOM 或被迫降批</td><td>每卡固定扣除缓冲额度再算 $B_{\\max}$</td></tr></tbody></table>\n<p>这三类误解共享一个根源：把 $M_{\\text{KV}}$ 当成“实际占用”而不是“最坏独占上界”。公式的适用边界是 KV 无压缩、无跨请求共享的独占情形；一旦进入分页、前缀共享、多卡 TP 的真实系统，就必须在公式外面套一层折算。容量决策中，该公式的正当用法是反推：给定 $S$ 与目标并发求最小显存，或给定显存反推可支撑的上下文长度——反推时把 $\\eta$、共享前缀、通信缓冲逐项写进不等式，得到的才是可上线的数，而不是纸面上的乐观上界。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-6\">六 · KV 容量公式的适用边界：它算的是什么，不算什么</h3>\n<p>把 KV 显存写成 $M_{\\text{KV}}=2\\,L\\,n_{\\text{kv}}\\,d_{\\text{h}}\\,S\\,B\\,b/8$ 之后，工程上真正容易出错的不是乘法本身，而是对这个乘积的语义归属判断。该式描述的是“每个请求独占全部上下文、KV 不做任何压缩、不做跨请求共享”的最坏情形上界，因此它天然是一个容量规划用的保守估计器，而不是运行时实际占用的测量值。一旦系统启用了前缀缓存（prefix caching），多个请求共享同一段系统提示或仓库级公共前缀，实际占用应按共享前缀折算，公式给出的数字会显著高于真实值；反过来，如果运维拿这个上界去承诺并发，长上下文仓库场景下就会出现“账面容量够、实测并发不够”的落差。所以第一件要建立的直觉是：公式是分母，不是账本。</p>\n<p>第二个边界来自分配器。分页分配（PagedAttention）把 KV 切成固定大小的块，按需分配给序列，块内最后一个未填满的块存在内部碎片，调度器还要为即将增长的序列预留块，这两项都会让有效容量低于理论值。工程上用一个有效利用率 $\\eta$ 折算，典型取 0.9 左右，于是并发上界应写成 $B_{\\max}=\\lfloor \\eta\\,(M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}})/M_{\\text{KV}}(S)\\rfloor$。这个 $\\eta$ 不是常数，它随块大小、序列长度分布、请求到达的突发性变化：块越大碎片越少但预留越粗，序列长度越参差碎片越多。把 $\\eta$ 当固定值写进容量表是可行的工程近似，但必须在上线后用实际块占用率回校，否则规划值与实测值会持续偏离。</p>\n<p>第三个边界是公式没有计入的显存项。CUDA Graph 捕获的静态缓冲、TP/EP 通信缓冲、临时 workspace、框架元数据（调度器状态、采样缓冲、tokenizer 与 detokenizer 的中间张量）都不在分子扣除项里。这些项在短上下文、大批量场景下占比小，但在长上下文、高 TP 度场景下会明显侵蚀可用空间。以 B200 的 192 GB HBM3e 为例，权重与激活扣完之后剩下的空间看似充裕，但若按 NVL72 做多卡 TP，每卡只存 $1/TP$ 的 KV，通信缓冲却随 TP 度上升而增加，净收益小于线性缩放。容量决策时应先按 $\\eta\\approx0.9$ 折算，再从剩余空间里硬性划出一块 workspace 余量，而不是把扣除权重后的全部余量都当作 KV 预算。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>公式给出的量</th><th>实际偏差来源</th><th>工程动作</th></tr></thead><tbody><tr><td>独占、无前缀共享</td><td>最坏上界</td><td>无（保守）</td><td>可直接用于容量下限</td></tr><tr><td>前缀缓存高命中</td><td>高估占用</td><td>共享前缀未折算</td><td>按命中率折算后再算并发</td></tr><tr><td>分页分配</td><td>高估并发</td><td>块内碎片、预留块</td><td>乘 $\\eta$，上线后回校</td></tr><tr><td>多卡 TP</td><td>每卡 KV 缩小</td><td>通信缓冲、workspace 增加</td><td>单独预留余量，不并入 KV 预算</td></tr></tbody></table>\n<p>由此可以给出一个明确的失效判据：当 $S$ 进入 $10^5$ 量级、$n_{\\text{kv}}$ 未通过 GQA/MQA 压缩、且系统未启用前缀缓存时，$M_{\\text{KV}}(S)$ 会迅速超过权重显存，此时 $B_{\\max}$ 完全由 KV 项决定，公式的保守性恰好是优点——它给出的是不可逾越的上界。反之，当命中率高、序列短、块利用率高时，公式的保守性变成规划误差的主要来源，此时应改用“按共享前缀折算 + $\\eta$ 修正”的实用式，并把 CUDA Graph 与通信缓冲作为独立扣减项单列，而不是继续挤在同一个分子里。真正决定容量表可信度的，是这三项修正是否被显式建模，而不是公式本身写得多漂亮。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-7\">七 · 容量公式的适用边界与失效条件</h3>\n<p>本节的公式不是“算完就能上线”的容量承诺，而是一个<strong>最坏独占上界</strong>。它成立的前提是三条隐含假设：KV 不做任何压缩、请求之间不共享任何前缀、显存分配没有碎片。三条中任意一条被打破，$B_{\\max}$ 就从“可兑现的并发”退化为“理论上限”。最典型的破法是前缀缓存命中：仓库级长上下文场景里，多个请求共享同一份代码库或文档前缀，实际 KV 占用应按共享前缀折算，而公式按每请求独占整段 $S$ 计费，于是容量被系统性高估。此时正确的做法是把 $S$ 拆成独占段 $S_{\\text{own}}$ 与共享段 $S_{\\text{shared}}$，共享段只计一次，公式退化为对独占部分的求和，而非 $B$ 倍的线性膨胀。</p>\n<p>第二个边界是分页分配带来的有效利用率 $\\eta$。PagedAttention 以块为单位分配，块内未填满的尾部、为后续增长预留的块、以及块表元数据都吃显存，因此真实的并发上界应为</p>\n<div class=\"formula\">$$B_{\\max}^{\\text{eff}}=\\left\\lfloor \\eta\\cdot\\frac{M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}-M_{\\text{other}}}{M_{\\text{KV}}(S)}\\right\\rfloor,\\quad \\eta\\approx 0.9$$</div>\n<p>其中 $M_{\\text{other}}$ 显式扣除 CUDA Graph 捕获的静态缓冲、TP 通信缓冲与临时 workspace。工程上最危险的误用正是跳过 $\\eta$ 与 $M_{\\text{other}}$：直接拿 192 GB 减去权重再除以单请求 KV，规划出一个漂亮的并发数，上线后块内碎片与预留块立刻把实际并发压到规划值以下，表现为“显存明明还有余量却拒绝新请求”。</p>\n<p>第三个边界来自并行切分。NVL72 上做 TP 时，每卡只存 $1/TP$ 的 KV，公式里的 $M_{\\text{KV}}$ 要按卡折算，但每卡同时多出通信缓冲与 all-reduce 的 workspace，且 TP 越大，单卡可用于 KV 的净显存越被这些固定开销侵蚀。判断标准很直接：当 $M_{\\text{weights}}+M_{\\text{act}}+M_{\\text{other}}$ 已接近 $M_{\\text{GPU}}$ 时，公式的分子趋近于零，此时瓶颈不再是 KV 而是权重与固定开销，扩容 TP 反而可能因通信缓冲增加而降低有效并发。反过来，当 $S$ 进入 $10^5$ 量级、$M_{\\text{KV}}(S)$ 远超权重时，公式才真正成为并发上限的唯一约束，GQA/MQA 缩小 $n_{\\text{kv}}$ 的收益也才按比例兑现。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>被打破时</th><th>对 $B_{\\max}$ 的影响</th></tr></thead><tbody><tr><td>无跨请求共享</td><td>前缀缓存命中</td><td>高估，需按共享前缀折算</td></tr><tr><td>无分配碎片</td><td>PagedAttention 块内碎片与预留块</td><td>高估，须乘 $\\eta\\approx0.9$</td></tr><tr><td>仅权重与 KV 占显存</td><td>CUDA Graph、通信缓冲、workspace</td><td>高估，分子需扣 $M_{\\text{other}}$</td></tr></tbody></table>\n<h3 id=\"th-kv-cache-capacity-sec-8\">八 · 系数 2 与位宽项：字节数从哪来</h3>\n<p>公式的骨架是六个因子的连乘，先把每个因子的物理来源钉死，后面的推导才不会飘。系数 2 不是经验常数，而是 K 与 V 两份张量在层内成对出现：每一层在自注意力里既缓存 key 也缓存 value，二者形状完全相同，因此层数每加一，KV 占用就加两份而非一份。$n_{\\text{kv}}$ 与 $d_{\\text{h}}$ 的乘积是每层每 token 的 KV 元素个数，注意这里用的是 KV 头数而非查询头数——GQA 把多个查询头映射到同一组 KV 头，正是靠缩小这个因子来压乘积，MQA 则把它压到 1。$S$ 是上下文长度，包含前缀缓存命中的共享部分，这一点在推导时要特别小心，因为它决定了公式算的是“独占最坏情形”还是“实际折算占用”。</p>\n<p>位宽项 $b/8$ 是把元素个数换算成字节的桥。FP16 时 $b=16$，每元素 2 字节；FP8 时 $b=8$，每元素 1 字节；INT4 时 $b=4$，每元素半字节。这一项是离散的，不存在“7.5 位”这种中间态，因此量化对 KV 容量的影响是阶跃式的：从 FP16 切到 FP8，$M_{\\text{KV}}$ 直接减半，$B_{\\max}$ 直接翻倍，没有平滑过渡。工程含义很直接——在 B200 的 192 GB HBM3e 上，若权重与激活占去大头，把 KV 从 FP16 降到 FP8 是把并发从个位数拉到两位数最省事的一刀，代价是数值精度，而这属于量化误差条目的话题，此处只指路。</p>\n<p>把因子写成乘积形式后，一个容易被忽略的推论是：$M_{\\text{KV}}$ 对 $S$ 和 $B$ 是双线性的。也就是说，给定显存预算，$S$ 与 $B$ 的可行域是一条双曲线 $S\\cdot B \\le \\text{const}$，而不是各自独立的两个上限。这解释了为什么长上下文与高并发在容量上天然互斥：把 $S$ 从数千推到 $10^5$ 量级，$B$ 必须按同样比例缩水才能守住同一块显存。</p>\n<div class=\"formula\">$$M_{\\text{KV}}=2\\,L\\,n_{\\text{kv}}\\,d_{\\text{h}}\\,S\\,B\\,\\frac{b}{8}$$</div>\n\n<h3 id=\"th-kv-cache-capacity-sec-9\">九 · 推导关键步：从单 token 到批上界</h3>\n<p>推导的第一步是“单请求单 token”的粒度。每层每 token 的 KV 字节数为 $2\\,n_{\\text{kv}}\\,d_{\\text{h}}\\,b/8$，乘以层数 $L$ 得到单 token 全模型 KV 字节数，再乘以序列长 $S$ 得到单请求占用。这一步没有任何近似，是精确的计数。第二步才是关键：把单请求占用乘以批大小 $B$，得到批级总占用。这一步隐含了一个强假设——每个请求的 KV 完全独立、互不共享，这正是公式的适用边界，也是后面所有失效条件的根源。</p>\n<p>第三步是容量约束的建立。单卡可用显存 $M_{\\text{GPU}}$ 要同时容纳权重 $M_{\\text{weights}}$、激活与临时缓冲 $M_{\\text{act}}$、以及 KV。把 KV 项移到不等式一侧，得到 $B \\le (M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}})/M_{\\text{KV}}(S)$，取整即得 $B_{\\max}$。这里的取整不是形式主义：批大小是整数，而分母随 $S$ 连续变化，因此 $B_{\\max}$ 作为 $S$ 的函数是阶梯状下降的，每跨过一个 $S$ 阈值就掉一档。工程上这意味着容量规划不能只看一个 $S$ 点，而要看目标上下文分布的上沿。</p>\n<p>第四步是长上下文下的主导项判断。权重显存 $M_{\\text{weights}}$ 与 $S$ 无关，是固定开销；而 $M_{\\text{KV}}(S)$ 随 $S$ 线性增长。当 $S$ 从数千涨到 $10^5$ 量级，KV 项膨胀约两个数量级，分子中被减去的权重项相对变得可以忽略，$B_{\\max}$ 近似反比于 $S$。这就是“长上下文下 KV 而非权重决定并发”的推导来源，也是仓库级长上下文场景中并发承诺频频落空的数学原因。伪代码层面，容量反推就是一行：给定目标 $B$ 与 $S$，最小显存需求为 $M_{\\text{weights}}+M_{\\text{act}}+B\\cdot M_{\\text{KV}}(S)$，再按利用率折算。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-10\">十 · 离散化与近似：三处必须打折的地方</h3>\n<p>公式是连续的，但显存分配是离散的，这是第一处近似。分页分配（PagedAttention）把 KV 切成固定大小的块，块内最后一个未填满的块存在内部碎片，同时调度器要为即将到达的请求预留块。这两项开销使实际可用 KV 空间小于名义值，因此 $B_{\\max}$ 必须乘以有效利用率 $\\eta$，典型取 0.9 左右。不乘 $\\eta$ 直接算并发，是上线后并发骤降最常见的来源：规划时算出 16 路并发，实际跑起来因碎片与预留只能稳定在 14 路左右。</p>\n<p>第二处近似是共享前缀的折算。公式中 $S$ 包含前缀缓存命中的共享部分，但乘法结构假设每个请求独占全部 $S$。当前缀缓存命中时，多个请求共享同一段前缀的 KV，实际占用应按共享前缀折算而非按独占计费。公式给出的是最坏独占上界，这在没有前缀复用的场景下是准确的，但在仓库级代码补全这类前缀高度重复的场景下会严重高估容量。修正方式是把 $S$ 拆成独占段与共享段，共享段只计一份，但这要求调度器能追踪前缀的引用计数，属于前缀缓存条目的机制，此处只指出公式的折算缺口。</p>\n<p>第三处近似是分子中被减去的项不完整。$M_{\\text{act}}$ 只涵盖了激活与临时 workspace 的名义值，未计入 CUDA Graph 捕获的静态缓冲、多卡 TP 的通信缓冲、以及框架元数据。这些项在单卡小批时占比不大，但在 NVL72 多卡 TP 场景下，每卡只存 $1/TP$ 的 KV，KV 项缩小了，通信缓冲的相对占比反而上升，分子的扣除项必须相应放大。忽略这些项的直接后果是显存预算被权重与 KV 吃满后触发 OOM，或被迫临时降批，表现为尾延迟尖刺。</p>\n<table class=\"mini\"><thead><tr><th>近似来源</th><th>偏差方向</th><th>工程修正</th></tr></thead><tbody><tr><td>分页块内碎片与预留块</td><td>高估并发</td><td>乘 $\\eta\\approx0.9$</td></tr><tr><td>前缀缓存共享未折算</td><td>高估容量</td><td>共享段只计一份</td></tr><tr><td>CUDA Graph/通信缓冲/元数据</td><td>高估可用显存</td><td>放大 $M_{\\text{act}}$ 扣除项</td></tr></tbody></table>\n\n<h3 id=\"th-kv-cache-capacity-sec-11\">十一 · 反推与预算：公式在容量决策中的两种用法</h3>\n<p>公式的工程价值在于双向可解。正向用法是给定 $S$ 与目标并发 $B$，反推最小显存需求：$M_{\\text{req}} = M_{\\text{weights}} + M_{\\text{act}} + B\\cdot M_{\\text{KV}}(S)/\\eta$。这个式子直接回答了“这张 B200 的 192 GB 能不能撑住 32K 上下文下的 8 路并发”这类问题。反向用法是给定显存反推可支撑的上下文长度：固定 $B$，解出 $S_{\\max} = \\eta\\,(M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}})/(B\\cdot 2Ln_{\\text{kv}}d_{\\text{h}}b/8)$。两种用法共享同一组因子，差别只在谁是未知数。</p>\n<p>实际预算时，顺序很重要：先按 $\\eta\\approx0.9$ 折算 KV 可用空间，再从剩余中扣权重与 workspace 余量，最后才除以单请求 KV 占用。反过来先除再打折，会把 $\\eta$ 作用到整个分子上，低估了权重项的固定性。一个具体例子：某模型权重占去相当一部分显存，$S$ 取 $10^5$ 量级时单请求 KV 占用已经可观，此时即便 $\\eta$ 只差 0.1，折算后的并发差出一路以上，对 SLO 是实质性影响。因此容量表应按 $S$ 分档列出 $B_{\\max}$，而不是给一个笼统的并发数。</p>\n<p>另一个常被忽略的维度是 TP 分片对公式的改写。NVL72 多卡 TP 时，每卡只存 $1/TP$ 的 KV，分母缩小 $TP$ 倍，看似并发能放大 $TP$ 倍，但通信缓冲随 TP 增大而增加，且 TP 组内的集合通信延迟会拉长单步时间。容量上去了，吞吐未必线性上去，这是并行与通信条目的话题。容量公式在这里的作用是给出显存侧的上界，而实际吞吐上界要由带宽与通信共同决定。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-12\">十二 · 误用清单与判断准则</h3>\n<p>三类误用值得单独列出，因为它们在生产环境中的表现各不相同。第一类是不乘 $\\eta$ 直接算并发，表现为上线初期并发达标、运行一段时间后因碎片累积与预留块竞争而掉档，尾延迟出现周期性尖刺。第二类是前缀缓存命中时仍按独占 KV 计费，表现为容量被严重高估，长上下文仓库场景下的并发承诺无法兑现，且问题随缓存命中率上升而恶化——命中率越高，高估越离谱。第三类是忽略 TP 分片后每卡 KV 缩小但通信缓冲增加的事实，表现为多卡配置下显存看似充裕却频繁 OOM。</p>\n<p>判断准则可以浓缩成一句：公式给的是上界，不是承诺。任何对外承诺的并发数都应是 $\\eta$ 折算后、扣除完整分子项、并按目标 $S$ 分布上沿计算的结果。工程上还应留出一档余量应对 CUDA Graph 捕获与框架元数据的增长，因为这些项随批大小与序列长度非线性上升。当 $S$ 进入 $10^5$ 量级，KV 项主导分母，此时任何对 $S$ 分布的误判都会被线性放大到并发上，因此容量规划的第一步不是算公式，而是拿到真实的上下文长度分布。</p>\n<p>最后落到一个具体机制上：把 $B_{\\max}$ 的计算封装成按 $S$ 分档的查表函数，输入是目标上下文分位数而非均值，输出是折算后的并发上界，并在每次调度器扩容或前缀缓存策略变更时重算。这个函数的分母里，$2Ln_{\\text{kv}}d_{\\text{h}}b/8$ 是模型常量，$\\eta$ 是运行时观测量，$S$ 是分布统计量——三者中只有 $\\eta$ 会随负载漂移，因此监控 $\\eta$ 的实测值比监控并发数本身更能提前预警容量失效。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-13\">十三 · 公式的失效边界：从最坏独占上界到可兑现并发</h3>\n<p>该公式给出的是<strong>最坏独占情形</strong>下的并发上界，而非可兑现容量。三项修正必须显式引入：其一，前缀缓存命中时实际占用按共享前缀折算，公式中的 $S$ 若仍按请求全长计费，容量被系统性高估——仓库级长上下文场景中多个请求共享同一份代码库前缀，独占计费会把并发承诺抬到无法兑现的水平。其二，分页分配（PagedAttention）存在块内碎片与预留块开销，$B_{\\max}$ 须乘以有效利用率 $\\eta$（典型 0.9 左右），否则上线后实际并发低于规划值。其三，分子扣除项不完整：CUDA Graph、通信缓冲、临时 workspace 与框架元数据均未计入，权重与 KV 吃满预算后触发 OOM 或被迫降批。修正后的形式为</p>\n<div class=\"formula\">$$B_{\\max}^{\\text{eff}}=\\left\\lfloor\\eta\\cdot\\frac{M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}-M_{\\text{meta}}}{M_{\\text{KV}}(S_{\\text{eff}})}\\right\\rfloor,\\qquad S_{\\text{eff}}=S_{\\text{own}}+\\frac{S_{\\text{shared}}}{N_{\\text{share}}}$$</div>\n<p>推导的关键近似在两处。第一处是线性化：把 KV 占用写成与 $S$ 和 $B$ 的乘积成正比，隐含假设每层每头的 KV 张量连续且无对齐填充；实际分配按块粒度取整，$S$ 非块对齐时尾部浪费随 $B$ 放大，$S$ 越小相对误差越大——短上下文高并发场景反而是碎片误差最敏感的区域。第二处是位宽离散化：$b/8$ 把 FP16、FP8、INT4 视为整字节，但 INT4 在硬件上常以打包形式存储并伴随缩放因子，每头每层的 scale 开销不随 $S$ 缩放，长上下文下可忽略、短序列高并发下不可忽略。</p>\n<p>系统代价随修正项转移。乘 $\\eta$ 直接压低可兑现并发，代价是吞吐按同比例下降；按共享前缀折算 $S_{\\text{eff}}$ 提升并发，代价是前缀缓存的查找与逐出逻辑占用 host 侧 CPU 与元数据显存，且跨请求共享引入块引用计数与生命周期管理。NVL72 多卡 TP 下每卡只存 $1/TP$ 的 KV，公式按单卡算出的 $B_{\\max}$ 看似宽裕，但通信缓冲随 TP 度与在飞请求数增长，且 all-reduce 的 workspace 与 CUDA Graph 捕获的静态缓冲是固定开销，在 $M_{\\text{GPU}}=192$ GB 的 B200 上这部分虽小，却在权重接近满载时决定是否触发 OOM。工程判断是：先按 $\\eta\\approx0.9$ 折算，再从分子中扣除固定的元数据与 workspace 余量，最后才用 $S_{\\text{eff}}$ 反推并发；给定 $S$ 与目标并发反推最小显存需求时同理，反过来给定显存反推可支撑上下文长度时，须把 $S$ 从 $10^5$ 量级回退到共享折算后的有效值，否则长上下文承诺在真实负载下无法兑现。</p>\n<table class=\"mini\"><thead><tr><th>修正项</th><th>对 $B_{\\max}$ 的方向</th><th>主要代价</th></tr></thead><tbody><tr><td>分页利用率 $\\eta$</td><td>下调</td><td>吞吐同比下降，块内碎片不可回收</td></tr><tr><td>前缀共享折算</td><td>上调</td><td>元数据显存、引用计数与逐出逻辑</td></tr><tr><td>TP 通信缓冲</td><td>下调</td><td>固定 workspace，与在飞请求数相关</td></tr></tbody></table>\n<h3 id=\"th-kv-cache-capacity-sec-14\">十四 · 公式成立所需的三个隐含假设</h3>\n<p>容量公式之所以能写成闭式，是因为它在推导时默认了三件事，而这三件事在真实推理栈里没有一件是自动成立的。第一，KV 张量是逐请求独占的：每个请求的 K/V 只属于自己，不存在任何跨请求的物理共享。第二，KV 的存储形态是稠密连续的：给定序列长 S，就占 S 个位置的字节，没有空洞、没有预留、没有对齐填充。第三，显存预算只被三样东西瓜分：权重、激活、KV。这三条假设共同构成了公式的适用域，一旦越界，$B_{\\max}$ 就不再是一个可兑现的承诺，而只是一个上界估计。</p>\n<p>把这三条写成可检验的形式更便于工程判断。设真实占用为 $M_{\\text{KV}}^{\\text{real}}=\\alpha\\cdot M_{\\text{KV}}(S)$，其中 $\\alpha$ 是共享折算系数（独占时 $\\alpha=1$，前缀全命中时 $\\alpha\\to 0$），再设分页与元数据带来的膨胀因子为 $\\beta\\ge 1$，则实际并发为</p>\n<div class=\"formula\">$$B_{\\max}^{\\text{real}}=\\left\\lfloor\\frac{\\eta\\,(M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}-M_{\\text{other}})}{\\alpha\\,M_{\\text{KV}}(S)}\\right\\rfloor$$</div>\n<p>公式原形相当于 $\\eta=1$、$\\alpha=1$、$M_{\\text{other}}=0$ 的特例。工程上真正要问的不是“公式对不对”，而是“我这套栈里 $\\eta$、$\\alpha$、$M_{\\text{other}}$ 各是多少”。三个参数里任何一个偏离 1，都会以线性方式直接改写并发上限——这正是失效条件的全部来源。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-15\">十五 · 前缀缓存命中：$\\alpha$ 让公式从最坏界变成保守界</h3>\n<p>前缀缓存（prefix caching）把多个请求共享的系统提示、仓库级代码骨架、长文档头部存成一份物理 KV，后续请求按 token 匹配复用。此时公式给出的 $M_{\\text{KV}}(S)$ 是“假如每个请求都独占整段 S”的最坏情形，而真实占用是 $\\alpha M_{\\text{KV}}(S)$，$\\alpha$ 大致等于（独占 token 数 + 共享 token 数/共享请求数）/ S。在仓库级长上下文场景里，共享前缀往往占据 S 的绝大部分，$\\alpha$ 可以低到零点几，于是公式会把并发低估数倍。</p>\n<p>低估并发听起来是安全的方向，但它带来的是另一类代价：按公式做容量规划会多买卡、多切分片，或者在同等硬件上把批大小压得远低于可行值，直接损失吞吐。更麻烦的是 $\\alpha$ 不是常数——它随请求到达顺序、前缀命中率、驱逐策略而漂移。一个缓存命中率高的时段 $\\alpha$ 小，命中率骤降时 $\\alpha$ 迅速回到 1，KV 占用在几十毫秒内翻几倍，触发驱逐风暴。因此前缀缓存场景下的正确做法不是把 $\\alpha$ 当常数代进公式，而是把公式当作“驱逐压力测试”的输入：按 $\\alpha=1$ 预留硬上限，按实测命中率做软超卖，并在命中率跌破阈值时主动降批。这里公式的价值从“算并发”转为“算最坏情况下的安全垫”。</p>\n<p>具体例子：一个代码仓库问答服务，系统提示加仓库索引前缀约 $10^5$ token 量级，用户问题只有几百 token。若按独占计，单请求 KV 就是 $S\\approx10^5$ 对应的字节数，B200 的 192 GB 在扣掉权重后能支撑的并发被压到个位数；而实际共享前缀命中后，新增占用只与问题长度成正比，真实并发可以高一个数量级。此时若仍按公式报容量，承诺的并发数会被严重低估；反过来，若运维误以为命中率永远很高而按 $\\alpha$ 很小的值规划，一旦缓存被驱逐，就会瞬间 OOM。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-16\">十六 · 分页与碎片：$\\eta$ 与预留块把上界打折</h3>\n<p>PagedAttention 把 KV 切成固定大小的块（block），按需分配、非连续存放。它解决了连续分配的外部碎片，但引入了两类新开销：块内碎片（最后一个块未填满）与预留块（为即将生成的 token 预分配的块）。序列越长、块越小，块内碎片占比越低；但并发请求数越多、每请求平均长度越短，预留块占比越高。二者合起来就是有效利用率 $\\eta$，典型在 0.9 左右，也就是说公式算出的并发要乘 0.9 才是可兑现值。</p>\n<p>$\\eta$ 的代价直接体现在吞吐上：少 10% 的并发意味着解码阶段每步少 10% 的 token 产出，而解码是带宽受限的，这部分损失无法靠提高单请求效率补回来。更隐蔽的是 $\\eta$ 随负载形态变化：长序列为主的负载块内碎片占比低，$\\eta$ 接近 1；短序列高并发负载预留块占比高，$\\eta$ 明显低于 0.9。所以固定用一个 $\\eta$ 常数做规划，在混合负载下必然出现某些时段实际并发低于规划、另一些时段又因预留块堆积而提前触发驱逐。</p>\n<p>工程上的处理是把 $\\eta$ 拆成两项分别估计：块内碎片期望约等于“平均浪费半个块 / 平均序列长度”，预留块开销约等于“每请求预留块数 × 块大小 / 平均序列 KV 字节”。两项相加得到负载相关的 $\\eta$，再代回并发公式。具体例子：块大小取 16 token、平均序列 2k token 时，块内碎片占比很小；但若服务的是大量 200 token 的短问答，块内碎片占比就上升到可观量级，此时若不乘 $\\eta$，规划并发会比实际高出十几个百分点，上线后在高峰段表现为“明明显存还有余量却开始拒绝请求”。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-17\">十七 · 被公式漏掉的显存项：CUDA Graph、通信缓冲与 workspace</h3>\n<p>公式分子只扣了权重与激活，但真实显存账本上还有几笔固定支出。CUDA Graph 捕获后需要为每个批形状保留静态的输入输出缓冲与内核参数区，批大小越多、图越多，这笔开销越大；它不随 S 缩放，却随并发档位数线性增长。通信缓冲在张量并行下必须存在：all-reduce 的输入输出暂存、NVLink 上的在途数据，都需要按最大消息尺寸预留。临时 workspace 则是 attention、GEMM 内核的临时区，通常按最大批与最长序列的乘积预留。框架元数据（块表、请求状态、采样器状态）随并发请求数线性增长，单请求开销不大，但高并发下总量可观。</p>\n<p>这些项的共同特征是“与 S 无关、与 B 有关或与批形状有关”，因此它们不会让公式在长上下文下失效，却会让公式在短上下文高并发下系统性高估。判断方法很简单：把 $M_{\\text{other}}$ 写成 $c_0+c_1 B$ 的形式，代回并发公式后解出 $B$，会发现当 $c_1$ 不可忽略时，$B_{\\max}$ 不再与可用显存成线性关系，而是被一个渐近上限封顶——即使显存无限，并发也受元数据与图缓冲的增长速度约束。具体例子：开启多档 CUDA Graph 且 TP=8 的部署，通信缓冲与图缓冲合计可能吃掉数十 GB 量级，若不从分子中扣除，公式给出的并发在权重加载后直接 OOM，表现为“按公式算明明够，一上线就炸”。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-18\">十八 · 规模上限：TP 分片改变的是分母，不是问题</h3>\n<p>NVL72 多卡张量并行时，每卡只存 $1/TP$ 的 KV，公式里的 $M_{\\text{KV}}(S)$ 要除以 TP，看起来并发随卡数线性放大。但这条推论只在“通信缓冲不随 TP 增长”时成立，而实际上通信缓冲、all-reduce workspace、NVLink 在途数据都随 TP 与批大小增长。于是每卡可用显存中可分配给 KV 的比例随 TP 上升而下降，并发放大的斜率被削平。更关键的是，TP 放大的是单卡视角的并发，而端到端吞吐还受集合通信延迟约束——这部分属于张量并行通信下界的讨论范围，此处只指出它对容量公式的修正：分母缩小 TP 倍的同时，分子要额外扣掉随 TP 增长的缓冲项。</p>\n<p>规模上限还有另一层：$S$ 到 $10^5$ 量级时，单请求 KV 已经大到让 $B_{\\max}$ 退化为个位数甚至 1。此时公式的离散性变得重要——$\\lfloor\\cdot\\rfloor$ 之下的余量可能不足以再塞进一个请求，而块粒度又要求按整块分配，实际并发可能比连续值计算少 1。在超长上下文服务里，“能不能再挤进一个请求”往往就是 SLA 的分水岭，此时应当直接用块粒度做整数规划，而不是先算连续值再取整。</p>\n<p>工程判断落在这里：容量公式是规划期的粗筛工具，不是运行期的调度依据。运行期应当以块为单位的实时账本为准，把 $\\eta$、$\\alpha$、$M_{\\text{other}}$ 都做成可观测指标随负载更新；公式则退居为“给定 S 与目标并发反推最小显存”和“给定显存反推可支撑上下文长度”的两个反解工具，并在反解时统一按 $\\eta\\approx0.9$ 折算、按 $\\alpha=1$ 预留硬上限、把 $M_{\\text{other}}$ 显式扣除。任何直接把 $M_{\\text{GPU}}$ 减权重再除以 $M_{\\text{KV}}$ 得到的并发数，都只能当作乐观上界看待。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-19\">十九 · 公式在什么条件下不再成立：η、共享前缀与隐藏显存</h3>\n<p>本节的边界不是“公式对不对”，而是“公式算的是哪一种情形”。$M_{\\text{KV}}=2Ln_{\\text{kv}}d_{\\text{h}}SB\\,b/8$ 与 $B_{\\max}=\\lfloor (M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}})/M_{\\text{KV}}(S)\\rfloor$ 描述的是<strong>独占、无压缩、无跨请求共享</strong>的 KV 布局：每个请求从第 0 个 token 到第 $S$ 个 token 都持有自己的一份 K/V。一旦系统引入前缀缓存（prefix caching），多个请求共享同一段系统提示或仓库级公共前缀，真实占用就不再是 $B\\cdot M_{\\text{KV}}(S)$，而是按“独有后缀 + 共享前缀的一份”折算。此时公式给出的不是实际占用，而是最坏独占上界——用它做容量规划会系统性低估可支撑并发，用它做准入控制则会过早拒绝请求。工程上应把 $S$ 拆成 $S_{\\text{shared}}+S_{\\text{own}}$，共享部分只计一次，再按引用计数判断何时真正释放。</p>\n<p>第二个失效点是分页分配带来的有效利用率 $\\eta$。PagedAttention 以块为单位分配，块内尾部碎片、为突发增长预留的块、以及块表元数据都吃掉显存，因此真实并发应写成 $B_{\\max}^{\\text{eff}}=\\lfloor \\eta\\cdot (M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}-M_{\\text{hidden}})/M_{\\text{KV}}(S)\\rfloor$，其中 $\\eta$ 典型在 0.9 左右。常见误用正是漏掉这一步：直接拿 $M_{\\text{GPU}}$ 减权重再除以单请求 KV，得到纸面并发，上线后块内碎片与预留块使实际并发低于规划值，表现为调度器频繁抢占（preemption）与请求排队。注意 $\\eta$ 不是常数，块尺寸越大、序列长度分布越离散，碎片占比越高；长上下文仓库场景下序列长度高度不均，$\\eta$ 的实测值会比短对话场景更差。</p>\n<p>第三个失效点是 $M_{\\text{hidden}}$ 这一项被整体忽略。分子里只扣了权重与激活，但 CUDA Graph 捕获的静态缓冲、TP/EP 通信缓冲、临时 workspace、框架元数据（块表、请求状态、采样缓冲）都常驻显存。NVL72 多卡 TP 时每卡只存 $1/TP$ 的 KV，看似宽裕，但通信缓冲随 TP 度与并发上升，抵消了分片收益；TP 度越高，单卡 KV 越小、通信缓冲占比越大，公式的分子必须显式减去它，否则高 TP 配置下 OOM 往往先于并发上限触发。一个具体判断：在 B200 的 192 GB HBM3e 上跑长上下文服务，权重与 workspace 先占去一大块，剩余空间再按 $\\eta\\approx0.9$ 折算，才是可用于 KV 的真实预算；把 $10^5$ 量级的 $S$ 代入时，$M_{\\text{KV}}(S)$ 随 $S$ 线性膨胀，$B_{\\max}$ 迅速跌到个位数，此时任何“再塞几个请求”的乐观估算都会被碎片与元数据击穿。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>失效表现</th><th>修正方式</th></tr></thead><tbody><tr><td>KV 无压缩、无共享</td><td>前缀缓存命中时容量被高估</td><td>共享前缀只计一份，按引用计数释放</td></tr><tr><td>分页无碎片</td><td>实际并发低于规划，触发抢占</td><td>乘 $\\eta\\approx0.9$，按序列长度分布实测校准</td></tr><tr><td>只扣权重与激活</td><td>CUDA Graph/通信缓冲/workspace 导致 OOM</td><td>分子显式减 $M_{\\text{hidden}}$，高 TP 时单独核算通信缓冲</td></tr></tbody></table>\n<p>规模上限还有一层来自 $S$ 与 $B$ 的乘积结构：$S$ 从数千涨到 $10^5$ 量级时 KV 项线性膨胀而权重固定，$B_{\\max}$ 由 KV 而非权重决定，这正是长上下文下并发承诺难以兑现的根源。因此容量决策应反向使用公式——给定目标并发与 $S$ 反推最小显存需求，或给定显存反推可支撑的上下文长度——并先把 $\\eta$ 与 $M_{\\text{hidden}}$ 折进去再留余量。若服务承诺的是“仓库级长上下文 + 高并发”，而实现上既未做 GQA/MQA 压缩 $n_{\\text{kv}}$、也未做前缀共享，那么公式里的乘积没有任何一项被压下去，边界就不是“接近上限”，而是从一开始就不成立。</p>\n<h3 id=\"th-kv-cache-capacity-sec-20\">二十 · 把容量公式变成可执行的预算表</h3>\n<p>容量决策的第一步不是算 $B_{\\max}$，而是把 $M_{\\text{GPU}}$ 拆成一张可核对的预算表。B200 的 192 GB HBM3e 不是全部可给 KV：权重常驻、激活峰值、CUDA Graph 捕获的静态缓冲、NCCL/NIXL 通信缓冲、框架元数据与临时 workspace 都要先扣。工程做法是把预算表写成三段：固定项（权重 + 图捕获 + 通信缓冲）、波动项（激活峰值 + workspace）、弹性项（KV 池）。弹性项才是 $B_{\\max}$ 公式里真正能用的分子，而不是 $M_{\\text{GPU}}-M_{\\text{weights}}$ 的粗减。固定项在服务启动后基本不动，波动项随批大小与序列长度变化，弹性项则按分页块粒度分配。预算表的意义在于：当线上出现 OOM 或被迫降批时，能立刻定位是固定项超了（例如图捕获吃掉了预留），还是弹性项被碎片吃掉。</p>\n<p>具体机制上，KV 池通常以固定大小的块（block）预分配，块数在启动时确定，之后不再向驱动申请。这意味着 $B_{\\max}$ 不是运行时动态算出来的，而是启动时由块数除以单请求所需块数得到的静态上限。单请求所需块数等于 $\\lceil S / S_{\\text{block}}\\rceil$，其中 $S_{\\text{block}}$ 是每块容纳的 token 数。于是并发上界可以写成块级别的形式：</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor \\frac{N_{\\text{block}}\\cdot\\eta}{\\lceil S/S_{\\text{block}}\\rceil}\\right\\rfloor,\\qquad N_{\\text{block}}=\\left\\lfloor\\frac{M_{\\text{KV,pool}}}{2\\,L\\,n_{\\text{kv}}\\,d_{\\text{h}}\\,S_{\\text{block}}\\,b/8}\\right\\rfloor$$</div>\n<p>这里 $\\eta$ 是分页有效利用率，典型 0.9 左右，吸收块内碎片与预留块开销。这个形式比直接除 $M_{\\text{KV}}(S)$ 更贴近实现：它显式暴露了 $S_{\\text{block}}$ 这个可调参数——块太小则元数据与碎片上升，块太大则短请求浪费尾部空间。系统代价上，块粒度直接决定显存浪费比例：一个请求实际占用 $\\lceil S/S_{\\text{block}}\\rceil\\cdot S_{\\text{block}}$ 个 token 的槽位，尾部浪费期望约为半个块。对 $S=10^5$ 量级的长上下文，块粒度的影响被摊薄；对短请求密集的对话场景，块粒度就是吞吐的关键旋钮。</p>\n<p>算例：设某模型 $L=80$、$n_{\\text{kv}}=8$（GQA）、$d_{\\text{h}}=128$、KV 用 FP8（$b=8$），则每 token 每请求的 KV 字节为 $2\\times80\\times8\\times128\\times1=163{,}840$ 字节，约 160 KB/token。若 $S=10^5$，单请求独占 KV 约 16 GB。B200 上扣掉权重与固定项后假设弹性池为 120 GB，则理论并发约 7；乘 $\\eta=0.9$ 后按 6 规划。若把 KV 降到 INT4（$b=4$），每 token 减半到 80 KB，单请求 8 GB，并发翻倍到 12 左右——这就是位宽作为容量杠杆的直接体现，代价是量化误差，需与精度条目联动评估。同一算例下若 $S$ 降到 $10^4$，单请求仅 1.6 GB，并发跃升到 60 以上，说明容量规划必须按目标 $S$ 分档，而不是用一个平均值。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-21\">二十一 · 由 SLO 反推批大小与并行度</h3>\n<p>容量公式给出的是“最多能放多少”，SLO 给出的是“最多该放多少”。两者取小才是可运营的批大小。解码阶段的单 token 时延由权重带宽项与 KV 带宽项共同决定：每步要读一遍权重，还要读当前批所有请求的 KV。KV 读量随 $B$ 线性增长，因此批越大，单步时延越长，但每 token 摊到的权重读摊薄，吞吐上升。这就是容量与延迟的张力：$B_{\\max}$ 是显存天花板，SLO 的 TPOT 上限则是时延天花板。工程判断是把两者画在同一张图上，取交点作为目标批大小，并留出突发余量。</p>\n<p>具体机制上，连续批处理让 $B$ 随时间波动，容量规划要用“稳态并发”而非峰值。稳态并发由到达率与平均驻留时间决定（Little 定律），而驻留时间又受 $S$ 影响：长上下文请求占用 KV 更久。于是容量决策变成一个反馈环——$S$ 越长，单请求 KV 越大，$B_{\\max}$ 越小，排队越长，驻留越久。这个环在仓库级长上下文下会自我强化，必须在准入控制处截断：对超长请求单独走低并发通道，或强制前缀缓存命中以折算占用。</p>\n<p>并行度的定法与之耦合。TP 增大时每卡只存 $1/TP$ 的 KV，$B_{\\max}$ 近似按 TP 放大，但每卡要额外承担通信缓冲，且 TP 的 all-reduce 在解码每步都发生，通信时延随 TP 上升。于是“用 TP 换并发”存在收益递减点：当 KV 已不是瓶颈时，加 TP 只增加通信开销。判断准则很直接——若 $M_{\\text{KV}}(S)\\cdot B$ 远小于弹性池，说明瓶颈在别处（权重带宽或通信），此时应优先加 DP 副本而非加 TP。反过来，若单卡 KV 已吃满弹性池而权重占比很小，加 TP 是唯一能把 $B_{\\max}$ 抬上去的手段。</p>\n<p>算例：目标 SLO 为 TPOT 不超过某阈值，实测在 $B=4$ 时单步时延有余量，$B=8$ 时接近上限，而容量公式在 $S=10^5$、FP8 下给出 $B_{\\max}\\approx6$（含 $\\eta$）。此时可运营批大小为 6，既未触显存天花板也未破时延天花板。若把 TP 从 2 提到 4，每卡 KV 减半，$B_{\\max}$ 名义翻倍到 12，但通信缓冲与 all-reduce 时延使 $B=12$ 的 TPOT 超出 SLO，实际可运营批仍停在 8 附近——这就是并行度收益被 SLO 截断的典型形态。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-22\">二十二 · KV 预算的分档与预留策略</h3>\n<p>KV 预算不应是一个数，而应是一组分档阈值。按 $S$ 分档（如短、中、长、超长四档），每档给出单请求 KV 占用与对应并发上限，服务在准入时按请求声明的最大长度归入某档并扣减该档配额。这样做的机制价值在于：避免一个超长请求把整池块占满导致其他请求饿死。分档配额的实现通常是一个令牌桶，每档独立计数，超长档配额小但优先级可调。系统代价是分档边界附近的请求可能被降级或排队，需要在路由层做长度预估，预估偏差会带来配额抖动。</p>\n<p>预留策略要区分“硬预留”与“软预留”。硬预留是启动时划走不动的块，用于保证最低并发；软预留是随负载伸缩的余量，用于吸收突发。工程上硬预留按最低 SLO 并发乘以单请求块数确定，软预留按 $\\eta$ 折算后的剩余块数动态分配。关键判断是：硬预留不能按峰值并发设，否则低峰期显存闲置；也不能按均值设，否则突发即 OOM。合理做法是按 P90 并发设硬预留，峰值靠软预留与准入排队兜底。</p>\n<p>前缀缓存命中时的折算必须进入预算逻辑。命中共享前缀的请求，其独占 KV 只算后缀部分，但共享前缀本身仍占块，且被多个请求引用。引用计数机制下，共享块的释放要等最后一个引用消失。容量公式给出的是最坏独占情形，实际占用应按“共享块 + 各请求后缀块”折算。误用在于把命中请求仍按全长计费，导致容量被严重高估；反向误用是假设命中率很高而把预算压得过紧，一旦命中率下降就集体 OOM。稳妥做法是按历史命中率的下限做预算，而不是按均值。</p>\n<p>算例：某仓库级代码服务，$S$ 常在 $10^5$ 量级，前缀（仓库骨架与系统提示）占 60%，后缀（当前文件与检索片段）占 40%。若按独占计费，单请求 16 GB、并发 6；按共享折算，共享部分约 9.6 GB 由多请求分摊，独占后缀约 6.4 GB，同样弹性池下并发可显著抬高。但预算若按高命中率设定，命中率一旦从高位回落，共享块引用数下降、独占比例上升，实际并发会骤降。因此该场景的 KV 预算应取“命中率下限”对应的折算值，并把差额留在软预留里。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-23\">二十三 · 失效条件的量化修正与上线校验</h3>\n<p>公式的四个失效条件要各自对应一个修正系数，而不是笼统乘一个 $\\eta$。分页碎片对应 $\\eta_{\\text{page}}$（典型 0.9 左右）；图捕获与通信缓冲对应固定扣减 $M_{\\text{fixed}}$；TP 分片对应每卡 KV 除以 TP 但通信缓冲乘以 TP 的修正；前缀共享对应折算系数 $\\rho$（独占比例）。合并后的可用形式是：</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor \\frac{(M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{fixed}}-M_{\\text{act}})\\cdot\\eta_{\\text{page}}\\cdot\\rho}{M_{\\text{KV}}(S)/TP}\\right\\rfloor$$</div>\n<p>注意 $M_{\\text{KV}}(S)$ 在 TP 下要除以 TP，因为每卡只存分片；而 $M_{\\text{fixed}}$ 里的通信缓冲随 TP 上升，两者方向相反，不能相互抵消着估。这个式子的用途不是求精确值，而是做敏感性分析：分别扰动 $\\eta_{\\text{page}}$、$\\rho$、$TP$，看 $B_{\\max}}$ 对哪个最敏感，就把工程精力放在哪个上。若对 $\\eta_{\\text{page}}$ 最敏感，说明块粒度与碎片是主要矛盾，应调 $S_{\\text{block}}$ 或换分配器；若对 $\\rho$ 最敏感，说明前缀缓存命中率是容量命门，应投资缓存命中优化。</p>\n<p>上线校验的做法是拿公式预测值与实测并发对比，偏差超过阈值就回查修正系数。常见偏差来源：框架元数据被低估、图捕获的静态缓冲随批大小增长、激活峰值在长上下文下被低估。校验时要分档对比，因为短请求档的碎片占比高、长请求档的共享占比高，同一组系数不可能同时拟合所有档。工程判断是每档独立标定系数，而不是全局一个 $\\eta$。</p>\n<p>算例：某服务按 $S=10^5$、FP8、TP=4 规划，公式给名义并发 24，乘 $\\eta_{\\text{page}}=0.9$ 与 $\\rho=0.7$ 后得 15。上线实测稳态并发只有 11，偏差来自图捕获缓冲被低估与激活峰值在长上下文下超出预留。回查后发现固定项少算了约一成弹性池，修正后预测降到 12，与实测接近。这个例子说明：容量公式的价值在于把偏差归因到具体项，而不是给一个漂亮数字。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-24\">二十四 · 容量决策的联动：位宽、GQA 与分离式部署</h3>\n<p>容量公式里的三个杠杆——$b$、$n_{\\text{kv}}$、$TP$——不是独立可调的，它们与精度、模型结构与部署形态联动。降 $b$ 从 FP16 到 FP8 使 KV 减半，直接翻倍 $B_{\\max}$，但量化误差会影响长上下文召回，需按精度条目的误差界评估是否可接受；再降到 INT4 又翻倍，但误差累积更明显，通常只用于对精度不敏感的后缀或草稿路径。缩 $n_{\\text{kv}}$ 靠 GQA/MQA，是结构层面的杠杆，推理侧无法改，只能在选型时计入容量模型。加 TP 是部署层面的杠杆，受通信与 SLO 截断。</p>\n<p>分离式预填/解码（PD 分离）改变了容量公式的适用对象。预填节点吃的是算力与激活，KV 在预填后要传给解码节点，传输量正比于 $S$ 与 $B$。解码节点才是 KV 常驻的地方，其 $B_{\\max}$ 按上面的公式算，但要多扣传输缓冲与 NIXL 的注册内存。PD 分离的容量收益在于：预填与解码各自按自己的瓶颈配资源，解码节点可以把显存几乎全给 KV，因为权重副本可共享或按需加载。代价是 KV 传输带宽成为新约束，长上下文下传输量可达数十 GB 量级，NVLink 5 与 RDMA 的选择直接决定这条路径是否可行。</p>\n<p>NVL72 机架级部署下，TP 跨多卡使每卡 KV 缩小，但机架内 all-to-all 与专家并行的通信缓冲要计入固定项。容量规划此时应按“每 GPU 弹性池”而非整机池来算，因为分片是每卡独立的。机架级的优势是权重可分片存放、KV 可分片扩展，劣势是任何一张卡的显存紧张都会拖累整组。工程判断是给每卡留一致的余量比例，而不是让某些卡满载、某些卡空闲。</p>\n<p>算例：同一模型在单卡 FP16 下 $S=10^5$ 单请求 KV 约 32 GB，192 GB 卡扣权重后并发个位数；改 FP8 后 16 GB，并发翻倍；再加 GQA 把 $n_{\\text{kv}}$ 从 32 降到 8，每 token KV 降到四分之一，单请求 4 GB，并发再翻两番。三个杠杆叠加的效果是数量级的，但每个都有代价：FP8 有精度代价，GQA 是选型既定，TP 有通信代价。容量决策的本质就是在这三个杠杆上按 SLO 与精度约束取折中，而不是把某一个杠杆拉满。</p>\n<p>最后落在具体机制上：把容量公式嵌进调度器的准入判断，而不是停留在规划文档里。每次准入时按请求声明的 $S$ 查分档配额、按当前 $\\rho$ 折算共享、按剩余块数决定放行或排队，并在块分配失败时触发降批而非 OOM。这套机制让 $B_{\\max}$ 从静态数字变成动态闸门，容量决策的准确性由系数标定与分档策略保证，而不是由公式本身的精度保证。</p>\n<h3 id=\"th-kv-cache-capacity-sec-25\">二十五 · 误用一：把 $B_{\\max}$ 当成算术除法，跳过分页有效利用率</h3>\n<p>最普遍的一类误用，是把并发上界公式当作纯算术题：拿单卡显存减去权重与激活，直接除以单请求 KV 字节数，得到一个整数就写进容量规划表。问题在于分母 $M_{\\text{KV}}(S)$ 是理想连续分配下的字节数，而真实运行时 KV 是按块分配的。PagedAttention 把 KV 切成固定大小的 block，每个序列的最后一个块几乎必然填不满，块内碎片随并发数线性累积；调度器还要为即将到达的请求预留块，避免解码步中途无块可分配而阻塞。这两项开销不体现在公式里，只能通过有效利用率 $\\eta$ 折算。</p>\n<div class=\"formula\">$$B_{\\max}^{\\text{eff}}=\\left\\lfloor \\eta\\cdot\\frac{M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}}{M_{\\text{KV}}(S)}\\right\\rfloor,\\qquad \\eta\\approx 0.9$$</div>\n<p>识别方法很直接：在压测中把并发从规划值逐步抬升，同时采集框架暴露的 KV 块占用率与“因无块可分配而排队”的请求计数。如果实际稳定并发明显低于 $\\lfloor(M_{\\text{GPU}}-M_{\\text{weights}})/M_{\\text{KV}}\\rfloor$，而块占用率又长期停在九成上下，就说明规划时漏掉了 $\\eta$。代价体现在两个方向：漏乘 $\\eta$ 会高估并发，上线后调度器频繁触发抢占与重算，尾延迟抬升；反过来若为保险把 $\\eta$ 压到远低于实际碎片水平，则白白浪费显存，吞吐上不去。以 B200 的 192 GB HBM3e 为例，权重与激活占去相当份额后，剩余空间除以长上下文单请求 KV 占用得到的商本就不大，少乘一个 0.9 的因子，规划并发就可能整体跨过一个调度档位，表现为上线首日即出现排队。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-26\">二十六 · 误用二：前缀缓存命中仍按独占 KV 计费</h3>\n<p>第二类误用出现在仓库级长上下文场景。多个请求共享同一段系统提示、同一份代码仓库索引或同一份文档前缀时，前缀缓存会把共享部分的 KV 只存一份，物理占用按共享前缀折算而非按请求数倍增。但很多容量表仍用每个请求的完整 $S$ 去乘 $B$，把共享前缀重复计费了 $B$ 次。公式里的 $S$ 明确写着“含前缀缓存命中的共享部分”，这句话的含义是：命中部分的边际成本接近零，只有各请求独有的后缀才按独占计。</p>\n<p>设共享前缀长度 $S_p$、各请求独有后缀长度 $S_u$，则实际 KV 占用近似为</p>\n<div class=\"formula\">$$M_{\\text{KV}}^{\\text{shared}}\\approx 2\\,L\\,n_{\\text{kv}}\\,d_{\\text{h}}\\,\\frac{b}{8}\\left(S_p+B\\cdot S_u\\right)$$</div>\n<p>与独占式 $2L n_{\\text{kv}} d_{\\text{h}} S B b/8$ 相比，差别就在 $S_p$ 是乘 1 还是乘 $B$。识别信号是缓存命中率指标：若前缀缓存的 block 命中率长期很高，而实测并发却远低于按独占公式算出的值，说明规划侧把共享前缀当成了每请求私有，容量被系统性低估；反过来，若规划按“全部命中”估算，一旦请求的前缀各不相同、命中率塌下来，实际占用会瞬间向独占式靠拢，并发承诺无法兑现。后者的后果更严重——长上下文仓库场景下 $S$ 达到 $10^5$ 量级，KV 项本就压过权重，命中率一掉，显存立刻吃紧，只能靠抢占降批兜底。工程判断是：容量表必须按“最坏独占情形”给出下限，再按实测命中率给出乐观上限，两个数都写进 SLO 文档，而不是只报一个好看的数字。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-27\">二十七 · 误用三：忽略 CUDA Graph、通信缓冲与临时 workspace</h3>\n<p>第三类误用是把分子 $M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}$ 当成干净的可用余量。实际显存账本上还挂着几笔固定开销：CUDA Graph 为捕获的解码图预留的私有内存池、张量并行与流水并行所需的通信缓冲、算子临时 workspace、框架自身的元数据与句柄。这些开销不随 $B$ 线性增长，却是一旦存在就必须扣除的常数项，在小 batch 或短上下文时占比尤其刺眼。</p>\n<p>把常数项记为 $M_{\\text{fix}}$，修正后的并发上界为</p>\n<div class=\"formula\">$$B_{\\max}=\\left\\lfloor \\eta\\cdot\\frac{M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}-M_{\\text{fix}}}{M_{\\text{KV}}(S)}\\right\\rfloor$$</div>\n<p>识别方式是做显存对账：在空载、单请求、满并发三个状态下分别读取框架与驱动报告的已分配显存，把差值拆成随 $B$ 变化的部分和不变的部分。若不变部分显著大于预期，多半是 CUDA Graph 池与通信缓冲被漏算。后果是显存预算被权重与 KV 吃满后，剩余空间不足以容纳一次图捕获或一次集合通信，触发 OOM 或被迫降批，表现为“压测能过、上线抖动”。在 NVL72 多卡 TP 部署下这条尤其容易踩：每卡只存 $1/TP$ 的 KV，看起来余量宽裕，但通信缓冲随 TP 度数与消息尺寸上升，漏算这笔常数项会让每卡的可用余量被高估。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-28\">二十八 · 反例：一次仓库级代码助手的并发规划</h3>\n<p>设想一个部署在单台 B200 上的仓库级代码助手，上下文长度按 $10^5$ 量级规划，权重常驻，激活按峰值预留。规划者用独占公式算出单请求 KV 占用，再用 192 GB 减去权重与激活，得到一个可观的并发数，直接写进容量承诺。上线后出现三个症状：其一，稳定并发只有规划值的八成上下，块占用率长期贴着高位，调度器偶发抢占；其二，当多个请求共享同一份仓库索引前缀时，实际显存占用远低于规划值，说明容量被低估、机器没吃满；其三，开启 CUDA Graph 后，原本“够用”的余量突然不够，个别卡出现 OOM。</p>\n<p>三个症状分别对应三处误用：漏乘 $\\eta$ 导致高估并发、按独占计费导致共享场景下低估容量、漏算图池与通信缓冲导致余量被吃穿。修正做法是把容量表拆成三栏——最坏独占下限（乘 $\\eta$、扣 $M_{\\text{fix}}$）、按实测命中率的乐观上限、以及两者之间的调度缓冲带；调度器据此设定抢占阈值，而不是拿单一数字硬扛。这个反例的价值在于说明：KV 容量公式的每一处简化都对应一个可观测的运行时信号，误用的识别不靠猜，靠把公式里的假设逐条与压测指标对齐。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-29\">二十九 · 误用的共同结构：把上界当承诺</h3>\n<p>三类误用共享同一个认识论错误：把公式给出的上界当成可兑现的承诺。$B_{\\max}$ 是在“KV 无压缩、无跨请求共享、分页无碎片、无框架开销”这一组假设下成立的数学上界，它的用途是给出容量决策的起点与反推显存需求的锚，而不是 SLA 里的并发数字。工程上正确的用法是双向校准：先用公式给出理论区间，再用压测把 $\\eta$、命中率、$M_{\\text{fix}}$ 三个修正项实测出来，回填成部署配置里的常数。任何一次模型换代、上下文长度调整、TP 度数变化，都会让这三个常数漂移，容量表必须随之重算。</p>\n<p>识别误用的通用手法是构造“假设违背实验”：故意让前缀缓存失效、故意把并发推到公式边界、故意开启图捕获，观察实际并发与显存占用的偏离方向。偏离方向告诉你哪一条假设被违背得最厉害，也就告诉你容量表里哪一栏需要收紧。KV 显存是长上下文推理里唯一随 $S$ 与 $B$ 双线性膨胀的项，权重固定、激活有界，因此容量规划的重心永远落在 KV 这一侧；把公式的假设逐条钉死在监控指标上，比把公式算得更精细更有价值。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-30\">三十 · 误用与反例：把 B_max 当承诺值时，最先崩的是哪一条假设</h3>\n\n<p>最常见的误用不是公式写错，而是把 $B_{\\max}$ 当成可对外承诺的并发数。工程上真正致命的一步，是拿 $M_{\\text{GPU}}$ 减掉权重后直接除以 $M_{\\text{KV}}$，既不乘分页有效利用率 $\\eta$，也不扣 CUDA Graph、通信缓冲与临时 workspace。B200 的 192 GB HBM3e 看着宽裕，但权重在长上下文仓库场景下往往只占一小块，剩下的大头全被 KV 吃掉；一旦按理论值排容量，分页分配（PagedAttention）的块内碎片与预留块会立刻把可用块数压到规划线以下。识别方法很直接：把线上实际 running batch 与规划 $B_{\\max}$ 做比值，若长期稳定低于 $\\eta\\approx0.9$ 且随序列长度上升而恶化，基本可判定是漏乘利用率、漏扣元数据，而不是调度器不够激进。代价体现在延迟尾部——为凑够规划并发而强行塞批，单卡 HBM 带宽被 KV 读写挤占，decode 的 ITL 抖动放大，SLO 先于 OOM 破裂。</p>\n\n<p>第二个反例更隐蔽：前缀缓存命中时仍按独占 KV 计费。多轮对话与仓库级长上下文里，共享前缀可能占序列的绝大部分，$S$ 中真正独占的只是增量部分；若容量模型仍用整段 $S$ 乘 $B$，等于把共享前缀重复计了 $B$ 次，容量被系统性高估。识别信号是缓存命中率很高、但显存占用曲线并不随命中率下降——说明计费口径与真实占用脱节。正确做法是把 $M_{\\text{KV}}$ 拆成共享前缀折算项与独占增量项，公式给出的是最坏独占上界，只能当保守天花板用，不能当期望值用。系统代价是承诺无法兑现：长上下文仓库场景下对外宣称的并发，在缓存未命中冷启动时瞬间跌回独占口径，表现为首请求排队、TTFT 飙升。</p>\n\n<p>第三个误用出在张量并行上。NVL72 多卡 TP 时每卡只存 $1/TP$ 的 KV，看似把 $B_{\\max}$ 放大了 TP 倍，但每卡还要额外承担通信缓冲，且 TP 组内 collective 的同步开销随批增大而上升。只按 $1/TP$ 缩小分母、不补通信缓冲，等于把省下的显存又悄悄花掉，最终在 all-reduce 峰值时触发 OOM 或被迫降批。识别方法是看显存峰值是否出现在通信阶段而非计算阶段——若是，问题不在 KV 公式本身，而在预算表漏项。下表给出同一 $S$、同一显存下三种口径的偏差方向，用于自查：</p>\n\n<table class=\"mini\">\n<thead><tr><th>计费口径</th><th>相对真实占用</th><th>后果</th></tr></thead>\n<tbody>\n<tr><td>独占 KV、不乘 η</td><td>高估并发</td><td>碎片与预留块使实际并发低于规划</td></tr>\n<tr><td>前缀命中仍按整段 S 计</td><td>严重高估容量</td><td>冷启动时并发承诺无法兑现</td></tr>\n<tr><td>TP 只缩 1/TP、不补通信缓冲</td><td>低估单卡峰值</td><td>通信阶段 OOM 或被迫降批</td></tr>\n</tbody>\n</table>\n\n<p>把这三类误用统一起来看，根因是同一个：$B_{\\max}$ 是在“无压缩、无共享、无框架开销”的假设下推出来的上界，任何一条假设被现实打破，它就从规划工具退化为乐观幻觉。工程判断应落在预算表的完整性上——先按 $\\eta\\approx0.9$ 折算，再显式扣除权重、workspace、CUDA Graph 与通信缓冲，最后才用剩余空间反推 $S$ 与 $B$ 的组合；容量决策里真正该锁死的是这条扣减链，而不是那个除出来的整数。</p>\n\n<h3 id=\"th-kv-cache-capacity-sec-31\">三十一 · 并发上界的三笔漏账：η、前缀共享与框架常驻</h3>\n<p>把 $B_{\\max}$ 直接当成可售并发，是容量规划里最贵的一次偷懒。分子 $M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}$ 只扣了权重与激活，分母 $M_{\\text{KV}}(S)$ 只算了单请求的独占 KV，两头都干净得像实验室，而线上显存从来不干净。第一笔漏账是分页有效利用率 $\\eta$：PagedAttention 按块分配，序列尾块填不满、调度器为防抖预留的块、以及块表本身的元数据，都会让名义容量打折，典型 $\\eta\\approx0.9$。修正后的并发应写成 $B_{\\max}^{\\text{eff}}=\\lfloor \\eta\\,(M_{\\text{GPU}}-M_{\\text{weights}}-M_{\\text{act}}-M_{\\text{framework}})/M_{\\text{KV}}(S)\\rfloor$，其中 $M_{\\text{framework}}$ 显式扣除 CUDA Graph 捕获缓冲、TP 通信缓冲与临时 workspace。以 B200 的 192 GB HBM3e 为例，权重与框架常驻先吃掉一大块，剩下给 KV 的空间再乘 0.9，规划值与实测值的差距往往就来自这一步没做。</p>\n<p>第二笔漏账是前缀缓存。仓库级长上下文场景里，同一份代码库或系统提示被大量请求共享，命中前缀的 KV 只应计一次，按独占口径计费会把容量严重高估——$S$ 里含共享部分，但共享部分不该乘以 $B$。正确做法是把 $M_{\\text{KV}}$ 拆成独占段与共享段分别累加，共享段按前缀树的实际驻留块计。反例很具体：一个代码补全服务，系统提示加仓库索引共 $10^5$ 量级 token，命中率很高，团队按独占公式算出可支撑的并发并对外承诺；上线后共享前缀的块被反复引用却无法按独占口径释放，加上尾块碎片，实际可调度并发远低于承诺，长上下文请求开始排队甚至触发抢占重算。</p>\n<p>第三笔漏账在 TP 方向。NVL72 多卡张量并行时每卡只存 $1/TP$ 的 KV，看起来分母缩小、并发翻倍，但每卡同时要背通信缓冲，且 TP 组内必须按最紧的那张卡对齐，木桶效应让“每卡富余”无法兑现。识别这类误用的办法很直接：把规划表里的 $B_{\\max}$ 与线上监控的活跃序列数、KV 块占用率、抢占次数三条曲线对齐，若块占用率长期贴着上限而活跃序列数上不去，就是 $\\eta$ 与碎片在收税；若前缀命中率高的时段显存不降反升，就是共享计费口径错了；若 TP 组内各卡显存方差明显，就是通信缓冲没进预算。工程判断只有一句：先按 $\\eta$ 折算、再把框架常驻与前缀共享显式建模，最后才拿这个数去谈 SLO。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>M_{\\text{KV}}</td><td>单请求 KV cache 显存占用（字节）</td></tr><tr><td>L</td><td>层数</td></tr><tr><td>n_{\\text{kv}}</td><td>KV 头数</td></tr><tr><td>d_{\\text{h}}</td><td>每头维度</td></tr><tr><td>S</td><td>上下文长度（含前缀缓存命中的共享部分）</td></tr><tr><td>B</td><td>并发批大小</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-kv-cache-capacity · 共 5 个片段</p>\n"},{"id":"th-batch-latency-slo","title":"连续批调度时延模型","direction":"dir-retrieval-repo","prereq":[],"plain":"代码补全的 TTFT 与 TPOT 由预填计算量、解码步数与批内排队共同决定；连续批处理把解码步摊薄到多请求，但每步都要重读全部 KV，因此批越大单步越慢，存在一个让 p99 时延最优的批上界。","definition":"代码补全的 TTFT 与 TPOT 由预填计算量、解码步数与批内排队共同决定；连续批处理把解码步摊薄到多请求，但每步都要重读全部 KV，因此批越大单步越慢，存在一个让 p99 时延最优的批上界。","formula":"$$\\text{TTFT}\\approx\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}+\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}+\\tau_{\\text{queue}},\\qquad \\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}},\\qquad B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$","variables":[{"sym":"S_{\\text{in}}","meaning":"输入（预填）token 数，仓库级上下文可达 10^5"},{"sym":"T_{\\text{out}}","meaning":"输出 token 数（代码补全通常 32–256）"},{"sym":"\\pi_{\\text{eff}}","meaning":"预填阶段有效算力（受 MMA 利用率与 attention 非线性影响）"},{"sym":"\\beta_{\\text{eff}}","meaning":"解码阶段有效带宽"},{"sym":"\\tau_{\\text{queue}}","meaning":"调度排队时延"},{"sym":"B^{*}","meaning":"使 p99 端到端时延最小的批大小"}],"derivation":"解码步时延 $$\\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$ 表明每步要重读批内全部 KV 与权重，$B$ 越大分子越大，故批增大摊薄了每请求的固定开销却抬高了单步时间，二者权衡决定最优批。","example":"推导的关键一步是把端到端时延写成 TTFT 加输出步数乘 TPOT 的线性叠加，再对 $B$ 求极小：$B$ 增大使排队项下降但 TPOT 项上升，交点即为最优批；p99 需用 M/G/1 或仿真求得，因为 $\\tau_{\\text{queue}}$ 依赖到达过程（泊松或突发）。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["线性叠加假设忽略预填与解码在同一 SM 上的争抢；chunked prefill 下二者交织，实际 TTFT 与 TPOT 存在耦合，需实测校准","τ_queue 依赖到达过程（泊松或突发），公式只给单请求路径时延，不含排队论尾部分布；p99 需用 M/G/1 或仿真求得","假设解码每步重读全 KV；若采用 KV 分块驻留或 prefix 复用命中，TPOT 的带宽项显著下降，B* 会上移"],"system_note":"适用边界是线性叠加假设，失效条件包括忽略预填与解码在同一 SM 上的争抢；chunked prefill 下二者交织，实际 TTFT 与 TPOT 存在耦合需实测校准；公式只给单请求路径时延不含排队论尾部分布；假设解码每步重读全 KV，若采用 KV 分块驻留或 prefix 复用命中则 TPOT 带宽项显著下降、$B^{*}$ 会上移。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["代码补全的 TTFT 与 TPOT 由预填计算量、解码步数与批内排队共同决定；连续批处理把解码步摊薄到多请求，但每步都要重读全部 KV，因此批越大单步越慢，存在一个让 p99 时延最优的批上界。","公式 $$\\text{TTFT}\\approx\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}+\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}+\\tau_{\\text{queue}}$$ 中第一项是预填算力时间（$S_{\\text{in}}$ 为输入 token 数，仓库级可达 $10^5$），第二项是预填 KV 写入带宽时间，$\\tau_{\\text{queue}}$ 为调度排队时延。","解码步时延 $$\\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$ 表明每步要重读批内全部 KV 与权重，$B$ 越大分子越大，故批增大摊薄了每请求的固定开销却抬高了单步时间，二者权衡决定最优批。","最优批 $$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$ 中 $T_{\\text{out}}$ 为输出 token 数（代码补全通常 32–256），$\\pi_{\\text{eff}}$ 为预填有效算力（受 MMA 利用率与 attention 非线性影响），$\\beta_{\\text{eff}}$ 为解码有效带宽；$B^{*}$ 需按 p99 而非均值求解。","推导的关键一步是把端到端时延写成 TTFT 加输出步数乘 TPOT 的线性叠加，再对 $B$ 求极小：$B$ 增大使排队项下降但 TPOT 项上升，交点即为最优批；p99 需用 M/G/1 或仿真求得，因为 $\\tau_{\\text{queue}}$ 依赖到达过程（泊松或突发）。","适用边界是线性叠加假设，失效条件包括忽略预填与解码在同一 SM 上的争抢；chunked prefill 下二者交织，实际 TTFT 与 TPOT 存在耦合需实测校准；公式只给单请求路径时延不含排队论尾部分布；假设解码每步重读全 KV，若采用 KV 分块驻留或 prefix 复用命中则 TPOT 带宽项显著下降、$B^{*}$ 会上移。","在推理性能决策中，该模型用于设定代码补全的批上界与 SLO：低延迟补全（$T_{\\text{out}}$ 32–256）应取较小 $B$ 保 p99，仓库级长上下文预填则应配合 chunked prefill 把 TTFT 的算力项与带宽项解耦，避免预填阻塞解码。","常见误用是只用均值时延调参而忽略 p99 尾部，导致突发到达下 SLO 违约；另一误用是在 chunked prefill 部署中仍按线性叠加估算 TTFT，忽略预填与解码争抢 SM 造成的耦合；还有误用是 prefix 复用命中后未下调 TPOT 带宽项，把 $B^{*}$ 定得过低浪费吞吐。"],"anchors":["32–256","10^5"],"pitfalls":["只按均值时延调批大小而忽略 p99 尾部，突发到达下排队时延击穿补全 SLO。","chunked prefill 部署中仍用线性叠加估 TTFT，忽略预填与解码争抢 SM 的耦合，实测与预测偏差大。","prefix 复用命中后未下调 TPOT 带宽项，B* 定得过低，吞吐被无谓牺牲。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-1\">一 · 一句话直觉与它到底在算什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-2\">二 · 为什么需要这个模型：三个决策它必须回答</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-3\">三 · 常见误解之一：把均值当目标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-4\">四 · 常见误解之二：线性叠加在 chunked prefill 下失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-5\">五 · 常见误解之三：prefix 复用命中后仍用旧 B*</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-6\">六 · 定义里必须写死的适用边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-7\">七 · 批上界不是容量上限：线性叠加模型的适用边界与三类失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-8\">八 · 批上界的边界：模型在哪里失效，代价落在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-9\">九 · 预填项的两块时间：算力主导与带宽尾巴</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-10\">十 · 解码项的分子结构：$B$ 为什么抬高单步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-11\">十一 · 线性叠加在哪一步成立、在哪一步破裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-12\">十二 · 对 $B$ 求极小的结构：为什么是 p99 而不是均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-13\">十三 · 边界条件下的项重估：prefix 命中与 KV 驻留</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-14\">十四 · 公式的适用边界：线性叠加在哪里断裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-15\">十五 · 批上界 B* 的适用边界：线性叠加在哪里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-16\">十六 · 线性叠加假设的成立条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-17\">十七 · chunked prefill 下的耦合失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-18\">十八 · 排队项与尾部分布：公式只给路径时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-19\">十九 · 每步重读全 KV 的假设与驻留优化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-20\">二十 · 规模上限：批大小与上下文长度的双重天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-21\">二十一 · 失效条件的工程清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-22\">二十二 · 边界在哪里：线性叠加假设的失效条件与规模上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-23\">二十三 · 从公式到决策变量：把 B 当作唯一可控旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-24\">二十四 · 定批大小：按 p99 求 B*，而不是按均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-25\">二十五 · 定并行度：N_active 与 B 的耦合约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-26\">二十六 · 定 KV 预算：把约束写进 B 的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-27\">二十七 · 定 SLO 与算例：反解可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-28\">二十八 · 三个必须校准的输入项与误用防线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-29\">二十九 · 批上界、并行度与 KV 预算：模型能定什么、定不了什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-30\">三十 · 误用一：用均值时延调批，把 p99 交给运气</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-31\">三十一 · 误用二：chunked prefill 下仍按线性叠加估 TTFT</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-32\">三十二 · 误用三：prefix 复用命中后不下调 TPOT 带宽项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-33\">三十三 · 反例：一次把 B* 定错的完整推演</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-34\">三十四 · 把误用变成检查项：上线前的四个对照</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-35\">三十五 · 批上界的三类误用：均值陷阱、叠加幻觉与复用失算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-slo-sec-36\">三十六 · 误用诊断：从均值陷阱到耦合盲区</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:527px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 527.0 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：代码补全的 TTFT 与 TPOT 由预填计算量、解码步数与批内排…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\text{TTFT}\\approx\\frac{2N_{\\te…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"445.0\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：线性叠加假设忽略预填与解码在同一 SM 上的争抢；chunked …</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-batch-latency-slo-sec-1\">一 · 一句话直觉与它到底在算什么</h3>\n<p>连续批调度的时延模型，一句话：<strong>把一次请求的端到端时延拆成“预填一次 + 解码 T<sub>out</sub> 次”，每次解码都要重读批内全部 KV 与权重，于是批越大单步越慢、但每请求摊到的固定开销越小，两条曲线交叉处就是 p99 时延最优的批上界 B<sup>*</sup>。</strong>这句话里藏着三个可被工程检验的断言：时延可加、批摊薄固定开销、存在极小点。本片段只做一件事——把这句直觉翻译成可写进容量规划文档的严格定义，并划清它不适用的边界。</p>\n<p>严格定义如下。设请求到达后进入调度器的等待队列，其端到端时延为</p>\n<div class=\"formula\">$$L = \\text{TTFT} + T_{\\text{out}}\\cdot\\text{TPOT}$$</div>\n<p>其中 TTFT 是首 token 时延，TPOT 是相邻输出 token 的平均间隔（time per output token）。模型进一步把两项展开为</p>\n<div class=\"formula\">$$\\text{TTFT}\\approx\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}+\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}+\\tau_{\\text{queue}},\\qquad \\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</div>\n<p>第一项是预填的算力时间（系数 2 对应前向两次矩阵乘的量级，S<sub>in</sub> 为输入 token 数，仓库级上下文可达 10<sup>5</sup>），第二项是预填阶段把 KV 写进显存的带宽时间，τ<sub>queue</sub> 是调度排队时延。TPOT 的分子是“批内全部 KV + 权重”的字节数，B 越大分子越大。于是目标函数写成</p>\n<div class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$</div>\n<p>注意这里求的是 p99 而非均值——这是定义的一部分，不是修辞。B<sup>*</sup> 是一个<strong>统计量上的极小点</strong>，不是解析式上的驻点，因为 τ<sub>queue</sub> 的尾部分布由到达过程决定，闭式解通常不存在。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-2\">二 · 为什么需要这个模型：三个决策它必须回答</h3>\n<p>没有这个模型，工程上只能靠“调大 batch 提吞吐、调小 batch 保时延”的口号拍脑袋。有了它，三个具体决策才有依据。</p>\n<ul>\n<li><strong>批上界。</strong>代码补全的 T<sub>out</sub> 通常只有 32–256，端到端时延里 TTFT 占比高、TPOT 累计项相对小，因此 B 不能照搬离线吞吐场景的大批。模型给出的 B<sup>*</sup> 直接写进调度器的 max_num_seqs 上限。</li>\n<li><strong>预填与解码的解耦。</strong>仓库级上下文 S<sub>in</sub> 达 10<sup>5</sup> 时，TTFT 第一项随 S<sub>in</sub> 线性膨胀；若不做 chunked prefill，一次长预填会把整批解码卡住，TPOT 出现尖刺。模型把算力项与带宽项分开写，正是为了判断“该切块还是该排队”。</li>\n<li><strong>SLO 反推容量。</strong>给定 p99 TTFT 与 p99 TPOT 的 SLO，模型可反推单副本能承载的并发与到达率上限，这是容量规划里唯一能写成不等式的部分。</li>\n</ul>\n<p>代价必须说清楚：解这个模型要跑仿真或 M/G/1 近似，本身有计算成本；更重要的是，模型里的 π<sub>eff</sub> 与 β<sub>eff</sub> 是<strong>实测标定值</strong>，受 MMA 利用率与 attention 非线性影响，换精度（NVFP4 与 FP8）、换并行切分都要重标。举例：同一张 B200 上，FP8 与 NVFP4 的 β<sub>eff</sub> 不同，若沿用旧标定值算出的 B<sup>*</sup>，批上界会系统性偏移，表现为 p99 时延在压测中稳定超标而均值正常——这正是尾部被忽略的典型症状。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-3\">三 · 常见误解之一：把均值当目标</h3>\n<p>最常见的误用是只用均值时延调参。均值意义上的最优批往往远大于 p99 意义上的最优批，因为均值对尾部不敏感。突发到达（而非泊松）时，τ<sub>queue</sub> 的尾部被拉长，均值仍好看，p99 已经击穿补全 SLO。工程判断很直接：<strong>调度器的批上限应当由 p99 目标函数决定，均值只用于容量估算的粗筛。</strong>求解 p99 需要 M/G/1 近似或离散事件仿真，把到达过程的方差作为输入，而不是假设泊松。</p>\n<p>代价体现在两个方向：批定得过大，尾请求排队时间击穿 SLO；批定得过小，GPU 利用率与吞吐被无谓牺牲。二者都不是“调参手感”问题，而是目标函数选错。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-4\">四 · 常见误解之二：线性叠加在 chunked prefill 下失效</h3>\n<p>公式把 TTFT 与 TPOT 写成互不相干的两项，前提是预填与解码不在同一 SM 上争抢。chunked prefill 部署恰恰打破这个前提：预填块与解码步交织在同一批里，预填吃算力、解码吃带宽，二者在同一 SM 上交替，实际 TTFT 与 TPOT 存在耦合。此时仍按线性叠加估算 TTFT，预测与实测偏差会很大。</p>\n<p>具体机制：一个 chunk 的预填插入解码批后，该步的 TPOT 分子里多了 chunk 的激活与 KV 写入，单步时间被抬高；反过来，解码批占用 SM 也稀释了预填的 π<sub>eff</sub>。因此 chunked prefill 下必须<strong>实测校准</strong>，把耦合项作为修正因子写进模型，而不是继续用两项相加。代价是标定工作量增加，收益是长上下文场景下 TTFT 尖刺被削平——仓库级 10<sup>5</sup> token 的预填若不分块，解码批会被整段阻塞，TPOT 尾部直接失控。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-5\">五 · 常见误解之三：prefix 复用命中后仍用旧 B<sup>*</sup></h3>\n<p>TPOT 公式假设解码每步重读全部 KV。若采用 KV 分块驻留或 prefix 复用命中，被复用的前缀 KV 不再每步从显存重读，TPOT 的带宽项显著下降。此时若仍按未命中时的标定值求 B<sup>*</sup>，批上界定得过低，吞吐被白白牺牲。</p>\n<p>机制上，prefix 命中把 M<sub>KV</sub>(S) 中命中部分从分子里扣掉，等价于降低了单步的 β 压力，最优批随之上移。工程判断：<strong>B<sup>*</sup> 必须按“命中率分层”分别求解</strong>——高命中率的补全流量可以用更大批，低命中率的长上下文请求维持小批，调度器按请求的 prefix 命中状态路由到不同批池。代价是调度逻辑复杂度上升与批池碎片化，收益是同一副本上吞吐与时延同时改善。若不做分层而统一取小批，等于用吞吐换一个并不存在的时延收益。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-6\">六 · 定义里必须写死的适用边界</h3>\n<p>把边界写进定义，模型才可被审计。四条：其一，线性叠加假设忽略预填与解码在同一 SM 上的争抢，chunked prefill 下需实测校准；其二，公式只给单请求路径时延，不含排队论尾部分布，p99 须由 M/G/1 或仿真求得；其三，假设解码每步重读全 KV，KV 分块驻留或 prefix 复用命中会显著下调 TPOT 带宽项并使 B<sup>*</sup> 上移；其四，τ<sub>queue</sub> 依赖到达过程，泊松与突发的尾部分布形状不同，同一 B<sup>*</sup> 不可跨流量模式复用。</p>\n<p>一个具体例子收束：代码补全副本上，T<sub>out</sub> 取 128、S<sub>in</sub> 为常规函数上下文时，B<sup>*</sup> 由 TPOT 项主导，批上限偏小；同一副本若接入仓库级 10<sup>5</sup> token 的检索增强请求，TTFT 算力项主导，必须切 chunked prefill 并单独标定耦合因子，否则两个流量混跑时 p99 一定违约。模型的价值不在于给出一个数，而在于把“哪个流量、哪种命中状态、哪条到达过程”作为求解 B<sup>*</sup> 的必要输入写死在定义里。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-7\">七 · 批上界不是容量上限：线性叠加模型的适用边界与三类失效</h3>\n<p>把连续批调度的时延写成 TTFT 加输出步数乘 TPOT 的线性叠加，本质是一次<strong>路径分解</strong>：先假设一个请求的端到端时延等于“进入调度器到首 token”加上“每个解码步的固定成本乘以步数”，再对批大小 B 求 p99 极小值。这个分解成立的前提是预填与解码在时间上可分离、在资源上不重叠。一旦部署形态打破这两条，公式给出的 B* 就不再是可用结论，而只是一个需要校准的初值。具体地，第一项预填算力时间 $2N_{\\text{active}}S_{\\text{in}}/\\pi_{\\text{eff}}$ 随活跃请求数与输入长度线性增长，仓库级上下文 $S_{\\text{in}}$ 可达 $10^5$，这一项在长上下文补全里往往直接吃掉 TTFT 预算的大头；第二项 $M_{\\text{KV}}(S_{\\text{in}})/\\beta_{\\text{eff}}$ 是预填阶段把 KV 写入显存的带宽时间，它与算力项串行叠加的假设，在 chunked prefill 下并不成立。</p>\n<p>失效条件之一是<strong>预填与解码争抢同一组 SM</strong>。chunked prefill 把长预填切成若干块，与解码步交织在同一迭代里，此时预填的 MMA 占用会挤压解码的带宽窗口，TTFT 与 TPOT 不再是两个独立可加的项，而是通过 SM 占用率耦合。工程上的表现是：按线性模型算出的 TTFT 偏乐观，实测首 token 时延随 chunk 大小与并发解码请求数漂移。校准方法是把 $\\pi_{\\text{eff}}$ 与 $\\beta_{\\text{eff}}$ 视为随 chunk 配置变化的经验系数，用少量实测点回归，而不是当作硬件常数。失效条件之二是<strong>排队项 $\\tau_{\\text{queue}}$ 只给单请求路径时延</strong>：公式里它是一个标量，但真实到达过程是泊松或突发的，尾部分布必须用 M/G/1 近似或离散事件仿真求得，否则 p99 无从谈起。失效条件之三是<strong>解码每步重读全 KV 的假设</strong>：一旦启用 KV 分块驻留或 prefix 复用命中，TPOT 的带宽项 $M_{\\text{KV}}(S)B/\\beta_{\\text{eff}}$ 显著下降，B* 随之上移，此时仍按原公式定批上界会白白牺牲吞吐。</p>\n<p>把三类失效放在一起看，可以得到一个工程判断表：</p>\n<table class=\"mini\"><thead><tr><th>部署形态</th><th>模型哪一项失真</th><th>后果</th><th>应对</th></tr></thead><tbody><tr><td>纯连续批处理、短输入</td><td>基本可用</td><td>B* 接近实测最优</td><td>按 p99 求解即可</td></tr><tr><td>chunked prefill 交织</td><td>TTFT 算力项偏乐观</td><td>首 token SLO 违约</td><td>实测校准 $\\pi_{\\text{eff}}$，解耦预填块</td></tr><tr><td>突发到达</td><td>$\\tau_{\\text{queue}}$ 无尾部</td><td>p99 击穿补全 SLO</td><td>M/G/1 或仿真求尾部分布</td></tr><tr><td>prefix 复用命中</td><td>TPOT 带宽项偏高</td><td>B* 定得过低、吞吐浪费</td><td>下调带宽项后重解 B*</td></tr></tbody></table>\n<p>代价侧的直觉是：批越大，每请求分摊的权重读取与调度固定开销越小，但单步要重读批内全部 KV，$\\text{TPOT}\\approx(M_{\\text{KV}}(S)B+M_{\\text{weights}})/\\beta_{\\text{eff}}$ 的分子随 B 线性上升，于是单步变慢、输出 token 的交付节奏变粗。对代码补全这种 $T_{\\text{out}}$ 仅 32–256 的短输出场景，端到端时延里 TPOT 乘步数的占比不高，TTFT 与排队项才是 p99 的主导，因此低延迟补全应取较小 B 保尾部；而仓库级长上下文预填则应靠 chunked prefill 把 TTFT 的算力项与带宽项解耦，避免一次长预填把整批解码阻塞。换句话说，B* 是 SLO 的函数而非硬件的函数：同一个集群，补全流与长上下文流应使用不同的批上界，混跑时必须按流量比例加权求解 p99，而不是取一个全局常数。</p>\n<p>最常见的误用是只按均值时延调 B，均值下排队项被摊薄得很漂亮，突发到达时 $\\tau_{\\text{queue}}$ 的尾部却直接击穿补全 SLO；第二类误用是在 chunked prefill 部署里继续用线性叠加估 TTFT，预测与实测偏差大却归因于“硬件波动”；第三类误用是 prefix 复用命中后没有下调 TPOT 带宽项，把 B* 定得过低，用吞吐换来了并不存在的时延收益。判断一个批上界是否可信，看它是否同时标注了到达过程假设、是否区分了预填与解码的资源重叠、以及是否在命中复用后重新求解。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-8\">八 · 批上界的边界：模型在哪里失效，代价落在哪里</h3>\n<p>这套时延模型的价值不在给出一个可套用的 B 值，而在明确它的适用域：单请求路径时延可加、解码每步重读全 KV、预填与解码不争抢同一组 SM。三条同时成立时，<span class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$</span> 才有意义；任一条被打破，交点位置就会偏移，按公式定的批上界要么保守浪费吞吐，要么激进击穿 SLO。代码补全的 T_out 只有 32–256，端到端时延里 TTFT 占比高，因此 B 的可行区间天然偏小；仓库级上下文 S_in 可达 10^5，预填项 2N_active·S_in/π_eff 会直接吃掉大部分时延预算，此时批大小的调节余地被预填挤压。</p>\n<p>第一个失效条件是线性叠加本身。chunked prefill 把长预填切成块与解码步交织，预填的算力项与解码的带宽项在同一 SM 上争抢，TTFT 与 TPOT 不再是独立相加的两段，而是通过 SM 占用率耦合。工程上的代价是预测偏差：按叠加式估出的 TTFT 偏乐观，实际 p99 被预填块拖长，补全首字延迟超出 SLO。校准手段只能是实测扫描 chunk 大小与并发组合，把耦合项作为修正因子回填，而不是继续信任解析式。</p>\n<p>第二个失效条件是 τ_queue 的分布假设。公式只描述单请求路径时延，排队项依赖到达过程——泊松到达与突发到达的尾部行为完全不同，均值相同的两种到达在 p99 上可差出一个量级。因此 B* 必须用 M/G/1 近似或离散事件仿真求 p99，而不是对均值时延求极小。只按均值调参是典型误用：均值达标、突发时排队时延击穿补全 SLO，且这种违约在平稳流量下不可见。</p>\n<p>第三个失效条件在 KV 驻留侧。模型假设解码每步重读批内全部 KV，TPOT 分子含 M_KV(S)·B；一旦 prefix 复用命中或 KV 分块驻留生效，带宽项显著下降，TPOT 随 B 上升的斜率变缓，B* 应上移。若沿用未修正的公式，会把批上界定得过低，用吞吐换取并不存在的时延收益。下表给出三种部署形态下模型可信度的快速判断。</p>\n<table class=\"mini\"><thead><tr><th>部署形态</th><th>模型可用性</th><th>主要代价</th></tr></thead><tbody><tr><td>纯解码、无 chunked prefill、无复用</td><td>可作一阶估算，B* 需 p99 校准</td><td>均值调参导致尾部违约</td></tr><tr><td>chunked prefill 交织</td><td>线性叠加失效，需实测修正</td><td>TTFT 预测偏乐观，首字超 SLO</td></tr><tr><td>prefix 复用 / KV 分块驻留</td><td>带宽项需下调，B* 上移</td><td>批上界过低，吞吐无谓牺牲</td></tr></tbody></table>\n<h3 id=\"th-batch-latency-slo-sec-9\">九 · 预填项的两块时间：算力主导与带宽尾巴</h3>\n<p>TTFT 公式的第一项 $\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}$ 常被误读成“一个系数乘 token 数除以算力”。系数 2 来自前向两遍矩阵乘（QKV 投影与输出投影各一次 GEMM 语义），$N_{\\text{active}}$ 是当前活跃请求数——注意它不是批大小 $B$，而是“此刻真正在预填的请求数”，在 chunked prefill 下它可能远小于 $B$。$\\pi_{\\text{eff}}$ 不是峰值 FLOPS，而是扣掉 MMA 利用率与 attention 非线性开销后的有效算力：attention 的 $O(S_{\\text{in}}^2)$ 部分不走 tcgen05 的大 MMA 形状，利用率天然低于线性层，所以 $\\pi_{\\text{eff}}$ 随 $S_{\\text{in}}$ 增长而下降，这一项对长上下文是超线性的。仓库级 $S_{\\text{in}}$ 可达 $10^5$，此时算力项是绝对主项，第二项 $\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}$ 只是把刚算出的 KV 写回 HBM 的带宽尾巴，量级上通常被第一项吞掉——但它是解耦点：chunked prefill 把 $S_{\\text{in}}$ 切成块后，每块的算力项线性缩小，而 KV 写入按块摊开，二者不再串行叠加，这正是后面要讲的耦合来源。</p>\n<p>推导关键步在于把“预填”当成一个不可中断的整体。若不做 chunk，一个 $10^5$ token 的仓库级请求会把整块 SM 占满数百毫秒量级，期间所有解码步被阻塞，$\\tau_{\\text{queue}}$ 对同批其他请求爆炸。所以第一项的工程含义不是“算得快”，而是“这块算力占用能否被切片”。代价侧：预填是算力密集、功耗高的阶段，B200 上大 MMA 打满时功耗接近封装上限，而解码阶段是带宽密集、功耗低得多；同一 SM 上两种负载交替，功耗与热节流会反过来压低 $\\pi_{\\text{eff}}$，这是公式里没写但实测必须校准的项。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-10\">十 · 解码项的分子结构：$B$ 为什么抬高单步</h3>\n<p>TPOT 公式 $\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$ 的分子有两块：批内全部 KV 的重读量与权重读取量。关键在 $M_{\\text{KV}}(S)$ 里的 $S$ 是“当前序列长度”，随解码步增长，所以同一请求的 TPOT 在生成过程中是单调上升的——代码补全 $T_{\\text{out}}$ 只有 32–256，这个上升幅度有限，但仓库级上下文下 $S$ 起点就是 $10^5$，$M_{\\text{KV}}$ 基数极大，$B$ 稍微一抬分子就爆。$M_{\\text{weights}}$ 是固定项，与 $B$ 无关，这正是连续批处理的收益来源：$B$ 增大时每请求分摊的权重读取下降，摊薄效应在 $B$ 小时最明显，随 $B$ 增大边际递减。而 KV 项随 $B$ 线性增长，两条曲线一个降一个升，交点附近就是吞吐最优，但不是 p99 最优。</p>\n<p>这里有个容易漏掉的推导细节：$\\beta_{\\text{eff}}$ 不是 HBM 峰值带宽，而是解码阶段实际能达到的有效带宽。解码每步是“读权重 + 读 KV + 写一个 token 的 KV”，读占绝对主导，写可以忽略；但权重读取在 $B$ 大时会与 KV 读取争抢 HBM 通道，且 KV 的访问模式（按 head 分块、跨请求不连续）比权重的顺序流式访问效率低，所以 $\\beta_{\\text{eff}}$ 随 $B$ 增大而轻微下降。公式把它当常数是近似，真实系统里分子涨得比线性更快一点，这使 $B^{*}$ 比纯线性模型预测的更靠左。工程代价：解码阶段是纯带宽瓶颈，SM 算力大量闲置，功耗低但 HBM 通道饱和，此时再增加 $B$ 只增加时延不增加有用算力。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-11\">十一 · 线性叠加在哪一步成立、在哪一步破裂</h3>\n<p>端到端时延写成 $\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}$ 这一步，隐含假设是预填与解码在时间上串行、在资源上不重叠。非 chunk 部署下这基本成立：预填跑完才进解码。但 chunked prefill 把预填切块后，块与解码步在同一 SM 上交织，预填块会挤占解码步的带宽与算力，实际 TPOT 在预填块插入的那几步会尖峰化。公式给出的 TPOT 是“稳态解码步”的时延，不含这些尖峰，所以按公式算出的 p99 会系统性偏低。校准办法不是改公式，而是把 $\\beta_{\\text{eff}}$ 拆成“纯解码带宽”和“被预填块占用后的有效带宽”两个实测值，按 chunk 占空比加权——这是离散化近似所在：连续时间的资源争抢被压成一个平均占空比系数。</p>\n<p>第二个破裂点是 $\\tau_{\\text{queue}}$。公式把它写成单请求路径上的一个加项，但排队时延本质是分布量，不是标量。到达过程若是泊松，$\\tau_{\\text{queue}}$ 的尾部按 M/G/1 的 Pollaczek–Khinchine 形式随利用率非线性发散；若是突发到达（代码补全的真实形态：开发者连续敲键触发多次补全），尾部比泊松更重。所以 $B^{*}=\\arg\\min_B \\text{p99}(\\cdot)$ 里的 p99 不能由公式解析求出，只能靠 M/G/1 近似或离散事件仿真。离散化近似在这里体现为：把连续到达流切成调度 tick，每个 tick 内按当前 $B$ 组批，tick 粒度决定了排队时延的量化误差——tick 太粗，小请求被无谓等待；tick 太细，组批开销吃掉摊薄收益。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-12\">十二 · 对 $B$ 求极小的结构：为什么是 p99 而不是均值</h3>\n<p>把 $B$ 当连续变量看，$\\text{TTFT}$ 里的 $\\tau_{\\text{queue}}(B)$ 随 $B$ 增大而下降（批越大，单请求等待组批的时间占比越小、调度次数越少），$T_{\\text{out}}\\cdot\\text{TPOT}(B)$ 随 $B$ 增大而上升（分子线性涨）。均值意义下两者交点给出一个温和的 $B$；但 p99 意义下，$\\tau_{\\text{queue}}$ 的尾部随 $B$ 下降得更快（大 $B$ 把突发吸收进批里），而 TPOT 的尾部随 $B$ 上升得更陡（$B$ 大时任何一次 KV 重读抖动都被放大到整批）。两条尾部曲线的交点比均值交点更靠左，这就是“低延迟补全应取较小 $B$ 保 p99”的数学来源。代码补全 $T_{\\text{out}}$ 只有 32–256，TPOT 项被 $T_{\\text{out}}$ 放大得不多，所以 $B^{*}$ 主要由 TTFT 的排队尾部决定——换句话说，补全场景的批上界是排队主导，不是解码带宽主导。</p>\n<div class=\"formula\">$$\\frac{\\partial}{\\partial B}\\Big[\\text{p99}\\big(\\tau_{\\text{queue}}(B)\\big)+T_{\\text{out}}\\cdot\\text{p99}\\big(\\text{TPOT}(B)\\big)\\Big]=0$$</div>\n<p>这个隐式方程说明 $B^{*}$ 是“排队尾部下降速率”与“解码尾部上升速率”之比等于 $T_{\\text{out}}$ 的点。工程判断：$T_{\\text{out}}$ 越大（长生成任务），TPOT 项权重越高，$B^{*}$ 越靠左；$T_{\\text{out}}$ 小（补全），$B^{*}$ 可以放宽但仍受排队尾部约束。代价侧要盯住的是：$B$ 过大时 p99 TPOT 抬升会直接击穿补全 SLO，而 $B$ 过小时权重读取摊薄不足、吞吐浪费，两者都是可观测的。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-13\">十三 · 边界条件下的项重估：prefix 命中与 KV 驻留</h3>\n<p>公式假设解码每步重读全部 KV。一旦 prefix 复用命中（同一仓库文件的公共前缀被缓存），$M_{\\text{KV}}(S)$ 里被命中的部分不再需要从 HBM 重读——它们已在更快的层级或已被复用，TPOT 带宽项显著下降。此时若仍按原公式定 $B^{*}$，会把批上界定得过低，白白牺牲吞吐。同理，KV 分块驻留（把热 KV 块留在片上或近存）也压低 $\\beta_{\\text{eff}}$ 的有效分子。修正方式是在 $M_{\\text{KV}}(S)$ 上乘一个命中折扣因子，折扣因子由实测命中率给出，$B^{*}$ 随折扣增大而上移。这是“失效条件”里最容易被忽略的一条，因为命中率是运行时统计量，不是静态配置。</p>\n<p>另一个边界是预填与解码争抢 SM。非 chunk 下预填独占，公式成立；chunk 下 $\\pi_{\\text{eff}}$ 与 $\\beta_{\\text{eff}}$ 都变成占空比的函数，TTFT 的算力项与 TPOT 的带宽项通过 SM 占用率耦合。此时线性叠加给出的 TTFT 是乐观下界，实测偏差随 chunk 占空比增大。工程上应把 chunk 大小作为独立调参维度：chunk 越小，TTFT 越平滑但组批开销越高；chunk 越大，预填块对解码步的尖峰越明显。仓库级 $10^5$ 上下文下，chunk 大小直接决定 TTFT 的算力项能否被切片到与解码步同量级，这是把公式从“估算”变成“可校准模型”的关键动作。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-14\">十四 · 公式的适用边界：线性叠加在哪里断裂</h3>\n<p>把端到端时延写成 <span class=\"formula\">$$\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}$$</span> 再对批大小 <span class=\"formula\">$$B$$</span> 求极小，这个推导之所以能给出闭式直觉，全靠一个隐含前提：预填阶段与解码阶段互不干扰，各自独占一份资源。真实部署里这条前提最先断裂。预填的算力项 <span class=\"formula\">$$\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}$$</span> 与解码的带宽项 <span class=\"formula\">$$\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 争抢的是同一批 SM：当 chunked prefill 把长预填切成小块插入解码步之间，二者在同一时间片上交织，预填吃掉的 MMA 周期直接压低了解码可用的有效带宽 <span class=\"formula\">$$\\beta_{\\text{eff}}$$</span>，反过来解码驻留的 KV 又挤占了预填可用的片上容量。此时 TTFT 与 TPOT 不再是两个独立可加的项，而是通过共享的 SM 占用率耦合在一起。工程含义很直接：在 chunked prefill 部署中按线性叠加估出的 TTFT 会系统性偏乐观，实测与预测的偏差随 chunk 粒度变细而放大，必须用实测校准系数替换公式里的 <span class=\"formula\">$$\\pi_{\\text{eff}}$$</span> 与 <span class=\"formula\">$$\\beta_{\\text{eff}}$$</span>，而不是照搬静态值。</p>\n<p>第二个断裂点是 <span class=\"formula\">$$\\tau_{\\text{queue}}$$</span>。公式只描述单请求沿路径的时延，排队项被当成一个可加常数，但真实到达过程是泊松或突发——代码补全的请求往往跟着编辑节奏成簇到达，突发窗口内排队时延的尾部远厚于均值。要拿到 <span class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$</span> 里的 p99，必须用 M/G/1 近似或离散事件仿真求出排队时延的尾部分布，再与路径时延卷积；直接把均值 <span class=\"formula\">$$\\tau_{\\text{queue}}$$</span> 代进去求出的 <span class=\"formula\">$$B^{*}$$</span> 会偏大，因为均值掩盖了突发下的长尾。这正是最常见的误用：只按均值时延调批大小，突发到达下排队时延击穿补全 SLO，而调参者看到的平均指标一切正常。</p>\n<p>第三个断裂点藏在解码带宽项的分母假设里：公式默认每个解码步重读批内全部 KV。一旦启用 KV 分块驻留或 prefix 复用命中，命中部分的 KV 不再从 HBM 重读，<span class=\"formula\">$$M_{\\text{KV}}(S)$$</span> 实际参与带宽计算的部分显著下降，TPOT 的带宽项随之收缩，<span class=\"formula\">$$B^{*}$$</span> 应当上移。若命中后仍按原式估算，会把批上界定得过低，用无谓的吞吐牺牲换取并不存在的时延收益。下表把三类失效条件与对应的修正动作并列，便于在调参时逐条核对。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>公式中被破坏的假设</th><th>系统代价表现</th><th>修正动作</th></tr></thead><tbody><tr><td>chunked prefill 交织</td><td>TTFT 与 TPOT 可加、资源独占</td><td>TTFT 预测偏乐观，实测偏差随 chunk 变细放大</td><td>实测校准 <span class=\"formula\">$$\\pi_{\\text{eff}}$$</span>、<span class=\"formula\">$$\\beta_{\\text{eff}}$$</span></td></tr><tr><td>突发到达</td><td><span class=\"formula\">$$\\tau_{\\text{queue}}$$</span> 为常数、无尾分布</td><td>p99 击穿 SLO，均值指标正常</td><td>M/G/1 或仿真求尾部，按 p99 求 <span class=\"formula\">$$B^{*}$$</span></td></tr><tr><td>prefix 复用命中</td><td>每步重读全 KV</td><td><span class=\"formula\">$$B^{*}$$</span> 偏低，吞吐被无谓牺牲</td><td>下调 TPOT 带宽项后重解 <span class=\"formula\">$$B^{*}$$</span></td></tr></tbody></table>\n<p>把这三条放在一起看，公式的真正用途不是给出一个可直接部署的 <span class=\"formula\">$$B$$</span> 值，而是给出各项的相对量级与单调方向：<span class=\"formula\">$$S_{\\text{in}}$$</span> 从常规上下文涨到仓库级 <span class=\"formula\">$$10^5$$</span> 时，预填算力项主导 TTFT，此时应配合 chunked prefill 把算力项与带宽项解耦，避免长预填阻塞解码；而 <span class=\"formula\">$$T_{\\text{out}}$$</span> 落在 32–256 的低延迟补全区间时，TPOT 被乘上输出步数后权重上升，批上界必须压小以保 p99。换句话说，<span class=\"formula\">$$B^{*}$$</span> 是随 <span class=\"formula\">$$S_{\\text{in}}$$</span>、<span class=\"formula\">$$T_{\\text{out}}$$</span> 与命中率漂移的曲面，任何把它当固定常数的调参都是在用均值思维替代尾部思维。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-15\">十五 · 批上界 B* 的适用边界：线性叠加在哪里失效</h3>\n<p>该模型的可信区间由三条假设划出。第一，TTFT 与 TPOT 被当作可加的两段，但预填与解码共享同一批 SM 的 MMA 与 TMEM 资源；一旦启用 chunked prefill，预填块被切碎插入解码步之间，二者在同一时间片上争抢算力，实际 TTFT 会随同批解码请求数上升，TPOT 也会因预填块插入而出现尖峰。此时 <span>TTFT + T_out·TPOT</span> 不再是两个独立项的相加，而是耦合函数，B* 必须用实测曲线而非解析式求解。第二，公式只描述单请求的路径时延，τ_queue 的尾部由到达过程决定：泊松到达下 M/G/1 的等待时间分布重尾，突发到达（仓库级补全常见的一次性大批量触发）下尾部更厚，p99 只能靠仿真或排队论近似取得，用均值代入会系统性低估 B*。第三，解码每步重读全 KV 的假设在 KV 分块驻留或 prefix 复用命中后不成立——命中前缀的 KV 不再重读，TPOT 的带宽项按命中比例下降，B* 随之上移；若仍按未命中公式定批，吞吐被无谓牺牲。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>失效场景</th><th>系统代价</th></tr></thead><tbody><tr><td>预填/解码线性叠加</td><td>chunked prefill 交织</td><td>TTFT 预测偏低，p99 违约</td></tr><tr><td>τ_queue 仅均值</td><td>突发到达</td><td>尾部排队击穿补全 SLO</td></tr><tr><td>每步重读全 KV</td><td>prefix 复用命中</td><td>B* 过低，吞吐损失</td></tr></tbody></table>\n<p>工程上的处理是把公式降级为标定骨架而非预测器：先用小批实测 π_eff 与 β_eff（含 MMA 利用率与 attention 非线性带来的折损），再在目标到达过程下扫 B 取 p99 曲线的最小点。对 T_out 仅 32–256 的补全请求，TPOT 项权重小，B* 主要由 τ_queue 与预填算力项决定，宜取小批保尾部；对 S_in 达 10^5 的仓库级上下文，则应让 chunked prefill 把预填的算力项与带宽项解耦，避免长预填阻塞解码队列，此时 B* 的求解必须把预填块占用的 SM 时间显式计入分母。</p>\n<div class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}(B)+T_{\\text{out}}\\cdot\\text{TPOT}(B)\\right),\\quad \\text{TPOT}(B)\\approx\\frac{(1-h)\\,M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</div>\n<p>式中 h 为 prefix 命中比例，是原公式未含的修正项；h 上升使 TPOT 斜率变缓，最优点右移。反过来，若部署中预填与解码争抢严重，TTFT(B) 随 B 增长快于线性，最优点左移。两类偏移方向相反，说明 B* 不是硬编码常数，而是随部署形态（是否 chunked、命中率高低、到达是否突发）漂移的运行参数，需按 SLO 定期重标定。</p>\n<h3 id=\"th-batch-latency-slo-sec-16\">十六 · 线性叠加假设的成立条件</h3>\n<p>公式把端到端时延写成 <span class=\"formula-inline\">TTFT + T_out·TPOT</span> 的线性叠加，这一步在工程上等价于声明：预填阶段与解码阶段在时间上互斥、在资源上不重叠。成立条件比多数人以为的苛刻——预填的最后一批 token 完成 KV 写入之后，解码步才开始读这份 KV；解码期间没有新的预填请求插入同一组 SM；两个阶段各自独占 <span class=\"formula-inline\">π_eff</span> 与 <span class=\"formula-inline\">β_eff</span> 这两个有效效率常数，且这两个常数与批大小无关。第三条最容易被忽略：<span class=\"formula-inline\">π_eff</span> 受 MMA 利用率与 attention 非线性影响，<span class=\"formula-inline\">β_eff</span> 受 HBM 访问模式与 KV 布局影响，二者在批大小跨过某个阈值后都会漂移，此时对 <span class=\"formula-inline\">B</span> 求极小得到的 <span class=\"formula-inline\">B*</span> 只是在局部常数假设下的驻点，不是全局最优。</p>\n<p>一个具体机制能说明这条边界：在非 chunked 的朴素连续批处理里，调度器把预填请求作为不可分割的整体提交，预填期间解码请求被整体挂起，线性叠加成立；一旦预填请求的 <span class=\"formula-inline\">S_in</span> 达到仓库级 <span class=\"formula-inline\">10^5</span> 量级，调度器不可能让整批解码停等这么久，于是必然切分，假设随之破裂。工程判断是：当 <span class=\"formula-inline\">2N_active·S_in/π_eff</span> 这一项与 <span class=\"formula-inline\">T_out·TPOT</span> 同量级或更大时，线性叠加已经不可用，必须换用耦合模型或直接实测标定。代价层面，误用线性叠加的直接后果是 TTFT 预测偏低、<span class=\"formula-inline\">B*</span> 定得偏大，p99 在突发到达下击穿补全 SLO。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-17\">十七 · chunked prefill 下的耦合失效</h3>\n<p>chunked prefill 把长预填切成若干块，与解码步在同一 SM 上交织执行，这正是线性叠加失效的典型场景。交织带来的耦合有两层：其一，每个解码步的 <span class=\"formula-inline\">TPOT</span> 不再只由 <span class=\"formula-inline\">M_KV(S)·B + M_weights</span> 决定，还要加上同周期内预填块占用的算力与带宽份额；其二，预填块被拉长后，<span class=\"formula-inline\">TTFT</span> 的第一项不再是单次 <span class=\"formula-inline\">2N_active·S_in/π_eff</span>，而是被解码步反复打断后的有效算力时间，实际值高于公式给出的理想值。</p>\n<p>伪代码层面的判据可以写成：设预填块占用的 SM 周期比例为 <span class=\"formula-inline\">ρ_p</span>，则交织期的解码有效带宽近似退化为 <span class=\"formula-inline\">β_eff·(1-ρ_p)</span>，代入 TPOT 得</p>\n<div class=\"formula\">$$\\text{TPOT}_{\\text{interleaved}}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}\\,(1-\\rho_p)}$$</div>\n<p>该式表明 <span class=\"formula-inline\">ρ_p</span> 越大，<span class=\"formula-inline\">B*</span> 越向小值移动，因为每步的固定成本被预填抬高了。具体例子：仓库级上下文 <span class=\"formula-inline\">S_in=10^5</span>、补全 <span class=\"formula-inline\">T_out</span> 取 32–256 的下沿时，若按线性叠加把 <span class=\"formula-inline\">B</span> 调到吞吐最优，实测 p99 会因 <span class=\"formula-inline\">ρ_p</span> 的周期性尖峰而明显高于预测；正确做法是把 <span class=\"formula-inline\">ρ_p</span> 作为调度器的可调旋钮，与 <span class=\"formula-inline\">B</span> 联合标定，而不是先定 <span class=\"formula-inline\">B</span> 再谈预填策略。代价是标定工作量上升，收益是 TTFT 与 TPOT 的预测偏差收敛到可接受范围。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-18\">十八 · 排队项与尾部分布：公式只给路径时延</h3>\n<p><span class=\"formula-inline\">τ_queue</span> 在公式里是一个标量，但真实系统中它是随机变量，其分布由到达过程决定。公式本身只描述单请求的路径时延，不含排队论的尾部分布；把 <span class=\"formula-inline\">τ_queue</span> 取均值代入 <span class=\"formula-inline\">B*</span> 的求解，等价于用均值时延调参，这是最常见的误用。代码补全的到达过程既非严格泊松也非平稳：IDE 侧的触发具有突发性，同一仓库的多个文件可能在秒级窗口内集中请求，此时排队时延的尾部远厚于泊松假设。</p>\n<p>求解 p99 需要 M/G/1 近似或离散事件仿真。M/G/1 的等待时间尾部分布依赖服务时间分布的前两阶矩，而本模型的服务时间（一次预填加若干解码步）方差很大——<span class=\"formula-inline\">S_in</span> 从数百到 <span class=\"formula-inline\">10^5</span> 跨越三个数量级，<span class=\"formula-inline\">T_out</span> 在 32–256 间波动，因此 Pollaczek–Khinchine 型近似只能给出量级判断，不能替代仿真。工程上的可行路径是：用仿真或在线采样得到 <span class=\"formula-inline\">p99(TTFT + T_out·TPOT)</span> 关于 <span class=\"formula-inline\">B</span> 的曲线，再取极小；公式的作用退化为给出曲线形状的先验（<span class=\"formula-inline\">B</span> 增大时排队项单调降、TPOT 项单调升），缩小搜索区间。代价是仿真基础设施的投入，以及在线采样带来的可观测性开销；不做这一步的代价则是突发到达下 SLO 违约，且违约不可预测。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-19\">十九 · 每步重读全 KV 的假设与驻留优化</h3>\n<p>TPOT 公式的分子 <span class=\"formula-inline\">M_KV(S)·B + M_weights</span> 建立在“解码每步重读批内全部 KV”之上。这条假设在标准 paged KV 布局下成立，但在两类优化下失效：KV 分块驻留（把热 KV 块固定在近端存储层级，减少每步的重读量）与 prefix 复用命中（共享前缀的 KV 只读一次或按命中率折算）。失效后 <span class=\"formula-inline\">M_KV(S)</span> 的有效值下降，TPOT 的带宽项显著变小，<span class=\"formula-inline\">B*</span> 随之上移——因为单步变便宜了，可以容纳更大的批而不牺牲 p99。</p>\n<p>量化这条边界的判据是命中率 <span class=\"formula-inline\">h</span>：有效 KV 读取量近似为 <span class=\"formula-inline\">(1-h)·M_KV(S)·B</span>，代入得</p>\n<div class=\"formula\">$$\\text{TPOT}_{h}\\approx\\frac{(1-h)\\,M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</div>\n<p>常见误用正是忽略这个 <span class=\"formula-inline\">(1-h)</span> 因子：prefix 复用已经上线、命中率可观，却仍按未命中的 TPOT 估 <span class=\"formula-inline\">B*</span>，结果批上界定得过低，吞吐被无谓牺牲。具体例子：同一仓库的连续补全请求共享大量文件级前缀，命中后每步 KV 读取量下降，若仍沿用旧 <span class=\"formula-inline\">B*</span>，解码步的带宽远未打满，GPU 在低利用率下空转。工程判断是：把 <span class=\"formula-inline\">h</span> 纳入 <span class=\"formula-inline\">B*</span> 的在线重估回路，命中率变化时同步上调批上界，而不是把 <span class=\"formula-inline\">B*</span> 当作静态配置。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-20\">二十 · 规模上限：批大小与上下文长度的双重天花板</h3>\n<p>模型在规模上有两条硬边界。第一条是批大小的天花板：<span class=\"formula-inline\">B</span> 增大到 <span class=\"formula-inline\">M_KV(S)·B</span> 主导分子后，TPOT 随 <span class=\"formula-inline\">B</span> 线性上升，而排队项的下降是次线性的，<span class=\"formula-inline\">B*</span> 之后继续加批只会拉高 p99；更硬的约束来自 KV 显存容量，超出并发容量后调度器被迫抢占或换出，此时公式里的 <span class=\"formula-inline\">B</span> 已不是有效批大小，模型失效。第二条是上下文长度的天花板：<span class=\"formula-inline\">S_in</span> 达到 <span class=\"formula-inline\">10^5</span> 时，预填算力项与 KV 写入带宽项同时膨胀，<span class=\"formula-inline\">π_eff</span> 因 attention 非线性而进一步下降，公式中两个常数假设同时漂移。</p>\n<p>两条边界交汇处是模型最不可靠的区域：大批加长上下文，预填与解码争抢同一组 SM，<span class=\"formula-inline\">π_eff</span> 与 <span class=\"formula-inline\">β_eff</span> 都无法当作常数。此时的工程做法不是继续解析求解，而是退化为约束优化：把 <span class=\"formula-inline\">B</span> 的上界交给显存容量与抢占策略决定，把 <span class=\"formula-inline\">S_in</span> 的上界交给 chunked prefill 的块大小决定，公式只用于在可行域内做粗筛。代价是失去了闭式最优解，收益是避免了在模型失效区做出错误的容量规划。可观测的判据是：当实测 <span class=\"formula-inline\">π_eff</span> 相对标定值漂移超过可接受带宽，或 <span class=\"formula-inline\">β_eff</span> 随 <span class=\"formula-inline\">B</span> 呈系统性下降，就应判定已越过适用边界，切换到实测驱动的调度参数搜索。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-21\">二十一 · 失效条件的工程清单</h3>\n<p>把上述边界收敛成一张可执行的检查表，用于在部署前判定公式是否仍可作为决策依据。</p>\n<table class=\"mini\">\n<thead>\n<tr><th>假设</th><th>失效触发条件</th><th>后果</th><th>替代手段</th></tr>\n</thead>\n<tbody>\n<tr><td>预填与解码时间互斥</td><td>启用 chunked prefill，<span class=\"formula-inline\">ρ_p</span> 不可忽略</td><td>TTFT 低估、TPOT 低估</td><td>耦合模型加实测标定</td></tr>\n<tr><td><span class=\"formula-inline\">π_eff</span>、<span class=\"formula-inline\">β_eff</span> 与 <span class=\"formula-inline\">B</span> 无关</td><td>批大小或 <span class=\"formula-inline\">S_in</span> 跨过阈值</td><td><span class=\"formula-inline\">B*</span> 偏离全局最优</td><td>分段标定效率常数</td></tr>\n<tr><td><span class=\"formula-inline\">τ_queue</span> 为标量均值</td><td>突发到达、非平稳负载</td><td>p99 违约不可预测</td><td>M/G/1 近似或仿真</td></tr>\n<tr><td>解码每步重读全 KV</td><td>KV 分块驻留、prefix 复用命中</td><td><span class=\"formula-inline\">B*</span> 定得过低、吞吐浪费</td><td>引入命中率 <span class=\"formula-inline\">h</span> 重估</td></tr>\n<tr><td>批大小可自由增大</td><td>触及 KV 显存容量、发生抢占换出</td><td>有效批失真、模型失效</td><td>显存约束下的可行域搜索</td></tr>\n</tbody>\n</table>\n<p>清单的使用方式是逐条打勾：任一条触发即意味着该部署场景下 <span class=\"formula-inline\">B*</span> 的解析解只能作为初值，最终值必须由实测 p99 曲线确定。代价是每次部署变更（上下文长度档位、prefix 命中率、chunk 块大小）都要重跑标定，收益是把 SLO 违约从“事后发现”变成“事前可判”。对于代码补全这类 <span class=\"formula-inline\">T_out</span> 仅 32–256 的低延迟场景，p99 对 <span class=\"formula-inline\">B</span> 的敏感度高于均值，清单中排队项与驻留项两条应优先核对；对于仓库级长上下文预填，耦合项与规模上限两条是主要风险源。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-22\">二十二 · 边界在哪里：线性叠加假设的失效条件与规模上限</h3>\n<p>这套时延模型能被工程直接使用，靠的是一个很强的结构性假设：端到端时延可以写成 <span class=\"sym\">TTFT</span> 与 <span class=\"sym\">T<sub>out</sub></span>·<span class=\"sym\">TPOT</span> 的线性叠加，且两项各自独立可估。代码补全场景里，<span class=\"sym\">T<sub>out</sub></span> 通常只有 32–256 个 token，输出项权重不大，模型的精度主要押在 <span class=\"sym\">TTFT</span> 上；而 <span class=\"sym\">TTFT</span> 的第一项 <span class=\"sym\">2N<sub>active</sub>S<sub>in</sub>/π<sub>eff</sub></span> 在仓库级上下文（<span class=\"sym\">S<sub>in</sub></span> 可达 10<sup>5</sup>）下会膨胀到主导地位。一旦预填与解码不再是时间上分离的两个阶段，这个叠加就不再成立——chunked prefill 把长预填切成若干块插入解码步之间，预填的算力项与解码的带宽项在同一 SM 上争抢执行资源，<span class=\"sym\">TTFT</span> 被拉长、<span class=\"sym\">TPOT</span> 被抬高，二者出现耦合。此时公式给出的两个数只是“无争抢”的理想下界，实测偏差随 chunk 粒度与批内预填比例上升。工程判断是：只要部署启用了 chunked prefill，就必须用实测校准系数替换 <span class=\"sym\">π<sub>eff</sub></span> 与 <span class=\"sym\">β<sub>eff</sub></span>，不能直接套用解析式。</p>\n<p>第二个失效点是排队项 <span class=\"sym\">τ<sub>queue</sub></span> 的分布性质。公式只描述单请求的路径时延，把 <span class=\"sym\">τ<sub>queue</sub></span> 当作一个可加的标量；但真实到达过程是泊松或突发的，排队时延是随机变量而非常数。要求 <span class=\"sym\">B<sup>*</sup></span> 就必须求 p99，而 p99 无法从单请求路径时延解析得到，需借助 M/G/1 近似或离散事件仿真。常见误用正是只按均值时延调批大小：均值下 <span class=\"sym\">B</span> 可以取得较大以摊薄固定开销，但突发到达时尾部排队时延击穿补全 SLO，p99 违约而均值指标仍然漂亮。规模上限也在这里显形——当 <span class=\"sym\">S<sub>in</sub></span> 达到 10<sup>5</sup> 量级、并发请求数上升时，预填算力项本身已接近单步预算，任何排队抖动都会被放大成数量级的尾延迟，模型退化为只能给出下界。</p>\n<p>第三个失效点来自 KV 驻留策略对 <span class=\"sym\">TPOT</span> 带宽项的改写。模型假设解码每步重读批内全部 KV，即 <span class=\"sym\">M<sub>KV</sub>(S)·B</span> 随 <span class=\"sym\">B</span> 线性增长；若启用 KV 分块驻留或 prefix 复用命中，命中部分的 KV 不再每步从 HBM 重读，<span class=\"sym\">TPOT</span> 的带宽项显著下降，最优批随之上移。反过来，prefix 复用命中后若仍按原带宽项估 <span class=\"sym\">TPOT</span>，会把 <span class=\"sym\">B<sup>*</sup></span> 定得过低，用吞吐换来了并不存在的时延收益。下表给出三类边界下模型的可用性判断：</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>模型状态</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>预填/解码时间分离</td><td>线性叠加成立</td><td>—</td><td>可直接用解析式定 <span class=\"sym\">B<sup>*</sup></span></td></tr><tr><td>chunked prefill 交织</td><td>两项耦合，解析式仅给下界</td><td>TTFT 拉长、TPOT 抬高，SM 争抢</td><td>实测校准 <span class=\"sym\">π<sub>eff</sub></span>、<span class=\"sym\">β<sub>eff</sub></span></td></tr><tr><td>prefix 复用命中</td><td>带宽项高估</td><td><span class=\"sym\">B<sup>*</sup></span> 偏低，吞吐被牺牲</td><td>下调 <span class=\"sym\">M<sub>KV</sub></span> 后重解</td></tr></tbody></table>\n<p>把边界收束成一句可执行的判据：当 <span class=\"sym\">S<sub>in</sub></span> 处于 10<sup>5</sup> 量级且部署启用 chunked prefill 时，<span class=\"sym\">TTFT</span> 的算力项与带宽项必须解耦估计，并把预填块对解码步的挤占作为独立惩罚项加入 <span class=\"sym\">TPOT</span>，否则 <span class=\"sym\">B<sup>*</sup></span> 的求解只是在优化一个不存在的系统；而当 <span class=\"sym\">T<sub>out</sub></span> 停留在 32–256 的补全区间、KV 复用命中率稳定时，带宽项应随命中率下调，让 <span class=\"sym\">B<sup>*</sup></span> 上移以释放吞吐——这两条判据的取舍点不在公式内部，而在部署形态是否破坏了“预填与解码不共享执行资源”这一前提。</p>\n<h3 id=\"th-batch-latency-slo-sec-23\">二十三 · 从公式到决策变量：把 B 当作唯一可控旋钮</h3>\n<p>在容量决策里，TTFT 与 TPOT 两条式子不是用来“解释现象”的，而是用来解出四个待定量的：批上界 <em>B</em>、并行度 <em>N</em><sub>active</sub>、KV 预算、以及 SLO 的可行域。做法是把端到端时延写成 <em>D</em>(<em>B</em>) = TTFT + <em>T</em><sub>out</sub>·TPOT，其中只有 <em>B</em> 出现在 TPOT 的分子里、同时通过 τ<sub>queue</sub> 反向出现在 TTFT 里。于是决策变成一次单变量求极小，其余三个量都由 <em>B</em><sup>*</sup> 反推。</p>\n<p>具体机制上，连续批处理每步重读批内全部 KV，TPOT 的分子 <em>M</em><sub>KV</sub>(<em>S</em>)·<em>B</em> + <em>M</em><sub>weights</sub> 随 <em>B</em> 线性增长，而每请求摊到的固定开销（权重读取、kernel 启动）按 1/<em>B</em> 衰减。前者是抬升项，后者是摊薄项，两者相抵的位置就是吞吐-时延的拐点。注意 <em>M</em><sub>weights</sub> 不随 <em>B</em> 变，所以当 <em>B</em> 大到 <em>M</em><sub>KV</sub>·<em>B</em> 远超权重项时，TPOT 近似正比于 <em>B</em>——这就是“批越大单步越慢”的定量来源，也是 <em>B</em><sup>*</sup> 存在的根本原因。</p>\n<p>系统代价上，<em>B</em> 的每一次上调都在用 TPOT 换吞吐：解码阶段的带宽占用从 <em>M</em><sub>weights</sub>/β<sub>eff</sub> 抬到 (<em>M</em><sub>KV</sub>·<em>B</em>+<em>M</em><sub>weights</sub>)/β<sub>eff</sub>，单步墙钟时间同比上升，而总吞吐（token/s）大致按 <em>B</em>/TPOT 变化，只有分子中权重项占比仍显著时才单调增。举例：代码补全 <em>T</em><sub>out</sub> 取 128，若把 <em>B</em> 从 8 翻到 32，TPOT 的 KV 项翻四倍，端到端时延中 128·TPOT 这一项直接主导 <em>D</em>，p99 立刻被推高——这正是低延迟补全必须压小 <em>B</em> 的原因。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-24\">二十四 · 定批大小：按 p99 求 B*，而不是按均值</h3>\n<p>求 <em>B</em><sup>*</sup> 的正确做法是对 p99 分位数求极小，而非对均值。均值下 τ<sub>queue</sub> 被平滑掉，<em>B</em> 会一路推到吞吐拐点；但补全 SLO 通常卡在 p99，突发到达时排队项会击穿预算。工程上的可执行流程是：固定 <em>S</em><sub>in</sub>、<em>T</em><sub>out</sub> 的分布，对候选 <em>B</em> 网格做离散扫描，每个 <em>B</em> 用 M/G/1 近似或事件仿真得到 τ<sub>queue</sub> 的 p99，再代入 <em>D</em>(<em>B</em>) 取最小。</p>\n<div class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right),\\qquad \\text{s.t.}\\;\\; B\\cdot M_{\\text{KV}}(S)\\le M_{\\text{KV,budget}}$$</div>\n<p>伪代码思路：对每个 <em>B</em>，先用 TPOT 式子算单步时间，再以到达率 λ 与单步服务时间构造 M/G/1 的等待时间分布取 p99 作为 τ<sub>queue</sub>，累加得 <em>D</em><sub>p99</sub>(<em>B</em>)；扫描区间上界由 KV 预算约束截断（见第四节）。这一步的代价是仿真开销，但只做一次离线标定，之后按负载档位查表。</p>\n<p>具体例子：仓库级上下文 <em>S</em><sub>in</sub> 达 10<sup>5</sup> 量级时，预填算力项 2<em>N</em><sub>active</sub><em>S</em><sub>in</sub>/π<sub>eff</sub> 本身就吃掉大部分 TTFT 预算，此时 <em>B</em><sup>*</sup> 被 TTFT 侧钉死在小值，继续加批只会让 TPOT 项在 128 步上放大 128 倍地恶化 p99。反过来，<em>T</em><sub>out</sub> 只有 32 的短补全，<em>T</em><sub>out</sub>·TPOT 权重低，<em>B</em><sup>*</sup> 可以明显上移——同一套公式，两个 <em>T</em><sub>out</sub> 档位给出完全不同的批上界，这就是“按场景定批”而非“全局一个批”的依据。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-25\">二十五 · 定并行度：N_active 与 B 的耦合约束</h3>\n<p>并行度 <em>N</em><sub>active</sub> 只出现在 TTFT 的第一项，看似与 <em>B</em> 独立，实则被同一条 SM 资源约束耦合：预填与解码争抢同一批 SM，<em>N</em><sub>active</sub> 越大，预填算力项越小但占用越多 SM，留给解码的带宽与算力被压缩，TPOT 的 β<sub>eff</sub> 实际下降。因此定并行度不能只看 TTFT，要把 β<sub>eff</sub> 作为 <em>N</em><sub>active</sub> 的函数一起标定。</p>\n<p>机制上，预填是算力受限（π<sub>eff</sub> 受 MMA 利用率与 attention 非线性影响），解码是带宽受限（β<sub>eff</sub>），两类负载对 SM 的占用形态不同。把 <em>N</em><sub>active</sub> 调大等价于把更多 SM 划给算力密集的预填，解码侧的有效带宽随之被稀释。工程判断是：先在纯解码工况下标定 β<sub>eff</sub>(<em>N</em><sub>active</sub>) 曲线，再回到 TTFT 式子选 <em>N</em><sub>active</sub>，使 2<em>N</em><sub>active</sub><em>S</em><sub>in</sub>/π<sub>eff</sub> 落入 TTFT 预算的预定份额（例如给排队与 KV 写入留出余量）。</p>\n<p>代价面：<em>N</em><sub>active</sub> 提升换来 TTFT 下降，但以解码 β<sub>eff</sub> 下降为代价，等价于把 TPOT 抬高、把 <em>B</em><sup>*</sup> 往下压。所以并行度与批大小不是两个独立旋钮，而是一条权衡曲线上的两个坐标；容量规划时应把它们作为一对 (<em>N</em><sub>active</sub>, <em>B</em><sup>*</sup>) 联合标定，而不是分别取“最大值”。长上下文场景下这条曲线尤其陡：<em>S</em><sub>in</sub>=10<sup>5</sup> 时预填项对 <em>N</em><sub>active</sub> 极其敏感，稍加并行就能把 TTFT 拉回预算内，代价是解码侧可用的 β<sub>eff</sub> 明显缩水。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-26\">二十六 · 定 KV 预算：把约束写进 B 的可行域</h3>\n<p>KV 预算是 <em>B</em><sup>*</sup> 搜索区间的硬上界：<em>B</em>·<em>M</em><sub>KV</sub>(<em>S</em>) ≤ <em>M</em><sub>KV,budget</sub>。这一步把显存容量公式（本模块另有专条，此处只引用结论）转成批大小的可行域边界。注意 <em>M</em><sub>KV</sub>(<em>S</em>) 随上下文长度增长，所以同一个 KV 预算在不同 <em>S</em> 档位下给出完全不同的 <em>B</em> 上限——仓库级上下文把 <em>B</em> 上限压得很低，短上下文则宽松。</p>\n<p>机制上，KV 预算的分配要在“批大小上限”与“上下文长度上限”之间做二维取舍：给定总显存，<em>B</em>·<em>S</em> 近似受同一容量约束，扩大 <em>S</em> 就必然压缩 <em>B</em>。工程做法是把预算切成三段：权重常驻、KV 池、以及为 chunked prefill 的中间激活留的余量。KV 池一旦定死，<em>B</em><sup>*</sup> 的搜索上界随之确定，若公式解出的最优批超出该上界，说明瓶颈已从时延转到显存，此时应下调 <em>S</em> 上限或引入 KV 分块驻留，而不是硬扛。</p>\n<p>代价面：KV 预算收紧直接压低并发容量，进而抬高 τ<sub>queue</sub> 的 p99，形成“显存→排队→SLO”的传导链。具体例子：<em>S</em><sub>in</sub>=10<sup>5</sup> 的仓库级请求，单请求 KV 占用极大，KV 池只允许很小的 <em>B</em>，此时 <em>B</em><sup>*</sup> 由显存而非时延决定；而 <em>T</em><sub>out</sub>=32 的短补全、<em>S</em><sub>in</sub> 仅数千 token 时，KV 池能容纳大得多的 <em>B</em>，<em>B</em><sup>*</sup> 回到时延主导区间。两类请求混跑时，应按 <em>S</em> 分池或分队列，否则长上下文请求会把短请求的 <em>B</em> 上限一起拖低。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-27\">二十七 · 定 SLO 与算例：反解可行域</h3>\n<p>定 SLO 是把上述过程反过来：给定 p99 预算 <em>D</em><sub>SLO</sub>，问是否存在 (<em>B</em>, <em>N</em><sub>active</sub>) 使 p99(<em>D</em>) ≤ <em>D</em><sub>SLO</sub>。由于 <em>D</em> 对 <em>B</em> 是“先降后升”的凸形，可行域是 <em>B</em> 轴上的一个区间 [<em>B</em><sub>min</sub>, <em>B</em><sub>max</sub>]，而非单点。区间为空即 SLO 不可达，需要放宽 <em>T</em><sub>out</sub>、拆分上下文长度档位，或引入 chunked prefill 解耦预填与解码。</p>\n<p>算例（定性数值关系，不引入实验数据）：设某补全档位 <em>T</em><sub>out</sub>=128，TTFT 预算与总 p99 预算已定。取 <em>B</em>=8 时 TPOT 较小、τ<sub>queue</sub> 的 p99 因并发不足而偏高；取 <em>B</em>=32 时 τ<sub>queue</sub> 下降但 TPOT 的 KV 项约翻四倍，128·TPOT 项反超，总 p99 上升。扫描网格上 <em>D</em><sub>p99</sub>(<em>B</em>) 呈 U 形，谷底即 <em>B</em><sup>*</sup>；把 <em>D</em><sub>SLO</sub> 画一条水平线，与 U 形曲线的两个交点就是 [<em>B</em><sub>min</sub>, <em>B</em><sub>max</sub>]。若 <em>D</em><sub>SLO</sub> 低于谷底，则该档位在现有 <em>N</em><sub>active</sub> 与 KV 预算下不可行。</p>\n<p>这个算例的工程含义是：SLO 不该写成“平均时延 ≤ X”，而应写成“在给定 <em>S</em>、<em>T</em><sub>out</sub> 分布下 p99 ≤ X，且存在非空批区间”。容量规划的输出因此是三张表——每个上下文档位的 <em>B</em><sup>*</sup>、对应的 <em>N</em><sub>active</sub>、以及该档位下 SLO 是否可达——而不是一个全局批大小。低延迟补全档取区间下沿保 p99，吞吐优先档取谷底附近；两者不能共用同一 <em>B</em>。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-28\">二十八 · 三个必须校准的输入项与误用防线</h3>\n<p>公式能用的前提是 π<sub>eff</sub>、β<sub>eff</sub>、τ<sub>queue</sub> 三个量经过实测校准，否则解出的 <em>B</em><sup>*</sup> 只是纸面最优。π<sub>eff</sub> 受 MMA 利用率与 attention 非线性影响，长 <em>S</em><sub>in</sub> 下衰减明显；β<sub>eff</sub> 随 <em>N</em><sub>active</sub> 与 KV 驻留策略变化；τ<sub>queue</sub> 依赖到达过程是泊松还是突发，突发到达下 p99 远高于泊松假设。三者都必须按档位标定，不能全负载共用一个常数。</p>\n<p>三条误用防线对应三种失效模式。其一，只按均值调 <em>B</em>：均值把 τ<sub>queue</sub> 的尾部抹平，<em>B</em> 被推到过大，突发到达时 p99 击穿补全 SLO——防线是任何调参都以 p99 为目标函数。其二，chunked prefill 部署下仍按线性叠加估 TTFT：预填与解码在同一 SM 上交织争抢，TTFT 与 TPOT 存在耦合，线性叠加会系统性低估，防线是用实测校准替代解析式，或把预填份额作为显式参数引入。其三，prefix 复用命中后未下调 TPOT 的带宽项：命中使每步重读的 KV 显著减少，TPOT 分子下降，<em>B</em><sup>*</sup> 本应上移，若仍按未命中标定就会把批定得过低、无谓牺牲吞吐——防线是在 <em>M</em><sub>KV</sub>(<em>S</em>) 中按命中率折算有效 KV 读取量，并随命中率变化重解 <em>B</em><sup>*</sup>。</p>\n<p>最后落在一条工程判断上：<em>B</em><sup>*</sup> 不是一次性常数，而是随 <em>S</em> 档位、<em>T</em><sub>out</sub> 分布、prefix 命中率、以及 <em>N</em><sub>active</sub> 配置漂移的量。把 <em>B</em><sup>*</sup> 做成在线可调的查表项——输入是当前上下文中位数与命中率，输出是批上界——比把它写死进部署配置更稳；而每次 KV 驻留策略或并行度变更，都必须重跑一次 p99 扫描，否则公式给出的最优点已经不在当前系统上。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-29\">二十九 · 批上界、并行度与 KV 预算：模型能定什么、定不了什么</h3>\n<p>这个模型在容量决策里能直接回答三类问题，且只回答这三类。第一，<strong>定批上界</strong>：把 $B^{*}=\\arg\\min_{B}\\mathrm{p99}(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT})$ 当作连续批处理的调度上限，而不是当作吞吐最优批。代码补全的 $T_{\\text{out}}$ 落在 32–256，端到端时延里 TPOT 项被乘了 32–256 次，因此 $B$ 的边际代价被放大数十倍——同样把 $B$ 从 8 抬到 32，对话类负载可能只多几毫秒，补全负载的 p99 会成倍恶化。第二，<strong>定并行度</strong>：$\\pi_{\\text{eff}}$ 与 $\\beta_{\\text{eff}}$ 是并行切分的函数，TP 增大使 $\\beta_{\\text{eff}}$ 上升但每卡权重份额下降、通信占比上升，PP 增大则引入流水气泡抬高 $\\tau_{\\text{queue}}$ 的等效值；把实测的 $\\pi_{\\text{eff}},\\beta_{\\text{eff}}$ 代回公式，可以判断某组 TP/PP 组合是否真的把 $B^{*}$ 推高了，而不是凭“卡多就快”拍板。第三，<strong>定 KV 预算</strong>：$M_{\\text{KV}}(S_{\\text{in}})$ 与 $M_{\\text{KV}}(S)$ 同时出现在 TTFT 的带宽项和 TPOT 的分子里，KV 预算不是“能塞多少塞多少”，而是要让常驻 KV 在 $\\beta_{\\text{eff}}$ 下重读一遍的时间不击穿 TPOT 目标，剩余空间才留给批宽度。</p>\n<p>算例按量纲走，不引具体实测值。设某仓库级补全请求 $S_{\\text{in}}=10^{5}$、$T_{\\text{out}}=128$，SLO 要求 p99 端到端不超过一个补全可接受的量级。预填项 $\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}$ 随活跃请求数线性增长，是 TTFT 的主项；此时若把 $B$ 调大以摊薄固定开销，TPOT 分子里的 $M_{\\text{KV}}(S)B$ 同步变大，$128\\times\\text{TPOT}$ 迅速吃掉时延预算。工程上的做法是先把 $B$ 压到只够维持 $\\beta_{\\text{eff}}$ 饱和的下界，再用 chunked prefill 把 $10^{5}$ 量级的预填切成块，使预填算力项与 KV 写入带宽项解耦，避免一次长预填把整批解码请求的 TPOT 顶穿。反过来，若 prefix 复用命中率高，$M_{\\text{KV}}(S)$ 的有效重读量下降，TPOT 带宽项随之收缩，此时应把 $B^{*}$ 上移——沿用未命中时的 $B$ 是把吞吐白白让给时延。</p>\n<p>边界必须写清楚，否则这套公式会被当成万能估算器。线性叠加 $\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}$ 的前提是预填与解码不共享 SM；chunked prefill 部署下二者在同一 SM 上交织争抢，实测 TTFT 与 TPOT 存在耦合，公式给出的两个数只能作为下界参考，必须用实测校准系数。$\\tau_{\\text{queue}}$ 只刻画单请求路径时延，不含排队论尾部分布：到达过程是泊松还是突发，决定 p99 与均值的偏离幅度，$B^{*}$ 必须用 M/G/1 近似或离散事件仿真求解，不能对均值时延求极小。还有一条隐含假设——解码每步重读全部 KV；一旦采用 KV 分块驻留或 prefix 复用，TPOT 的带宽项显著下降，$B^{*}$ 会上移，此时不修正模型就会把批上界定得过低。</p>\n<table class=\"mini\"><thead><tr><th>决策对象</th><th>模型给出的量</th><th>失效时的系统代价</th></tr></thead><tbody><tr><td>批上界 $B$</td><td>$B^{*}$（按 p99 求极小）</td><td>按均值调参 → 突发到达下排队击穿补全 SLO</td></tr><tr><td>并行度 TP/PP</td><td>$\\pi_{\\text{eff}},\\beta_{\\text{eff}}$ 代入后的 $B^{*}$ 走向</td><td>忽略通信与气泡 → $\\tau_{\\text{queue}}$ 被低估，TTFT 预测偏乐观</td></tr><tr><td>KV 预算</td><td>$M_{\\text{KV}}(S)$ 的重读时间</td><td>预算给满 → TPOT 带宽项抬高，$T_{\\text{out}}$ 放大后违约</td></tr><tr><td>chunked prefill 块长</td><td>预填项与带宽项的解耦程度</td><td>仍按线性叠加估 TTFT → 实测与预测偏差大</td></tr></tbody></table>\n<p>三种误用对应三种可观测的代价。只按均值时延调 $B$，在突发到达下 $\\tau_{\\text{queue}}$ 的尾部把 p99 推过 SLO，表现为“平均很快、用户偶尔卡死”；在 chunked prefill 部署里继续用线性叠加估 TTFT，预填与解码争抢 SM 的耦合被忽略，容量规划按预测值配卡，上线后 TTFT 系统性偏高；prefix 复用命中后不下调 TPOT 带宽项，$B^{*}$ 定得过低，GPU 在 $\\beta_{\\text{eff}}$ 未饱和的状态下空转，吞吐被无谓牺牲。判断这套模型是否仍然可信，看一个信号即可：把实测 p99 与模型预测的比值按 $B$ 分档画出来，若比值随 $B$ 单调漂移，说明线性叠加已失效，应切换到仿真驱动的批上界搜索，而不是继续在解析式上微调参数。</p>\n<h3 id=\"th-batch-latency-slo-sec-30\">三十 · 误用一：用均值时延调批，把 p99 交给运气</h3>\n<p>最常见的误用是把 <span class=\"sym\">B</span> 的选取建立在对 <span class=\"formula\">$$\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}$$</span> 求均值再最小化的基础上，而不是对 p99 求最小。均值最优化在数学上完全合法，但它优化的对象错了：代码补全的 SLO 通常写在尾部，例如“p99 端到端不超过某阈值”，而均值最优点与 p99 最优点在突发到达下并不重合。机制上，均值把 <span class=\"sym\">τ_queue</span> 压成一个标量，等于假设到达过程平滑；一旦到达是突发的，排队时延的分布有长尾，均值最优点会把 <span class=\"sym\">B</span> 推到偏大一侧，因为大 <span class=\"sym\">B</span> 摊薄了每请求固定开销、均值好看，但每个解码步要重读的 KV 更多，单步时间抬高，尾部请求在队列里等得更久。</p>\n<p>识别方法很直接：把线上同一时段的 <span class=\"sym\">B</span>、实测 TTFT 分布与 TPOT 分布拉出来，若均值 TTFT 稳定而 p99 TTFT 随 <span class=\"sym\">B</span> 上升而恶化，说明调参目标选错了。系统代价体现在两个方向：<span class=\"sym\">B</span> 偏大时单步带宽时间按 <span class=\"formula\">$$\\frac{M_{\\text{KV}}(S)\\,B}{\\beta_{\\text{eff}}}$$</span> 线性增长，尾部请求的 TPOT 被拉长；<span class=\"sym\">B</span> 偏小时固定开销 <span class=\"formula\">$$\\frac{M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 摊不薄，吞吐掉下去而 p99 未必改善。举例：仓库级补全 <span class=\"sym\">S_in</span> 到 10^5、<span class=\"sym\">T_out</span> 在 32–256 之间，若按均值把 <span class=\"sym\">B</span> 定在较大值，突发到达时新请求的 <span class=\"sym\">τ_queue</span> 被前面的大批解码步拖长，p99 端到端击穿 SLO，而均值报表一切正常——这正是“均值合规、尾部违约”的典型形态。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-31\">三十一 · 误用二：chunked prefill 下仍按线性叠加估 TTFT</h3>\n<p>线性叠加假设预填与解码互不干扰，各自占用独立的算力与带宽预算。chunked prefill 恰恰打破这个假设：预填被切成块，与解码步在同一 SM 上交织执行，预填的 MMA 占用与解码的 KV 重读共享同一份 <span class=\"sym\">β_eff</span> 与同一批 SM 周期。此时 <span class=\"formula\">$$\\text{TTFT}\\approx\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}+\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}+\\tau_{\\text{queue}}$$</span> 里的 <span class=\"sym\">π_eff</span> 与 <span class=\"sym\">β_eff</span> 不再是常数，而是随同批解码请求数 <span class=\"sym\">B</span> 变化的耦合量：解码请求越多，预填块能拿到的算力份额越少，第一项被系统性低估。</p>\n<p>后果是容量规划失真：按线性叠加算出的 TTFT 偏乐观，运维据此放大 <span class=\"sym\">B</span> 或收紧副本数，实测 p99 TTFT 却显著高于预测，SLO 在长上下文场景首先崩。识别信号是“预测-实测偏差随 <span class=\"sym\">S_in</span> 增大而增大”——短输入时预填块小、争抢弱，偏差不明显；<span class=\"sym\">S_in</span> 到 10^5 时预填块本身就很重，与解码争抢 SM 的效应被放大。校准手段不是改公式系数，而是把 <span class=\"sym\">π_eff</span>、<span class=\"sym\">β_eff</span> 写成 <span class=\"sym\">B</span> 与 chunk 大小的函数，用实测拟合，再把拟合结果代回 <span class=\"sym\">B*</span> 的搜索。系统代价是双重的：预填块切得太细，解码步被频繁打断、TPOT 抖动；切得太粗，预填独占 SM 时间长，解码请求的 <span class=\"sym\">τ_queue</span> 抬升。这个权衡必须靠实测校准，公式只能给出结构，不能给出数值。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-32\">三十二 · 误用三：prefix 复用命中后不下调 TPOT 带宽项</h3>\n<p>公式的推导前提是“解码每步重读批内全部 KV”。prefix 复用命中后，被复用的前缀 KV 常驻且不再每步重算重读，<span class=\"formula\">$$\\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 的分子实际小于按全量 <span class=\"sym\">M_KV(S)</span> 估算的值。若部署中已经启用前缀缓存却仍按全量 KV 代入公式求 <span class=\"sym\">B*</span>，得到的 <span class=\"sym\">B*</span> 会偏低——因为模型“以为”每步很贵，于是把批压小，牺牲了本可摊薄的吞吐。</p>\n<p>机制上，命中率决定有效 KV 重读量：命中比例越高，TPOT 对 <span class=\"sym\">B</span> 的敏感度越低，<span class=\"sym\">B*</span> 越应上移。识别方法是做一次对照：固定 <span class=\"sym\">B</span>，分别在有、无 prefix 复用的两组请求上测 TPOT，若实测 TPOT 明显低于按全量 KV 的预测值，说明公式的带宽项需要按命中率折减。系统代价是吞吐被无谓牺牲：<span class=\"sym\">B</span> 定得过低，权重读取的固定开销 <span class=\"formula\">$$\\frac{M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 摊不薄，GPU 带宽利用率上不去，单位 token 成本抬高。举例：同一仓库的连续补全请求共享大量前缀，命中后每步只需重读增量 KV，此时把 <span class=\"sym\">B</span> 从按全量 KV 算出的值上调，可在 p99 不变的前提下显著提升吞吐——但前提是先把 TPOT 公式的分子改成“未命中 KV + 命中增量”，否则上调 <span class=\"sym\">B</span> 只是盲目冒险。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-33\">三十三 · 反例：一次把 B* 定错的完整推演</h3>\n<p>设某代码补全服务，<span class=\"sym\">S_in</span> 主体在 10^5 量级（仓库级上下文），<span class=\"sym\">T_out</span> 取 128，SLO 为 p99 端到端不超过给定阈值。团队按线性叠加公式估算：预填算力项与 KV 写入项相加得 TTFT 预测，再用 <span class=\"formula\">$$\\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$$</span> 对 <span class=\"sym\">B</span> 求均值最优，得到一个偏大的 <span class=\"sym\">B</span>，理由是“大批摊薄固定开销、均值吞吐最好”。上线后两个问题同时出现：其一，chunked prefill 已启用，预填块与解码争抢 SM，实测 TTFT 高于预测，且 <span class=\"sym\">S_in</span> 越长偏差越大；其二，突发到达时 <span class=\"sym\">τ_queue</span> 的长尾把 p99 端到端推过 SLO，而均值报表仍显示达标。</p>\n<p>正确的推演顺序应是：先用实测校准 <span class=\"sym\">π_eff</span>、<span class=\"sym\">β_eff</span> 随 <span class=\"sym\">B</span> 的耦合关系；再按 prefix 命中率折减 TPOT 分子；最后用 M/G/1 或仿真求 p99 端到端分布，对 <span class=\"sym\">B</span> 搜索 <span class=\"formula\">$$B^{*}=\\arg\\min_{B}\\;\\text{p99}\\!\\left(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT}\\right)$$</span>。这个反例的教训不是“公式错了”，而是公式的三个前提——线性叠加、全量 KV 重读、均值可代表尾部——在真实部署里同时不成立时，<span class=\"sym\">B*</span> 会被推向错误方向。识别这类错误的通用判据是：预测与实测的偏差是否随 <span class=\"sym\">S_in</span>、<span class=\"sym\">B</span>、突发强度三者之一单调增大；若是，先怀疑前提失效，再怀疑参数标定。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-34\">三十四 · 把误用变成检查项：上线前的四个对照</h3>\n<p>把上述误用固化成上线前的对照实验，比事后调参便宜得多。第一，均值对照：同一 <span class=\"sym\">B</span> 下比较均值与 p99 端到端，若两者随 <span class=\"sym\">B</span> 的变化方向不一致，说明尾部主导，<span class=\"sym\">B*</span> 必须按 p99 求。第二，预填对照：固定 <span class=\"sym\">B</span>，扫 <span class=\"sym\">S_in</span> 从短到 10^5，看 TTFT 预测偏差是否随 <span class=\"sym\">S_in</span> 增大，若是则 chunked prefill 的耦合未被建模。第三，命中对照：开、关 prefix 复用各测一组 TPOT，按实测比值折减带宽项后再求 <span class=\"sym\">B*</span>。第四，突发对照：用泊松与突发两种到达过程各跑一遍仿真，比较两种到达下 p99 最优的 <span class=\"sym\">B</span> 是否一致；不一致说明 <span class=\"sym\">τ_queue</span> 的尾部分布不能省略。</p>\n<p>这四项对照的系统代价都很低——每组只需固定 <span class=\"sym\">B</span> 扫一个维度，不需要全网格搜索——但它们能挡住三类高频误用。真正昂贵的是误用上线后的代价：<span class=\"sym\">B</span> 偏大时尾部违约触发告警与回滚，<span class=\"sym\">B</span> 偏小时吞吐浪费直接体现为单位 token 成本。工程判断上，宁可把 <span class=\"sym\">B*</span> 的搜索做成带前提校验的流程，也不要把公式当成黑箱直接代参数：公式给的是结构，前提给的是适用域，两者缺一，<span class=\"sym\">B*</span> 就只是一个看起来精确的错误答案。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-35\">三十五 · 批上界的三类误用：均值陷阱、叠加幻觉与复用失算</h3>\n<p>这套时延模型最容易被误用的地方，不是公式本身写错，而是把它的三个前提当成无条件成立。第一个前提是 p99 可解：$B^{*}=\\arg\\min_{B}\\ \\text{p99}(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT})$ 要求排队时延 $\\tau_{\\text{queue}}$ 的尾部分布已知，而 $\\tau_{\\text{queue}}$ 由到达过程决定——代码补全的请求到达既非严格泊松，也常在保存文件、切换分支、批量重构时突发成簇。工程上常见的做法是拿一段时间的均值时延曲线扫 $B$，取均值最低点当 $B^{*}$，结果在突发窗口里排队项被放大数倍，p99 端到端时延击穿补全 SLO。识别方法很直接：把同一 $B$ 下的时延分布按到达率分桶画出来，若均值曲线平缓而高分位曲线在某一 $B$ 之后陡升，说明 $B^{*}$ 已被均值掩盖；此时应改用 M/G/1 近似或离散事件仿真求尾部分布，而不是继续用均值扫参。代价是显性的——为压 p99 而把 $B$ 调小，解码步摊薄不足，每请求固定开销占比上升，吞吐下降；但若不调，突发时违约的补全请求会成片超时，重试又进一步抬高到达率，形成正反馈。</p>\n<p>第二个误用出现在 chunked prefill 部署里：仍按 $\\text{TTFT}\\approx\\frac{2N_{\\text{active}}S_{\\text{in}}}{\\pi_{\\text{eff}}}+\\frac{M_{\\text{KV}}(S_{\\text{in}})}{\\beta_{\\text{eff}}}+\\tau_{\\text{queue}}$ 做线性叠加估算。这个式子的隐含假设是预填与解码互不干扰，各自占用独立的算力与带宽预算；但在同一 SM 上二者交织执行，chunked prefill 把长预填切成小块插入解码步之间，预填的 MMA 占用会挤占解码步的带宽窗口，解码的 KV 重读又反过来拉长预填分块的有效算力时间。结果是实测 TTFT 系统性高于预测，且偏差随 $S_{\\text{in}}$ 增大而扩大——仓库级上下文 $S_{\\text{in}}$ 可达 $10^5$，此时预填算力项本就占主导，争抢带来的耦合误差足以让按公式选出的 $B$ 偏离真实最优。识别信号是：同一 $B$ 下把 chunk size 调小，若 TTFT 不降反升或 TPOT 同步恶化，说明耦合已经显著，公式的加法结构失效。此时应把 $\\pi_{\\text{eff}}$ 与 $\\beta_{\\text{eff}}$ 视为随 chunk 配置变化的实测标定量，用一组 chunk size 扫描做校准，而不是沿用离线测得的固定值。</p>\n<p>第三个误用与 prefix 复用有关。TPOT 公式 $\\text{TPOT}\\approx\\frac{M_{\\text{KV}}(S)\\,B+M_{\\text{weights}}}{\\beta_{\\text{eff}}}$ 假设解码每步重读批内全部 KV；一旦 prefix 复用命中，被复用的前缀 KV 可驻留或分块复用，实际重读量显著低于 $M_{\\text{KV}}(S)\\cdot B$，带宽项下降，$B^{*}$ 理应上移。若部署中已开启 prefix 缓存却仍按未命中情形定 $B$，批上界被压在过低位置，解码步摊薄不足，吞吐被无谓牺牲——这是三个误用里唯一“保守反而吃亏”的情形。识别方法是统计命中率与实测 TPOT 的比值：命中率上升而 TPOT 未按预期下降，说明带宽项没被正确下调；反之若 TPOT 明显低于公式预测而 $B$ 未上调，就是 $B^{*}$ 定低的直接证据。修正时把 $\\beta_{\\text{eff}}$ 的有效分母按命中比例折算，重新解 $B^{*}$，并注意复用命中率本身随批内请求的上下文相似度变化，$B$ 增大可能降低平均命中率，二者需联合扫描而非单向调参。</p>\n<p>三类误用共享同一个工程判断：这套模型的输出是<strong>批上界的初值</strong>，不是可以直接下发的配置。它把 TTFT 拆成预填算力、KV 写入与排队三项，把 TPOT 拆成 KV 重读与权重读取两项，价值在于指出每一项随 $B$、$S_{\\text{in}}$、$T_{\\text{out}}$ 的走向，从而给出“往哪个方向调”的信号；但 $\\pi_{\\text{eff}}$、$\\beta_{\\text{eff}}$、$\\tau_{\\text{queue}}$ 的尾部分布、以及 chunked prefill 与 prefix 复用带来的耦合，都必须在目标部署上实测标定。一个可操作的反例是：某代码补全服务按均值扫参把 $B$ 定在较大值，仓库级长上下文请求突发时排队项击穿 p99，同时 chunked prefill 的争抢使实测 TTFT 高于预测，运维误以为是模型算错而继续加大 $B$ 摊薄开销，结果 TPOT 与 TTFT 同步恶化；正确动作是先用仿真求尾部分布定 $B$ 的上界，再按 chunk 配置校准 $\\pi_{\\text{eff}}$，最后按 prefix 命中率下调 TPOT 带宽项，三步都做完才谈得上把 $B^{*}$ 落到配置里。</p>\n\n<h3 id=\"th-batch-latency-slo-sec-36\">三十六 · 误用诊断：从均值陷阱到耦合盲区</h3>\n<p>最常见的误用是把 <span class=\"sym\">B</span> 调到均值时延最低的点，而不是按 <span class=\"sym\">\\(B^{*}=\\arg\\min_{B}\\;\\text{p99}(\\text{TTFT}+T_{\\text{out}}\\cdot\\text{TPOT})\\)</span> 求解。均值最优的批往往偏大：因为 <span class=\"sym\">τ_queue</span> 的尾部在突发到达下呈非线性抬升，均值项被大量小排队样本稀释，而 p99 已被少数长排队请求击穿。识别方法很直接——在同一 <span class=\"sym\">B</span> 下同时记录均值与 p99 的 TTFT，若两者比值随 <span class=\"sym\">B</span> 增大而扩大，说明批已越过 p99 拐点。代价是吞吐指标好看、SLO 违约率上升：代码补全 <span class=\"sym\">\\(T_{\\text{out}}\\)</span> 仅 32–256，端到端时延里 TPOT 项占比小，p99 几乎完全由 <span class=\"sym\">τ_queue</span> 尾部决定，此时把 <span class=\"sym\">B</span> 按均值推到上限，等于用补全体验换纸面吞吐。</p>\n<p>第二类误用出现在 chunked prefill 部署里：仍用线性叠加式估算 TTFT，把预填算力项 <span class=\"sym\">\\(2N_{\\text{active}}S_{\\text{in}}/\\pi_{\\text{eff}}\\)</span> 与解码带宽项当成可加的两段。实际上 chunk 与解码步在同一 SM 上交替占用，预填的 MMA 占用会挤掉解码的带宽窗口，二者耦合使实测 TTFT 系统性偏离预测，且偏差随 <span class=\"sym\">\\(S_{\\text{in}}\\)</span> 增大而放大——仓库级上下文 <span class=\"sym\">\\(S_{\\text{in}}\\)</span> 可达 <span class=\"sym\">10^5</span>，此时预填 chunk 数多、交织次数多，耦合误差不可忽略。识别信号是：把 chunk 尺寸减半后 TTFT 不降反升，或 TPOT 随预填负载同步抖动，即说明两阶段争抢已成主导。工程上必须以实测校准替代公式直算，把 <span class=\"sym\">\\(π_{\\text{eff}}\\)</span> 视为随 chunk 配置变化的经验量而非常数。</p>\n<p>第三类误用方向相反：prefix 复用命中或 KV 分块驻留生效后，解码每步不再重读全 KV，<span class=\"sym\">\\(M_{\\text{KV}}(S)\\,B\\)</span> 项显著下降，但调参者仍沿用旧 <span class=\"sym\">\\(β_{\\text{eff}}\\)</span> 与旧曲线，把 <span class=\"sym\">B^{*}</span> 定得过低。此时 TPOT 对 <span class=\"sym\">B</span> 的敏感度已减弱，最优批应上移；继续用小批等于主动放弃摊薄固定开销的机会，吞吐被无谓牺牲而 p99 并无改善。识别方法是做一次 <span class=\"sym\">B</span> 扫描并观察 TPOT 斜率：若斜率明显低于无复用时的预期，就应重估 <span class=\"sym\">B^{*}</span>。三类误用共享一个根因——把模型当成静态公式而非随部署形态（到达过程、chunk 配置、复用命中率）漂移的近似，因此每次变更调度策略或缓存策略后都应重跑 p99 扫描，而不是复用上一版参数。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>按均值定批</td><td>均值/p99 比值随 B 扩大</td><td>突发下 SLO 违约</td></tr><tr><td>线性叠加估 TTFT</td><td>chunk 减半 TTFT 反升</td><td>预填阻塞解码、尾延迟抖动</td></tr><tr><td>复用命中后不调 B*</td><td>TPOT 对 B 斜率偏低</td><td>吞吐无谓损失</td></tr></tbody></table>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>S_{\\text{in}}</td><td>输入（预填）token 数，仓库级上下文可达 10^5</td></tr><tr><td>T_{\\text{out}}</td><td>输出 token 数（代码补全通常 32–256）</td></tr><tr><td>\\pi_{\\text{eff}}</td><td>预填阶段有效算力（受 MMA 利用率与 attention 非线性影响）</td></tr><tr><td>\\beta_{\\text{eff}}</td><td>解码阶段有效带宽</td></tr><tr><td>\\tau_{\\text{queue}}</td><td>调度排队时延</td></tr><tr><td>B^{*}</td><td>使 p99 端到端时延最小的批大小</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-batch-latency-slo · 共 5 个片段</p>\n"},{"id":"th-quant-error-bound","title":"量化误差与草稿模型保真界","direction":"dir-structured-decode","prereq":[],"plain":"把目标模型或草稿模型量化到低比特，单层权重量化误差以 ℓ2 范数上界传播，经 L 层放大后进入 logits；投机解码的接受率对草稿与目标分布的总变差距离敏感，量化草稿会直接压低接受长度。","definition":"把目标模型或草稿模型量化到低比特，单层权重量化误差以 ℓ2 范数上界传播，经 L 层放大后进入 logits；投机解码的接受率对草稿与目标分布的总变差距离敏感，量化草稿会直接压低接受长度。","formula":"$$\\|\\Delta \\mathbf{h}_L\\|_2\\le\\left(\\prod_{l=1}^{L}\\|W_l\\|_2\\right)\\sum_{l=1}^{L}\\frac{\\|\\Delta W_l\\|_2}{\\|W_l\\|_2}\\|\\mathbf{h}_{l-1}\\|_2,\\qquad \\mathbb{E}[\\text{accept}]\\ge 1-\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})\\ge 1-\\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})}$$","variables":[{"sym":"\\Delta W_l","meaning":"第 l 层权重量化误差矩阵"},{"sym":"\\|W_l\\|_2","meaning":"第 l 层权重谱范数"},{"sym":"\\mathbf{h}_{l-1}","meaning":"第 l 层输入激活"},{"sym":"p_{\\text{draft}}","meaning":"草稿模型下一 token 分布"},{"sym":"p_{\\text{target}}","meaning":"目标模型下一 token 分布"},{"sym":"\\mathrm{TV}","meaning":"总变差距离"}],"derivation":"接受率界 $$\\mathbb{E}[\\text{accept}]\\ge 1-\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})\\ge 1-\\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})}$$ 中 $p_{\\text{draft}}$ 为草稿模型下一 token 分布，$p_{\\text{target}}$ 为目标模型分布，$\\mathrm{TV}$ 为总变差距离；TV 越小接受率越高，KL 通过 Pinsker 不等式给出更松的下界。","example":"适用边界是稠密 Transformer 且草稿与目标共享词表与采样温度；失效条件包括谱范数乘积上界极松、实际误差常低数个数量级，该界只用于判断量化是否可能崩溃而不能预测 perplexity 或 pass@1 的具体退化；TV/KL 界假设逐 token 独立同分布，温度缩放与 top-p 截断会改变接受率需按实际采样分布重算；未刻画离群通道与 per-group scaling 的非均匀误差。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["谱范数乘积上界极松，实际误差常低数个数量级；该界只用于判断量化是否可能崩溃，不能预测 perplexity 或 pass@1 的具体退化","TV/KL 界假设逐 token 独立同分布，且草稿与目标共享词表与采样温度；温度缩放、top-p 截断会改变接受率，公式需按实际采样分布重算","未刻画离群通道（outlier channel）与 per-group scaling 的非均匀误差；INT4 权重量化在代码模型上对长尾 token（标识符、数字）的伤害远大于均值误差所示"],"system_note":"在推理容量决策中，该界用于判断草稿模型能否量化到低比特而不崩接受率：若 TV 界给出的接受率下界已低于可接受阈值，则不应量化草稿；同时谱范数乘积可用于筛查哪些层的量化误差会被放大，指导混合精度分配。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["把目标模型或草稿模型量化到低比特，单层权重量化误差以 $\\ell_2$ 范数上界传播，经 $L$ 层放大后进入 logits；投机解码的接受率对草稿与目标分布的总变差距离敏感，量化草稿会直接压低接受长度。","误差传播界 $$\\|\\Delta \\mathbf{h}_L\\|_2\\le\\left(\\prod_{l=1}^{L}\\|W_l\\|_2\\right)\\sum_{l=1}^{L}\\frac{\\|\\Delta W_l\\|_2}{\\|W_l\\|_2}\\|\\mathbf{h}_{l-1}\\|_2$$ 中 $\\Delta W_l$ 为第 $l$ 层权重量化误差矩阵，$\\|W_l\\|_2$ 为谱范数，$\\mathbf{h}_{l-1}$ 为第 $l$ 层输入激活；谱范数乘积刻画逐层放大，相对误差项刻画每层注入。","接受率界 $$\\mathbb{E}[\\text{accept}]\\ge 1-\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})\\ge 1-\\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})}$$ 中 $p_{\\text{draft}}$ 为草稿模型下一 token 分布，$p_{\\text{target}}$ 为目标模型分布，$\\mathrm{TV}$ 为总变差距离；TV 越小接受率越高，KL 通过 Pinsker 不等式给出更松的下界。","推导的关键一步是把每层量化误差视为加性扰动，用谱范数把扰动从 $\\mathbf{h}_{l-1}$ 传到 $\\mathbf{h}_l$ 并逐层累乘，得到 $\\ell_2$ 上界；接受率一侧则用 TV 距离界定拒绝概率，再用 Pinsker 不等式把 TV 换成更易估计的 KL。","适用边界是稠密 Transformer 且草稿与目标共享词表与采样温度；失效条件包括谱范数乘积上界极松、实际误差常低数个数量级，该界只用于判断量化是否可能崩溃而不能预测 perplexity 或 pass@1 的具体退化；TV/KL 界假设逐 token 独立同分布，温度缩放与 top-p 截断会改变接受率需按实际采样分布重算；未刻画离群通道与 per-group scaling 的非均匀误差。","在推理容量决策中，该界用于判断草稿模型能否量化到低比特而不崩接受率：若 TV 界给出的接受率下界已低于可接受阈值，则不应量化草稿；同时谱范数乘积可用于筛查哪些层的量化误差会被放大，指导混合精度分配。","常见误用是把极松的谱范数乘积上界当作实际误差估计，据此过度保守地放弃量化；另一误用是忽略 INT4 权重量化在代码模型上对长尾 token（标识符、数字）的伤害远大于均值误差所示；还有误用是在温度缩放或 top-p 截断后仍用原始分布的 TV/KL 界估接受率。"],"anchors":["未给出"],"pitfalls":["把极松的谱范数乘积上界当实际误差，过度保守放弃量化，损失本可获得的带宽收益。","忽略 INT4 量化对代码长尾 token（标识符、数字）的伤害，均值误差达标但 pass@1 明显退化。","温度缩放或 top-p 截断后仍用原始分布 TV/KL 界估接受率，投机解码接受长度被高估。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-1\">一 · 一句话直觉：误差不是“平均掉”，而是被逐层放大后压到采样分布上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-2\">二 · 严格定义：两个界各自的量、假设与推导骨架</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-3\">三 · 为什么需要：两个界分别卡住“能不能量化”和“草稿能不能压”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-4\">四 · 常见误解之一：把极松的上界当成实际误差估计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-5\">五 · 常见误解之二：均值误差达标就等于模型保真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-6\">六 · 常见误解之三：采样改造后仍套用原始 TV/KL 界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-7\">七 · 两个上界各自管什么、不管什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-8\">八 · 误差传播界：逐项拆解与谱范数的角色</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-9\">九 · 推导关键步：加性扰动、逐层传递、连乘放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-10\">十 · 接受率界：TV 界定拒绝概率，Pinsker 换 KL</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-11\">十一 · 两套界的耦合点：量化草稿同时踩两条线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-12\">十二 · 失效条件的工程读法：界是守门员不是估价师</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-13\">十三 · 稠密假设：界从哪里开始松动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-14\">十四 · 谱范数乘积：极松的上界与筛查用法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-15\">十五 · 独立同分布假设：采样分布一变，界就失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-16\">十六 · 非均匀误差：离群通道与 per-group scaling</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-17\">十七 · 规模上限：层数、词表与批维度的三重约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-18\">十八 · 边界在哪里：谱范数乘积、TV 界与采样分布的三重失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-19\">十九 · 边界之外：谱范数乘积为何只是崩溃筛查器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-20\">二十 · 把界翻译成容量决策变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-21\">二十一 · 用 TV 界定草稿模型精度与投机并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-22\">二十二 · KV 预算与 SLO 的联动定法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-23\">二十三 · 算例：三层决策的串联</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-24\">二十四 · 把界当成容量决策的筛子：阈值、预算与失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-25\">二十五 · 把上界当估计：谱范数乘积的过度保守误用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-26\">二十六 · 均值误差达标而长尾崩掉：代码模型上的 INT4 反例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-27\">二十七 · 采样分布变了，界没跟着变</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-28\">二十八 · 忽略非均匀误差：per-group scaling 与离群通道</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-29\">二十九 · 界的正确位置：筛查而非预测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-quant-error-bound-sec-30\">三十 · 误用与反例：当上界被当作预言</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:597px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 597.1 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：把目标模型或草稿模型量化到低比特，单层权重量化误差以 ℓ2 范数上…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\|\\Delta \\mathbf{h}_L\\|_2\\le\\le…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：谱范数乘积上界极松，实际误差常低数个数量级；该界只用于判断量化是否…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-quant-error-bound-sec-1\">一 · 一句话直觉：误差不是“平均掉”，而是被逐层放大后压到采样分布上</h3>\n<p>把权重压到低比特，本质是给每一层的线性映射注入一个加性扰动 $\\Delta W_l$。工程直觉容易停在“量化误差很小、均值接近零、应该没事”，但推理链路真正关心的是这个扰动经过 $L$ 层谱范数连乘之后，落到最后一层隐藏状态 $\\mathbf{h}_L$ 上的 $\\ell_2$ 幅度，以及它最终如何改变 logits 与采样分布。误差传播界与接受率界是同一件事的两端：前者回答“量化会不会把激活打崩”，后者回答“草稿分布偏离目标分布多远时，投机解码的接受长度会塌”。一句话直觉可以写成：**单层误差按相对量注入，按谱范数逐层放大，最后以总变差距离的形式折算成投机解码的接受率损失。** 这句话里没有任何“平均”的位置——均值误差为零不代表 $\\ell_2$ 误差为零，更不代表采样分布不变。</p>\n<p>需要强调的是，这两个界服务于不同的决策。误差传播界是**崩溃筛查器**：它给出的是最坏情况的上界，用来判断某组量化配置是否已经把模型推到数值失效的边缘。接受率界是**草稿保真度判据**：它把草稿模型与目标模型的分布差异折算成期望接受概率的下界，直接对应投机解码的有效吞吐。两者共享同一个物理量——分布偏移，但一个从权重侧度量，一个从输出侧度量。</p>\n\n<h3 id=\"th-quant-error-bound-sec-2\">二 · 严格定义：两个界各自的量、假设与推导骨架</h3>\n<p>先固定符号。第 $l$ 层权重量化误差矩阵记为 $\\Delta W_l$，该层权重谱范数为 $\\|W_l\\|_2$，第 $l$ 层输入激活为 $\\mathbf{h}_{l-1}$。把量化视为加性扰动后，逐层递推并累乘，得到隐藏状态的 $\\ell_2$ 上界：</p>\n<div class=\"formula\">$$\\|\\Delta \\mathbf{h}_L\\|_2\\le\\left(\\prod_{l=1}^{L}\\|W_l\\|_2\\right)\\sum_{l=1}^{L}\\frac{\\|\\Delta W_l\\|_2}{\\|W_l\\|_2}\\|\\mathbf{h}_{l-1}\\|_2$$</div>\n<p>结构上它分成两个因子：$\\prod_l \\|W_l\\|_2$ 是**放大因子**，刻画扰动从底层传到顶层能被放大多少倍；求和项里的 $\\|\\Delta W_l\\|_2/\\|W_l\\|_2$ 是**相对注入项**，刻画每层自己注入了多少相对误差，再乘上该层输入激活的幅度。推导的关键一步是把每层量化误差当作加性扰动，用谱范数把扰动从 $\\mathbf{h}_{l-1}$ 传到 $\\mathbf{h}_l$，逐层累乘得到 $\\ell_2$ 上界。这个定义域很明确：稠密 Transformer、逐层线性映射、扰动可加。</p>\n<p>再看接受率一侧。设草稿模型下一 token 分布为 $p_{\\text{draft}}$，目标模型分布为 $p_{\\text{target}}$，$\\mathrm{TV}$ 为总变差距离。投机解码的接受率对两者的 TV 距离敏感，量化草稿会直接压低接受长度：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{accept}]\\ge 1-\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})\\ge 1-\\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})}$$</div>\n<p>推导骨架是：用 TV 距离界定拒绝概率，再用 Pinsker 不等式把 TV 换成更易估计的 KL。TV 越小接受率越高，KL 给出的是更松的下界。这里的假设必须写清楚：逐 token 独立同分布，草稿与目标共享词表与采样温度。任何一条不成立，公式的数值就不再对应真实接受率。</p>\n\n<h3 id=\"th-quant-error-bound-sec-3\">三 · 为什么需要：两个界分别卡住“能不能量化”和“草稿能不能压”</h3>\n<p>在推理容量决策里，这两个界承担的是**否决权**而非**预测器**。误差传播界的用途是筛查：谱范数乘积刻画逐层放大，相对误差项刻画每层注入，二者结合可以判断某组量化配置是否可能让激活数值崩溃。它还能指导混合精度分配——哪些层的 $\\|W_l\\|_2$ 偏大、相对误差项偏大，就说明这些层的量化误差会被放大，应保留更高精度，其余层放手压到低比特以换取带宽收益。这是一个纯结构性的判断，不依赖任何实测 perplexity。</p>\n<p>接受率界的用途更直接：判断草稿模型能否量化到低比特而不崩接受率。若 TV 界给出的接受率下界已经低于可接受阈值，则不应量化草稿——因为投机解码的收益完全建立在接受长度上，接受率一旦塌，草稿再便宜也没有意义。反过来，若下界仍高于阈值，量化草稿换来的带宽与显存节省就是净收益。这里必须注意界的松紧：TV 界本身已经偏松，KL 经 Pinsker 之后更松，所以“下界高于阈值”是充分条件而非必要条件；真正危险的信号是下界已经低于阈值，此时没有讨论余地。</p>\n<p>两个界共同回答了一个工程问题：低比特量化的代价不是均匀摊在均值上的，而是集中在被谱范数放大的层与被 TV 距离放大的 token 上。忽略这一点，就会在“均值误差达标”的假象下接受一个实际已经崩掉的配置。</p>\n\n<h3 id=\"th-quant-error-bound-sec-4\">四 · 常见误解之一：把极松的上界当成实际误差估计</h3>\n<p>最普遍的误用是把谱范数乘积上界当作实际误差估计，据此过度保守地放弃量化。这个上界极松，实际误差常低数个数量级——因为谱范数乘积假设每层扰动都沿着最坏方向对齐，而真实量化误差在层间并不相干，激活分布也远非最坏情况。把上界当预测值，会得出“任何低比特量化都会崩”的错误结论，从而损失本可获得的带宽收益。</p>\n<p>正确的用法是把它当**崩溃筛查器**：只有当上界已经大到离谱时，才说明这组配置有数值失效风险；上界在合理范围内时，它不提供任何“实际会退化多少”的信息。它不能预测 perplexity 或 pass@1 的具体退化，这一点必须在决策文档里写死，否则工程团队会拿它当精度预算表用。一个具体例子：某层 $\\|W_l\\|_2$ 很大导致乘积项膨胀，上界报警，但该层激活幅度很小、相对误差项也小，实际贡献有限；此时应做的是对该层单独保留高精度并复测，而不是整体放弃量化。</p>\n\n<h3 id=\"th-quant-error-bound-sec-5\">五 · 常见误解之二：均值误差达标就等于模型保真</h3>\n<p>第二个误用是忽略 INT4 权重量化在代码模型上对长尾 token 的伤害远大于均值误差所示。标识符、数字这类 token 在词表里处于长尾，其 logits 对权重扰动的敏感度远高于高频 token；均值误差被高频 token 稀释后看起来很小，但长尾 token 的采样分布已经偏移，pass@1 明显退化。这就是“均值达标、任务崩”的典型路径。</p>\n<p>这个误解与界的假设直接相关：误差传播界只给 $\\ell_2$ 幅度，不给逐 token 的分布偏移；接受率界虽然逐 token 度量 TV，但它假设独立同分布，无法刻画长尾 token 的系统性偏移。因此两个界都不能替代按任务形态的抽样验证。工程判断应是：代码、数学这类长尾 token 密集的领域，量化配置的验收必须看任务指标而非均值误差；界只用来排除崩溃，不用来签发精度合格证。</p>\n\n<h3 id=\"th-quant-error-bound-sec-6\">六 · 常见误解之三：采样改造后仍套用原始 TV/KL 界</h3>\n<p>第三个误用是在温度缩放或 top-p 截断后仍用原始分布的 TV/KL 界估接受率，导致投机解码接受长度被高估。TV/KL 界假设草稿与目标共享词表与采样温度，且逐 token 独立同分布；一旦引入温度缩放或 top-p 截断，实际采样分布已被改造，接受率必须按实际采样分布重算。原始分布上的 TV 小，不代表改造后的采样分布 TV 也小——截断会放大分布尾部的相对差异，温度缩放会改变分布的尖锐程度，两者都会让接受率偏离原始界的估计。</p>\n<p>还有一个未被界刻画的维度：离群通道与 per-group scaling 的非均匀误差。per-group scaling 让不同通道的量化步长不同，误差不再均匀，谱范数上界无法刻画这种非均匀性；离群通道的误差可能远大于均值，而界只给一个全局 $\\ell_2$ 幅度。这意味着界在存在显著离群通道的模型上会系统性低估风险。工程上的应对是把界当作必要条件：界通过不代表安全，界报警则一定有问题；真正的验收要靠按实际采样分布重算的接受率与任务指标。</p>\n<p>把这三个误解放在一起看，会发现它们共享同一个错误结构：把界当成预测器。界的正确位置是**否决权与筛查器**——它告诉你什么时候不能做，不告诉你做了之后能拿到多少。推理系统里真正决定量化配置的，是带宽收益与任务指标的联合权衡；界的作用是在权衡之前先把明显会崩的选项划掉。</p>\n\n<h3 id=\"th-quant-error-bound-sec-7\">七 · 两个上界各自管什么、不管什么</h3>\n<p>这套方案由两条互相独立的界拼成：一条管「量化之后隐藏状态能歪多远」，一条管「歪了之后投机解码还能接受多少」。前者是谱范数乘积式的误差传播界，把每层量化误差矩阵 ΔW_l 当作加性扰动，用 ‖W_l‖₂ 逐层放大并累乘，得到 ‖Δh_L‖₂ 的上界；后者用草稿与目标分布的总变差距离 TV 界定拒绝概率，再用 Pinsker 不等式换成更易估计的 KL。两条界的角色完全不同：误差传播界回答「量化会不会把模型打崩」，接受率界回答「草稿量化后还能不能换来加速」。把它们混成一个「量化损失估计器」是这一节要划清的边界。</p>\n<p>误差传播界的失效条件首先是松。谱范数乘积 ∏‖W_l‖₂ 在深层稠密 Transformer 上通常远大于 1，而实际量化误差常比该上界低数个数量级，因为真实激活并不落在谱范数取到的最坏方向上，逐层误差也大量相消。因此它只能做崩溃筛查：若上界本身已经小到不足以威胁 logits 量级，量化基本安全；若上界巨大，也不能据此断定会崩，只能说明该层组合对扰动敏感，值得单独测。它无法预测 perplexity 或 pass@1 的具体退化，因为这两者取决于误差在词表长尾上的分布，而非 ℓ2 总量。</p>\n<p>接受率界的失效条件更隐蔽。TV/KL 界假设逐 token 独立同分布，且草稿与目标共享词表与采样温度；一旦启用温度缩放或 top-p 截断，实际采样分布被重塑，原始 p_draft、p_target 上的 TV 不再对应真实拒绝概率，必须按截断后的分布重算，否则会系统性高估接受长度。此外该界未刻画离群通道与 per-group scaling 带来的非均匀误差——同一层内不同通道的量化误差可以差出数量级，ℓ2 总量达标不代表关键通道没被破坏。工程上最典型的翻车是 INT4 权重量化用于代码模型：标识符与数字落在词表长尾，均值误差看起来合格，pass@1 却明显退化。</p>\n<table class=\"mini\"><thead><tr><th>界</th><th>能回答</th><th>不能回答</th><th>系统代价</th></tr></thead><tbody><tr><td>谱范数误差传播</td><td>量化是否可能崩溃、哪些层对扰动敏感</td><td>perplexity / pass@1 的具体退化</td><td>逐层谱范数估计需额外算力与显存，离线一次性</td></tr><tr><td>TV/KL 接受率</td><td>草稿能否量化到低比特而不崩接受长度</td><td>截断/温度后的真实接受率、长尾 token 伤害</td><td>需在线或离线采样估计两分布，采样开销换容量决策置信度</td></tr></tbody></table>\n<p>容量决策上的用法因此是「双向闸门」：先用接受率界算出下界，若已低于可接受阈值，就不该量化草稿——省下的带宽抵不过接受长度缩短带来的目标模型前向次数上升；若下界仍有余量，再用谱范数乘积筛查哪些层的量化误差会被放大，把混合精度预算压到这些层上，其余层放开到更低比特。代价是这两步都要额外的离线测量：谱范数估计与分布采样都不是零成本，但它们换掉的是线上反复试错的 GPU 小时。</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{accept}]\\ge 1-\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})\\ge 1-\\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})}$$</div>\n<h3 id=\"th-quant-error-bound-sec-8\">八 · 误差传播界：逐项拆解与谱范数的角色</h3>\n<p>误差传播界写成一行不等式，但每一项都对应推理系统里一个可测量的量。左边 $\\|\\Delta \\mathbf{h}_L\\|_2$ 是第 $L$ 层输出激活相对全精度激活的 ℓ2 偏差，它最终线性映射进 logits，因此这个量是量化是否“崩”的第一道闸门。右边乘积 $\\prod_{l=1}^{L}\\|W_l\\|_2$ 是逐层权重谱范数的连乘，刻画的是网络对扰动的放大能力：谱范数就是该层线性映射在 ℓ2 意义下的最大拉伸倍数，连乘即整条残差主干的最坏情况增益。求和项 $\\sum_{l=1}^{L}\\frac{\\|\\Delta W_l\\|_2}{\\|W_l\\|_2}\\|\\mathbf{h}_{l-1}\\|_2$ 是每层注入误差的相对量乘以该层输入激活的幅度——$\\|\\Delta W_l\\|_2/\\|W_l\\|_2$ 是量化误差相对于权重本身的相对谱扰动，$\\|\\mathbf{h}_{l-1}\\|_2$ 决定这份扰动被激活放大到多大绝对值。两项相乘再相加，含义清晰：每一层往主干里注入一份绝对误差，随后被后续所有层的谱范数连乘放大。</p>\n<p>工程上要抓住的是两个因子的量级差异。谱范数连乘在稠密 Transformer 上通常远大于 1，而相对谱扰动在 NVFP4/FP8 权重量化下通常是百分之一到十分之一量级。这意味着上界的主导项往往不是单层误差大小，而是“哪一层的 $\\|\\mathbf{h}_{l-1}\\|_2$ 特别大”或“哪一层的谱范数特别大”。前者指向激活离群通道——某些通道的激活幅度比均值高一个量级以上，per-group scaling 若按组均一化就会在这些通道上留下大残差；后者指向那些权重谱范数偏大的层（常见于 attention 输出投影与 MLP 下投影）。这条界因此在混合精度分配里直接可用：把 $\\|W_l\\|_2$ 与 $\\|\\mathbf{h}_{l-1}\\|_2$ 联合排序，谱范数大且输入激活大的层保留 FP8，其余层下探到 NVFP4，能在不触碰崩溃区的前提下拿到带宽收益。</p>\n<p>代价侧要算清楚：这条界本身不产生运行时开销，但它约束了精度选择，而精度选择直接决定权重带宽。以 B200 的 HBM3e 带宽为背景，权重从 FP8 降到 NVFP4 意味着每 token 每层读取的字节数减半，解码阶段的 roofline 带宽界（见同模块解码 roofline 条目）会把这一半直接翻译成吞吐上限的提升。反过来，若因误判上界过松而全模型保留 FP8，损失的就是这份带宽。这条界不能预测 perplexity 或 pass@1 的具体退化，只能回答“会不会崩”这个二值问题——把它当精度预算的守门员，而不是精度预算的估价师。</p>\n\n<h3 id=\"th-quant-error-bound-sec-9\">九 · 推导关键步：加性扰动、逐层传递、连乘放大</h3>\n<p>推导的骨架只有三步，每一步都藏着一个近似。第一步把量化写成加性扰动：$\\tilde{W}_l = W_l + \\Delta W_l$，并假设量化误差与激活、与后续层无关。这一步在数学上是恒等变形，但在物理上已经丢掉了量化误差与激活分布的相关性——per-group scaling 下，误差大小依赖该组的激活范围，而激活范围又依赖输入，所以 $\\Delta W_l$ 并非独立于 $\\mathbf{h}_{l-1}$。这个相关性正是后面“界极松”的根源之一。</p>\n<p>第二步做单层传递。第 $l$ 层输出偏差为 $\\Delta \\mathbf{h}_l = W_l \\Delta \\mathbf{h}_{l-1} + \\Delta W_l \\mathbf{h}_{l-1}$（忽略非线性与归一化的雅可比，这是第二个近似：把 LayerNorm/RMSNorm 与激活函数视为 1-Lipschitz 或干脆视为恒等）。取 ℓ2 范数并用谱范数放缩，得 $\\|\\Delta \\mathbf{h}_l\\|_2 \\le \\|W_l\\|_2 \\|\\Delta \\mathbf{h}_{l-1}\\|_2 + \\|\\Delta W_l\\|_2 \\|\\mathbf{h}_{l-1}\\|_2$。这是一个线性递推，第三步就是把它展开：把每层的注入项乘以后续所有层的谱范数再求和，整理即得书中那条界。展开过程等价于对递推做归纳，连乘项来自齐次部分的传播，求和项来自每层非齐次注入的累加。</p>\n<div class=\"formula\">$$\\|\\Delta \\mathbf{h}_L\\|_2\\le\\left(\\prod_{l=1}^{L}\\|W_l\\|_2\\right)\\sum_{l=1}^{L}\\frac{\\|\\Delta W_l\\|_2}{\\|W_l\\|_2}\\|\\mathbf{h}_{l-1}\\|_2$$</div>\n<p>离散化与近似发生在三处，值得逐一点名。其一，非线性被线性化：softmax、SiLU/GELU、RMSNorm 的雅可比谱范数被吸收进 $\\|W_l\\|_2$ 或被当作 1，实际这些算子的局部拉伸因子随输入变化，在激活饱和区会显著偏离 1。其二，残差连接被并入谱范数连乘：残差主干的恒等路径本应贡献增益 1，但界把它与权重矩阵的增益混在一起，导致连乘被高估。其三，逐 token 独立性：界对每个 token 单独成立，但 batch 内不同 token 的激活幅度差异巨大，用单 token 的 $\\|\\mathbf{h}_{l-1}\\|_2$ 代表整批会低估长尾 token 的误差——这正是代码模型里标识符与数字 token 受害更重的数学来源。</p>\n<p>系统代价体现在这条界对 batch 组成敏感。连续批处理把长短请求混在一批，长上下文请求的激活幅度与短请求差异大，界的求和项若按批内最大激活估算就会过度保守，若按均值估算又会漏掉长尾。工程判断是：用这条界做层间筛查而非批间筛查，把 $\\|W_l\\|_2$ 当作静态量预先算好（一次校准，随权重固化），把 $\\|\\mathbf{h}_{l-1}\\|_2$ 用校准集上的分位数而非均值，这样界才既有守门能力又不至于把可量化的层误杀。</p>\n\n<h3 id=\"th-quant-error-bound-sec-10\">十 · 接受率界：TV 界定拒绝概率，Pinsker 换 KL</h3>\n<p>投机解码一侧的界结构完全不同，它不追踪激活，而是追踪两个分布的距离。核心事实是：拒绝概率被草稿与目标分布的总变差距离控制，$\\mathbb{E}[\\text{accept}] \\ge 1 - \\mathrm{TV}(p_{\\text{draft}}, p_{\\text{target}})$。这一步的推导关键是把“接受”事件写成对采样对的耦合：当草稿分布与目标分布在每个 token 上的概率质量重叠越多，按目标分布校正后接受的概率越高；TV 恰好度量两个分布概率质量不重叠的那一半，因此它是拒绝概率的紧上界。TV 越小接受率越高，这个方向对量化草稿是致命的——量化把 $p_{\\text{draft}}$ 推离 $p_{\\text{target}}$，TV 上升，接受长度直接被压低。</p>\n<p>第二段不等式用 Pinsker 把 TV 换成 KL：$\\mathrm{TV}(p,q) \\le \\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p\\|q)}$，代入得 $\\mathbb{E}[\\text{accept}] \\ge 1 - \\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})}$。换的目的是可估计性：TV 需要对整个词表做绝对差求和，KL 只需在目标分布采样的 token 上算对数比，工程上更容易在线估计。代价是松——Pinsker 界在分布接近时是二阶紧的，但在 TV 较大时明显松，所以这个下界在量化草稿已经明显偏离时会给出过于乐观的接受率估计，不能单独作为“能不能量化草稿”的判据，必须与 TV 直接估计并用。</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{accept}]\\ge 1-\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})\\ge 1-\\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})}$$</div>\n<p>离散化与近似在这里是采样层面的。TV/KL 界假设逐 token 独立同分布，且草稿与目标共享词表与采样温度；一旦启用温度缩放或 top-p 截断，实际采样分布是原始分布经过截断与重归一化后的版本，TV 必须按截断后的分布重算。top-p 截断会砍掉低概率长尾，这既可能缩小 TV（两边都砍掉同样的尾巴）也可能放大 TV（草稿的尾巴形状与目标不同，截断点落在不同位置），所以不能沿用原始分布的界。系统代价是接受长度的期望直接乘进投机解码的加速比（见同模块投机解码期望加速比条目）：TV 上升 $\\delta$，接受率下界下降 $\\delta$，在草稿步数固定的配置下，端到端延迟按接受长度的倒数上升。一个具体例子：代码补全场景里草稿模型量化到 INT4 后，标点与关键字 token 的分布仍接近，但标识符与数字 token 的分布被量化拉偏，TV 在这类 token 上集中上升，而这些 token 恰恰是长尾——按词表平均的 TV 会低估它们对接受长度的伤害，必须按 token 类别分层估计 TV。</p>\n\n<h3 id=\"th-quant-error-bound-sec-11\">十一 · 两套界的耦合点：量化草稿同时踩两条线</h3>\n<p>把两条界放在一起看，量化草稿模型会同时触发两个失效通道。第一条是激活误差通道：草稿模型自身被量化，$\\Delta W_l$ 经谱范数连乘放大后进入草稿 logits，改变 $p_{\\text{draft}}$；第二条是分布距离通道：$p_{\\text{draft}}$ 的偏移直接抬高 TV，压低接受率。两条界共享同一个量化动作，但度量的是不同对象——前者度量草稿模型内部激活的绝对偏差，后者度量草稿与目标在输出分布上的相对距离。工程含义是：判断草稿能否量化，不能只看激活误差界是否“没崩”，还要看 TV 界给出的接受率下界是否仍高于可接受阈值；若 TV 下界已低于阈值，即使激活误差界看起来很安全，也不应量化草稿。</p>\n<p>耦合的推导关键步在于把 $\\Delta W_l$ 与 TV 连起来：激活误差经输出投影与 softmax 进入 logits，logits 的 ℓ2 偏差经 softmax 的局部 Lipschitz 常数（与温度成反比）映射为概率分布的 TV。这条链上每一步都有放缩，所以最终 TV 界比激活误差界更松。实际工程做法是绕过这条链，直接在校准集上测 TV：用全精度目标模型与量化草稿模型对同一批前缀采样，逐 token 算 TV 的经验估计，再按 token 类别分层。这比解析界可靠，因为解析界在 softmax 饱和区（高置信 token）会严重高估 TV——饱和区 logits 偏差对概率的影响被指数压小，而界按最坏情况放缩不会体现这一点。</p>\n<p>代价侧：草稿模型量化的收益是草稿前向的权重带宽减半，直接缩短草稿步延迟；代价是接受长度下降，端到端延迟按接受长度倒数上升。两者相抵的临界点由 TV 界给出：当 TV 下界对应的接受率下降幅度超过草稿步延迟的节省幅度时，量化草稿净亏。这个判断不需要实验数字，只需要在容量规划时把 TV 经验估计与草稿步延迟模型并排放进同一个表，按 SLO 的延迟预算做取舍。一个具体机制：per-group scaling 的组大小是这条耦合上的可调旋钮——组越小，$\\|\\Delta W_l\\|_2$ 越小、TV 越小，但元数据开销与反量化指令增加，草稿步延迟上升；组越大反之。这条权衡的数学形状由两套界共同决定，而非单一界。</p>\n\n<h3 id=\"th-quant-error-bound-sec-12\">十二 · 失效条件的工程读法：界是守门员不是估价师</h3>\n<p>谱范数乘积上界极松，实际误差常低数个数量级，这是这条界最重要的工程事实。松的来源已在第二节点名：非线性被线性化、残差被并入连乘、逐 token 独立性假设。后果是：若把上界当实际误差估计，会得出“任何低比特量化都会崩”的结论，从而过度保守地放弃量化，损失本可获得的带宽收益——这是书中明确列出的失败模式。正确读法是二值化使用：上界远大于崩溃阈值时，量化有崩溃风险，需要逐层筛查；上界远小于阈值时，量化安全；上界落在阈值附近时，界失去分辨力，必须回到经验测量。这条界不能预测 perplexity 或 pass@1 的具体退化，任何把它当精度预测器的用法都是误用。</p>\n<p>第二个失效条件是未刻画离群通道与 per-group scaling 的非均匀误差。界的求和项用 $\\|\\Delta W_l\\|_2$ 这个全局量，把组内误差抹平了；实际 per-group scaling 下，误差在组间高度非均匀，离群通道所在组的相对误差可能比全局相对误差高一个量级。工程读法：把 $\\|\\Delta W_l\\|_2$ 拆到通道级，按通道排序找离群通道，对这些通道单独保留高精度或缩小 scaling 组，其余通道下探低比特。这比整层保留 FP8 省带宽，也比整层下探 NVFP4 稳。INT4 权重量化在代码模型上对长尾 token 的伤害远大于均值误差所示，正是这个非均匀性在 token 层面的投影：标识符与数字的 logits 由少数通道主导，这些通道的量化误差被均值掩盖，却在采样时决定 token 选择。</p>\n<p>第三个失效条件是温度缩放与 top-p 截断后仍用原始分布的 TV/KL 界估接受率。工程读法：接受率界必须按实际采样分布重算，即把 $p_{\\text{draft}}$ 与 $p_{\\text{target}}$ 都过一遍温度缩放与 top-p 截断再算 TV。这一步在在线服务里可以低成本实现：采样时本就要做截断与重归一化，顺手在截断后的支撑集上算 TV 即可，不需要额外前向。代价是每 token 一次词表级归约，在词表规模下是微秒级开销，相对于草稿步延迟可忽略；收益是避免高估接受长度导致的 SLO 违约。这条界的最终落点是容量规划表里的一个下界列：接受率下界、草稿步延迟、目标步延迟三列并排，按 SLO 延迟预算决定草稿是否量化、量化到几比特、per-group 组多大。</p>\n<h3 id=\"th-quant-error-bound-sec-13\">十三 · 稠密假设：界从哪里开始松动</h3>\n<p>误差传播界 $$\\|\\Delta \\mathbf{h}_L\\|_2\\le\\left(\\prod_{l=1}^{L}\\|W_l\\|_2\\right)\\sum_{l=1}^{L}\\frac{\\|\\Delta W_l\\|_2}{\\|W_l\\|_2}\\|\\mathbf{h}_{l-1}\\|_2$$ 的推导前提是把每层量化误差当作加性扰动，沿残差主干逐层乘谱范数放大。这个前提要求网络是稠密 Transformer：每一层都有完整的 $W_l$，激活沿单一主干前传，没有分支、没有门控、没有跨层跳跃。一旦模型换成 MoE，$W_l$ 变成按 token 路由的专家集合，单个 token 只经过被选中的少数专家，$\\prod_l\\|W_l\\|_2$ 这个连乘就不再对应任何一条真实的前向路径——被跳过的专家其 $\\|\\Delta W_l\\|_2$ 根本不进入该 token 的 logits，而不同 token 走过的路径长度不同，界必须按路由分布重写为路径期望，而不是全局连乘。</p>\n<p>同理，带门控的线性注意力、状态空间层（其权重不构成固定谱范数的矩阵乘）以及跨层残差缩放，都会让“逐层累乘”这一步失真。工程判断很直接：拿到一个模型先看它是否稠密、是否所有层都是同构矩阵乘；若不是，这个界只能作为量级筛查，不能作为逐层误差预算。代价体现在显存与带宽决策上——MoE 模型量化时若照搬稠密界的层敏感度排序，会把预算错配到不参与热路径的专家上，浪费掉本可用于热专家的低比特带宽收益。</p>\n\n<h3 id=\"th-quant-error-bound-sec-14\">十四 · 谱范数乘积：极松的上界与筛查用法</h3>\n<p>这个界最容易被误读的地方是它的松紧度。$\\prod_l\\|W_l\\|_2$ 随层数指数增长，而真实网络在残差归一化下激活范数被稳定约束，实际误差常比上界低数个数量级。把上界当实际误差估计，会得出“量化必然崩溃”的结论，从而过度保守地放弃低比特，损失本可获得的带宽收益——这是本卷反复警告的失败模式之一。</p>\n<p>正确的用法是把它当<em>崩溃筛查器</em>而非<em>精度预测器</em>。伪代码思路：对每层计算 $\\|\\Delta W_l\\|_2/\\|W_l\\|_2$ 作为相对注入量，再乘以该层输入激活范数 $\\|\\mathbf{h}_{l-1}\\|_2$，得到单层贡献项；按贡献项排序，找出被谱范数放大最严重的若干层。这些层就是混合精度分配的候选——给它们保留 FP8 甚至更高精度，其余层压到 NVFP4。代价是：筛查本身要跑一次校准前向收集 $\\|\\mathbf{h}_{l-1}\\|_2$，这是一次性开销；换来的是避免整模型统一低比特导致的接受率崩塌，或避免因恐惧上界而全模型停在 FP8、白白多占一倍权重带宽。</p>\n<p>注意这个界不能预测 perplexity 或 pass@1 的具体退化。它能回答“量化是否可能崩溃”，不能回答“会掉几个点”。容量规划里若需要后者，只能靠小规模校准集实测，界只负责把搜索空间从全层缩到少数敏感层。</p>\n\n<h3 id=\"th-quant-error-bound-sec-15\">十五 · 独立同分布假设：采样分布一变，界就失效</h3>\n<p>接受率界 $$\\mathbb{E}[\\text{accept}]\\ge 1-\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})\\ge 1-\\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})}$$ 的推导假设逐 token 独立同分布，且草稿与目标共享词表与采样温度。这两个假设在真实服务里几乎总被破坏。温度缩放把 $p_{\\text{target}}$ 锐化或平坦化，top-p 截断把分布支撑集砍掉一截，两者都直接改变 TV 距离，而原始分布上算出的界对此一无所知。</p>\n<p>后果是接受长度被高估。工程上必须按<em>实际采样分布</em>重算 TV：在温度 $T$ 与 top-p 阈值下重新归一化两个分布，再取总变差。若沿用未缩放分布的界做容量决策，会高估投机解码的期望加速比，进而低估所需的目标模型并发副本数——解码阶段 roofline 带宽界那条线会告诉你，副本数不足时带宽先饱和，接受率的高估直接转化成 SLO 违约。共享词表假设同样关键：草稿若用了裁剪词表或不同 tokenizer，TV 的定义域就不一致，界失去意义，此时应退回按对齐后的公共词表重算。</p>\n\n<h3 id=\"th-quant-error-bound-sec-16\">十六 · 非均匀误差：离群通道与 per-group scaling</h3>\n<p>界里的 $\\|\\Delta W_l\\|_2$ 是一个矩阵级范数，它把逐通道、逐组的误差压成一个标量。但低比特量化的真实误差高度非均匀：少数离群通道承载大动态范围，per-group scaling 让每组有自己的缩放因子，组内误差与组间误差量级不同。矩阵范数看不见这种结构，于是界对“均值误差达标但长尾崩坏”的情形完全失明。</p>\n<p>最具体的例子是代码模型上的 INT4 权重量化：标识符、数字这类长尾 token 的 logits 对少数通道的量化扰动极其敏感，而均值 ℓ2 误差可能看起来很小。结果是 pass@1 明显退化，界却给出“安全”的结论。工程对策是把敏感度分析下沉到通道级：对每个通道单独估计 $\\|\\Delta W_{l,c}\\|_2$ 与其激活能量 $\\|\\mathbf{h}_{l-1,c}\\|_2$ 的乘积，把高能量、高误差的通道挑出来保留高精度。代价是 per-group scaling 的元数据占显存、反量化在 tcgen05 的 MMA 前多一步缩放，但相比整层回退到 FP8，这个代价小得多。</p>\n<p>这也解释了为什么界只能做筛查：它给出的是矩阵级上界，而伤害发生在通道级和 token 级。容量规划里若只信均值误差，会在代码、数学这类长尾密集的负载上踩坑。</p>\n\n<h3 id=\"th-quant-error-bound-sec-17\">十七 · 规模上限：层数、词表与批维度的三重约束</h3>\n<p>界随规模失效有三个方向。其一是层数：$\\prod_l\\|W_l\\|_2$ 的指数放大在深层模型上让上界彻底失去信息量，层数越多界越松，筛查分辨率越低——此时应按块（若干层一组）而非逐层做敏感度排序，否则排序被数值噪声淹没。其二是词表：TV/KL 界在词表很大时对尾部概率的质量极其敏感，草稿与目标在长尾上的微小分歧就能撑大 TV，而 top-p 截断恰好切在尾部，使界的假设与真实采样错位。其三是批维度：逐 token 独立同分布假设在连续批处理下被批内不同序列的混合分布破坏，批内接受率的方差远大于单序列估计，容量规划必须按批内最差序列而非均值来定副本数。</p>\n<p>工程判断落在阈值上：当 TV 界给出的接受率下界已低于可接受阈值时，不应量化草稿——这是本界在容量决策中的核心用法。但阈值本身要按实际采样分布、按批内最差情形重算，而不是套用未缩放、单序列的原始界。规模越大，界越只能回答“能不能”，越不能回答“有多好”；把“有多好”交给校准实测，把“能不能”交给这个界，是唯一不误用的分工。</p>\n\n<h3 id=\"th-quant-error-bound-sec-18\">十八 · 边界在哪里：谱范数乘积、TV 界与采样分布的三重失效</h3>\n<p>这套界的第一层边界写在假设里：稠密 Transformer、草稿与目标共享词表与采样温度、每层量化误差可视为加性扰动。一旦模型换成 MoE 或带稀疏注意力的结构，逐层谱范数累乘的推导链就断了——路由带来的条件分支使 $\\mathbf{h}_{l-1}$ 的分布随 token 而变，单一 $\\|W_l\\|_2$ 无法覆盖被激活的不同专家子矩阵。更隐蔽的是共享采样温度这一条：投机解码的接受率界建立在 $p_{\\text{draft}}$ 与 $p_{\\text{target}}$ 同温度采样的前提上，工程里常给草稿模型单独设温度或 top-p 以提升多样性，此时 $\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})$ 必须按实际采样后的截断分布重算，直接套用原始 logits 分布的界会系统性高估接受长度，容量规划据此排出的 batch 会在真实负载下塌陷。</p>\n<p>第二层失效来自界本身的松紧。误差传播界 $$\\|\\Delta \\mathbf{h}_L\\|_2\\le\\left(\\prod_{l=1}^{L}\\|W_l\\|_2\\right)\\sum_{l=1}^{L}\\frac{\\|\\Delta W_l\\|_2}{\\|W_l\\|_2}\\|\\mathbf{h}_{l-1}\\|_2$$ 中谱范数乘积随层数指数增长，而真实网络里相邻层的放大与收缩大量抵消，实际误差常比上界低数个数量级。这意味着该界只能回答“量化会不会崩溃”这个二值问题，不能回答“perplexity 涨多少、pass@1 掉几个点”。把它当实际误差估计，典型后果是因为上界看起来已经溢出 fp16 动态范围而放弃 INT4，白白丢掉权重带宽减半带来的解码吞吐收益——在 decode 阶段受限于权重读取带宽的形态里，这笔收益直接对应每 token 延迟的下降。</p>\n<p>第三层是分布刻画不到的维度。TV/KL 界假设逐 token 独立同分布，且把误差当作均匀的分布偏移；但 per-group scaling 与离群通道让量化误差高度非均匀，少数通道的 $\\|\\Delta W_l\\|_2$ 贡献被均值掩盖。代码模型是放大这一点的场景：标识符、数字这类长尾 token 落在词表尾部，其 logits 对少量通道的扰动极其敏感，均值误差达标而 pass@1 明显退化。此时接受率界仍显示安全，因为 TV 距离被高频 token 主导，长尾的拒绝被平均掉了。工程判断应落在两处：用谱范数乘积筛查哪些层的相对误差项 $\\|\\Delta W_l\\|_2/\\|W_l\\|_2$ 会被放大，据此做混合精度分配而非全局低比特；用 TV 界给出的接受率下界对照 SLO 阈值，下界已低于可接受接受长度时就不量化草稿，改走目标模型侧量化或保留 fp8 草稿。</p>\n<table class=\"mini\"><thead><tr><th>边界条件</th><th>界的行为</th><th>系统代价</th></tr></thead><tbody><tr><td>谱范数乘积远大于实际放大</td><td>上界溢出，实际误差低数个数量级</td><td>过度保守放弃量化，损失权重带宽收益与 decode 吞吐</td></tr><tr><td>温度缩放 / top-p 截断</td><td>TV 界未按截断分布重算</td><td>接受长度被高估，batch 与 KV 预算排错</td></tr><tr><td>代码长尾 token</td><td>均值误差达标，长尾 logits 敏感</td><td>pass@1 退化而 TV 界仍显示安全</td></tr></tbody></table>\n\n<h3 id=\"th-quant-error-bound-sec-19\">十九 · 边界之外：谱范数乘积为何只是崩溃筛查器</h3>\n<p>该误差传播界成立的前提是稠密 Transformer、逐层加性扰动、草稿与目标共享词表与采样温度。一旦模型含 MoE 路由或跨层残差重参数化，<span>\\(\\|\\Delta W_l\\|_2\\)</span> 就不再是单一路径的注入量，谱范数乘积会把多条专家路径的放大混叠成一个标量，界本身失去可解释性。更实际的失效在于松紧度：<span>\\(\\prod_l\\|W_l\\|_2\\)</span> 随层数指数增长，而真实激活落在权重的主奇异子空间附近，实际误差常比该界低数个数量级。因此它只能回答“量化会不会崩溃”，不能回答 perplexity 或 pass@1 退化多少——把它当误差预测器使用，代价是过度保守地放弃 INT4/FP8 权重量化，白白损失显存带宽与解码吞吐。</p>\n<p>接受率一侧的 TV/KL 界同样有硬边界。它假设逐 token 独立同分布采样，而温度缩放与 top-p 截断会重塑分布尾部：截断后 <span>\\(p_{\\text{target}}\\)</span> 的支撑集收缩，TV 距离按实际采样分布重算才有效，沿用原始 logits 分布的界会系统性高估接受长度，导致容量规划中把草稿长度设得过大、目标模型前向次数被低估。工程上应把该界当作筛查门槛：若 <span>\\(1-\\mathrm{TV}\\)</span> 下界已低于可接受阈值，就不量化草稿；若远高于阈值，也不代表可以放心量化，因为界未刻画离群通道与 per-group scaling 的非均匀误差。</p>\n<p>最隐蔽的失效在长尾 token。INT4 权重量化对代码模型中标识符、数字这类低频高熵 token 的伤害远大于均值误差所示：均值 ℓ2 误差达标，但长尾 token 的 logits 排序被翻转，pass@1 明显退化。此时谱范数界与 TV 界都不会报警，因为二者都是对分布整体取范数或距离，尾部质量在 TV 中占比小。判断规模上限时应按词表分层统计误差，而非只看全局指标。</p>\n<table class=\"mini\"><thead><tr><th>失效来源</th><th>界是否报警</th><th>系统代价</th></tr></thead><tbody><tr><td>谱范数乘积过松</td><td>报警但虚高</td><td>放弃量化，损失带宽收益</td></tr><tr><td>温度/top-p 改变采样分布</td><td>不报警</td><td>接受长度高估，目标前向增多</td></tr><tr><td>代码长尾 token</td><td>不报警</td><td>pass@1 退化，均值指标掩盖</td></tr></tbody></table>\n<h3 id=\"th-quant-error-bound-sec-20\">二十 · 把界翻译成容量决策变量</h3>\n<p>容量决策要的不是“误差有多大”，而是“哪个旋钮先动、动多少”。误差传播界给出的是逐层注入与逐层放大的乘积结构，因此它天然对应两类决策：一是<strong>混合精度分配</strong>（哪些层允许低比特），二是<strong>量化后的批大小上限</strong>。把界写成可决策形式，需要把 $\\|\\Delta W_l\\|_2/\\|W_l\\|_2$ 视为每层的相对扰动 $\\rho_l$，把 $\\prod_l\\|W_l\\|_2$ 视为放大因子 $G$，于是 $\\|\\Delta \\mathbf{h}_L\\|_2 \\le G\\sum_l \\rho_l\\|\\mathbf{h}_{l-1}\\|_2$。工程上真正可控的是 $\\rho_l$ 的分布：per-group scaling 让 $\\rho_l$ 在通道间非均匀，离群通道的 $\\rho$ 远高于均值，因此“均值误差达标”不等于界达标。决策规则是：先按层测 $\\rho_l$ 与 $\\|W_l\\|_2$，算出各层对 $\\sum_l \\rho_l\\|\\mathbf{h}_{l-1}\\|_2$ 的贡献份额，把份额最高的少数层留在 FP8，其余层下探到 NVFP4；这一步省下的是权重带宽，直接换算为解码阶段每 token 的显存读取量下降，从而抬高 roofline 带宽界下的 token/s 上限。代价是混合精度破坏了 kernel 的统一性，tcgen05 MMA 的 tile 形状与 TMEM 布局需要按精度分组，编译期与运行期的调度开销上升，吞吐收益被部分抵消。</p>\n<p>批大小的定法要区分两个方向。预填阶段是计算密集，量化带来的带宽节省几乎不转化为吞吐，反而因低比特 MMA 的累加精度问题需要额外缩放步骤；解码阶段是带宽密集，权重读取量按位宽线性下降，批大小可以按“每 token 权重字节数”反推：给定 KV 预算与权重占用，剩余显存决定最大并发序列数，而量化把权重占用压下来后，同一张卡能容纳的并发数上升。这里的界只用于筛查：若某层 $\\rho_l$ 使 $\\|\\Delta \\mathbf{h}_L\\|_2$ 相对激活范数的比值超过可容忍阈值，则该层不能进入低比特，批大小上限随之被权重占用锁死。界不能预测 perplexity 退化，因此批大小决策必须配一个在线验收：用固定 prompt 集比对量化前后的 top-1 一致率与长尾 token（标识符、数字）的命中率，一致率跌破阈值就回退该层精度。</p>\n\n<h3 id=\"th-quant-error-bound-sec-21\">二十一 · 用 TV 界定草稿模型精度与投机并行度</h3>\n<p>投机解码的容量决策核心是接受长度 $\\tau$，而 $\\tau$ 由 $\\mathbb{E}[\\text{accept}]\\ge 1-\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})$ 下界约束。把草稿量化到低比特会抬高 TV，下界随之下移；当 $1-\\mathrm{TV}$ 低于系统设定的接受率阈值 $\\alpha^\\star$ 时，投机链路期望收益转为负——草稿每步的验证开销与拒绝后的回退开销超过其节省。决策形式是：对候选草稿精度 $b\\in\\{\\text{FP8},\\text{NVFP4}\\}$，估计 $\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})$ 的逐 token 均值，代入 Pinsker 界得 $\\alpha_b=1-\\sqrt{\\tfrac{1}{2}\\overline{\\mathrm{KL}}}$，若 $\\alpha_b&lt;\\alpha^\\star$ 则不量化草稿。注意 $\\alpha^\\star$ 不是拍脑袋的数：它由目标模型的单步解码延迟、草稿的单步延迟、验证批的并行度共同决定，只有当草稿步延迟显著低于目标步延迟时，低 $\\alpha$ 才仍划算。</p>\n<p>投机并行度（草稿树宽度或链长）也受此界约束。链长 $k$ 增大时，逐 token 独立同分布的假设开始失效，TV 沿链累积，实际接受长度低于按单 token 界逐位相乘的估计；因此容量规划里应把 $k$ 限制在使累积 TV 仍低于阈值的范围，而不是盲目加长草稿链。代价体现在显存与带宽两侧：更宽的草稿树意味着草稿 KV 与验证批的激活占用上升，挤占目标模型的 KV 预算；更长的链意味着验证步的批内序列更长，预填与解码的混合调度更复杂。一个具体例子是代码补全场景：草稿模型在标识符与数字位置分布尖锐，INT4 量化后这些位置的 TV 抬升远高于均值，$\\alpha_b$ 的下界被长尾 token 拖低，于是正确决策是把草稿留在 FP8 而只对目标模型的非敏感层做 NVFP4，而不是两边一起压。</p>\n\n<h3 id=\"th-quant-error-bound-sec-22\">二十二 · KV 预算与 SLO 的联动定法</h3>\n<p>KV 预算不是独立变量，它由权重占用、激活峰值与并发数三者挤出来。量化把权重占用压低后，KV 预算扩大，但扩大多少取决于精度分配结果：混合精度下权重占用是各层字节数的加权和，不是单一比特数的乘积。设总显存 $M$，权重占用 $M_W(b)$、运行时激活与 workspace $M_A$、每序列每 token 的 KV 字节 $s_{\\text{kv}}$，则最大并发 $N_{\\max}=\\lfloor (M-M_W(b)-M_A)/(s_{\\text{kv}}\\cdot L_{\\text{ctx}})\\rfloor$。误差界在这里的作用是给 $M_W(b)$ 加上可行性约束：若某层因 $\\rho_l$ 超标必须留在高精度，$M_W$ 下降幅度小于预期，$N_{\\max}$ 的提升被压缩，容量规划不能按“全模型统一低比特”的理想值估算。</p>\n<p>SLO 的定法要把延迟分解到可归因的项上。解码阶段单 token 延迟近似为 $\\max(\\text{权重读取}/\\text{带宽},\\ \\text{KV 读取}/\\text{带宽},\\ \\text{MMA 计算}/\\text{算力})$ 加上调度与通信开销；量化降低第一项，从而在带宽受限区间直接缩短延迟，但在算力受限区间（大 batch、长上下文预填）收益消失。SLO 决策因此要按负载形态分段：低并发低延迟段靠量化权重换带宽，高并发吞吐段靠 KV 预算换并发，两段的精度策略可以不同。代价是功耗：低比特 MMA 的单位算力能耗下降，但为维持数值稳定增加的缩放与反量化步骤引入额外访存，净功耗收益需要按实际 kernel 而非位宽理论值评估。工程判断是：把 SLO 拆成 TTFT 与 TPOT 两条约束，TTFT 由预填算力与 KV 写入决定，量化几乎不帮忙；TPOT 由解码带宽决定，量化是主要杠杆，而误差界负责划定哪些层不能被这个杠杆碰。</p>\n\n<h3 id=\"th-quant-error-bound-sec-23\">二十三 · 算例：三层决策的串联</h3>\n<p>设一个稠密 Transformer 目标模型与一个同词表草稿模型，部署在单卡上，上下文长度固定。第一步定草稿精度：测得草稿 INT4 后逐 token 的 $\\overline{\\mathrm{KL}}$ 使 Pinsker 下界 $\\alpha_b$ 落到系统阈值 $\\alpha^\\star$ 之下，判定草稿不可量化，草稿保持 FP8，投机链长 $k$ 取使累积 TV 仍低于阈值的保守值。第二步定目标模型混合精度：按层计算 $\\rho_l\\|W_l\\|_2$ 的贡献份额，把份额最高的少数层留 FP8，其余层 NVFP4，得到 $M_W$ 的实际下降量；用该 $M_W$ 反算 $N_{\\max}$，得到比统一低比特方案更小的并发提升，但避免了长尾 token 退化。第三步定 SLO：在 $N_{\\max}$ 下测算 TPOT，若仍不满足，则不是继续压精度，而是缩 $k$ 或降低并发换取单序列带宽，因为继续压精度会同时压低 $\\alpha_b$ 与长尾命中率，属于用质量换一个已经不够的延迟指标。</p>\n<p>这个算例的关键在于三个决策不是独立的：草稿精度决定 $\\tau$，$\\tau$ 决定投机链的有效吞吐，有效吞吐又反过来影响目标模型侧可接受的并发与 KV 预算分配。误差界在两处起作用——谱范数乘积筛查目标模型的层，TV 界筛查草稿模型的精度——但都不作为性能预测器，只作为“是否可能崩溃”的门槛。真正的容量数字来自实测的 $\\rho_l$、$\\overline{\\mathrm{KL}}$ 与 kernel 级带宽，界只负责把不可行的组合提前排除，避免把工程时间花在注定回退的量化方案上。</p>\n<p>最后一个工程判断落在验收闭环上：任何按界做出的精度分配，都必须在目标负载的真实采样分布（含温度缩放与 top-p 截断）下重算 TV，因为截断会改变 $p_{\\text{draft}}$ 与 $p_{\\text{target}}$ 的形状，原始分布的界不再成立；同时用长尾 token 的一致率而非均值误差作为回退触发器。界给出的是可行性边界，容量决策的精度必须由这条闭环提供。</p>\n\n<h3 id=\"th-quant-error-bound-sec-24\">二十四 · 把界当成容量决策的筛子：阈值、预算与失效面</h3>\n<p>在容量决策里，这两个界不是用来预测指标的，而是用来做<b>准入筛选</b>：先判断某个量化方案是否会让系统越过不可接受的悬崖，再决定批大小、并行度与 KV 预算怎么配。工程上把它落成两条判据。第一条针对草稿模型：设业务可容忍的最低接受长度为 <span>τ</span>，则要求 <span>1−TV(p_draft,p_target) ≥ τ</span>，等价于 <span>TV ≤ 1−τ</span>；若实测或估计的 TV 已越过该阈值，草稿就不该量化到低比特，宁可保留高精度权重换取带宽。第二条针对目标模型：用谱范数乘积 <span>Π‖W_l‖₂</span> 与逐层相对误差 <span>‖ΔW_l‖₂/‖W_l‖₂</span> 相乘，筛出放大因子最高的若干层，把这些层留在 FP8 而其余层走 NVFP4，形成混合精度分配。注意这条判据只回答“会不会崩”，不回答“崩多少”——谱范数乘积上界极松，实际误差常低数个数量级，把它当实际误差估计会过度保守地放弃量化，白白损失本可拿到的带宽收益。</p>\n<div class=\"formula\">$$\\text{admit}_{\\text{draft}}:\\ \\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})\\le 1-\\tau,\\qquad \\text{admit}_{\\text{layer}}:\\ \\frac{\\|\\Delta W_l\\|_2}{\\|W_l\\|_2}\\prod_{j\\ge l}\\|W_j\\|_2\\le \\epsilon_{\\text{rel}}$$</div>\n<p>算例给一个可复算的骨架（不引入实验数字，只演示决策流程）。某部署的 SLO 要求解码阶段每 token 延迟不超过预算，草稿模型承担 <span>k</span> 个候选 token 的生成，接受长度 <span>A</span> 直接决定目标模型前向次数，约为 <span>k/A</span>。若草稿量化后 TV 界给出接受率下界 <span>1−TV</span>，则最坏情况下有效接受长度按 <span>A_min = k·(1−TV)</span> 折算，目标模型前向次数上界为 <span>k/A_min = 1/(1−TV)</span>。当 <span>TV=0.3</span> 时每 token 至少一次目标前向，投机收益归零；当 <span>TV=0.1</span> 时约 1.11 次，收益仍在。于是容量规划的顺序是：先用 TV 阈值卡掉不达标的草稿量化方案，再按剩余方案的接受长度反推目标模型的批大小与 KV 预算——接受长度越长，单次目标前向摊到的 token 越多，KV 增长越慢，可支撑的并发就越高。反过来，若为了省草稿带宽强行量化，接受长度塌缩会把省下的带宽全部吐回给目标模型的前向次数，吞吐净亏。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>用哪个界</th><th>判据形式</th><th>越界后的系统代价</th></tr></thead><tbody><tr><td>草稿是否低比特</td><td>TV/KL 接受率界</td><td>TV ≤ 1−τ</td><td>接受长度塌缩，目标前向次数上升，解码延迟与功耗上升</td></tr><tr><td>层精度分配</td><td>谱范数乘积</td><td>逐层放大因子 ≤ ε_rel</td><td>误差经 L 层放大进入 logits，长尾 token 退化</td></tr><tr><td>批大小与 KV 预算</td><td>接受长度折算</td><td>前向次数 ≈ 1/(1−TV)</td><td>KV 增长快于吞吐收益，显存先于算力成为瓶颈</td></tr></tbody></table>\n<p>边界与失效面必须写进决策文档，否则界会被误用。TV/KL 界假设逐 token 独立同分布，且草稿与目标共享词表与采样温度；一旦开启温度缩放或 top-p 截断，实际采样分布已变，必须按截断后的分布重算 TV，否则接受长度被高估、批大小定得过大。该界也未刻画离群通道与 per-group scaling 的非均匀误差，均值意义上的 ℓ2 上界达标不代表安全。最典型的坑是代码模型：INT4 权重量化对标识符、数字这类长尾 token 的伤害远大于均值误差所示，perplexity 看似无恙而 pass@1 已明显退化——这类场景应把长尾 token 的 logits 偏差单独纳入判据，而不是只看全局 ℓ2。工程判断落在这一句：界只做否决票，不做预测票；用它筛掉会崩的方案、定位需保精度的层，剩下的容量参数仍要由实测接受长度与显存曲线来定。</p>\n<h3 id=\"th-quant-error-bound-sec-25\">二十五 · 把上界当估计：谱范数乘积的过度保守误用</h3>\n<p>本卷前四节已经把两条界写清楚了：一条是逐层放大的 ℓ2 传播界，一条是 TV/KL 给出的接受率下界。这一节只谈它们被用错的样子。最常见的一种，是把 <span class=\"sym\">∏‖W_l‖₂</span> 这个乘积当成“实际误差会有多大”的预测值。它的推导方式是每层扰动取最坏方向、逐层取最坏放大，因此是一个<strong>可行性判据</strong>而非<strong>估计量</strong>：只要它没有爆炸，就说明量化不至于把网络推到崩溃区；它爆炸了，也不能反推实际误差同样大。工程上真正危险的动作是反过来用——看到乘积项量级可观，就直接判定“这一层不能量化”，于是整模型退回 FP8 甚至 BF16，白白丢掉 NVFP4 在 B200 上带来的权重带宽与显存收益。</p>\n<p>识别这种误用有一个很干净的操作性判据：把界拆成“放大因子”和“注入项”两部分分别看。<span class=\"sym\">∏‖W_l‖₂</span> 是放大因子，<span class=\"sym\">∑‖ΔW_l‖₂/‖W_l‖₂·‖h_{l-1}‖₂</span> 是注入项。误用者只看乘积，而正确用法是看<strong>相对注入项</strong>——即每层 <span class=\"sym\">‖ΔW_l‖₂/‖W_l‖₂</span> 与激活范数的乘积是否在数值上被放大因子吃掉。伪代码思路如下：对每层计算 <span class=\"sym\">r_l = ‖ΔW_l‖₂/‖W_l‖₂</span>，再算累积放大 <span class=\"sym\">A_l = ∏_{k≤l}‖W_k‖₂</span>，只有当 <span class=\"sym\">A_l·r_l·‖h_{l-1}‖₂</span> 相对 <span class=\"sym\">‖h_l‖₂</span> 已经接近同量级时，才把该层列入“不可量化”清单；否则它只是被一个极松的界吓到了。代价侧要算清楚：一次错误的保守决策，把某几层从 NVFP4 退回 FP8，权重带宽需求翻倍，解码阶段的 roofline 带宽界直接收紧，单 token 延迟上升、并发容量下降——这是用真实的吞吐换一个并不存在的安全感。</p>\n\n<h3 id=\"th-quant-error-bound-sec-26\">二十六 · 均值误差达标而长尾崩掉：代码模型上的 INT4 反例</h3>\n<p>第二个误用更隐蔽：用<strong>平均</strong>量化误差（层输出 ℓ2、或全模型 perplexity）作为验收标准，据此判定 INT4 权重量化“没问题”。在代码推理上这个判据会系统性失效。标识符、数字、缩进层级、括号配对这类 token 处在词表的长尾，其 logits 对少数通道的扰动极其敏感；per-group scaling 与离群通道的非均匀误差恰恰集中在这里，而均值误差被大量高频、低敏感 token 稀释，看不出问题。</p>\n<p>给一个反例（结构性描述，不引具体数字）：某代码补全服务把草稿模型整体量化到 INT4，权重带宽下降、单步草稿延迟改善，验收时看的是全模型平均 ℓ2 输出偏差与通用 perplexity，两项都在容忍范围内，于是上线。上线后观察到的是：普通自然语言前缀的接受长度正常，但一旦前缀进入函数体、出现长标识符与数字字面量，草稿给出的候选 token 与目标模型的分歧迅速放大，接受长度塌陷。原因不在均值，而在长尾：草稿在这些位置的 <span class=\"sym\">p_draft</span> 与 <span class=\"sym\">p_target</span> 的 TV 距离被量化误差显著抬高，而 TV 界 <span class=\"sym\">E[accept] ≥ 1 − TV</span> 是按<strong>逐 token 分布</strong>成立的，不是按平均误差成立的。均值达标与接受率达标是两件事。</p>\n<p>识别方法：不要用单一均值指标验收量化草稿，而应按 token 类别分层统计草稿与目标的分布距离——把标识符、数字、标点结构单列出来，看这些桶里的 TV 或 KL 是否显著高于整体。若某一桶的 TV 已经逼近可接受阈值，即便整体均值漂亮，也应把该桶对应的通道或层保留更高精度（混合精度分配），而不是整模型一刀切。系统代价上，这个反例的教训是：接受长度塌陷直接吃掉投机解码的期望加速比，草稿步数变多、目标模型验证次数上升，端到端吞吐反而低于不量化草稿的配置。</p>\n\n<h3 id=\"th-quant-error-bound-sec-27\">二十七 · 采样分布变了，界没跟着变</h3>\n<p>第三个误用出在接受率一侧：在温度缩放或 top-p 截断之后，仍然拿<strong>原始 logits 分布</strong>的 TV/KL 去估接受率。TV/KL 界的前提是草稿与目标共享词表与采样温度、逐 token 独立同分布；一旦采样被改造，实际被比较的是<strong>截断并重归一化后的分布</strong>，TV 会变，界必须按实际采样分布重算。温度调低会让分布更尖锐，草稿与目标在头部 token 上的一致度上升，但尾部被压掉后 TV 的构成也变了；top-p 截断则直接把候选集缩小，草稿在截断边界附近的概率质量错配会被放大或掩盖，方向不定。</p>\n<p>识别这种误用的办法是检查界的输入是否与运行时采样配置一致：如果容量规划时用贪心或温度 1 的分布算出的 TV 下界，去预测一个温度 0.2、top-p 0.9 的线上服务的接受长度，这个下界既不紧也不对应。正确做法是把界重算在<strong>实际采样算子之后</strong>的分布上——先应用温度与截断，再归一化，再算 TV/KL，再代入 <span class=\"sym\">E[accept] ≥ 1 − TV ≥ 1 − √(½KL(p_target‖p_draft))</span>。注意 Pinsker 那一步给出的是更松的下界，用它做容量决策时要预留余量，别把松下界当紧估计。代价侧：接受长度被高估的直接后果是 SLO 规划失真——按高接受率排的并发容量，在真实流量下目标模型验证次数超标，尾延迟抬升，连续批处理的有效 batch 被验证步骤挤占。</p>\n\n<h3 id=\"th-quant-error-bound-sec-28\">二十八 · 忽略非均匀误差：per-group scaling 与离群通道</h3>\n<p>两条界都把量化误差当成一个可以用范数概括的<strong>均匀加性扰动</strong>，而实际低比特量化（尤其 NVFP4/INT4 的 per-group scaling）产生的是非均匀误差：少数离群通道承担了绝大部分误差能量，其余通道几乎无损。谱范数界对这种结构不敏感——它只看到 <span class=\"sym\">‖ΔW_l‖₂</span> 的总量，看不到误差集中在哪几个通道、这些通道是否正好驱动长尾 token 的 logits。于是会出现“界很松、实际误差也不大，但特定 token 崩了”的组合，这正是第二节反例的机理来源。</p>\n<p>识别方法：把误差矩阵按通道分解，检查 <span class=\"sym\">ΔW_l</span> 的列范数分布是否重尾；若少数列的相对误差远高于中位数，说明 per-group scaling 的组划分与离群通道没有对齐，此时即使整体 <span class=\"sym\">‖ΔW_l‖₂/‖W_l‖₂</span> 很小，也不能判定安全。工程动作是调整 group size 或对离群通道单独保留高精度，而不是靠缩小整体比特数来“压均值”。代价上，group size 变小会增加缩放因子的元数据开销与反量化指令数，在 tcgen05 的 MMA 流水里体现为额外的 TMEM 读写与指令发射压力；这是一个需要在带宽收益与元数据开销之间权衡的具体决策，而不是靠界的松紧来拍板。</p>\n\n<h3 id=\"th-quant-error-bound-sec-29\">二十九 · 界的正确位置：筛查而非预测</h3>\n<p>把上述误用收束成一条工程判断：这两条界在推理系统里的正确位置是<strong>筛查器</strong>，不是<strong>预测器</strong>。它们能回答的问题是“量化到这一档会不会崩”“哪些层的误差会被逐层放大到值得警惕”“草稿量化后接受率下界是否已经跌破阈值”，不能回答“perplexity 会退多少”“pass@1 会掉几个点”。前者是可行性判断，后者必须靠分层实测（按 token 类别、按任务形态）来拿。</p>\n<p>因此一个可执行的流程是：先用谱范数乘积与相对注入项筛出高风险层，用 TV/KL 界（按实际采样分布重算）筛出草稿能否量化的档位；筛过的部分放心交给 NVFP4/FP8 去换带宽；筛不过的部分做混合精度，并对长尾 token 桶单独验收。任何把筛查结果直接当性能预测、或把均值指标当唯一验收标准的做法，都会落进本节的三个反例里——要么过度保守丢掉带宽收益，要么均值达标而接受长度塌陷，要么用错分布的界把容量规划做飘。</p>\n\n<h3 id=\"th-quant-error-bound-sec-30\">三十 · 误用与反例：当上界被当作预言</h3>\n<p>最常见的误用，是把误差传播界里的谱范数乘积当成实际误差估计。该界的形式是 <span class=\"formula\">$$\\|\\Delta \\mathbf{h}_L\\|_2\\le\\left(\\prod_{l=1}^{L}\\|W_l\\|_2\\right)\\sum_{l=1}^{L}\\frac{\\|\\Delta W_l\\|_2}{\\|W_l\\|_2}\\|\\mathbf{h}_{l-1}\\|_2$$</span> 其中 <span class=\"formula\">$$\\prod_l \\|W_l\\|_2$$</span> 随层数指数增长，而实际误差常低数个数量级。工程后果很直接：团队据此判定某层“必然崩溃”，把整网留在 FP8 甚至 BF16，放弃 NVFP4 权重带来的显存与带宽收益——在 NVL72 这类显存带宽被 KV cache 挤占的部署里，这等于把本可腾出的容量白白丢掉。识别方法：拿该界与实测逐层 ℓ2 误差做比值，若比值稳定在几个数量级以上，说明界只具备“是否可能崩溃”的筛查价值，不能作为精度预算的输入。正确用法是把它当粗筛——界都过不了的层才需要回退，界过得去的层交给实测。</p>\n<p>第二个误用出在代码模型上。INT4 权重量化对长尾 token（标识符、数字、缩进符）的伤害远大于均值误差所示：均值误差达标，pass@1 却明显退化。原因是这些 token 的 logits 间距窄，量化噪声足以翻转 argmax，而它们在语料中占比低，拉不动平均指标。系统代价体现为“指标合格但线上返工率上升”——吞吐看似提升，重试与人工修复把收益吃掉。识别方法：不要只看 perplexity，按 token 类别切片统计 top-1 翻转率，重点看标识符与数字片段；若翻转率在长尾切片上显著高于均值切片，就应给嵌入层与 lm_head 保留更高精度，或对离群通道启用 per-group scaling 而非全局 scale。这也是该界未刻画离群通道与 per-group scaling 非均匀误差的直接后果。</p>\n<p>第三个误用发生在投机解码一侧。接受率界 <span class=\"formula\">$$\\mathbb{E}[\\text{accept}]\\ge 1-\\mathrm{TV}(p_{\\text{draft}},p_{\\text{target}})\\ge 1-\\sqrt{\\tfrac{1}{2}\\mathrm{KL}(p_{\\text{target}}\\|p_{\\text{draft}})}$$</span> 的推导假设逐 token 独立同分布，且草稿与目标共享词表与采样温度。一旦启用温度缩放或 top-p 截断，实际采样分布已被重写，仍用原始分布的 TV/KL 估接受率，就会系统性高估接受长度。后果是容量规划失真：按高估的接受长度去配草稿模型算力与 KV 预留，实际运行时接受长度缩水，目标模型前向次数上升，端到端延迟超出 SLO。识别方法：在真实采样配置下重算 TV——把温度与 top-p 施加到两侧分布后再求距离，而不是复用未截断的 logits；若重算后的下界已低于可接受阈值，就不应把草稿量化到低比特。</p>\n<p>一个具体反例：某团队把 7B 级草稿模型量化到 INT4 以省显存，离线用未截断分布的 KL 算出接受率下界仍高于阈值，遂上线。生产环境开启温度缩放与 top-p 后，重算的 TV 明显变大，接受长度下降，目标模型调用频次上升，单请求延迟反而高于未量化草稿的基线；同时代码类请求的长尾 token 翻转率抬升，返工率上升。两个误用叠加，量化草稿既没省下有效吞吐，又损了质量。工程判断应落在两处闸门：谱范数乘积只做崩溃筛查、不做精度预算；TV/KL 界必须在实际采样分布下重算，并与长尾切片翻转率一起作为是否量化草稿的放行条件。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\Delta W_l</td><td>第 l 层权重量化误差矩阵</td></tr><tr><td>\\|W_l\\|_2</td><td>第 l 层权重谱范数</td></tr><tr><td>\\mathbf{h}_{l-1}</td><td>第 l 层输入激活</td></tr><tr><td>p_{\\text{draft}}</td><td>草稿模型下一 token 分布</td></tr><tr><td>p_{\\text{target}}</td><td>目标模型下一 token 分布</td></tr><tr><td>\\mathrm{TV}</td><td>总变差距离</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-quant-error-bound · 共 5 个片段</p>\n"},{"id":"th-comm-lower-bound","title":"张量并行的通信下界","direction":"dir-agent-loop-serve","prereq":[],"plain":"NVL72 上 TP 每层两次 all-reduce，单次通信量正比于批大小×隐藏维×字节数；当互联带宽除以算力之比超过算术强度时，通信成为解码步的硬下界，这也是为什么解码更适合 EP/DP 而非大 TP。","definition":"NVL72 上 TP 每层两次 all-reduce，单次通信量正比于批大小×隐藏维×字节数；当互联带宽除以算力之比超过算术强度时，通信成为解码步的硬下界，这也是为什么解码更适合 EP/DP 而非大 TP。","formula":"$$T_{\\text{comm}}^{\\text{TP}}\\ge\\frac{2\\,(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B\\,d\\,b}{\\beta_{\\text{NVLink}}},\\qquad \\text{Speedup}_{\\text{TP}}\\le\\frac{1}{1+\\frac{2(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B d b}{\\beta_{\\text{NVLink}}\\,T_{\\text{compute}}}}$$","variables":[{"sym":"\\text{TP}","meaning":"张量并行度"},{"sym":"B","meaning":"批大小"},{"sym":"d","meaning":"隐藏维"},{"sym":"b","meaning":"通信元素位宽（BF16=16，FP8=8）"},{"sym":"\\beta_{\\text{NVLink}}","meaning":"NVLink 有效带宽（NVL72 单 GPU 约 900 GB/s 双向）"},{"sym":"T_{\\text{compute}}","meaning":"同层计算时间"}],"derivation":"推导关键一步：环状 all-reduce 分 reduce-scatter 与 all-gather 两阶段，每阶段每卡收发量约为 (N−1)/N 倍总数据量，总数据量为 B·s·h·b_elem，故单次通信量下界为 2(N−1)/N 乘该量除以带宽。","example":"容量决策用途：用于判断给定 NVLink 域内张量并行度与批大小组合是否使通信成为解码步瓶颈，从而决定长上下文解码的并发上限与是否值得跨节点扩展。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设 ring all-reduce 且无计算通信重叠；实际框架用 reduce-scatter + all-gather 与计算流水重叠，有效下界可低于公式值","仅覆盖 TP 的集合通信；EP 的 all-to-all 与 PP 的 point-to-point 有不同拓扑常数，需替换 β 与消息尺寸","未计入 NVLink 域内 vs 跨域（NVL72 机柜内 NVLink、机柜间 InfiniBand）的带宽落差；跨域时 β 下降一个量级，下界急剧恶化"],"system_note":"常见误用：用环状模型估算 NVLS 多播场景而高估通信成本，错失可扩展空间；或忽略跨节点带宽骤降仍按域内带宽外推，导致多节点部署时延远超预期。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["直觉：张量并行每层需两次 all-reduce，单次通信量正比于批内 token 数乘隐藏维，通信时间下界由互联带宽与环状算法决定，解释 NVL72 内 NVLink 域为何是长上下文解码的容量边界。","公式含义：$$t_{\\text{comm}} \\ge \\frac{2(N-1)}{N} \\cdot \\frac{B \\cdot s \\cdot h \\cdot b_{\\text{elem}}}{\\text{BW}_{\\text{link}}}$$ 中 N 为张量并行卡数，B 为批内并发序列数，s 为每步 token 数（解码为 1，投机为 k+1），h 为隐藏维，b_elem 为通信元素字节数，BW_link 为互联有效带宽；因子 2(N−1)/N 来自环状 all-reduce 的两次遍历。","推导关键一步：环状 all-reduce 分 reduce-scatter 与 all-gather 两阶段，每阶段每卡收发量约为 (N−1)/N 倍总数据量，总数据量为 B·s·h·b_elem，故单次通信量下界为 2(N−1)/N 乘该量除以带宽。","适用边界：环状 all-reduce 模型；改用 tree 或 NVLS 多播可降低常数因子，公式变为保守上界；假设通信与计算不重叠，实际流水线可隐藏部分通信；跨节点带宽骤降且引入协议开销，需替换 BW_link 并加固定延迟项。","容量决策用途：用于判断给定 NVLink 域内张量并行度与批大小组合是否使通信成为解码步瓶颈，从而决定长上下文解码的并发上限与是否值得跨节点扩展。","常见误用：用环状模型估算 NVLS 多播场景而高估通信成本，错失可扩展空间；或忽略跨节点带宽骤降仍按域内带宽外推，导致多节点部署时延远超预期。"],"anchors":["NVL72","解码为 1","投机为 k+1"],"pitfalls":["用环状 all-reduce 模型估算 NVLS 多播场景，高估通信成本并错误限制并行度。","忽略跨节点带宽骤降与协议开销，按域内 NVLink 带宽外推多节点部署时延。","假设通信与计算完全不重叠，未计入流水线隐藏，导致对端到端时延的保守误判。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-1\">一 · 一句话直觉：TP 的通信量是&quot;每层两趟全量交换&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-2\">二 · 严格定义：下界、变量与因子来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-3\">三 · 为什么需要这个下界：三个决策场景</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-4\">四 · 常见误解：三个必须拆掉的错误直觉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-5\">五 · 一个具体例子：NVL72 内 TP=8、BF16、解码步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-6\">六 · 定义边界与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-7\">七 · 下界成立的前提，以及它在哪里先失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-8\">八 · 公式逐项：把每一符号钉到硬件与负载上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-9\">九 · 推导关键步：从环状两阶段到因子 2(N−1)/N</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-10\">十 · 离散化与近似：三个被折叠掉的东西</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-11\">十一 · 失效条件与误用：两类典型错判</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-12\">十二 · 把公式当分段函数用：域内与跨域的两次代入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-13\">十三 · 环状下界的常数因子、失效边界与跨域代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-14\">十四 · 公式成立所依赖的四条假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-15\">十五 · 跨域：β 换一个量级，下界整体失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-16\">十六 · 算子替换：EP 与 PP 的常数不同</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-17\">十七 · 规模上限：TP 增大后公式的饱和与失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-18\">十八 · 何时该弃用公式：三个判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-19\">十九 · 公式在什么条件下才配叫“下界”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-20\">二十 · 把下界改写成决策变量：从“通信多久”到“能开多大”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-21\">二十一 · 定并行度：域内 TP 的上限与 EP/DP 的切换点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-22\">二十二 · 定 KV 预算：TP 省下的显存是否被通信吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-23\">二十三 · 定 SLO：把时延预算切成计算段与通信段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-24\">二十四 · 算例：一个可复算的容量推演</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-25\">二十五 · 把下界塞进容量模型：批大小、并行度与 SLO 的联立求解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-26\">二十六 · 误用一：把环状常数套到 NVLS 多播上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-27\">二十七 · 误用二：拿域内带宽外推跨节点时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-28\">二十八 · 误用三：假设通信与计算零重叠</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-29\">二十九 · 反例：一次被公式误导的扩容决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-30\">三十 · 识别清单与工程判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-comm-lower-bound-sec-31\">三十一 · 把下界当实测：三类误用如何把容量决策带偏</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:498px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 497.7 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"415.7\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"415.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：NVL72 上 TP 每层两次 all-reduce，单次通信量正…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"415.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\text{comm}}^{\\text{TP}}\\ge\\…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"415.7\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设 ring all-reduce 且无计算通信重叠；实际框架用…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-comm-lower-bound-sec-1\">一 · 一句话直觉：TP 的通信量是\"每层两趟全量交换\"</h3>\n<p>张量并行的通信下界可以用一句话钉死：<strong>在 NVL72 的 NVLink 域内，TP 每层要做两次 all-reduce，单次通信量正比于批大小 × 隐藏维 × 通信元素字节数；当互联带宽与算力之比超过该层的算术强度时，通信时间就成为解码步的硬下界。</strong>这句话里每个词都不是修辞。两次 all-reduce 对应 Transformer 层里两个必须跨卡汇合的点：注意力输出投影之后（各卡持有部分头，需把部分和加回完整激活）与前馈网络下投影之后（各卡持有部分中间维，需把部分和加回残差流）。所谓\"全量交换\"，指参与归约的张量尺寸是 B·d·b，而不是某个分片尺寸——分片只改变每卡收发比例，不改变归约对象的逻辑大小。</p>\n<p>把这句话翻译成工程判断：TP 不是免费的并行度旋钮。每加一档 TP，你就把一层里原本在 SM 内部完成的加法，搬到 NVLink 上做成跨卡集合通信。解码阶段每步只处理 B 个 token（投机解码时是 B·(k+1)），算术强度极低，于是这条通信路径的固定开销直接压在步时上。这就是为什么长上下文解码在 NVL72 里更像\"容量问题\"而非\"算力问题\"：NVLink 域的大小划定了你能把 TP 推到多高而不让通信吃掉步时。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-2\">二 · 严格定义：下界、变量与因子来源</h3>\n<p>本系列讨论的\"通信下界\"是一个<strong>单层、单次解码步、纯 TP 集合通信</strong>意义下的时间下界，不是端到端时延模型。定义如下：给定 TP 度 N、批内并发序列数 B、每步 token 数 s（解码为 1，投机为 k+1）、隐藏维 h、通信元素字节数 b_elem、互联有效带宽 BW_link，则</p>\n<div class=\"formula\">$$t_{\\text{comm}} \\ge \\frac{2(N-1)}{N} \\cdot \\frac{B \\cdot s \\cdot h \\cdot b_{\\text{elem}}}{\\text{BW}_{\\text{link}}}$$</div>\n<p>因子 2(N−1)/N 的来源必须讲清楚，否则后面所有误用都从这里长出来。环状 all-reduce 拆成 reduce-scatter 与 all-gather 两阶段：每阶段每卡收发的数据量约为 (N−1)/N 倍的总数据量，总数据量为 B·s·h·b_elem，两阶段相加即得 2(N−1)/N。N 趋于无穷时该因子趋近 2，意味着即便 TP 无限大，每层仍要付出两倍全量数据的搬运代价——这是环状算法的拓扑常数，不是实现缺陷。N=2 时因子为 1，N=8 时因子为 1.75，N=72 时因子约为 1.97：曲线在 N 较小时上升快，之后饱和，这解释了为什么小 TP 度下通信占比对 N 敏感、大 TP 度下则几乎只由 B·s·h·b_elem/BW_link 决定。</p>\n<p>与之配套的加速比上界为</p>\n<div class=\"formula\">$$\\text{Speedup}_{\\text{TP}} \\le \\frac{1}{1+\\frac{2(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B\\,d\\,b}{\\beta_{\\text{NVLink}}\\,T_{\\text{compute}}}}$$</div>\n<p>分母第二项就是\"通信时间 / 计算时间\"之比。它给出一个可操作的判据：当该项接近或超过 1 时，加 TP 的边际收益被通信吞掉。注意这是<strong>上界</strong>，因为它假设通信与计算完全不重叠；真实框架用 reduce-scatter + all-gather 与计算流水重叠，有效下界可低于公式值。所以这个公式的正确用法是\"排除法\"——若连这个保守下界都撑不住目标 SLO，方案不必再谈；若撑得住，才有资格去谈重叠能省多少。</p>\n<p>变量语义需逐一定死：sym=TP 为张量并行度；B 为批大小（并发序列数）；d 为隐藏维；b 为通信元素位宽（BF16=16，FP8=8）；β_NVLink 为 NVLink 有效带宽，NVL72 单 GPU 约 900 GB/s 双向；T_compute 为同层计算时间。位宽 b 是这里最容易被忽略的杠杆：FP8 相对 BF16 直接把通信量减半，而 NVFP4 若用于激活通信则再减半——但激活量化的数值风险不在本片段讨论范围，此处只记其带宽效应。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-3\">三 · 为什么需要这个下界：三个决策场景</h3>\n<p><strong>场景一：解码并发上限。</strong>给定 NVLink 域内 TP 度与批大小组合，下界直接回答\"通信是否已成为解码步瓶颈\"。把 t_comm 与同层计算时间 T_compute 并列，若前者占步时的主要份额，则继续加 B 只会线性抬高通信时间而不改善单 token 成本，长上下文解码的并发上限由此确定。这正是\"NVLink 域是容量边界\"的定量版本：域内带宽固定，B·s·h·b_elem 随上下文与并发增长，交点即上限。</p>\n<p><strong>场景二：是否值得跨节点扩展。</strong>跨域时 β 下降一个量级（NVL72 机柜内 NVLink、机柜间 InfiniBand），下界急剧恶化。用域内带宽外推多节点部署的时延是典型错误：消息尺寸不变、带宽掉一个量级、还叠加协议开销与固定延迟项，实际步时会远超线性预期。下界的作用是在部署前就把这条曲线画出来，而不是等上线后发现 TP=16 跨机柜的 decode 步时不可接受。</p>\n<p><strong>场景三：EP/DP 与 TP 的取舍。</strong>解码阶段每步 s=1，算术强度低，通信项在分母中占比高；这正是解码更适合 EP/DP 而非大 TP 的定量理由。EP 的 all-to-all 与 PP 的 point-to-point 有不同拓扑常数，需替换 β 与消息尺寸——本下界只覆盖 TP 的集合通信，把 EP 的专家路由 all-to-all 塞进这个公式会得到错误的量级。指路一句：EP 的通信形态与容量模型属于并行与通信模块的其他条目，此处不展开。</p>\n<p>代价维度要分开记：这个下界约束的是<strong>延迟</strong>（解码步时）与<strong>带宽</strong>（NVLink 有效吞吐），间接约束<strong>显存</strong>（TP 度决定每卡权重分片，进而决定可容纳的 KV cache 预算）与<strong>功耗</strong>（跨卡搬运的 SerDes 能耗随消息量线性增长）。四者中延迟是最先被击穿的，因为解码步时对固定开销极其敏感。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-4\">四 · 常见误解：三个必须拆掉的错误直觉</h3>\n<p><strong>误解一：用环状模型估算 NVLS 多播场景。</strong>公式的 2(N−1)/N 因子是环状 all-reduce 的拓扑常数。改用 tree 或 NVLS 多播可降低常数因子，此时公式变为保守上界而非紧下界。把它当作 NVLS 场景的真实成本，会高估通信开销、错误限制并行度，错失可扩展空间。判断方法：先确认框架在该层实际走的是 ring 还是 NVLS/tree，再决定用哪个常数；两者混用是本系列最常见的定量错误。</p>\n<p><strong>误解二：忽略跨节点带宽骤降仍按域内带宽外推。</strong>NVL72 机柜内 NVLink 与机柜间 InfiniBand 的带宽落差是一个量级，且跨域引入协议开销与固定延迟项。用 β_NVLink 代入跨域消息，得到的 t_comm 会乐观一个量级，多节点部署时延远超预期。正确做法是把 BW_link 换成跨域有效带宽并加固定延迟项，重新算交点。</p>\n<p><strong>误解三：假设通信与计算完全不重叠。</strong>公式的失效条件之一就是\"无计算通信重叠\"。实际框架用 reduce-scatter + all-gather 与计算流水重叠，有效下界可低于公式值。把公式值当成端到端时延会得到保守误判——但这不等于可以反过来乐观：重叠能隐藏的是计算窗口内的通信，解码步计算窗口极短，可隐藏比例有限，所以公式在解码场景反而更接近真实。这个不对称性正是本下界在 prefill 与 decode 两个阶段解释力不同的根源。</p>\n<p>还有一个隐性误解值得点名：把\"下界\"读成\"实际值\"。下界是排除性工具，不是预测工具。它的价值在于快速否掉不可行组合，而不是精确预报步时；精确预报需要把重叠、NVLS 常数、跨域延迟项都补进去，那是后续部分的工作。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-5\">五 · 一个具体例子：NVL72 内 TP=8、BF16、解码步</h3>\n<p>取 NVL72 机柜内一个 TP=8 的部署，BF16 通信（b_elem=2 字节），解码步 s=1，隐藏维取一个常见量级、批内并发 B 逐步抬高。代入因子 2(N−1)/N = 2×7/8 = 1.75，单次通信量为 1.75·B·h·2 字节，除以 β_NVLink≈900 GB/s 得 t_comm。定性地说：B 较小时 t_comm 远小于同层计算时间，TP=8 在域内是划算的；随着 B 与上下文长度上升，t_comm 线性增长而 T_compute 增长较缓（解码算力利用率低），交点出现，此后加 B 只抬高步时。把 b_elem 从 2 换成 1（FP8 通信），整条曲线下移一半，交点右移——这就是量化对 TP 通信下界的直接杠杆，与量化误差问题是两回事。</p>\n<p>同一例子换到跨机柜：β 掉一个量级，t_comm 上升约十倍，交点急剧左移，TP=8 跨域在解码阶段基本不可行。这不是\"大概会慢\"，而是公式给出的量级判断：带宽项在分母，十倍带宽落差就是十倍通信时间，无可回避。此时正确动作是缩回域内 TP、改用 EP/DP 扩展，而不是硬扛跨域 all-reduce。</p>\n<p>再换到投机解码：s = k+1，通信量按 k+1 倍放大。投机解码的期望加速比本身有独立上界（见该条目），但这里要记的是它对 TP 下界的副作用——投机把每步 token 数抬高，等于把 t_comm 抬高同样倍数，若 TP 度已经接近交点，投机带来的通信开销可能吃掉相当一部分草稿收益。这是两个界耦合的地方，也是容量规划时必须联立求解的原因。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-6\">六 · 定义边界与工程判断</h3>\n<p>本下界的适用边界必须写进任何一份容量文档：环状 all-reduce 模型；tree 或 NVLS 多播下公式变为保守上界；假设通信与计算不重叠，流水线可隐藏部分通信；仅覆盖 TP 的集合通信，EP 的 all-to-all 与 PP 的 point-to-point 需替换 β 与消息尺寸；未计入 NVLink 域内与跨域的带宽落差，跨域时 β 下降一个量级、下界急剧恶化。五条边界里任何一条被违反，公式给出的数字就只能当量级参考，不能当判据。</p>\n<p>工程判断落在具体机制上：拿到一个部署方案，先算 2(N−1)/N·B·s·h·b_elem/β 与 T_compute 的比值，比值远小于 1 则 TP 可加，接近 1 则加 TP 无益、应转向 EP/DP 或降 b_elem，远大于 1 则当前 TP 度与批大小组合在解码阶段已被通信锁死，唯一出路是缩域或换并行形态。这个比值不需要任何实测，只需要拓扑常数、带宽与形状——这正是下界的工程价值：在写第一行配置之前就把不可行组合排除掉。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-7\">七 · 下界成立的前提，以及它在哪里先失效</h3>\n<p>公式里那个 2(TP−1)/TP 的系数不是拓扑常数，而是环状 all-reduce 的算法常数：reduce-scatter 与 all-gather 各走一遍环，每卡每阶段收发 (TP−1)/TP 倍的总数据量。一旦框架改用 NVLS 多播或 tree 归约，这个系数就不再是下界而是保守上界——用环状模型去估算 NVLS 场景，会把通信成本算高，进而错误地压低并行度、错失本可扩展的空间。反过来，把域内 900 GB/s 双向带宽直接外推到跨机柜 InfiniBand，β 下降一个量级且叠加协议固定延迟，公式必须改写为 T_comm ≥ 2(TP−1)/TP·B·d·b/β_cross + L_proto，此时下界急剧恶化，多节点部署时延远超按域内带宽的预期。</p>\n<p>第二个前提是“通信与计算不重叠”。真实框架用 reduce-scatter + all-gather 与同层 MMA 流水重叠，有效下界可低于公式值；把不重叠假设当成端到端时延预测，会系统性高估解码步耗时。第三个前提是“只覆盖 TP 的集合通信”：EP 的 all-to-all 与 PP 的点对点有完全不同的拓扑常数与消息尺寸，必须替换 β 与消息量，不能拿 TP 的 2(TP−1)/TP 直接套用。这也解释了为什么解码阶段更适合 EP/DP——TP 每层两次 all-reduce 的通信量与批大小×隐藏维成正比，而解码每步 token 数固定为 1（投机为 k+1），算术强度低，通信项在 T_compute 面前占比被放大。</p>\n<table class=\"mini\"><thead><tr><th>假设</th><th>失效后的修正</th><th>系统代价方向</th></tr></thead><tbody><tr><td>环状 all-reduce</td><td>NVLS/tree 降低常数因子</td><td>高估通信、低估可扩展性</td></tr><tr><td>无计算通信重叠</td><td>流水线隐藏部分通信</td><td>高估解码步时延</td></tr><tr><td>域内 NVLink 带宽</td><td>跨域替换 β 并加固定延迟</td><td>多节点时延远超预期</td></tr><tr><td>仅 TP 集合通信</td><td>EP/PP 替换拓扑常数与消息尺寸</td><td>误判瓶颈所在层</td></tr></tbody></table>\n<p>工程判断上，这个下界的用途是容量决策而非精确预测：给定 NVLink 域内的 TP 度与批大小组合，判断通信是否已成为解码步瓶颈，从而定出长上下文解码的并发上限、以及是否值得跨节点扩展。使用时必须标注它属于哪一类集合通信、是否假设重叠、β 取自域内还是跨域，三者任一错配，结论就会偏向保守或激进。</p>\n<h3 id=\"th-comm-lower-bound-sec-8\">八 · 公式逐项：把每一符号钉到硬件与负载上</h3>\n<p>先把公式摆正，再逐项拆。TP 解码步的通信下界写成</p>\n<div class=\"formula\">$$T_{\\text{comm}}^{\\text{TP}}\\ge\\frac{2\\,(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B\\,d\\,b}{\\beta_{\\text{NVLink}}}$$</div>\n<p>这里每一个符号都不是抽象代数，而是能在 NVL72 机柜里指到具体位置的东西。TP 是张量并行度，也就是同一层权重被切成的份数，同时等于参与该层集合通信的 GPU 数；B 是批内并发序列数（不是 token 总数，解码步每序列出一个 token）；d 是隐藏维；b 是通信元素的位宽，BF16 取 16、FP8 取 8，单位是比特，落到公式里要和带宽单位对齐；β_NVLink 是 NVLink 有效带宽，NVL72 单 GPU 双向约 900 GB/s 量级，注意“有效”二字——它已经扣掉了协议开销与实测可达比例，不是理论峰值。分子 B·d·b 是单次 all-reduce 搬运的原始数据量：一个解码步里，B 条序列各产生一个 d 维向量，按 b 比特打包。分母 β 把它换算成时间。前面的因子 2(TP−1)/TP 是环状算法的拓扑常数，两个来源：一是每层要两次 all-reduce（前向一次、反向传播在推理中不存在，但注意这里是每层权重切分后的前向激活同步，实际推理每层一次激活 all-reduce，公式里的 2 对应 reduce-scatter 与 all-gather 两个阶段），二是环上每卡收发的比例 (TP−1)/TP——因为每卡自己那一份不需要发给自己。</p>\n<p>关键要看清：这个式子里 B 和 d 是负载侧可调的，b 是精度策略可调的，TP 是并行策略可调的，只有 β 是硬件给定的。工程上所有讨论都围绕“把哪个变量按住、让哪个变量动”展开。一个具体例子：B=32、d=8192、b=16 bit（即 2 字节）、TP=8，则单次通信原始量为 32×8192×2 B = 512 KiB，乘因子 2×7/8 = 1.75，得 896 KiB；除以 900 GB/s，单层单次约 1.0 μs 量级。若模型有 80 层，一个解码步的纯通信下界就在 80 μs 量级——这已经和一个小 batch 解码步的计算时间同量级，通信不再是“顺带”，而是步长的主项之一。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-9\">九 · 推导关键步：从环状两阶段到因子 2(N−1)/N</h3>\n<p>推导的核心不在积分也不在近似，而在一个离散的、有明确拓扑假设的计数论证。设总数据量为 M = B·d·b（比特）。环状 all-reduce 拆成 reduce-scatter 与 all-gather 两段，每段在 N 张卡组成的环上走 N−1 步，每步每卡向邻居发送 M/N 的数据块。于是每段每卡的总发送量为 (N−1)·M/N，两段相加得 2(N−1)M/N，这就是因子 2(N−1)/N 的全部来历。它随 N 单调上升并趋近 2：N=2 时为 1，N=8 时为 1.75，N=16 时为 1.875，N=72 时逼近 1.97。也就是说，TP 越大，拓扑常数越接近 2，但边际收益递减——从 8 到 16 只把常数从 1.75 抬到 1.875，真正恶化的是 β 在跨域时的骤降，而不是这个常数。</p>\n<p>把通信时间与计算时间并列，就得到加速比上界：</p>\n<div class=\"formula\">$$\\text{Speedup}_{\\text{TP}}\\le\\frac{1}{1+\\frac{2(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B d b}{\\beta_{\\text{NVLink}}\\,T_{\\text{compute}}}}$$</div>\n<p>分母第二项是“通信时间 / 计算时间”的无量纲比。推导上它来自把 T_comm 除以 T_compute 后代入 Amdahl 型串行份额：TP 带来的计算缩短被通信的固定开销吃掉一部分。这一步的离散化在于：T_compute 被当作同层一次矩阵乘的时间，而实际解码步里 GEMM 的 M 维只有 B（每序列一个 token），是典型的瘦长矩阵乘，算术强度低、受显存带宽约束而非算力约束——所以 T_compute 本身不是算力峰值除 FLOPs，而是权重读取时间除带宽。这一点决定了分母第二项往往比直觉大：B 小的时候 T_compute 被权重加载主导，通信占比反而更突出。</p>\n<p>近似的边界必须写清楚。第一，模型假设 ring all-reduce 且通信与计算完全不重叠；实际框架用 reduce-scatter + all-gather 与计算流水重叠，有效下界可低于公式值，公式因此是保守上界而非精确预测。第二，只覆盖 TP 的集合通信；EP 的 all-to-all 与 PP 的 point-to-point 有不同拓扑常数，需替换 β 与消息尺寸，不能拿这个式子套 EP。第三，未计入 NVLink 域内与跨域的带宽落差：NVL72 机柜内走 NVLink，机柜间走 InfiniBand，跨域时 β 下降一个量级，下界急剧恶化。第四，未加固定延迟项，小消息时协议开销与 kernel launch 占比不可忽略。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-10\">十 · 离散化与近似：三个被折叠掉的东西</h3>\n<p>公式之所以“下界”而不是“精确值”，是因为推导里折叠了三类离散结构。其一是消息分块：环状算法把 M 切成 N 块，块大小必须是元素对齐的，d 不能被 N 整除时会有 padding，实际搬运量略高于 M；这个偏差在 d=8192、N=8 时可忽略，但在 N=72、d 较小时会显现。其二是步进延迟：N−1 步不是零开销的，每步有固定的 hop latency 与协议处理，公式只用 β 除总量，等于假设带宽完全饱和、延迟被摊薄；小消息场景下这个假设失效，应加一项 α·(N−1) 的固定延迟。其三是重叠粒度：真实流水线以层为单位重叠，重叠效率取决于计算与通信的时长比，公式取“不重叠”是取了下界的最坏一侧，取“完全重叠”则是另一侧极端，两者之间才是工程可调区间。</p>\n<p>工程含义很直接：当你用这个式子做容量判断时，它给的是“通信不可能比这更快”的硬地板，而不是“通信将会花这么久”的预测。用它来否决一个 TP 配置是安全的（实际只会更好），用它来承诺一个 SLO 是不安全的（实际可能因跨域、padding、延迟项而更差）。一个具体判断：长上下文解码时 KV cache 读取已经把每步时间压在显存带宽上，此时若公式给出的 T_comm 与 T_compute 同量级，说明 TP 已经触及 NVLink 域的天花板，继续加 TP 只会让因子趋近 2 而 β 不变，加速比上界趋平——这正是“解码更适合 EP/DP 而非大 TP”的定量依据。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-11\">十一 · 失效条件与误用：两类典型错判</h3>\n<p>第一类误用是用环状模型估算 NVLS 多播场景。NVLink Switch 的多播把 all-reduce 的常数因子压低，实际通信成本低于 2(N−1)/N·M/β，此时公式变成保守上界；若照搬它去限制并行度，会高估通信成本、错失可扩展空间。第二类误用是忽略跨节点带宽骤降，仍按域内 900 GB/s 外推多节点部署时延。跨域时 β 下降一个量级并引入协议开销，公式里的分母骤减，下界急剧恶化——多节点 TP 的实测时延远超按域内带宽算出的预期，根源就在这里。两类误用的共同点是：把 β 当成一个与拓扑无关的常数。事实上 β 是分段函数，域内一段、跨域一段，公式必须分段代入。</p>\n<p>还有一个隐蔽的失效点：把 B 当成 token 总数。解码步每序列只出一个 token，投机解码则为 k+1 个，所以公式里的 B·d 在投机场景要乘上 (k+1)。若误用总 token 数，会把通信量高估一个量级，进而错误地判定 TP 不可行。反过来，若在投机场景仍按 B·d 算，会低估通信、给出过于乐观的加速比上界。数字锚点很明确：解码为 1，投机为 k+1，这个乘数必须显式写进 B 的有效值里。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-12\">十二 · 把公式当分段函数用：域内与跨域的两次代入</h3>\n<p>正确的用法是把同一个式子代入两次。域内代入 β_NVLink（约 900 GB/s 量级），得到机柜内的通信地板；跨域代入 β_IB（低一个量级）再加固定延迟项，得到跨机柜的地板。两次结果的比值就是“值不值得跨节点扩展 TP”的判据：若跨域地板已经超过 T_compute 的数倍，加速比上界趋近于 1，扩展无意义，应转向 EP/DP 或减少 TP、增加副本。这个判据不需要任何实测数字，只需要把 B、d、b、TP 和两段 β 代进去比较量级。</p>\n<p>具体到 NVL72：机柜内 72 张 GPU 共享 NVLink 域，域内 TP 的 β 高、常数趋近 2，地板由 B·d·b 主导；一旦 TP 超过单机柜粒度需要跨域，β 骤降使分母缩小一个量级，同样的 B·d·b 产生的地板抬高一个量级。于是容量决策变成一个简单的不等式：让 2(TP−1)/TP·B·d·b/β_domain 与 T_compute 同量级，是域内 TP 的甜点；再往上加 TP，分子因子趋近 2 而分母不变，收益封顶。这也解释了为什么长上下文解码的并发上限本质上是 NVLink 域的容量边界——不是显存不够，而是每步 all-reduce 的地板已经把步长锁死。</p>\n<p>最后落到一个可操作的工程判断：把这个式子写进容量规划脚本时，β 必须按拓扑分段配置，B 必须按解码/投机分别取 1 或 k+1，T_compute 必须按显存带宽约束而非算力峰值估算，并显式保留一个“重叠效率”系数在 0 到 1 之间调节——公式给的是地板，重叠效率决定实际离地板多远。任何把 β 当全局常数、把 B 当 token 总数、把 T_compute 当算力除 FLOPs 的用法，都会让这个下界失去判据价值。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-13\">十三 · 环状下界的常数因子、失效边界与跨域代价</h3>\n<p>把公式拆开看，真正决定量级的是三个乘子：因子 2(TP−1)/TP、消息量 B·d·b、以及带宽 β。因子在 TP=2 时为 1，TP=8 时为 1.75，TP=72 时逼近 2——也就是说并行度越高，单次 all-reduce 的收发量越接近“两倍消息量”，但永远不超过它。这就是为什么扩大 TP 的边际收益递减：分母里的 T_compute 随 TP 缩小，分子里的通信量却随 (TP−1)/TP 饱和。推导的关键一步在于 reduce-scatter 与 all-gather 两阶段各让每卡收发 (TP−1)/TP 倍总数据量，两阶段相加才得到那个 2 倍系数；若把两阶段误当成一次遍历，下界会被低估一半，容量规划就会偏向过于乐观的并发上限。离散化误差来自消息量按 B·d·b 连续估算，而实际 all-reduce 以固定大小的 chunk 流水推进，隐藏维不能被 chunk 整除时尾部小块拉低有效带宽；解码步 s=1、投机步 s=k+1 的差别也在这里体现——投机把消息量乘以 k+1，通信下界同步放大，收益必须由接受率来偿还。</p>\n<p>公式的适用边界比公式本身更重要。它假设环状 all-reduce 且通信与计算完全不重叠，因此是一个保守上界而非精确预测：实际框架用 reduce-scatter + all-gather 与计算流水重叠，有效下界可低于公式值；改用 tree 或 NVLS 多播会把常数因子压下来，此时继续套用环状模型就会高估通信成本，错误地限制并行度、错失可扩展空间。它也只覆盖 TP 的集合通信——EP 的 all-to-all 与 PP 的 point-to-point 有各自的拓扑常数，必须替换 β 与消息尺寸，不能拿同一个 β 外推。最危险的失效条件是跨域：NVL72 机柜内走 NVLink，机柜间走 InfiniBand，β 下降一个量级，下界急剧恶化，还要叠加协议固定延迟项。用域内 900 GB/s 双向带宽去外推多节点时延，得到的数字与实测会差出一个数量级，这正是长上下文解码把 NVLink 域当作容量边界的根本原因。</p>\n<p>工程判断落在“该不该跨域”这一条线上。给定域内 TP 与批大小组合，先算通信下界占解码步时间的比例：若 2(TP−1)/TP·B·d·b/β 已经与 T_compute 同量级，说明通信是硬下界，此时增大 TP 只会把瓶颈从算力搬到互联，正确动作是降 TP、改走 EP/DP 扩并发，或缩短上下文以压低 B·d。跨域扩展只在一种情形下值得：域内并发已被 β 卡死，而跨域后 β 降一个量级仍能靠更大的聚合带宽摊薄单卡消息量——这需要把固定延迟项一并计入，否则流水线隐藏不掉的那部分延迟会直接吃掉吞吐。</p>\n<table class=\"mini\"><thead><tr><th>场景</th><th>β 取值口径</th><th>下界修正</th><th>系统代价</th></tr></thead><tbody><tr><td>域内环状</td><td>NVLink 有效带宽</td><td>公式原值，保守上界</td><td>TP 增大后通信占比饱和</td></tr><tr><td>域内 NVLS 多播</td><td>同上，常数因子更小</td><td>环状模型高估成本</td><td>误限并行度，浪费可扩展空间</td></tr><tr><td>跨域</td><td>InfiniBand，降一个量级</td><td>替换 β 并加固定延迟</td><td>时延远超域内外推值</td></tr></tbody></table>\n<p>因此这条下界的正确用法是当筛子而非当尺子：先用它筛掉“通信必然压过计算”的 TP×B 组合，再用实测的有效 β 与重叠效率去校准剩下的候选。任何把环状常数、域内带宽、零重叠三个假设同时当真并外推到多机的估算，都会在机柜边界上失效。</p>\n<h3 id=\"th-comm-lower-bound-sec-14\">十四 · 公式成立所依赖的四条假设</h3>\n<p>本卷前两部分给出的下界并非无条件成立，它是一组假设的产物。把这组假设逐条拆开，才能判断在什么部署形态下公式仍然可用、在什么形态下必须替换参数或整体弃用。四条假设分别是：其一，集合通信算子为环状 all-reduce，即 reduce-scatter 与 all-gather 两阶段各遍历一次环；其二，通信与计算完全不重叠，通信时间被串行计入解码步；其三，参与通信的链路是同构的，全部落在 NVL72 机柜内的 NVLink 域，有效带宽取单 GPU 约 900 GB/s 双向；其四，被建模的通信只有张量并行这一种，专家并行的 all-to-all 与流水并行的点对点不在项内。四条同时成立时，$$T_{\\text{comm}}^{\\text{TP}}\\ge\\frac{2(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B\\,d\\,b}{\\beta_{\\text{NVLink}}}$$ 才是一个可信的下界；任何一条被破坏，公式要么变成保守上界，要么直接失去量纲上的意义。工程上最常见的错误不是公式本身算错，而是把四条假设默默带进了不满足它们的场景。</p>\n<p>第一条假设的代价最容易被低估。环状算法的因子 2(TP−1)/TP 在 TP 较大时趋近于 2，意味着每层通信量约等于两倍激活数据量；而 NVLS 多播把同一份数据一次写入域内所有 GPU 的显存，常数因子显著低于环状两阶段。用环状模型去估算 NVLS 场景，会把通信成本高估，进而得出“并行度不能再涨”的错误结论，错失本可扩展的空间。反过来，在 NVLS 不可用（例如跨域或拓扑不支持多播）时套用多播的低常数，则会低估时延。判断依据是框架实际下发的通信原语：TensorRT-LLM 与 vLLM 在 NVLink 域内倾向于走 NVLS 或多播路径，此时公式应视为保守上界而非紧下界。</p>\n<p>第二条假设的工程含义是流水线隐藏。实际框架把 reduce-scatter 与下一层的计算重叠、把 all-gather 与后续算子重叠，有效通信时间可低于公式值。这条假设被破坏的方向是“公式偏保守”，对容量规划而言是安全侧；但如果据此认为通信永远可以被完全隐藏，就会在计算密度低的解码步上翻车——解码每步只有一次矩阵向量乘，计算时间短到无法覆盖通信，隐藏率趋近于零，此时公式反而接近真实。一个具体例子：长上下文解码、批大小 B 较大、隐藏维 d 固定时，计算时间几乎不随 B 增长而通信量正比于 B，重叠窗口被迅速吃穿，公式从保守转为紧致。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-15\">十五 · 跨域：β 换一个量级，下界整体失效</h3>\n<p>第三条假设是最锋利的失效边界。NVL72 机柜内是 NVLink 域，单 GPU 有效带宽约 900 GB/s 双向；一旦 TP 组跨出机柜，链路落到机柜间 InfiniBand，有效带宽下降一个量级，并引入协议栈固定延迟。此时公式结构不变，但必须替换 β 并追加固定延迟项：</p>\n<div class=\"formula\">$$T_{\\text{comm}}^{\\text{TP}}\\ge\\frac{2(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B\\,d\\,b}{\\beta_{\\text{cross}}}+L_{\\text{proto}}$$</div>\n<p>其中 β_cross 是跨域有效带宽，L_proto 是协议与路由引入的固定开销。带宽降一个量级意味着同一批大小下通信时间涨一个量级，原本被 NVLink 域压住的通信项立刻跃升为主导项。这正是“NVL72 内 NVLink 域是长上下文解码容量边界”这句话的定量来源：域内 TP 可以撑到较大并行度而通信仍不致命，跨域后同样的并行度直接把解码步拖垮。工程判断因此变得清晰——TP 的规模上限由域边界而非 GPU 数量决定；需要更大并行度时，正确动作是换并行策略（EP/DP）而不是把 TP 硬推出机柜。</p>\n<p>跨域失效还有一个隐蔽变体：机柜内并非所有通信都同构。NVL72 内部的 NVLink 交换机拓扑使得部分 all-reduce 路径经过多跳，有效带宽低于单跳峰值；把 900 GB/s 当作全域统一值会在中等并行度上系统性低估时延。稳妥做法是按实际拓扑分层取 β，而不是用一个数字外推所有 TP 取值。容量规划时若只能取单值，应取该 TP 组内最差路径的带宽，得到的是悲观但可交付的下界。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-16\">十六 · 算子替换：EP 与 PP 的常数不同</h3>\n<p>第四条假设限定公式只覆盖 TP 的集合通信。专家并行的 all-to-all 与流水并行的点对点有完全不同的拓扑常数与消息尺寸，不能把 TP 的因子直接搬过去。EP 的 all-to-all 消息尺寸取决于路由到的专家数与被激活 token 数，在 MoE 解码中每个 token 只路由到少数专家，消息尺寸小于 TP 的激活量，但 all-to-all 的拓扑常数与环状 all-reduce 不同，且对不均衡路由极其敏感——热点专家会把个别链路的有效带宽压到远低于平均值。PP 的点对点则是微批流水，消息尺寸为单微批激活，常数接近 1 而非 2(TP−1)/TP，但引入流水气泡，气泡代价不在通信项内而在调度项内。</p>\n<p>因此“解码更适合 EP/DP 而非大 TP”这一判断的正确读法是：在 NVLink 域内，TP 的通信下界随 TP 增大而趋近饱和值，而 EP 的消息尺寸随路由稀疏度下降，DP 则几乎不产生集合通信。三者不是同一公式的不同参数，而是不同公式。把 TP 公式套到 EP 上会得出错误的并行度建议：EP 的瓶颈往往不在带宽而在路由不均衡与 all-to-all 的同步点，此时增加 EP 度未必改善时延，反而放大长尾。一个具体例子：MoE 解码层中若某专家承接了远超均值的 token，all-to-all 的完成时间由最慢链路决定，TP 公式里的平均带宽假设在这里彻底失效。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-17\">十七 · 规模上限：TP 增大后公式的饱和与失真</h3>\n<p>即便四条假设全部成立，公式也有规模上限。观察因子 2(TP−1)/TP，TP 从 2 增至 8 时该因子从 1 升到 1.75，继续增至 72 时趋近 2，边际变化迅速衰减。这意味着在固定 B、d、b 下，通信时间随 TP 的增长很快饱和，而计算时间随 TP 近似按 1/TP 下降——加速比上界 $$\\text{Speedup}_{\\text{TP}}\\le\\frac{1}{1+\\frac{2(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B d b}{\\beta_{\\text{NVLink}}\\,T_{\\text{compute}}}}$$ 中分母第二项的相对权重随 TP 上升而上升，最终加速比被通信项钉死。公式在 TP 很大时仍然“成立”，但它给出的结论已经从“通信可忽略”翻转为“通信是硬下界”，此时继续增大 TP 的收益趋近于零。</p>\n<p>规模上限还有第二个来源：批大小 B。解码步中 B 是并发序列数，通信量正比于 B，而单序列的计算量固定，因此存在一个临界批大小，超过它之后通信项主导、吞吐不再随 B 线性增长。容量决策正是用这个临界点判断长上下文解码的并发上限：在给定 NVLink 域与 TP 度下，把 B 推到临界点之上只会增加时延而不增加有效吞吐。这也是为什么长上下文场景下“堆并发”不是免费午餐——KV cache 显存与 TP 通信下界从两侧同时收紧并发容量，前者约束能放多少序列，后者约束放进去之后每步要付多少通信代价。</p>\n<p>公式失真的第三种情形是隐藏维 d 与元素位宽 b 的组合。NVFP4/FP8 把 b 从 16 降到 8 或 4，通信量按比例下降，公式给出的下界随之放松；但如果框架在量化前后插入反量化与重排算子，这些算子的时间不计入通信项却计入解码步，端到端时延不会按 b 的比例改善。把 b 的下降直接换算成时延下降，是把公式的适用范围悄悄扩大到了它没有建模的算子边界之外。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-18\">十八 · 何时该弃用公式：三个判据</h3>\n<p>给出可操作的弃用判据比罗列失效条件更有用。判据一：通信原语不是环状 all-reduce。若框架下发的是 NVLS 多播或 tree，公式退化为保守上界，可用于安全侧容量规划，但不能用于判断“是否值得增加并行度”，因为常数被高估会系统性压低可行并行度。判据二：TP 组跨越 NVLink 域边界。此时必须替换 β 并追加固定延迟，未替换的公式输出没有工程意义；跨域部署的时延由 β_cross 与 L_proto 决定，与域内公式不在同一量级。判据三：被建模的通信不是 TP。EP 的 all-to-all 与 PP 的点对点需各自建立消息尺寸与拓扑常数，套用 TP 公式会给出方向性错误的并行策略建议。</p>\n<p>三个判据之外还有一条软判据：计算通信重叠率未知时，公式是下界还是上界取决于重叠率。重叠率高则公式偏保守，重叠率低（解码步、大 B、低计算密度）则公式接近紧致。工程上应把重叠率作为显式参数记录在容量模型里，而不是默认它等于某个经验值。一个具体机制：把每层的 reduce-scatter 与下一层注意力计算排在同一流上，用事件同步控制依赖，重叠窗口等于下一层计算时间；当该时间小于通信时间时，重叠率由计算时间除以通信时间给出，公式的保守程度随之可算。</p>\n<p>最终落在工程判断上：这条下界的价值不在于给出一个精确数字，而在于给出一个可替换参数的骨架——β 按拓扑分层取、常数按通信原语取、消息尺寸按并行策略取、重叠率按计算密度取。四个取值一旦确定，公式就从“教科书下界”变成“该部署形态下的容量判据”；四个取值中任何一个被默认成域内峰值带宽或环状常数，公式的输出就会偏离实际一个量级，而偏离的方向往往是低估多节点部署时延，这正是多节点上线后时延远超预期的根因。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-19\">十九 · 公式在什么条件下才配叫“下界”</h3>\n<p>该下界成立的前提是三件事同时为真：拓扑是环、算法是两次遍历的 all-reduce、通信与计算串行。三者缺一，公式就从“下界”退化为“某个特定实现的估计值”。最典型的失效是 NVLS 多播：机柜内 NVLink Switch 支持把一份数据一次分发到多卡，reduce-scatter 阶段的常数因子不再是 (N−1)/N 而是接近 1/N 量级的分摊，此时仍套用环状模型会把通信成本高估数倍，直接导致并行度被错误压低、长上下文解码的并发上限被人为砍掉。反过来，若框架已用 reduce-scatter + all-gather 与计算流水重叠，公式给出的值只是保守上界，真实解码步里通信可被大部分隐藏——用保守值做容量规划会过量采购，用乐观值做 SLO 承诺则会违约，两者都不对。</p>\n<p>第二个边界是“只覆盖 TP 集合通信”。EP 的 all-to-all 是另一套拓扑常数：消息尺寸随专家路由的 token 分布而抖动，最热专家决定尾延迟，不能用 B·d·b 这个规整量代入；PP 的 point-to-point 更是只传激活切片，消息尺寸与微批数挂钩。把这些通信混进同一个 β 里做统一估算，等于假设所有集合通信共享同一带宽曲线，而 NVL72 机柜内 NVLink 与机柜间 InfiniBand 之间存在一个量级的落差，跨域时 β 骤降、协议开销与固定延迟项浮现，下界急剧恶化。工程判断因此很直接：先确认并行组的物理跨度是否落在同一 NVLink 域内，再决定用哪个 β；跨域扩展的收益必须用替换后的 β 重算，而不是按域内带宽线性外推。</p>\n<div class=\"formula\">$$T_{\\text{comm}}^{\\text{TP}}\\ge\\frac{2(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B\\,s\\,d\\,b}{\\beta_{\\text{link}}}+\\tau_{\\text{proto}},\\qquad \\beta_{\\text{link}}=\\begin{cases}\\beta_{\\text{NVLink}} &amp; \\text{域内}\\\\ \\beta_{\\text{IB}} &amp; \\text{跨域}\\end{cases}$$</div>\n<p>第三个边界是规模上限本身。当 TP 增大，2(TP−1)/TP 迅速饱和到 2，通信量不再随并行度下降，而每卡承载的计算量却按 1/TP 缩小，算术强度被摊薄，加速比曲线提前压平；此时继续加卡只是把同一份 B·d·b 在更多链路上搬运。解码场景尤其残酷：s=1，投机解码也不过 k+1，分子小到无法摊薄固定延迟 τ_proto，通信占比反而随 TP 上升。这正是解码更适合 EP/DP 而非大 TP 的定量理由——把并行维度换到专家或数据侧，让每卡保留足够算术强度，比在 NVLink 域内硬堆 TP 更划算。容量决策上，应把该式作为筛选器：给定 NVLink 域大小与目标批大小，先算出通信占解码步的比例，超过阈值就停止扩 TP，转而评估跨域 EP 的 all-to-all 尾延迟是否可接受。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>公式状态</th><th>系统代价表现</th></tr></thead><tbody><tr><td>环状 all-reduce、无重叠</td><td>有效下界</td><td>解码步被通信钉死，TP 扩不动</td></tr><tr><td>NVLS 多播</td><td>高估（保守上界）</td><td>误限并行度，浪费可扩展空间</td></tr><tr><td>计算通信流水重叠</td><td>偏保守</td><td>端到端时延被低估风险在反向</td></tr><tr><td>跨 InfiniBand 域</td><td>失效，需换 β 并加 τ</td><td>多节点部署时延远超预期</td></tr></tbody></table>\n<h3 id=\"th-comm-lower-bound-sec-20\">二十 · 把下界改写成决策变量：从“通信多久”到“能开多大”</h3>\n<p>前面给出的下界是时间量纲的：给定 TP、B、d、b、β，算出解码一步里 all-reduce 至少要多久。但在容量决策里，工程上真正要问的往往反过来——给定一个 SLO（每 token 时延上限、或每秒 token 数下限），我最多能开多大的 TP、多大的批、多长的上下文。做法是把不等式两边对 B 求解，把时间下界翻译成批大小的上界。设解码步的计算时间为 T_compute，则端到端一步时间不小于 T_compute + T_comm^TP，要求它不超过 SLO 给出的单步预算 T_slo，于是</p>\n<div class=\"formula\">$$B \\le \\frac{\\text{TP}}{2(\\text{TP}-1)}\\cdot\\frac{\\beta_{\\text{NVLink}}\\,b}{d\\,b_{\\text{elem}}}\\cdot\\left(T_{\\text{slo}}-T_{\\text{compute}}\\right)$$</div>\n<p>这个式子的结构值得逐项读：TP/(TP−1) 随 TP 增大迅速趋近 1，说明并行度本身对批上限的“惩罚”是饱和的；β/d 说明隐藏维越大、单 token 的通信字节越多，批就越开不上去；括号里那一项才是关键——它把 SLO 切成“计算预算”和“通信预算”两块，通信预算一旦被 T_compute 吃掉大半，批上限就塌下来。工程含义是：在 NVLink 域内，TP 从 2 加到 8 对 B 上限的压缩远小于把 d 从 4k 翻到 8k 带来的压缩。所以定并行度时先看 d，再看 SLO 里留给通信的那一段余量。</p>\n<p>注意这个 B 是“批内并发序列数”而非 token 数，解码步 s=1，投机解码时 s=k+1，此时把 B·s 整体代入，等价于把有效批放大 k+1 倍——这解释了为什么投机解码在 TP 较大的部署里对通信下界格外敏感：草稿 token 数直接把 all-reduce 的消息尺寸乘上去，而验证阶段的计算时间并未同比例增长。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-21\">二十一 · 定并行度：域内 TP 的上限与 EP/DP 的切换点</h3>\n<p>把加速比上界写成 TP 的函数，可以读出“加卡还值不值”。令 ρ = 2·B·d·b_elem / (β_NVLink·T_compute) 为通信时间与计算时间之比在 TP→∞ 时的极限（因子 (TP−1)/TP→1），则 Speedup_TP ≤ 1/(1+ρ·(TP−1)/TP)。当 ρ 很小，分母趋近 1，加卡几乎线性；当 ρ 接近或超过 1，分母趋近 1+ρ，TP 再大也只是把加速比钉死在 1/(1+ρ)。这就是“通信成为硬下界”的定量版本：ρ 是判据，不是感觉。</p>\n<p>具体机制上，ρ 里的 T_compute 是同一层做 GEMM 的时间，随 TP 增大而缩小（每卡分到的权重和激活都变小），而通信量 B·d·b_elem 与 TP 无关（all-reduce 的消息尺寸不随切分变小，因为归约的是完整激活）。于是 TP 越大，ρ 越大——这是一个自我强化的恶化过程：加卡降低计算时间，同时抬高通信/计算比。工程判断因此很直接：先在 TP=1 或 2 上测出单层 GEMM 时间，算出 ρ，若 ρ 已接近 1，则继续加 TP 的边际收益趋零，应转向 EP（把专家切到不同卡，all-to-all 的消息尺寸随 token 路由稀疏而缩小）或 DP（复制权重、切分请求，完全不动激活）。这正是“解码更适合 EP/DP 而非大 TP”的算术根据，而不是拓扑偏好。</p>\n<p>系统代价上要盯住一个不对称：TP 的通信在关键路径上（每层两次，层数一多就累积成几十次同步点），EP 的 all-to-all 虽然拓扑常数不同、消息尺寸也不同，但可以与专家计算流水重叠；DP 则把通信挪到请求级、几乎不进解码步的关键路径。因此定并行度的顺序应是：先确认 ρ，再判断能否用 DP 吸收并发，最后才在必须共享权重的场景（单模型放不下一张卡）用 TP。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-22\">二十二 · 定 KV 预算：TP 省下的显存是否被通信吃掉</h3>\n<p>KV cache 的容量公式在别处已讲，这里只接它的决策接口：TP 把每层的 KV 按头切到各卡，单卡 KV 占用近似正比于 1/TP，于是 TP 增大直接抬高可容纳的并发序列数。但由第一节的 B 上限可知，通信下界同时给并发封了顶。两者取小：</p>\n<div class=\"formula\">$$B_{\\text{eff}}=\\min\\left(B_{\\text{KV}}(\\text{TP}),\\;\\frac{\\text{TP}}{2(\\text{TP}-1)}\\cdot\\frac{\\beta_{\\text{NVLink}}\\,b}{d\\,b_{\\text{elem}}}\\cdot\\left(T_{\\text{slo}}-T_{\\text{compute}}\\right)\\right)$$</div>\n<p>B_KV(TP) 随 TP 上升，通信项随 TP 上升但饱和于一个与 TP 无关的常数（因为 TP/(TP−1)→1）。这意味着存在一个交叉点：TP 较小时 KV 是瓶颈，加 TP 直接换来并发；越过交叉点后通信项封顶，再加 TP 只增加卡数不增加并发，纯属浪费。长上下文场景把这个交叉点推得更早，因为 d 不变而每 token 的 KV 更长、注意力计算占比更高，T_compute 里注意力的份额上升，留给通信的预算被压缩。这就是“NVLink 域是长上下文解码容量边界”的算术表达：不是带宽不够用，而是 KV 换来的并发被通信下界截断。</p>\n<p>一个具体例子：某模型 d 较大、BF16 通信，在 NVL72 机柜内单 GPU 约 900 GB/s 双向带宽下，TP=8 时 TP/(TP−1)=1.14，若单层 GEMM 时间已因切分而很短，ρ 会明显大于 TP=2 时；此时把 TP 从 8 降到 4、用省下的 4 张卡做 DP 副本，往往能在相同 SLO 下拿到更高总吞吐，因为 DP 副本不增加每步同步点。判断依据就是上面那个 min：先算 B_KV 在 TP=4 和 TP=8 的差，再算通信项在这两个点的差，若后者更紧，降 TP 换 DP 是正收益。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-23\">二十三 · 定 SLO：把时延预算切成计算段与通信段</h3>\n<p>SLO 通常写成 P99 每 token 时延或 TTFT/TPOT 的组合。用下界做容量规划时，把 TPOT 预算 T_slo 显式拆成三段：权重与激活的 GEMM 段、注意力段、以及 all-reduce 段。all-reduce 段的下界就是 2(TP−1)/TP·B·d·b_elem/β，它在每层出现两次，层数为 L 时整步的下界是</p>\n<div class=\"formula\">$$T_{\\text{step}}\\ge L\\cdot\\left(T_{\\text{layer}}^{\\text{compute}}+\\frac{2(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B\\,d\\,b_{\\text{elem}}}{\\beta_{\\text{NVLink}}}\\right)$$</div>\n<p>这个式子的用途不是预测绝对时延（实际框架用 reduce-scatter + all-gather 与计算流水重叠，有效值低于此），而是给出“通信段占 TPOT 的比例”这一硬指标。工程上把它当预算表用：若算出通信段已占 TPOT 的相当比例，则任何靠加 TP 降时延的方案都失效，因为通信段随 TP 单调不减而计算段在缩小，比例只会更糟。反过来，若通信段占比很小，加 TP 是安全的时延手段。这也解释了为什么在严格 TPOT 的在线服务里，运维倾向于用 DP 扩副本而不是加深 TP——副本不改变单请求的关键路径，只改变排队。</p>\n<p>跨域是这条预算表最容易被误用的地方。NVL72 机柜内走 NVLink，机柜间走 InfiniBand，β 下降一个量级并叠加协议开销与固定延迟项。若仍按域内 β 外推多节点 TP 的 TPOT，算出的通信段会乐观一个量级，实际部署时时延远超预期。正确做法是把 β 换成跨域有效带宽、并在公式里加一项与消息数成正比的固定延迟，然后重新解 B 上限——通常会得到“跨域 TP 只适合极低并发或极长计算段”的结论，从而把跨域扩展改走 PP 或分离式预填/解码的路径。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-24\">二十四 · 算例：一个可复算的容量推演</h3>\n<p>设某解码服务，隐藏维 d、BF16 通信（b_elem=16 bit）、NVL72 域内 β 取单 GPU 约 900 GB/s 双向、层数 L、单层 GEMM 时间 T_layer^compute 已知（由实测给出，此处不填数字以免编造）。要求 TPOT ≤ T_slo。步骤一：对候选 TP∈{2,4,8} 分别算通信段 t_comm(TP)=2(TP−1)/TP·B·d·16/β，其中 B 先取 KV 预算允许的最大并发。步骤二：算 T_step 下界并与 T_slo 比较，若超预算则降 B 或降 TP。步骤三：对每个可行 (TP,B) 组合算总吞吐 ≈ B/T_step，取最大者。</p>\n<p>推演中会出现三种典型结局。其一，TP=2 时通信段小、KV 预算成为并发瓶颈，此时加 TP 到 4 能同时抬高 B_KV 且通信段仍可接受，是最优区。其二，TP=8 时通信段已占满预算，B 被迫压到很低，总吞吐反而低于 TP=4——这就是“大 TP 在解码里亏”的具体形态。其三，若把同一模型跨机柜部署，β 降一个量级，通信段瞬间超预算，任何 TP>1 的跨域方案都不可行，必须改 PP 或 PD 分离。这三种结局不依赖具体数字，只依赖 ρ 与 min 的取值顺序，因此可以作为部署前的检查清单：先算 ρ 判 TP 是否还有效，再算 min 判 KV 与通信谁是瓶颈，最后换 β 判跨域是否成立。</p>\n<p>算例里还要防一个常见误用：用环状 all-reduce 模型去估算 NVLS 多播场景。NVLS 多播把常数因子降下来，实际通信成本低于环状下界，若仍按环状公式限死并行度，会错失可扩展空间。判断方法是看框架是否启用了多播归约路径；若启用，则把公式当保守上界用，只用于排除明显不可行的组合，而不用于精确卡边界。反之，若框架走的是普通 ring，公式就是贴近实际的下界，可以放心用来定 B 上限。</p>\n<p>最后一个工程判断落在“同步点数量”上：TP 的代价不只是每步字节数，还有每层两次同步带来的流水线气泡。层数越多，气泡累积越显著，而公式里的 L 因子正是这一累积的线性化表达。因此在长层数模型上，即便单次 all-reduce 的字节量不大，同步点总数也会把通信段推高；此时用 PP 把层分段、让不同段在不同卡组上流水，能把同步点从关键路径上挪走，代价是引入 PP 的 point-to-point 通信与其自己的拓扑常数。决策顺序因此是：先按 ρ 排除无效 TP，再按 min 定 B，再按同步点总数决定是否用 PP 换掉一部分 TP，最后按 β 的域内外落差决定跨域只走 PP 或 PD 分离。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-25\">二十五 · 把下界塞进容量模型：批大小、并行度与 SLO 的联立求解</h3>\n<p>工程上真正要回答的不是“通信下界是多少”，而是“给定 SLO，哪一组 (TP, B, 上下文长度) 可行”。把公式改写为约束形式：令解码步时延预算为 <span>L</span>，则需满足 <span>T_comm + T_compute ≤ L</span>，代入得 <span>B ≤ (L − T_compute)·β_NVLink·TP / (2(TP−1)·d·b)</span>。注意右端随 TP 增大而趋近 <span>L·β/(2db)</span> 的上限——这意味着在固定 NVLink 域内，加大 TP 并不能无限抬高并发上限，因为每卡分担的通信量按 (TP−1)/TP 收敛到 1，收益递减。反过来，若已知目标并发 B 与上下文长度，可解出满足 SLO 的最小 TP，并检查它是否超出单机柜 NVLink 域；一旦超出，β 下降一个量级，解会跳到“不可行”，此时正确动作是改用 EP/DP 拆分而非继续堆 TP。</p>\n<p>KV 预算与批大小是同一枚硬币的两面。解码期每步通信量正比于 B·d·b，与上下文长度无关；而 KV cache 占用正比于 B·上下文长度。于是存在一个交叉点：短上下文时通信下界主导，长上下文时显存容量主导。把两者写成联立约束 <span>B·d·b·2(TP−1)/TP ≤ β·(L − T_compute)</span> 与 <span>B·ctx·kv_bytes ≤ HBM_budget</span>，可解出可行域是一个由通信约束封顶、由显存约束封底的区间；当上界低于下界时，该 (TP, ctx) 组合在 NVL72 单域内无解，必须降上下文、降并发或引入跨域。这正是“NVLink 域是长上下文解码容量边界”的定量表达。</p>\n<p>边界条件必须显式标注，否则模型会给出过于乐观的并行度。第一，公式假设 ring all-reduce 且无重叠；实际框架用 reduce-scatter + all-gather 与计算流水重叠，有效下界可低于公式值，因此按公式定容量是保守的——这对 SLO 是安全的，但对“是否值得跨节点扩展”的判断会偏保守，可能错失可扩展空间。第二，NVLS 多播把常数因子压低，此时公式变成保守上界，用它估算会高估通信成本并错误限制并行度。第三，公式只覆盖 TP 集合通信；EP 的 all-to-all 与 PP 的点对点有不同拓扑常数，需替换 β 与消息尺寸，不能直接套用。第四，跨机柜走 InfiniBand 时 β 骤降且引入固定延迟项，必须加 <span>+ t_0</span>，否则多节点部署时延会远超预期。</p>\n<p>算例（定性量级，不引用具体实测）：设 d 与 b 固定，单卡 NVLink 有效带宽约 900 GB/s 双向，取 L 为某解码 SLO 预算。若 T_compute 占预算一半，则通信预算为 L/2；代入得 B 的上限约为 <span>β·L·TP/(4(TP−1)·d·b)</span>。当 TP 从 8 增至 16，因子 (TP−1)/TP 从 0.875 降到 0.9375 的倒数变化仅约 7%，即通信下界几乎不随 TP 改善，而 KV 显存却按 TP 分摊——于是“加 TP 换并发”在解码期是低效的，这正是解码更适合 EP/DP 的容量侧理由。工程判断落在：先用该不等式筛掉不可行的 (TP, B) 组合，再对剩余组合做显存核算，最后只在跨域不可避免时才引入 IB 带宽重算下界。</p>\n<h3 id=\"th-comm-lower-bound-sec-26\">二十六 · 误用一：把环状常数套到 NVLS 多播上</h3>\n<p>公式里的因子 2(N−1)/N 是环状 all-reduce 的结构性产物：reduce-scatter 与 all-gather 各走一遍环，每卡收发量约为总量的 (N−1)/N。这个常数在 NVLink 域内并非不可动摇——Blackwell 机柜内的 NVLink 交换机支持 NVLS 多播，reduce-scatter 阶段可让一份数据同时落到多卡，all-gather 阶段可由交换机复制分发，常数因子显著低于环状。把环状公式直接代入 NVLS 场景，得到的是保守上界，而不是下界。</p>\n<p>后果是并行度被错误压低。设某解码层 B·s·h·b_elem 对应的单次通信量为 M，环状模型给出 t_comm ≈ 2(N−1)/N · M/β；运维者据此判定 TP=8 已触顶，转而把请求拆到更多副本上做 DP，牺牲了单副本可承载的上下文长度。识别方法很直接：看框架实际启用的集合通信实现。TensorRT-LLM 与 vLLM 在 NVL72 域内默认走 NVLS 或 tree 路径，NCCL 的算法选择日志会打印所用算法；若日志显示 NVLS 而容量模型仍按环状常数外推，就是误用。修正方式是把公式降级为“上界”，用实测的有效 β 反推常数，或直接以 all-gather 阶段的消息尺寸重估。</p>\n<div class=\"formula\">$$T_{\\text{comm}}^{\\text{NVLS}} \\approx \\frac{M}{\\beta_{\\text{NVLink}}}\\cdot c_{\\text{NVLS}},\\quad c_{\\text{NVLS}} &lt; \\frac{2(\\text{TP}-1)}{\\text{TP}}$$</div>\n<p>代价体现在容量决策上：一个本可在单机柜内以 TP=8 承载的长上下文解码服务，被误判为必须跨节点，平白引入机柜间 InfiniBand 的带宽落差与协议开销。这不是公式错了，而是公式的适用条件被忽略——它描述的是环，不是交换机多播。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-27\">二十七 · 误用二：拿域内带宽外推跨节点时延</h3>\n<p>NVL72 机柜内单 GPU 的 NVLink 有效带宽约 900 GB/s 双向，这是域内数字。一旦 TP 组跨出机柜，消息要经过 InfiniBand，有效带宽下降一个量级，且叠加协议栈的固定延迟项。公式中 β_NVLink 必须替换为跨域有效带宽，同时补上固定延迟，否则下界被系统性低估。</p>\n<p>识别信号来自部署形态与实测的背离：容量模型预测 TP=16 的跨机柜解码步时延与 TP=8 域内相近，实测却成倍恶化。此时应检查 TP 组的物理落位——NCCL 的拓扑探测会区分 NVLink 域与 IB 域，框架的并行组划分若未与机柜边界对齐，就会把最重的 all-reduce 压到最窄的链路上。具体例子：一个 72 GPU 的 NVL72 部署，若把 TP 组切成跨两个机柜的 16 卡，每层两次 all-reduce 都要穿越 IB，单次通信量 M 不变而 β 掉一个量级，解码步的通信下界随之抬升，连续批处理的批大小被迫压缩，吞吐与 SLO 同时受损。</p>\n<p>工程判断是：TP 组的规模应以 NVLink 域为硬边界，跨域扩展改用 EP 或 DP，让 all-to-all 与副本并行承担跨机柜流量。公式在这里的作用不是算出精确时延，而是提示“β 换一个量级，下界就换一个量级”，从而把并行组的拓扑约束前置到部署设计里。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-28\">二十八 · 误用三：假设通信与计算零重叠</h3>\n<p>公式的推导假设通信与计算串行，因此给出的是硬下界。实际框架用 reduce-scatter + all-gather 与计算流水重叠：当一层的 all-gather 在传下一层权重或激活时，当前层的 MMA 正在 tcgen05 上跑。有效通信成本可低于公式值，端到端时延并非简单的 t_comm + t_compute 相加。</p>\n<p>误用表现为两种极端。其一是把公式当作精确预测，看到预测时延高于实测就怀疑公式，进而弃用整套容量模型；其二是反向误用——因为“有重叠”就认为通信可忽略，在批大小增大时仍按无重叠假设排容量，结果在 B 上升、算术强度下降时被突发的通信瓶颈击穿。识别办法是看重叠的成立条件：重叠要求计算时间足够长以掩盖通信，即 T_compute 与 t_comm 同量级或更大；当批大小小、隐藏维大、TP 度高时，t_comm 可能超过 T_compute，重叠失效，公式重新变成紧下界。</p>\n<div class=\"formula\">$$T_{\\text{step}} \\ge \\max\\left(T_{\\text{compute}},\\; T_{\\text{comm}}^{\\text{TP}}\\right)\\ \\text{（完全重叠的理想情形）}$$</div>\n<p>代价是容量规划的保守或激进偏差：按零重叠估算会高估时延、低估并发上限，浪费 NVLink 域内的可扩展空间；按完全重叠估算则在通信主导区间低估时延，SLO 违约。正确做法是把公式当作区间的一端，另一端是 max 形式，实际值落在两者之间，由框架的重叠深度决定。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-29\">二十九 · 反例：一次被公式误导的扩容决策</h3>\n<p>考虑一个长上下文解码服务，隐藏维 d 较大，解码步 s=1，BF16 通信即 b=16。初始部署为单机柜 TP=8，实测解码步时延满足 SLO，但单副本并发受 KV cache 容量限制（该约束由另一条目的公式描述，此处不展开）。运维团队希望提升总吞吐，于是用环状公式推算：把 TP 提到 16 可使单副本算力翻倍，通信项 2(N−1)/N 从 1.75 变为 1.875，增幅有限，判断“通信不是瓶颈”，遂将 TP 组扩为跨两机柜的 16 卡。</p>\n<p>结果与预测背离：跨机柜后 β 掉一个量级，通信项在公式中放大约十倍，解码步时延远超 SLO，连续批处理被迫把批大小压到很小以维持时延，吞吐不升反降。更糟的是，小批大小进一步降低了算术强度，使通信占比更高，形成正反馈。这个反例里，公式本身没有错，错在两点：一是把环状常数用于 NVLS 域内场景（低估了域内可扩展空间，本可在单机柜内做更优的批调度），二是跨域时未替换 β（高估了跨机柜的可行性）。</p>\n<p>识别这类事故的工程信号是“预测与实测的比值随 TP 增大而单调恶化”，且恶化幅度与机柜边界对齐。修复路径不是调公式，而是把 TP 组锁回 NVLink 域，跨机柜流量交给 EP 的 all-to-all 或 DP 副本；同时用实测的有效 β 校准模型，把公式从“预测器”降级为“判据”——只回答通信是否已成为解码步的硬下界，不回答具体毫秒数。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-30\">三十 · 识别清单与工程判据</h3>\n<p>把误用挡在决策之前，需要一张与部署形态绑定的检查清单，而不是反复验算公式。</p>\n<ul>\n<li>算法核对：框架实际启用的集合通信是环、tree 还是 NVLS；日志里的算法名与容量模型假设的算法是否一致。</li>\n<li>拓扑核对：TP 组的物理落位是否全部落在同一 NVLink 域；跨域消息是否已替换 β 并补固定延迟项。</li>\n<li>重叠核对：当前批大小与隐藏维下，T_compute 是否足以掩盖 t_comm；若 t_comm 已超过 T_compute，重叠假设失效，公式转为紧下界。</li>\n<li>并行方式核对：EP 的 all-to-all 与 PP 的点对点有各自的拓扑常数与消息尺寸，不能沿用 TP 的 2(N−1)/N。</li>\n<li>量级核对：β 变化一个量级时，下界同比例变化；任何跨域扩容提案都应先回答“β 掉了多少”。</li>\n</ul>\n<p>这张清单的代价很低，但能挡住最贵的错误：一次错误的跨机柜 TP 扩容会同时损失吞吐、时延与功耗预算，而修复它需要重新划分并行组、重排请求路由，代价远高于事前核对。工程判据可以浓缩为一句话：公式的常数因子属于环，公式的 β 属于域，公式的重叠假设属于批大小——三者任一与部署不符，公式就只剩定性方向，不能再用来算毫秒。</p>\n<p>最终落在机制上：把 TP 通信下界写进容量模型时，应把它实现为一个带条件的判据函数——输入是并行组拓扑、集合通信算法、批大小与隐藏维，输出是“通信是否为硬下界”的布尔值与一个区间，而非单一数值。Blackwell 机柜内的 NVLink 交换机与 tcgen05 的流水重叠共同决定了这个区间的一端，跨域 IB 与协议开销决定另一端；误用的根源，始终是把区间的一端当成了全部。</p>\n\n<h3 id=\"th-comm-lower-bound-sec-31\">三十一 · 把下界当实测：三类误用如何把容量决策带偏</h3>\n<p>第一类误用是把环状 all-reduce 的常数因子当成普适常数。公式里的 2(TP−1)/TP 来自 reduce-scatter 与 all-gather 两阶段各遍历一次环，前提是每卡只与两个邻居收发。NVLS 多播走的是交换机侧归约，消息不必绕环一周，常数因子显著小于环状值。若仍按环状模型估算，就会把通信成本算高，进而错误地压低 TP 度或批大小，把本可扩展的配置判成不可行。识别方法很直接：看框架实际下发的集合通信原语。TensorRT-LLM 与 vLLM 在 NVL72 域内默认走 NVLS 路径，NCCL 日志里出现 NVLS 或 multicast 标记时，环状公式只能作为保守上界使用，不能作为容量规划的依据。反例：某长上下文解码服务在 NVL72 单机柜内把 TP 从 8 降到 4，理由是“TP=8 时通信时间已超过计算时间”，但该估算用的是环状模型；实际 NVLS 下通信被压到计算之下，降 TP 反而使每卡权重与 KV cache 占用翻倍，并发上限下降，端到端吞吐变差。代价落在显存与并发上，而不是落在带宽上。</p>\n<p>第二类误用是跨域外推。NVL72 机柜内是 NVLink 域，单 GPU 有效带宽约 900 GB/s 双向；机柜之间走 InfiniBand，带宽下降一个量级，且引入协议开销与固定延迟。把域内的 β_NVLink 直接代入多机柜部署，等于把下界算小了一个数量级。此时应替换带宽并加固定延迟项：</p>\n<div class=\"formula\">$$T_{\\text{comm}}^{\\text{TP}}\\ge\\frac{2(\\text{TP}-1)}{\\text{TP}}\\cdot\\frac{B\\,d\\,b}{\\beta_{\\text{cross}}}+L_{\\text{proto}}$$</div>\n<p>其中 β_cross 为跨域有效带宽，L_proto 为协议与路由引入的固定项。识别信号是拓扑：TP 组跨越机柜边界时，通信时间对批大小不再线性，而会出现与消息数成正比的台阶。工程判断是，解码步的 s 为 1、投机解码为 k+1，消息尺寸本就小，固定延迟项占比高，跨域 TP 在解码阶段几乎必然成为硬下界；这正是解码更适合 EP/DP 而非大 TP 的原因。反例：把 TP=16 铺到两个机柜上跑长上下文预填，预填阶段计算密度高、消息大，尚能靠流水线隐藏部分通信；切到解码阶段后每步只搬 B·d·b 量级的数据，固定延迟主导，单步时延远超域内 TP=8 的配置，容量规划里按域内带宽算出的并发上限完全失效。</p>\n<p>第三类误用是忽略重叠。公式假设通信与计算不重叠，实际框架用 reduce-scatter + all-gather 与计算流水交错，有效下界可低于公式值。把公式值直接当作端到端时延，会对 SLO 做出过度保守的误判，表现为过早增加副本数、抬高功耗与显存占用。识别方法是看时间线：若 all-gather 与下一层 GEMM 或 attention 重叠，通信只暴露未被隐藏的那部分。此时应把公式中的 T_compute 视为可隐藏窗口，用 Speedup_TP ≤ 1/(1+通信/计算) 判断加速比上限，而不是用通信时间绝对值判断可行性。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>环状模型套 NVLS</td><td>高估通信、错误压低 TP 与批大小</td><td>NCCL 日志出现 NVLS/multicast</td></tr><tr><td>域内带宽外推跨域</td><td>多机柜解码时延远超预期</td><td>TP 组跨机柜、时延出现固定台阶</td></tr><tr><td>忽略计算通信重叠</td><td>过度保守、副本与功耗虚高</td><td>时间线上 all-gather 与 GEMM 交错</td></tr></tbody></table>\n<p>三类误用的共同根源是把一个带假设的下界当成测量值。下界的用途是判断“通信是否会成为解码步瓶颈”，而不是预测实际时延；一旦拓扑、原语或重叠方式改变，β 与常数因子必须同步替换，否则容量决策就会沿着错误的方向锁死。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\text{TP}</td><td>张量并行度</td></tr><tr><td>B</td><td>批大小</td></tr><tr><td>d</td><td>隐藏维</td></tr><tr><td>b</td><td>通信元素位宽（BF16=16，FP8=8）</td></tr><tr><td>\\beta_{\\text{NVLink}}</td><td>NVLink 有效带宽（NVL72 单 GPU 约 900 GB/s 双向）</td></tr><tr><td>T_{\\text{compute}}</td><td>同层计算时间</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-comm-lower-bound · 共 5 个片段</p>\n"},{"id":"th-speculative-acceptance","title":"投机解码的期望加速比","direction":"dir-code-posttrain-data","prereq":[],"plain":"投机解码每轮用草稿模型猜 γ 个 token，再由目标模型一次前向并行验证；期望接受 token 数等于接受率序列的累积和，加速比取决于接受长度与草稿/验证的相对开销，代码任务因语法强约束接受率偏高。","definition":"投机解码每轮用草稿模型猜 γ 个 token，再由目标模型一次前向并行验证；期望接受 token 数等于接受率序列的累积和，加速比取决于接受长度与草稿/验证的相对开销，代码任务因语法强约束接受率偏高。","formula":"$$\\mathbb{E}[\\text{tokens/round}]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\alpha_j,\\qquad \\text{Speedup}=\\frac{\\mathbb{E}[\\text{tokens/round}]}{1+c\\,\\gamma},\\qquad \\alpha=\\mathbb{E}_{x\\sim p_{\\text{target}}}\\left[\\min\\!\\left(1,\\frac{p_{\\text{draft}}(x)}{p_{\\text{target}}(x)}\\right)\\right]$$","variables":[{"sym":"\\gamma","meaning":"每轮草稿 token 数"},{"sym":"\\alpha_j","meaning":"第 j 个草稿位置的接受概率"},{"sym":"c","meaning":"草稿单步开销与目标验证单步开销之比"},{"sym":"p_{\\text{draft}}","meaning":"草稿分布"},{"sym":"p_{\\text{target}}","meaning":"目标分布"}],"derivation":"加速比公式含义：$$\\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens}]}{1 + \\gamma\\, c_{\\text{draft}}/c_{\\text{target}}}$$ 分母是每轮相对目标单 token 成本的归一化代价——1 次目标前向加上 γ 次草稿前向按成本比折算；分子是每轮期望产出的 token 数，二者相除即单位目标算力换来的 token 吞吐。","example":"适用边界：该式只在验证采用拒绝采样、严格保持目标分布时成立；温度采样、top-p 截断、top-k 会改变接受判据，α_j 必须按实际采样分布重算，否则期望产出被高估。此外 c_draft/c_target 随批大小漂移，大批量下两者都访存受限，草稿的相对成本上升，加速比被摊薄。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设草稿与验证串行且验证一次前向可并行校验 γ 个位置；树状草稿（Medusa/EAGLE）下接受长度按树路径重算，公式需改为树期望深度","α 假设逐位置独立，实际代码 token 存在强自相关（缩进、括号配对），独立假设低估长串接受概率","c 为草稿/验证单步开销比，随批大小变化；大批量下验证被摊薄，c 下降，但草稿模型自身也受带宽约束，加速比在 B 增大时饱和"],"system_note":"用途：容量规划时用它反推所需草稿模型规模与 γ 取值——给定实测 α_j 衰减曲线与成本比，可算出最优 γ（边际收益 $$\\prod_{j\\le\\gamma}\\alpha_j$$ 低于边际成本时停止加长草稿）；也可判断某部署是否值得引入投机路径，例如 α 衰减过快时加速比趋近 1 而显存被草稿模型占用。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["直觉：草稿模型一次抛出 γ 个候选 token，目标模型用一次前向并行验证整条链，只要前缀被逐位接受，就能用一次目标前向换回多个 token，收益来自把目标模型串行步数压缩为原来的 1/E[tokens]。","公式含义：$$\\mathbb{E}[\\text{tokens}] = 1 + \\sum_{i=1}^{\\gamma} \\prod_{j=1}^{i} \\alpha_j$$ 中，第 i 项是“前 i 个草稿 token 全部被接受”的联合概率，即链长至少达到 i+1 的概率；首项 1 表示无论接受多少，目标模型至少产出 1 个由自身分布确定的 token，因此期望产出是各前缀存活概率之和加一。","加速比公式含义：$$\\text{speedup} \\approx \\frac{\\mathbb{E}[\\text{tokens}]}{1 + \\gamma\\, c_{\\text{draft}}/c_{\\text{target}}}$$ 分母是每轮相对目标单 token 成本的归一化代价——1 次目标前向加上 γ 次草稿前向按成本比折算；分子是每轮期望产出的 token 数，二者相除即单位目标算力换来的 token 吞吐。","推导关键一步：把每轮产出写成指示变量之和，利用期望线性性与“第 i 位被接受当且仅当前 i−1 位均被接受且第 i 位判据通过”的链式条件，得到 $$\\prod_{j=1}^{i}\\alpha_j$$；再假设草稿与目标成本可加、忽略调度与批处理重叠，才得到可除的加速比近似。","适用边界：该式只在验证采用拒绝采样、严格保持目标分布时成立；温度采样、top-p 截断、top-k 会改变接受判据，α_j 必须按实际采样分布重算，否则期望产出被高估。此外 c_draft/c_target 随批大小漂移，大批量下两者都访存受限，草稿的相对成本上升，加速比被摊薄。","用途：容量规划时用它反推所需草稿模型规模与 γ 取值——给定实测 α_j 衰减曲线与成本比，可算出最优 γ（边际收益 $$\\prod_{j\\le\\gamma}\\alpha_j$$ 低于边际成本时停止加长草稿）；也可判断某部署是否值得引入投机路径，例如 α 衰减过快时加速比趋近 1 而显存被草稿模型占用。","常见误用：用平均接受率代替逐位置 α_j 代入公式，忽略代码任务中接受率的强位置衰减，导致长草稿链的期望产出被系统性高估；或把训练时的接受率直接搬到推理，未考虑温度与截断改变判据。后果是上线后实测加速比远低于预估，甚至因草稿开销为负收益。","代码任务特性：代码受语法与标识符强约束，草稿模型在括号、关键字、缩进等位置容易命中，但一旦进入自由命名的标识符或长表达式，后续位置接受率快速衰减，尾部 α_j 可能趋近于零；因此代码场景宜用较短 γ 并配合语法感知草稿，而非盲目加长草稿链。"],"anchors":[],"pitfalls":["用单一平均接受率替代逐位置 α_j 估算加速比，忽略位置衰减，导致容量规划高估吞吐、低估草稿显存占用。","在高温采样或 top-p 截断下沿用默认拒绝采样接受判据，未重算 α_j，使输出分布偏离目标模型且实测加速比与公式不符。","大批量部署时仍按小批量测得的 c_draft/c_target 估算，未计入两者同时访存受限导致的成本比上升，投机路径反而拖低整体吞吐。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-1\">一 · 一句话直觉与它到底在换什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-2\">二 · 期望接受长度的严格推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-3\">三 · 为什么非要有这个量：容量规划与引入判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-4\">四 · 常见误解：平均接受率、独立假设、判据漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-5\">五 · 代码场景下的形态判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-6\">六 · 边界条件：公式在什么情况下会骗你</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-7\">七 · 期望产出项的逐位拆解</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-8\">八 · 接受判据 \\(\\alpha\\) 的期望形式与离散化位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-9\">九 · 加速比分母：成本比的可加性假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-10\">十 · 树状草稿：公式必须改写为树期望深度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-11\">十一 · 用公式反推 γ 与草稿规模</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-12\">十二 · 公式的适用边界与工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-13\">十三 · 接受率衰减曲线：公式在什么条件下开始说谎</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-14\">十四 · 串行假设的边界：验证一次前向能并行校验多少</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-15\">十五 · 逐位置独立假设在代码 token 上的崩塌</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-16\">十六 · 成本比 c 随批大小漂移，加速比在 B 增大时饱和</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-17\">十七 · 分布保真与采样参数的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-18\">十八 · 规模上限：最优 γ 与边际收益归零</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-19\">十九 · 边界条件：公式在什么工况下失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-20\">二十 · 把加速比公式改写成容量约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-21\">二十一 · 定批大小：加速比饱和点决定 B 的上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-22\">二十二 · 定并行度：γ 与 TP 的联合选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-23\">二十三 · 定 KV 预算：草稿模型的隐性占用</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-24\">二十四 · 定 SLO：尾延迟而非均值</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-25\">二十五 · 算例：从 α 曲线到部署参数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-26\">二十六 · 把期望加速比折进容量账本：批大小、并行度、KV 与 SLO 的联立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-27\">二十七 · 误用一：把平均接受率塞进逐位置公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-28\">二十八 · 误用二：采样参数变了，判据没重算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-29\">二十九 · 误用三：小批量测得的成本比搬到大批量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-30\">三十 · 反例：树状草稿套用链式公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-speculative-acceptance-sec-31\">三十一 · 误用与反例：平均接受率、判据漂移与大批量成本比</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:580px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 579.6 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"497.6\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"497.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：投机解码每轮用草稿模型猜 γ 个 token，再由目标模型一次前向…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"497.6\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\mathbb{E}[\\text{tokens/round}]…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"497.6\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设草稿与验证串行且验证一次前向可并行校验 γ 个位置；树状草稿（…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-speculative-acceptance-sec-1\">一 · 一句话直觉与它到底在换什么</h3>\n<p>投机解码的直觉可以压缩成一句工程话术：<strong>用便宜模型的串行步，换目标模型的一次并行前向</strong>。草稿模型一次抛出 γ 个候选 token，目标模型把这 γ 个位置放进同一次前向里并行校验，只要前缀逐位通过拒绝采样判据，这一轮就产出多个 token，而目标模型只走了一步。收益的本质不是“算得更少”，而是“把目标模型的串行步数压缩”。设每轮期望产出为 E[tokens/round]，则目标模型的串行步数被压缩为原来的 1/E[tokens/round]；解码阶段本来就是访存受限的（见解码阶段 roofline 带宽界），目标模型每步的时间由权重与 KV 的字节数决定而非 FLOPs，所以把 γ 个位置塞进一次前向几乎不增加目标侧的时间，这才是投机能成立的前提。</p>\n<p>严格定义：给定目标分布 p_target 与草稿分布 p_draft，草稿自回归生成 γ 个候选 x_1…x_γ，目标模型对这条链做一次前向得到各位置的 p_target(·|前缀)，按逐位判据接受或拒绝，一旦某位被拒即从该位置的修正分布重采样并终止本轮。形式化地，第 j 位的接受概率为</p>\n<div class=\"formula\">$$\\alpha=\\mathbb{E}_{x\\sim p_{\\text{target}}}\\left[\\min\\!\\left(1,\\frac{p_{\\text{draft}}(x)}{p_{\\text{target}}(x)}\\right)\\right]$$</div>\n<p>这个 α 不是“草稿猜对的概率”，而是“按拒绝采样规则被保留的概率”——它同时惩罚草稿过度自信（p_draft 大于 p_target 的位置被截断）与草稿覆盖不足。定义清楚了，才能谈期望加速比；否则后面所有估算都建在流沙上。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-2\">二 · 期望接受长度的严格推导</h3>\n<p>把每轮产出写成指示变量之和是最干净的推导路径。令 I_i 表示“第 i 个草稿 token 被接受”，则本轮产出 = 1 + Σ_{i=1}^{γ} I_i，那个 1 是无论接受多少、目标模型至少产出的一个由自身分布确定的 token（被拒位置的重采样结果）。关键一步是链式条件：第 i 位被接受，当且仅当前 i−1 位全部被接受且第 i 位判据通过，于是 P(I_i=1) = ∏_{j=1}^{i} α_j。由期望线性性：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens/round}]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\alpha_j,\\qquad \\text{Speedup}=\\frac{\\mathbb{E}[\\text{tokens/round}]}{1+c\\,\\gamma}$$</div>\n<p>注意这里的求和从 i=1 起，等价于“各前缀存活概率之和再加一”：第 i 项正是链长至少达到 i+1 的概率。这个写法比“平均接受率乘 γ”精确得多，因为它把衰减结构显式化了。分母 1 + c·γ 是每轮相对目标单 token 成本的归一化代价：一次目标前向，加上 γ 次草稿前向按成本比 c = c_draft/c_target 折算。分子除以分母，就是单位目标算力换来的 token 吞吐。</p>\n<p>代价侧要盯住三件事：延迟上，每轮墙钟时间 ≈ t_target + γ·t_draft，只有当 E[tokens] 的增长快过这条线性开销，端到端 TPOT 才下降；吞吐上，草稿模型自身占用显存与带宽，γ 越长草稿的 KV 与激活越大；显存上，草稿权重是纯增量开销，在 KV cache 已经吃满容量的部署里（见 KV cache 显存容量公式），这笔开销直接挤压并发。举例：一个 8B 目标模型配 1B 草稿、γ=4，若实测 α 序列为 0.9/0.75/0.6/0.45，则 E[tokens] = 1 + 0.9 + 0.675 + 0.405 + 0.182 ≈ 3.16，若 c≈0.1 则分母为 1.4，加速比约 2.26；若有人误用平均接受率 0.675 直接乘 4 得 2.7 个 token，就会把加速比高估到接近 1.93 倍分子、实则系统性偏高。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-3\">三 · 为什么非要有这个量：容量规划与引入判据</h3>\n<p>期望加速比不是论文里的装饰公式，它是两个工程决策的唯一量化依据。第一是<strong>是否值得引入投机路径</strong>：把实测 α_j 衰减曲线与成本比代入，若算出的 Speedup 贴近 1，说明草稿开销吃掉了全部收益，而草稿模型还占着显存——此时正确判断是不上投机，把显存留给 KV 与并发。第二是<strong>γ 取多长</strong>：边际收益是 ∏_{j≤γ} α_j（第 γ+1 位被接受的联合概率），边际成本是每加一位草稿的 c；当边际收益低于边际成本时停止加长。这给出一条可执行的停机准则，而不是拍脑袋定 γ=5。</p>\n<p>它同时是 SLO 与容量规划的输入：给定目标 TPOT 上限与实测 α、c，反推所需草稿模型规模（草稿越大 α 越高但 c 越大，存在最优点）与每 GPU 可承载的并发数。这里必须警惕 c 的批依赖：大批量下目标验证被摊薄，单 token 的目标成本下降，c 相对上升；而草稿模型自身也受带宽约束，两者同时访存受限时成本比漂移，加速比在批大小 B 增大时饱和甚至回落。用小批量测得的 c 去做大集群容量规划，是这类系统最常见的规划错误。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-4\">四 · 常见误解：平均接受率、独立假设、判据漂移</h3>\n<p>误解一，<strong>用单一平均接受率代替逐位置 α_j</strong>。平均接受率抹掉了位置衰减，而期望产出是前缀存活概率之和，对尾部 α 极其敏感。代码任务里这一点被放大：语法与标识符强约束让括号、关键字、缩进位置的 α 很高，但一旦进入自由命名的标识符或长表达式，后续位置接受率快速衰减，尾部 α_j 可能趋近于零。用平均值代入会把长草稿链的期望产出系统性高估，上线后实测加速比远低于预估，甚至因草稿开销变成负收益。</p>\n<p>误解二，<strong>把 α 当成逐位置独立</strong>。公式里 ∏α_j 的链式结构只要求条件化，并不要求独立；但很多估算工具默认独立同分布，而真实代码 token 存在强自相关——括号配对、缩进层级、重复的样板行——独立假设会低估长串被整体接受的概率。反过来，若在自由文本上套用代码场景的高 α，又会高估。正确做法是按位置分桶统计条件接受率，而不是抽一个标量。</p>\n<p>误解三，<strong>判据漂移</strong>。上面的 α 定义只在验证采用拒绝采样、严格保持目标分布时成立。温度采样、top-p、top-k 会改变接受判据，α_j 必须按实际采样分布重算，否则不仅期望产出被高估，输出分布还会偏离目标模型——这是正确性问题，不只是性能问题。把训练阶段测得的接受率直接搬到推理服务，同样犯这个错：温度与截断一变，判据就变了。</p>\n<p>误解四，<strong>把公式当成树状草稿的通用式</strong>。Medusa/EAGLE 这类树状草稿下，接受长度要按树路径重算，公式需改为树期望深度，直接套用链式公式会错得离谱。此外公式假设草稿与验证串行、验证一次前向可并行校验 γ 个位置、忽略调度与批处理重叠——这些假设在真实服务里都会被打破，公式给出的是上界性质的近似，不是承诺。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-5\">五 · 代码场景下的形态判断</h3>\n<p>代码任务的 α 曲线是“头部陡、尾部塌”的形状：语法强约束让前几位命中率高，但标识符与长表达式的自由度高，尾部 α_j 迅速衰减。这意味着代码场景宜用较短 γ 并配合语法感知草稿（按 AST 或括号结构约束候选），而不是盲目加长草稿链——加长的部分边际收益 ∏α_j 已经很低，却仍要付 γ·c 的成本。工程判断可以写得很直接：先测出 α_j 的位置衰减曲线，找出 ∏_{j≤γ}α_j 跌破 c 的 γ*，把 γ 钉在 γ* 附近；再用语法感知草稿把中段 α 抬起来，从而把 γ* 右移。这两步的先后顺序不能反——先定 γ 再加长，否则调参空间被无效的尾部位置吃掉。</p>\n<p>最后落在一个具体机制上：拒绝采样的接受判据本身决定了 α 的上限，而 γ 的选择由边际收益与边际成本的交点决定；任何绕过逐位置 α_j 实测、绕过批大小对 c 的漂移、绕过采样参数对判据的改写的估算，都不是“近似”，而是错的模型。把这三件事测准，期望加速比才是一个能拿去做容量规划的工程量，而不是一个好看的理论数字。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-6\">六 · 边界条件：公式在什么情况下会骗你</h3>\n<p>把 <span class=\"sym\">E[tokens/round]</span> 写成前缀存活概率之和，依赖一条极强的前提：草稿与验证严格串行，且验证阶段一次目标前向能并行校验 γ 个位置。真实部署里这条前提经常被打破。树状草稿（Medusa、EAGLE）每轮抛出的不是一条链而是一棵树，验证一次前向校验的是多个分支，接受长度必须按树路径重新计算——期望产出变成树上的期望最大接受深度，而不是简单的前缀乘积。此时把链式公式直接套上去，会把并行的分支收益算丢，也会把树构建的额外开销漏掉。更隐蔽的是 α 的独立性假设：公式默认第 j 位的接受判据只与第 j 位有关，但代码 token 存在强自相关，缩进层级、括号配对、关键字序列让相邻位置的接受事件高度耦合。独立假设在长串上系统性低估联合存活概率，于是短 γ 时公式偏保守，长 γ 时又偏乐观，两种偏差方向相反、互相掩盖，实测曲线看着“差不多对”却无法用来定 γ。</p>\n<p>接受判据本身也是边界。公式里的 α 只在拒绝采样、严格保持目标分布时成立；一旦开启温度采样、top-p 截断或 top-k，判据被改写，α_j 必须按实际采样分布重算。沿用默认判据估出的 α 会高估期望产出，同时让输出分布偏离目标模型——这是正确性问题，不只是性能问题。工程上判断某部署是否值得引入投机路径，要看 α 的衰减曲线而非平均值：若尾部 α_j 快速趋近零，边际收益 <span class=\"sym\">∏_{j≤γ}α_j</span> 低于边际成本，加速比趋近 1，而草稿模型的显存却实打实被占住。代码场景正是典型：括号、关键字、缩进位置命中率高，一旦进入自由命名的标识符或长表达式，后续位置接受率骤降，因此宜用较短 γ 配合语法感知草稿，盲目加长草稿链只会把显存换成负收益。</p>\n<p>成本比 c 是第二个漂移量。分母 <span class=\"sym\">1 + cγ</span> 把每轮代价归一化为“一次目标前向 + γ 次草稿前向按成本比折算”，这假设两者成本可加、调度与批处理重叠可忽略。小批量下草稿单步相对便宜，c 小，加速比好看；大批量下验证被摊薄，看似 c 下降，但草稿模型自身也撞上带宽墙，其相对成本反而上升，加速比在批大小 B 增大时饱和甚至回落。用小批量测得的 c 去推算大批量容量，是容量规划最常见的翻车点。下表把三类失效条件与对应的系统代价对齐：</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>被破坏的假设</th><th>系统代价表现</th></tr></thead><tbody><tr><td>树状草稿</td><td>单链串行验证</td><td>接受长度需按树路径重算，树构建与验证显存上升</td></tr><tr><td>α 位置自相关</td><td>逐位置独立</td><td>长 γ 期望产出被误估，γ 选择失准</td></tr><tr><td>大批量部署</td><td>c 为常数</td><td>草稿访存受限，加速比饱和，吞吐被拖低</td></tr></tbody></table>\n<p>因此这套公式的正确用法是“反推”而非“预测”：给定实测的逐位置 α_j 衰减曲线与当前批大小下的成本比，解出最优 γ——当下一位置的边际存活概率乘以收益低于草稿边际成本时停止加长。它回答的是“这个部署值不值得开投机路径、草稿模型该多大”，而不是“上线后一定能快多少”。把平均接受率代进去、把训练期接受率搬到推理期、把高温采样下的判据当默认判据，这三种误用共同指向同一个后果：预估吞吐虚高、草稿显存被低估，实测加速比远低于账面，甚至因草稿开销转为负收益。</p>\n<h3 id=\"th-speculative-acceptance-sec-7\">七 · 期望产出项的逐位拆解</h3>\n<p>把每轮产出写成指示变量之和，是这条公式唯一干净的推导起点。设第 i 个草稿位置是否被接受为指示变量 \\(I_i\\in\\{0,1\\}\\)，则每轮产出的 token 数 \\(N=1+\\sum_{i=1}^{\\gamma}I_i\\)——那个常数 1 是目标模型在最长被接受前缀之后必然自行采出的那一个 token，它不依赖任何草稿判据。对 \\(N\\) 取期望，线性性给出 \\(\\mathbb{E}[N]=1+\\sum_{i=1}^{\\gamma}\\Pr[I_i=1]\\)。关键一步在于把 \\(\\Pr[I_i=1]\\) 展开：第 i 位被接受当且仅当前 i−1 位全部被接受、且第 i 位自身判据通过，于是</p>\n<div class=\"formula\">$$\\Pr[I_i=1]=\\Pr[I_{i-1}=1]\\cdot\\Pr[I_i=1\\mid I_{i-1}=1]=\\prod_{j=1}^{i}\\alpha_j$$</div>\n<p>这里 \\(\\alpha_j\\) 是条件接受概率，而非无条件接受率。这个区别在工程上极其致命：把实测的平均接受率当作 \\(\\alpha_j\\) 代入，等价于假设接受概率沿位置不衰减，而代码 token 的强自相关（缩进、括号配对、关键字后紧跟固定语法结构）恰恰让尾部 \\(\\alpha_j\\) 快速塌陷。因此第 i 项 \\(\\prod_{j\\le i}\\alpha_j\\) 的物理含义是“链长至少达到 i+1 的概率”，它是一个单调递减的存活函数，期望产出就是这条存活曲线的离散积分再加一。γ 增大时新增项的边际贡献恰为 \\(\\prod_{j\\le\\gamma}\\alpha_j\\)，这一项就是容量规划里判断“是否再加长草稿”的边际收益，一旦它低于多一个草稿位置的边际成本，加长草稿链即为负收益。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-8\">八 · 接受判据 \\(\\alpha\\) 的期望形式与离散化位置</h3>\n<p>接受概率的严格定义是拒绝采样下的最小比值期望：</p>\n<div class=\"formula\">$$\\alpha=\\mathbb{E}_{x\\sim p_{\\text{target}}}\\left[\\min\\!\\left(1,\\frac{p_{\\text{draft}}(x)}{p_{\\text{target}}(x)}\\right)\\right]$$</div>\n<p>逐项看：采样点 \\(x\\) 取自目标分布而非草稿分布，这是保证输出分布无偏的核心；比值 \\(p_{\\text{draft}}/p_{\\text{target}}\\) 在草稿过度自信处被截断到 1，在草稿低估处按比例缩小，被拒时从残差分布重采样。工程上这个期望无法解析计算，实际实现是在词表上做离散求和，或直接用一次采样代替期望——这就是第一处离散化近似：单次判据是伯努利抽样，其期望才是 \\(\\alpha\\)，逐轮方差会让短观测窗口内的实测加速比抖动。第二处近似在温度与截断：一旦启用 top-p/top-k 或温度缩放，判据不再是原始比值，\\(\\alpha_j\\) 必须按实际采样分布重算，否则公式分子被系统性高估，且输出分布偏离目标模型。第三处近似是位置独立性假设——公式把 \\(\\alpha_j\\) 当作与历史无关的条件概率，而真实代码序列中第 j 位的接受强烈依赖前 j−1 位是否已构成合法前缀，独立假设在长串上低估联合存活概率，在自由命名标识符处又高估。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-9\">九 · 加速比分母：成本比的可加性假设</h3>\n<p>加速比的分母 \\(1+c\\gamma\\) 是把每轮代价按目标单 token 成本归一化后的结果：1 次目标前向（并行校验 γ 个位置）加上 γ 次草稿前向，后者按成本比 c 折算。这个可除结构依赖三个假设：草稿与验证严格串行、成本可加、调度与批处理重叠可忽略。真实系统里草稿的 γ 步是自回归串行的，每步都是一次小 batch 前向，其单步成本受权重访存带宽支配而非算力支配；验证则是把 γ 个位置拼成一次前向，算力利用率高但同样受 KV 读取带宽约束。于是 c 不是常数，它随批大小 B 漂移：B 增大时验证被摊薄、单位 token 的目标成本下降，c 相对上升；同时草稿模型自身也进入带宽受限区，其相对成本不再线性于 γ。这就是加速比在大批量下饱和的机制根源——分子 \\(\\mathbb{E}[N]\\) 不随 B 变，分母的相对成本却随 B 恶化，两条曲线交叉处即为该部署的吞吐拐点。</p>\n<table class=\"mini\"><thead><tr><th>项</th><th>含义</th><th>工程代价载体</th><th>失效触发</th></tr></thead><tbody><tr><td>\\(\\prod_{j\\le i}\\alpha_j\\)</td><td>前缀存活概率</td><td>草稿显存占用</td><td>平均接受率替代逐位值</td></tr><tr><td>\\(1\\)</td><td>目标自采 token</td><td>每轮固定一次目标前向</td><td>无</td></tr><tr><td>\\(c\\gamma\\)</td><td>草稿折算代价</td><td>带宽、功耗</td><td>大批量下 c 漂移</td></tr></tbody></table>\n\n<h3 id=\"th-speculative-acceptance-sec-10\">十 · 树状草稿：公式必须改写为树期望深度</h3>\n<p>Medusa/EAGLE 一类树状草稿把 γ 个候选组织成多分支树，一次验证前向并行校验多个路径。此时“链”不再是单链，接受长度是树上从根到被接受最深叶子的路径长度，期望产出须改为对树各路径的存活概率求和：若树有节点集合 \\(\\mathcal{T}\\)，每个节点 v 的存活概率为其根路径上各 \\(\\alpha\\) 之积，则 \\(\\mathbb{E}[N]=1+\\sum_{v\\in\\mathcal{T}}\\prod_{u\\in\\text{path}(v)}\\alpha_u\\)。这不是把单链公式换个符号，而是改变了离散化的粒度：单链公式的求和下标是位置序号，树公式的下标是节点，同一深度上多个节点各自贡献存活概率，因此树的期望深度可以显著超过任何单条链。代价侧同样改写：验证一次前向的代价随树节点数增长而非随深度增长，分母变为 \\(1+c\\cdot|\\mathcal{T}|_{\\text{有效}}\\)，树越宽 c 的有效值越高。工程判断是：树的宽度换期望深度，但验证前向的 KV 读取与注意力掩码开销随节点数上升，宽树在长上下文下容易把收益吃回去。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-11\">十一 · 用公式反推 γ 与草稿规模</h3>\n<p>给定实测的逐位置 \\(\\alpha_j\\) 衰减曲线与成本比 c，最优 γ 由离散边际条件确定：加长一位草稿的边际收益是 \\(\\prod_{j\\le\\gamma+1}\\alpha_j\\) 个 token，边际成本是 c 个目标 token 当量，停止条件为</p>\n<div class=\"formula\">$$\\prod_{j=1}^{\\gamma+1}\\alpha_j \\;&lt;\\; c$$</div>\n<p>这条不等式把“草稿该多长”从调参变成可算的量。代码任务的典型形态是前若干位 \\(\\alpha_j\\) 接近饱和（括号、关键字、缩进命中率高），随后进入自由命名标识符区快速衰减，尾部趋近于零；此时乘积在少数几位之后就跌破 c，最优 γ 很短，盲目加长只会让分母膨胀而分子不动。反过来，若某部署实测 \\(\\alpha\\) 衰减极快，加速比趋近 1，而草稿模型仍占着显存与一份额外权重带宽，此时引入投机路径是净负收益——公式给出的判据是分子增益不足以覆盖 \\(c\\gamma\\) 与草稿常驻显存的机会成本。容量规划时还应把 c 按目标批大小实测，而非沿用小块测得的比值，否则分母被低估、γ 被高估，上线后实测加速比远低于预估。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-12\">十二 · 公式的适用边界与工程落点</h3>\n<p>这条公式是拒绝采样保分布前提下的期望近似，它的三处近似——词表离散求和替代连续期望、位置独立替代条件依赖、成本可加替代流水重叠——分别对应三类上线偏差：短窗口抖动、长串接受被低估、大批量饱和被忽略。工程落点不在公式本身，而在把 \\(\\alpha_j\\) 曲线与 c(B) 曲线作为两个实测输入喂进容量模型：前者决定 γ 上限与草稿是否值得常驻，后者决定该部署在目标并发下的实际拐点。语法感知草稿的作用正是抬高自由命名区的 \\(\\alpha_j\\)，把存活曲线的尾部抬起来，从而让边际条件在更长的 γ 上仍然成立；而一旦验证被摊薄到 c 上升，同样的 \\(\\alpha_j\\) 曲线会给出更短的 γ。两条曲线一起动，才是投机路径在 Blackwell 上是否开、开多长的真正判据。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-13\">十三 · 接受率衰减曲线：公式在什么条件下开始说谎</h3>\n<p>把 <span>$$\\mathbb{E}[\\text{tokens}] = 1 + \\sum_{i=1}^{\\gamma} \\prod_{j=1}^{i} \\alpha_j$$</span> 逐项展开看，第 i 项的物理意义是“链长至少达到 i+1 的概率”，也就是前 i 个草稿位置全部存活的联合概率。推导的关键一步是把每轮产出写成指示变量之和：第 i 位被接受当且仅当前 i−1 位均被接受且第 i 位判据通过，于是利用期望线性性直接得到前缀概率的连乘，无需任何分布假设之外的近似。真正被悄悄塞进公式的是两处：其一，α_j 被当作逐位置独立的量，连乘才成立；其二，分母 <span>$$1+c\\,\\gamma$$</span> 假设草稿与验证成本可加、调度与批处理重叠可忽略，才使分子分母可除。这两处近似决定了公式的适用边界，也决定了它在哪些部署里会系统性高估收益。</p>\n<p>第一处近似的失效在代码任务上最典型。代码 token 受语法与标识符强约束，缩进、括号配对、关键字位置草稿极易命中，但一旦进入自由命名的标识符或长表达式，后续位置接受率快速衰减，尾部 α_j 可能趋近于零。此时逐位置 α_j 的连乘衰减远快于用单一平均接受率代入的结果——平均接受率把高 α 的头部与接近零的尾部混在一起，等价于假设整条链的存活概率按几何方式缓慢下降，而真实曲线是断崖式的。后果是长草稿链的期望产出被系统性高估：容量规划按公式算出 γ 加长仍有正边际收益，实际部署却发现第 γ 位的边际收益 <span>$$\\prod_{j\\le\\gamma}\\alpha_j$$</span> 早已低于边际成本。工程判断因此很直接：代码场景宜用较短 γ 并配合语法感知草稿，而不是盲目加长草稿链；公式的正确用法是代入实测的逐位置衰减曲线，而非一个标量。</p>\n<p>第二处近似随批大小漂移。c 定义为草稿单步开销与目标验证单步开销之比，小批量下目标前向受权重带宽约束、草稿模型相对轻量，c 较小；大批量下验证被摊薄，但草稿模型自身也受带宽约束，其相对成本上升，c 不再是小批量测得的那个值。分母 <span>$$1+c\\,\\gamma$$</span> 因此被低估，加速比在 B 增大时饱和甚至回落。更隐蔽的失效来自采样路径：公式只在验证采用拒绝采样、严格保持目标分布时成立，α 的判据是 <span>$$\\alpha=\\mathbb{E}_{x\\sim p_{\\text{target}}}\\left[\\min\\!\\left(1,\\frac{p_{\\text{draft}}(x)}{p_{\\text{target}}(x)}\\right)\\right]$$</span>；一旦启用温度采样、top-p 截断或 top-k，接受判据改变，α_j 必须按实际采样分布重算，否则不仅期望产出被高估，输出分布还会偏离目标模型。把训练时的接受率直接搬到推理、未考虑温度与截断，是上线后实测加速比远低于预估、甚至草稿开销造成负收益的常见来源。</p>\n<p>树状草稿（Medusa/EAGLE）把公式的结构也改了：一次验证覆盖多条候选路径，接受长度按树路径重算，期望产出不再是单链前缀概率之和，而应改为树期望深度——每条从根到叶的路径各自贡献存活概率，验证一次前向的并行校验能力被用来覆盖分支而非延长单链。这意味着 γ 的语义从“链长”变为“树宽×深度”，c 的分母也不再是单次目标前向对应 γ 个位置，而是对应整棵树的节点数。系统代价随之变化：树越宽，验证前向的算力占用越接近满载，草稿侧的显存与带宽开销按分支数增长，而期望深度受最可能路径支配。工程上判断是否值得引入投机路径，应看实测 α 衰减曲线与成本比 c 的组合：α 衰减过快时加速比趋近 1，草稿模型的显存却被长期占用，此时应退回纯目标模型部署，把显存留给 KV cache 与更大批。</p>\n<table class=\"mini\"><thead><tr><th>失效来源</th><th>公式中被破坏的假设</th><th>系统代价表现</th></tr></thead><tbody><tr><td>单一平均接受率</td><td>逐位置 α_j 连乘</td><td>高估吞吐、低估草稿显存</td></tr><tr><td>高温/top-p 截断</td><td>拒绝采样判据与 α 定义</td><td>分布偏离、实测加速比不符</td></tr><tr><td>大批量部署</td><td>c 为常数、成本可加</td><td>成本比上升、加速比饱和</td></tr><tr><td>树状草稿</td><td>单链前缀求和</td><td>验证算力满载、显存按分支增长</td></tr></tbody></table>\n<h3 id=\"th-speculative-acceptance-sec-14\">十四 · 串行假设的边界：验证一次前向能并行校验多少</h3>\n<p>加速比公式的分母写作 1+cγ，隐含了一个很强的结构假设：草稿的 γ 步是串行的，而目标的验证是单次前向并行覆盖 γ 个位置。这个假设在自回归草稿（单模型逐 token 生成）加标准拒绝采样验证的路径上成立，一旦换成树状草稿就立刻失效。Medusa、EAGLE 这类方案让草稿模型一次吐出多条候选分支，验证阶段要沿树路径逐条比对，接受长度不再是单链前缀存活概率之和，而是树的期望深度——每层存活的分支数随层数衰减，期望产出要对树做加权求和而非对链做累乘。工程上这意味着：把链式公式直接套到树状草稿上，会系统性高估产出，因为树的分支在同一层共享前缀，接受判据在分叉点之后不再独立累乘。</p>\n<p>另一层边界在“一次前向并行校验 γ 个位置”本身。目标模型一次前向能吃下 γ 个位置，前提是这些位置的 KV 已在同一 batch 内排布好，且验证 kernel 的并行度足以覆盖 γ 个 query 位置。当 γ 增大到接近目标模型单次前向的算力饱和点，验证前向的耗时不再与 γ 无关，分母里的“1”开始随 γ 增长，公式的归一化代价被低估。容量规划时若按小 γ 实测的验证耗时外推大 γ，会得到偏乐观的加速比。判断方法是：固定批大小，扫 γ，测验证前向的实际时延曲线，找到它开始偏离常数的拐点，γ 的上界就落在那附近。</p>\n<div class=\"formula\">$$\\text{Speedup}=\\frac{\\mathbb{E}[\\text{tokens/round}]}{1+c\\,\\gamma},\\qquad \\mathbb{E}[\\text{tokens/round}]=\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\alpha_j$$</div>\n<p>代价侧的具体例子：代码补全场景里，若把 γ 从 4 拉到 16 而验证前向时延从常数变成线性增长，分母从 1+4c 涨到 1+16c 的同时分子因尾部 α_j 衰减几乎不增，加速比反而下降。这不是公式错了，是公式的适用域被越过了。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-15\">十五 · 逐位置独立假设在代码 token 上的崩塌</h3>\n<p>α_j 的链式累乘依赖一个未明说的假设：第 j 位的接受判据与前 j−1 位是否被接受无关，各位置判据独立。真实文本里这个假设勉强能用，代码里则明显失真。缩进、括号配对、关键字序列构成强自相关：一旦草稿模型在左括号位置命中，右括号位置的命中概率被显著抬高；一旦在 `def` 后命中函数名，参数列表的语法约束又让后续若干位置的接受率不同于边缘分布。独立假设下算出的 ∏α_j 会低估长串的整体接受概率，因为条件概率在命中前缀后上升，而公式用的是边缘 α_j 的乘积。</p>\n<p>反过来，自由命名标识符和长表达式是另一极：草稿模型在进入一个新标识符后，后续字符的接受率快速衰减，尾部 α_j 趋近于零。这两极叠加的结果是接受率曲线呈“前段高、中段陡降、尾段近零”的形状，用单一平均接受率代入公式会同时犯两个错——高估尾部产出、低估前段串行收益。正确做法是保留逐位置 α_j 向量，按前缀条件重算，或至少在容量规划时用分段 α 而非全局均值。</p>\n<ul>\n<li>机制：接受判据 α=𝔼[min(1, p_draft/p_target)] 在拒绝采样下严格保持目标分布，但温度、top-p、top-k 会改写采样分布，α_j 必须按实际采样分布重算，否则分子被高估。</li>\n<li>代价：代码场景下若沿用训练期测得的接受率，未计入推理时温度与截断的影响，上线实测加速比会明显低于预估，草稿显存却已按乐观 γ 分配。</li>\n<li>例子：语法感知草稿在括号与关键字位置命中率高，但进入自由命名标识符后衰减快，因此代码任务宜用较短 γ 配语法约束草稿，而非盲目加长链。</li>\n</ul>\n\n<h3 id=\"th-speculative-acceptance-sec-16\">十六 · 成本比 c 随批大小漂移，加速比在 B 增大时饱和</h3>\n<p>c 被定义为草稿单步开销与目标验证单步开销之比，公式把它当成常数。实际部署里 c 是批大小的函数：大批量下验证前向被摊薄，单 token 的目标成本下降，c 相对上升；同时草稿模型自身也受带宽约束，草稿的绝对开销不随批增大而线性摊薄。两者同向变化的结果是，加速比随批大小 B 增大而饱和——分子 E[tokens] 与 B 基本无关（接受率由分布决定），分母里的 cγ 却随 B 上升，比值趋平。</p>\n<div class=\"formula\">$$\\text{Speedup}(B)\\approx\\frac{\\mathbb{E}[\\text{tokens}]}{1+\\gamma\\,c(B)},\\qquad c(B)\\ \\text{随}\\ B\\ \\text{增大而上升}$$</div>\n<p>这条边界的工程含义很直接：投机解码的收益在高并发、大 batch 的吞吐型部署里被压缩，而在低并发、延迟敏感的部署里最显著。用小块测得的 c 去估算大 batch 的加速比，会得到偏乐观的数字。容量规划时应按目标 batch 区间实测 c(B)，而不是拿单请求数据外推。具体例子：一个在线代码补全服务在 batch=1 时投机路径收益明显，迁到 batch 数十的离线批处理队列后，验证被摊薄、草稿相对成本上升，投机路径反而拖低整体吞吐——此时应关掉草稿或改用更短 γ。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-17\">十七 · 分布保真与采样参数的耦合</h3>\n<p>公式只在验证采用标准拒绝采样、严格保持目标分布时成立。温度采样、top-p、top-k 改变的是采样分布本身，接受判据 α 的定义随之改变，若仍用默认判据代入，输出分布会偏离目标模型，实测加速比也与公式不符。这不是数值误差，是判据与分布不匹配导致的结构性偏差。工程判断：把采样参数纳入 α 的实测流程，按实际部署的 temperature/top-p 重测逐位置接受率，再代入公式；否则公式给出的分子只是理论值，不能用于容量规划。</p>\n<p>代价侧：分布偏离在代码场景尤其危险，因为语法约束下的小概率偏差可能让生成结果从“可编译”滑向“语法错误”，下游校验成本上升，抵消了投机带来的延迟收益。机制上，拒绝采样保证无偏的前提是草稿分布与目标分布在同一采样参数下比较；一旦目标侧做了截断，草稿侧未同步，min(1, p_draft/p_target) 的比值失去意义。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-18\">十八 · 规模上限：最优 γ 与边际收益归零</h3>\n<p>γ 不是越大越好。分子对 γ 的边际增益是第 γ+1 位的存活概率 ∏_{j≤γ+1}α_j，分母对 γ 的边际成本是常数 c。当存活概率降到 c 以下，继续加长草稿链就是净亏。最优 γ 由 ∏_{j≤γ}α_j ≈ c 的位置决定，这个判据把公式从“算加速比”变成“定 γ 上界”的工具。代码任务里 α_j 衰减快，最优 γ 往往落在个位数；自然语言任务衰减慢，γ 可以更大。</p>\n<ul>\n<li>机制：逐位置 α_j 衰减曲线决定边际收益，c 决定边际成本，两者交点即 γ 上界。</li>\n<li>代价：γ 过大时草稿显存与草稿前向次数线性上升，而分子趋平，显存被草稿模型占用却不换吞吐。</li>\n<li>例子：α 衰减过快时加速比趋近 1，此时引入投机路径只增加显存占用与调度复杂度，不带来收益，应判定为不值得部署。</li>\n</ul>\n<p>规模上限还有一层：当 α 整体偏低（例如目标模型与草稿模型容量差距过大），E[tokens] 趋近 1，加速比趋近 1/(1+cγ)，小于 1 即为负收益。此时公式并未失效，它正确地告诉你投机路径在此部署下不成立——失效的是“投机总能加速”这个先验，而非公式本身。工程上把这条判据前置到选型阶段：先用小样本测 α_j 曲线与 c(B)，代入公式判断是否值得引入草稿模型，再决定 γ 与草稿规模。</p>\n<p>最后落在具体机制上：把逐位置 α_j 向量、c(B) 曲线、验证时延随 γ 的拐点三张实测表作为投机路径的准入条件，任何一项缺失都意味着公式的适用域未被验证，此时公式给出的加速比只能当作上界而非预测值。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-19\">十九 · 边界条件：公式在什么工况下失效</h3>\n<p>加速比公式的成立依赖三个隐含契约：草稿与验证严格串行、验证一次前向能并行校验 γ 个位置、α_j 逐位置独立。任何一条被打破，分子分母都要重算。树状草稿（Medusa/EAGLE）是最典型的反例——候选不再是单链而是分支树，接受长度不再等于前缀存活概率之和，而应按树路径的期望深度计算：每条根到叶路径各自乘以其路径概率，再对深度加权求和。此时若仍套用链式 <span>∏α_j</span>，会把并行分支的覆盖收益算丢，同时把验证侧的一次前向代价低估——树验证要携带多路径的注意力掩码与位置编码，验证前向的实际耗时高于单链。工程判断上，树宽与树深直接决定验证 kernel 的有效 batch，树越宽，验证越接近“小批量多序列”，TMEM 与 SM 占用上升，c_target 不再是单链常数。</p>\n<p>第二个失效点是 α 的独立性假设。代码 token 存在强自相关：缩进层级、括号配对、关键字序列让相邻位置的接受事件高度耦合。独立假设下长串联合概率被系统性低估，但反过来，用单一平均接受率代替逐位置 α_j 又会系统性高估——两种误差方向相反，谁占主导取决于任务形态。正确做法是实测 α_j 衰减曲线并按位置代入，而不是取一个标量。代码场景的典型形态是：括号、关键字、缩进位置 α_j 接近饱和，一旦进入自由命名标识符或长表达式，尾部 α_j 快速塌陷至近零，此时继续加长 γ 只增加草稿开销而不增加期望产出，边际收益 <span>∏_{j≤γ}α_j</span> 低于边际成本即应停止加长。语法感知草稿配合较短 γ，比盲目拉长链更划算。</p>\n<p>第三个失效点来自采样策略对接受判据的改写。公式中的 α 是拒绝采样判据下的期望，一旦启用温度、top-p、top-k，接受判据变为按实际采样分布重算的比较，草稿分布与目标分布的比值不再是原始 p_draft/p_target。沿用默认判据会导致两个后果：输出分布偏离目标模型（正确性受损），实测加速比与预估脱节。容量规划时必须用部署时的真实采样参数重测 α_j，训练阶段的接受率不能直接搬用。</p>\n<p>最后是规模上限，也是最容易被忽略的一项。c 是草稿单步与验证单步的开销比，随批大小漂移：大批量下验证被摊薄，单 token 验证成本下降，c 看似变小；但草稿模型自身同样受带宽约束，其权重读取与 KV 访问并不随批线性摊薄，于是 c 在 B 增大到某点后不再下降甚至回升。加速比因此在批大小上饱和——继续加批，分子（期望接受长度）不变，分母的相对草稿开销上升，投机路径从增益转为拖累。下表给出四种工况下公式的适用性判断：</p>\n<table class=\"mini\"><thead><tr><th>工况</th><th>公式状态</th><th>系统代价落点</th></tr></thead><tbody><tr><td>单链、低温、小批</td><td>成立，可直接用于选 γ</td><td>草稿显存占用、串行步数</td></tr><tr><td>树状草稿</td><td>失效，需换树期望深度</td><td>验证 kernel 有效 batch 上升、掩码开销</td></tr><tr><td>高温 / top-p 截断</td><td>失效，α_j 须按实际分布重算</td><td>分布偏移、实测加速比脱节</td></tr><tr><td>大批量</td><td>饱和，c 不再单调下降</td><td>草稿带宽受限、整体吞吐被拖低</td></tr></tbody></table>\n<p>由此得到的工程判据是：先用实测 α_j 衰减曲线与部署批大小下的 c 反推最优 γ，再判断该部署是否值得引入投机路径。α 衰减过快时加速比趋近 1，而草稿模型仍占着显存与一条额外的权重读取路径——此时投机解码不是“没收益”，而是负收益，因为它把本可用于增大验证批的显存与带宽挪给了草稿。</p>\n<h3 id=\"th-speculative-acceptance-sec-20\">二十 · 把加速比公式改写成容量约束</h3>\n<p>在容量规划语境里，<span class=\"sym\">Speedup</span> 不是一个用来“展示效果”的指标，而是一个必须与批大小 B、并行度 T、KV 预算和 SLO 同时求解的约束方程。做法是把公式两侧都乘上目标模型的单 token 成本，得到每轮的实际时间预算：</p>\n<div class=\"formula\">$$T_{\\text{round}}(B)\\approx \\underbrace{t_{\\text{target}}(B)}_{\\text{一次验证前向}}+\\underbrace{\\gamma\\cdot t_{\\text{draft}}(B)}_{\\text{草稿串行步}}+\\underbrace{t_{\\text{sched}}}_{\\text{调度与同步}}$$</div>\n<p>分子是每轮期望产出 <span class=\"sym\">E[tokens]</span>，于是单请求的有效 token 吞吐为 <span class=\"sym\">E[tokens]/T_round</span>，系统吞吐再乘 B。关键判断在于：<span class=\"sym\">t_target(B)</span> 与 <span class=\"sym\">t_draft(B)</span> 都不是常数，它们随 B 增大而分别趋近各自的带宽下界（解码阶段的 roofline 带宽界已在别处给出，此处只用其结论）。因此容量决策的第一步不是选 γ，而是先固定 B 的量级，再在该 B 下实测 <span class=\"sym\">c=t_draft/t_target</span>，把 c 当作 B 的函数而非全局常数。忽略这一点，就会得到“小批量测得加速比 2.4、上线大批量实测 1.1”的典型偏差。</p>\n<p>具体机制上，工程上把上述方程离散化为一张表：对每个候选 (B, γ) 组合，记录实测的逐位置接受率 α_j 与两个前向的耗时，算出 E[tokens] 与 T_round，再与 SLO 的 token 间隔上限比较。这张表就是容量规划的原始输入，而不是事后验证。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-21\">二十一 · 定批大小：加速比饱和点决定 B 的上界</h3>\n<p>批大小与投机路径的耦合来自 c 的漂移。小批量下目标验证前向受权重带宽主导，草稿模型因参数量小而相对便宜，c 较小，投机收益明显；当 B 增大到两者都进入访存受限区，草稿的相对成本上升，c 变大，分母 <span class=\"sym\">1+cγ</span> 被抬高，加速比被摊薄直至饱和。于是存在一个由公式直接给出的 B 上界判据：</p>\n<div class=\"formula\">$$\\frac{\\partial}{\\partial B}\\left[\\frac{\\mathbb{E}[\\text{tokens}]}{1+c(B)\\,\\gamma}\\right]\\le 0 \\;\\Longrightarrow\\; \\text{投机路径不再贡献吞吐}$$</div>\n<p>由于 E[tokens] 与 B 基本无关（接受率由分布决定，不由批量决定），饱和条件简化为 c(B) 的增长吞掉分子增益。工程做法是：先在目标硬件上扫 B ∈ {小、中、大} 三档，测出 c(B) 曲线，找到 c(B)·γ 与 E[tokens]−1 相等的交点，该点即为“引入投机仍然划算”的最大批量。超过该点，正确决策是把投机路径关掉、退回纯目标模型大批量解码，而不是继续加 γ。</p>\n<p>代价面：这个交点直接决定显存分配。草稿模型常驻显存（权重 + 其自身的 KV），在 B 较大时这部分显存挤占的是目标模型的 KV 预算，形成“投机换吞吐”与“KV 换并发”的对冲。一个具体例子：代码补全服务在 B 较小时投机收益显著，但当并发请求数上升到使验证前向进入带宽饱和区，草稿模型占用的那份显存若改分配给 KV cache，反而能多容纳若干并发序列，整体 token/s 更高。判断依据就是上面那个交点，而不是拍脑袋的“投机总是好的”。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-22\">二十二 · 定并行度：γ 与 TP 的联合选择</h3>\n<p>γ 的选择不是孤立的最优化，它与张量并行度 T 共享同一份算力与带宽预算。给定实测的 α_j 衰减曲线，最优 γ 由边际条件给出：</p>\n<div class=\"formula\">$$\\gamma^\\*=\\max\\left\\{\\gamma:\\ \\prod_{j\\le\\gamma}\\alpha_j \\;&gt;\\; c\\cdot\\gamma\\ \\text{的边际成本项}\\right\\}$$</div>\n<p>更精确地说，增加第 γ+1 个草稿位置的边际收益是“前 γ 位全部接受”的联合概率 <span class=\"sym\">∏_{j≤γ}α_j</span>（它等于链长能延伸到 γ+1 的概率），边际成本是额外一次草稿前向折算到目标成本上的 c。当边际收益跌破边际成本，停止加长。代码任务的 α_j 衰减极快——括号、关键字、缩进位置命中率高，一旦进入自由命名标识符或长表达式，尾部 α_j 迅速趋零——因此代码场景的 γ* 通常远小于自然语言场景，宜用较短 γ 配合语法感知草稿，而不是盲目加长链。</p>\n<p>与 TP 的耦合在于：提高 T 会同时降低 <span class=\"sym\">t_target</span> 与 <span class=\"sym\">t_draft</span>，但草稿模型参数量小，TP 对它的收益递减更快（通信开销占比更高，张量并行通信下界已在别处给出）。结果是增大 T 往往抬高 c，压缩 γ*。因此并行度决策应把 (T, γ) 作为二维网格联合搜索：每个格点用实测 α_j 与两个前向耗时算出加速比与显存占用，选满足 SLO 且显存可行的最优点。代价面是通信量随 T 增长，而 γ 增长带来的是串行草稿步的延迟叠加，两者对尾延迟的影响方向不同，必须分开计量。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-23\">二十三 · 定 KV 预算：草稿模型的隐性占用</h3>\n<p>投机路径对 KV 预算的影响常被低估。草稿模型自身需要 KV cache 来生成 γ 个候选 token，其每 token 的 KV 尺寸由草稿模型的层数、头数与头维度决定，通常小于目标模型但不为零；同时验证阶段目标模型要为 γ 个位置一次性写入 KV（因为验证是并行前向，γ 个位置的 KV 同时落盘）。于是单序列的 KV 占用近似为：</p>\n<div class=\"formula\">$$M_{\\text{KV}}^{\\text{seq}}\\approx L_{\\text{ctx}}\\cdot k_{\\text{target}}+L_{\\text{ctx}}\\cdot k_{\\text{draft}}+\\gamma\\cdot k_{\\text{target}}^{\\text{step}}$$</div>\n<p>其中前两项是常驻上下文 KV，第三项是验证窗口的瞬时增量。容量规划时若只按目标模型的 KV 容量公式估算并发数，会系统性高估可承载序列数——草稿模型的常驻 KV 与验证窗口的瞬时峰值都要从同一块显存里扣。具体机制上，验证窗口的 γ 个位置在拒绝采样后只有被接受的前缀需要保留，未接受位置的 KV 可丢弃，因此瞬时峰值出现在验证前向进行中而非之后；调度器必须按峰值而非稳态分配，否则在高并发下触发 OOM 或被迫降低 B。</p>\n<p>工程判断：当 α_j 衰减快、γ* 很小时，验证窗口的瞬时增量小，KV 预算的主要压力来自草稿模型的常驻 KV；此时若草稿模型与目标模型共享分词器与部分层（如 EAGLE 式结构），常驻开销可压缩。反之若 γ 较大而 α 衰减慢（自然语言场景），瞬时峰值成为主导项，需要为验证窗口预留额外显存余量。两种情形对应不同的容量公式取舍，不能套用同一套参数。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-24\">二十四 · 定 SLO：尾延迟而非均值</h3>\n<p>SLO 通常约束的是 token 间隔的尾部分位数（如 P99 inter-token latency），而加速比公式给的是期望值。期望产出高不代表尾延迟好：草稿链在某一轮被全部拒绝时，该轮只产出 1 个 token，却付出了 γ 次草稿前向的串行代价，这一轮的时间是 <span class=\"sym\">t_target+γ·t_draft</span>，远高于纯目标模型的单步。全拒绝轮的概率是 <span class=\"sym\">1−α_1</span>，在 α_1 偏低的场景（高温采样、top-p 截断改变判据）并不罕见。</p>\n<div class=\"formula\">$$T_{\\text{round}}^{\\text{worst}}\\approx t_{\\text{target}}+\\gamma\\cdot t_{\\text{draft}},\\qquad P(\\text{全拒绝})=1-\\alpha_1$$</div>\n<p>因此 SLO 决策要把“最坏轮时间”纳入约束：若 SLO 的 P99 间隔上限低于 <span class=\"sym\">t_target+γ·t_draft</span>，则无论期望加速比多高，该 γ 都不可用，必须缩短 γ 或改用树状草稿把最坏路径摊薄。温度与截断在这里是硬约束：拒绝采样判据下 α_j 按实际采样分布重算，温度升高会拉低 α_1，直接抬高全拒绝轮概率，尾延迟恶化。用训练时的接受率搬到推理、或沿用默认判据而不重算 α_j，都会让实测加速比与 SLO 同时失守。</p>\n<p>一个具体例子：交互式代码补全的 SLO 要求 P99 间隔在百毫秒量级，若 γ 取较大值使最坏轮时间超过该上限，即便平均加速比可观，用户仍会感知到卡顿。正确做法是按 SLO 反推 γ 的上界，再在该上界内用边际条件选 γ*，两个约束取交集。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-25\">二十五 · 算例：从 α 曲线到部署参数</h3>\n<p>设某代码补全部署，实测逐位置接受率呈快速衰减：α_1 较高，α_2 起明显下降，尾部趋零（定性描述，不引用具体数值）。目标模型单步耗时 <span class=\"sym\">t_target</span>，草稿单步耗时 <span class=\"sym\">t_draft</span>，在该 B 下实测 c = t_draft/t_target。按公式算期望产出：</p>\n<div class=\"formula\">$$\\mathbb{E}[\\text{tokens}]=1+\\alpha_1+\\alpha_1\\alpha_2+\\alpha_1\\alpha_2\\alpha_3+\\cdots$$</div>\n<p>由于 α_2 之后乘积迅速缩小，E[tokens] 很快收敛，加长 γ 的边际收益 <span class=\"sym\">∏_{j≤γ}α_j</span> 在少数几个位置后就跌破 c，故 γ* 取小值。代入加速比 <span class=\"sym\">E[tokens]/(1+cγ*)</span>，若 c 在该 B 下偏大（草稿相对不便宜），加速比可能仅略高于 1，此时引入投机路径的收益不足以抵消草稿模型占用的显存——若那份显存改分配给 KV cache 能多承载并发序列，则整体吞吐更优，决策应是放弃投机、退回纯目标模型。</p>\n<p>反之，若换到自然语言场景，α_j 衰减慢、E[tokens] 随 γ 持续增长，γ* 可取较大值，加速比显著高于 1，此时应把显存优先给草稿模型并预留验证窗口峰值。同一套公式，两种场景给出相反的容量结论，差别全部来自 α_j 曲线的形状与 c(B) 的实测值。这就是把公式用作决策工具而非展示指标的全部意义：输入是实测的逐位置 α 与随 B 漂移的 c，输出是 (B 上界, γ*, T, KV 余量, SLO 可行性) 这组互相咬合的部署参数，任何一项用平均值或训练期数字替代，都会让整组参数失配。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-26\">二十六 · 把期望加速比折进容量账本：批大小、并行度、KV 与 SLO 的联立</h3>\n<p>公式一旦离开纸面进入部署决策，最先暴露的是它的“单请求假设”。<span class=\"formula\">$$\\text{Speedup}(B)=\\frac{\\mathbb{E}[\\text{tokens/round}]}{1+c(B)\\,\\gamma}$$</span> 里只有 c 带批维度，而 E[tokens/round] 由 α_j 决定、与 B 无关——这个不对称正是工程判断的入口。定批大小时不能拿单请求测得的 c 直接外推：B 增大后目标验证的一次前向被更多请求摊薄，c 名义下降，但草稿模型自身也落入带宽受限区，其单步开销不再随 B 摊薄，于是 c(B) 先降后升，加速比在某个 B* 处饱和。容量规划的做法是固定 γ，扫 B 测出 c(B) 曲线，取 Speedup(B)·B 的极大点作为批上界；越过该点，投机路径每多带一个请求都在净亏目标算力。并行度同理：TP 扩大压低单步延迟却抬高通信占比，草稿模型因层数浅、通信敏感，其相对成本 c 随 TP 上升而恶化，故草稿侧宜用较小 TP 或独立部署，把“草稿—验证”的成本比锁在可控区间。</p>\n<p>KV 预算要按“双模型共存”重算，这是最容易被漏掉的一项。草稿模型虽小，仍需自己的权重与 KV；γ 越长，验证阶段目标模型要一次性持有 γ 个位置的 KV 与 logits 缓冲，峰值显存随 γ 线性抬升。设目标模型每 token KV 为 k、草稿为 k_d，则每请求额外占用约为 γ(k+k_d) 量级，B 个并发请求叠加后直接吃掉原本留给长上下文的余量。因此定 KV 预算的顺序应是：先由 SLO 的 TTFT/TPOT 反推可接受的最大 γ，再由 γ 与 B 反推草稿模型可用的显存上限，最后才决定草稿模型规模——而不是先选一个“够聪明”的草稿模型再挤显存。当 α 衰减过快时，加长 γ 的边际收益 ∏_{j≤γ}α_j 迅速跌破边际成本，此时正确动作是缩 γ 甚至摘掉投机路径，把显存还给 KV。</p>\n<p>SLO 约束下这套公式的用法是“反解”而非“正算”。给定 TPOT 上限与目标吞吐，先由 1+cγ 的相对代价确定每轮时间预算，再由 E[tokens/round] 折算每轮可交付 token 数，二者相除即单请求 token 速率；把它乘以可并发请求数，得到满足 SLO 的吞吐上界。算例：某代码补全服务实测 α 序列在前几位接近饱和、进入自由命名标识符后快速衰减，取 γ=4 时 E[tokens/round] 明显高于 γ=8 的边际增量，而 c 在小批量下约为零点几量级；按上式，γ=4 的加速比高于 γ=8，且验证缓冲的显存占用减半。据此把批大小定在 c(B) 拐点之前、γ 压到 4、草稿模型独立小 TP 部署，KV 预算按 4(k+k_d) 预留——这套联立解比“平均接受率×γ”的粗算更贴近上线实测。</p>\n<table class=\"mini\"><thead><tr><th>决策量</th><th>依赖的公式项</th><th>失效信号</th></tr></thead><tbody><tr><td>批大小 B</td><td>c(B) 的拐点</td><td>Speedup(B)·B 转降</td></tr><tr><td>草稿长度 γ</td><td>∏α_j 的边际衰减</td><td>边际收益低于边际成本</td></tr><tr><td>KV 预留</td><td>γ(k+k_d)·B</td><td>长上下文被挤掉</td></tr><tr><td>并行度</td><td>c 随 TP 恶化</td><td>通信占比压过收益</td></tr></tbody></table>\n<p>边界条件必须写进决策文档，否则公式会以“预估很美、上线为负”的方式反噬。第一，α_j 的逐位置衰减不可用平均值替代，代码任务的强自相关使独立假设低估长串接受概率、却又因尾部趋零而高估总产出，两种偏差方向相反、净效果取决于 γ；第二，温度采样与 top-p/top-k 截断改变接受判据，α_j 必须按实际采样分布重算，否则既偏离目标分布又对不上实测加速比；第三，c 的批依赖不可忽略，小批量测得的成本比搬到大并发部署会系统性低估草稿开销。工程判断落在一条硬规则上：任何投机部署上线前，必须用逐位置 α_j 曲线与实测 c(B) 曲线重跑一次 Speedup(B,γ)，若最优点落在 γ≤2 或 B 很小的角落，说明该负载的接受结构不支持投机路径，应直接退回纯目标模型解码，把省下的显存与调度复杂度换成长上下文容量。</p>\n<h3 id=\"th-speculative-acceptance-sec-27\">二十七 · 误用一：把平均接受率塞进逐位置公式</h3>\n<p>最常见也最隐蔽的误用，是把一整段实测的“平均接受率”<em>ᾱ</em> 直接代入逐位置累积式，令 <span class=\"sym\">α_j</span> ≡ <em>ᾱ</em>，于是期望产出退化为 <em>1 + ᾱ + ᾱ² + … + ᾱ^γ</em>。这在数学上等价于假设接受事件在草稿链上独立同分布，而真实代码 token 恰恰是强自相关的：缩进、括号配对、关键字序列让前缀一旦存活，后续若干位几乎必然命中；而一旦进入自由命名标识符或长表达式，尾部 <span class=\"sym\">α_j</span> 会快速塌陷。平均化把这两种截然不同的区段抹平，结果是对长链期望产出的系统性高估——因为几何级数在 <em>ᾱ</em> 中等偏高的假设下衰减太慢，而真实序列是“前段接近 1、尾段接近 0”的断崖。</p>\n<p>识别方法很直接：在容量规划阶段不要只记录一个标量接受率，而是按草稿位置 <em>j</em> 分桶统计 <span class=\"sym\">α_j</span>，画出衰减曲线。若曲线呈明显前高后低且尾部趋零，则任何用单一均值算出的 γ 最优解都不可信。工程上应改用实测的逐位置乘积 <em>∏_{j≤i} α_j</em> 直接累加得到 <em>E[tokens]</em>，再与分母 <em>1 + γ·c</em> 做边际比较：当新增第 γ 位的边际收益 <em>∏_{j≤γ} α_j</em> 低于其边际成本 <em>c</em> 时停止加长。代价层面，这一误用直接体现为显存与吞吐的双重错配——按高估的期望产出选定的 γ 会让草稿模型常驻显存、每轮多做 γ 次前向，而实测每轮只多换回一两个 token，投机路径从增益变成纯开销。</p>\n<div class=\"formula\">$$\\text{误估：}\\ \\mathbb{E}[\\text{tokens}] \\approx \\sum_{i=0}^{\\gamma}\\bar{\\alpha}^{\\,i}\\ \\ \\text{vs 实测：}\\ \\mathbb{E}[\\text{tokens}] = 1+\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\alpha_j$$</div>\n<p>具体例子：一个代码补全服务在离线评测中测得平均接受率处于中等水平，据此把 γ 设得较长并预留了草稿模型显存。上线后真实流量以自由命名标识符与长表达式为主，尾部 <span class=\"sym\">α_j</span> 迅速趋零，长草稿链的后半段几乎从不被接受，实测加速比远低于预估，且草稿前向的固定开销把整体吞吐拖到基线以下。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-28\">二十八 · 误用二：采样参数变了，判据没重算</h3>\n<p>加速比公式的成立前提是验证采用拒绝采样、严格保持目标分布，此时接受判据为 <span class=\"sym\">α = E[min(1, p_draft/p_target)]</span>。一旦推理端开启温度采样、top-p 截断或 top-k，采样分布本身被改写，接受判据必须按<strong>实际采样后</strong>的分布重算；沿用默认判据得到的 <span class=\"sym\">α_j</span> 与真实接受概率脱节。更严重的是分布正确性问题：草稿与验证若不在同一套截断/温度语义下比较，拒绝采样不再保证输出服从目标分布，投机路径会悄悄改变模型行为，而这类偏差在离线平均接受率指标上完全看不出来。</p>\n<p>识别信号是“公式与实测不符且随采样参数漂移”：同一模型在贪心解码下加速比正常，切到高温或宽 top-p 后加速比骤降，而草稿模型与 γ 均未改动。此时应检查验证端是否对草稿分布与目标分布做了同样的截断归一化，并把 <span class=\"sym\">α_j</span> 的统计口径改为按当前采样配置采集。系统代价上，这类误用往往以“看似省了验证算力、实则输出质量漂移”的形式出现——吞吐数字好看，但采样语义被破坏，属于典型的静默失效。</p>\n<p>具体例子：某对话服务为提升多样性把温度调高、top-p 放宽，草稿模型仍按贪心路径生成候选，验证端却用原始拒绝判据比对。结果是被接受的草稿 token 集中在高概率区，输出分布明显窄于目标分布，而容量规划里引用的加速比来自贪心配置的实测值，两者不可比。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-29\">二十九 · 误用三：小批量测得的成本比搬到大批量</h3>\n<p>分母中的 <span class=\"sym\">c</span> 是草稿单步开销与目标验证单步开销之比，它不是常数，而是随批大小漂移的量。小批量下目标验证受权重带宽约束、单步成本高，草稿的相对成本显得低，<span class=\"sym\">c</span> 偏小；批一大，验证被摊薄、单步成本下降，同时草稿模型自身也撞上带宽墙，两者同时访存受限，<span class=\"sym\">c</span> 反而上升。用实验室小批量标定的 <span class=\"sym\">c</span> 去推算生产大批量吞吐，会把加速比估得过于乐观，甚至在 <em>E[tokens]/(1+cγ)</em> 逼近 1 时仍以为有正收益。</p>\n<p>识别方式是做 <span class=\"sym\">c</span> 随批大小的扫描曲线，而不是单点测量；若曲线在大批量段上翘，则投机路径的净收益随并发上升而收缩，加速比在 B 增大时饱和。容量决策上应把 <span class=\"sym\">c(B)</span> 与 <em>E[tokens]</em> 一起代入，求使 <em>E[tokens] > 1 + c(B)·γ</em> 成立的批大小区间；超出该区间就应关闭投机或缩短 γ。这里的系统代价是吞吐与显存的双向挤压：大批量本已把显存推向 KV cache 容量边界，再叠加草稿模型权重与草稿 KV，等于用稀缺的显存换一个正在消失的加速。</p>\n<p>具体例子：一个高并发在线推理集群按单请求低并发测得成本比并据此开启投机，扩容到大批量后目标验证被充分摊薄，草稿前向的相对开销上升，整体吞吐不升反降；运维侧看到的是 GPU 利用率上升而有效 token 吞吐下降，根因正是成本比随批漂移未被建模。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-30\">三十 · 反例：树状草稿套用链式公式</h3>\n<p>下面给一个完整的反例。某代码生成系统采用树状草稿（Medusa/EAGLE 类），草稿端一次展开多条候选路径形成树，验证端一次前向校验整棵树上的多个位置。团队却直接套用链式期望式 <em>E[tokens] = 1 + Σ ∏ α_j</em>，把树上每个位置的边际接受概率当作一条线性链上的 <span class=\"sym\">α_j</span> 连乘。这在结构上就错了：树状草稿的接受长度不是沿单链累积，而是按<strong>被接受的最长树路径</strong>重算——同一层上多个候选共享前缀，接受事件在分支间不独立，正确口径应是树的期望深度，而非某条链的乘积和。</p>\n<p>后果有三层。其一，期望产出被高估：链式公式把分支上的候选当成串行位，重复计入了共享前缀的存活概率。其二，γ 的语义错位：树状草稿的“每轮草稿 token 数”是树节点总数，而分母里的 γ 若仍按链长理解，成本被低估。其三，显存与验证代价被低估：树验证一次前向要覆盖全部树节点，注意力与 KV 占用随树宽增长，而链式模型对此毫无体现。识别信号是“实测接受长度分布呈多峰、且与链式预测的单调衰减不符”——树状草稿的接受长度往往集中在若干固定深度，因为语法结构决定了哪些分支能存活。</p>\n<div class=\"formula\">$$\\text{链式误用：}\\ \\mathbb{E}[\\text{tokens}] = 1+\\sum_{i=1}^{\\gamma}\\prod_{j=1}^{i}\\alpha_j\\ \\ \\text{应改为树期望深度：}\\ \\mathbb{E}[\\text{depth}]=\\sum_{d\\ge 1}\\Pr(\\text{存在存活路径深度}\\ge d)$$</div>\n<p>具体例子：该系统在括号与关键字密集的区段接受长度表现良好，团队据此加宽树、加深树，并按链式公式预估吞吐翻倍。上线后树验证的 KV 占用挤占了本已紧张的 KV cache 容量，并发容量下降，而实测每轮产出远低于链式预估——因为多数分支在第二、三层就被剪掉，长路径存活概率被链式乘积严重高估。工程判断很明确：树状草稿必须用树深度期望与树节点总数重算分子分母，链式公式只适用于单链草稿；一旦草稿结构改变，公式的适用前提就失效，继续沿用等于用错误的模型做容量规划。</p>\n<p>这三类误用共享同一个根因：把公式里的符号当成常数，而 <span class=\"sym\">α_j</span>、<span class=\"sym\">c</span>、草稿结构都是随任务分布、采样配置与批大小漂移的量。可靠的工程做法是把它们当作随部署条件变化的曲线来测量，并在每次改动采样参数、批策略或草稿结构后重新标定，而不是复用上一次的标量结论。</p>\n\n<h3 id=\"th-speculative-acceptance-sec-31\">三十一 · 误用与反例：平均接受率、判据漂移与大批量成本比</h3>\n\n<p>最常见的误用是把实测的<strong>单一平均接受率</strong>直接塞进 \\(\\alpha_j\\) 的位置，仿佛整条草稿链上每个位置的存活概率都相同。这个替换在数学上等价于假设 \\(\\alpha_j\\equiv\\bar\\alpha\\)，于是期望产出退化为 \\(1+\\bar\\alpha+\\bar\\alpha^2+\\cdots\\)，一条几何级数——它对长链极为慷慨。而真实分布是位置衰减的：代码任务里括号、关键字、缩进这些强约束位置命中率高，一旦草稿进入自由命名的标识符或长表达式，尾部 \\(\\alpha_j\\) 快速塌向零。用平均率代入，等于把尾部的低存活概率替换成了中段的高值，长草稿链的期望产出被系统性高估。工程后果不是“算得不准”，而是容量规划直接错位：按高估的 tokens/round 反推所需目标卡数，上线后发现吞吐缺口，同时草稿模型的显存已经被常驻占用，两头都收不回来。识别方法很直接——把实测的逐位置接受率画成衰减曲线，若尾部已经贴近零而部署仍配置了长 \\(\\gamma\\)，就是典型误用；正确做法是让 \\(\\gamma\\) 停在边际收益 \\(\\prod_{j\\le\\gamma}\\alpha_j\\) 低于边际成本的那一位，而不是取一个“看起来够长”的整数。</p>\n\n<p>第二类误用发生在采样判据上。加速比公式只在验证采用拒绝采样、严格保持目标分布时成立；一旦部署切到温度采样、top-p 或 top-k 截断，接受判据本身被改写，\\(\\alpha_j\\) 必须按<em>实际采样分布</em>重算。很多团队把训练阶段或贪心解码下测得的接受率直接搬到线上高温服务，既不重算 \\(\\alpha\\)，也不检查输出分布是否仍与目标模型一致。后果是双重的：公式给出的期望产出与实测加速比脱节，且截断后的接受判据不再保证无偏，输出分布悄悄偏离目标模型——这类偏差在离线评测里往往看不出来，只在长尾采样行为上暴露。识别信号是“公式预测的加速比稳定高于实测”且“温度参数在服务端被动态调整”，两者同时出现时，先怀疑判据漂移而不是怀疑硬件。</p>\n\n<p>第三类误用与批大小绑定。\\(c\\) 是草稿单步开销与目标验证单步开销之比，它<strong>随批大小漂移</strong>：小批量下目标前向是权重带宽受限、草稿相对便宜，\\(c\\) 偏小；大批量下验证被摊薄，但草稿模型自身也撞上带宽墙，其相对成本上升，\\(c\\) 变大。用小批量测得的 \\(c\\) 去估算大并发部署的加速比，会把分母 \\(1+c\\gamma\\) 算小，从而高估收益。更糟的是这个误差方向与第一类误用同向叠加，两者一起把预估推向乐观。识别方式是做 \\(c\\) 随 batch 的扫描曲线，若曲线在大 batch 段明显上翘而容量模型仍用单点值，即为失效。此时投机路径不仅不加速，还可能因草稿占用 SM 与显存、挤占验证批的空间而拖低整体吞吐——负收益的典型形态。</p>\n\n<p>给一个反例：某代码补全服务在贪心解码下测得平均接受率处于高位，据此配置了较长的 \\(\\gamma\\) 并预留了草稿模型常驻显存，容量模型按该平均率外推吞吐。上线后服务切到带温度的采样并开启 top-p，接受判据改变而 \\(\\alpha_j\\) 未重算；同时并发抬升使 \\(c\\) 上翘。两个误差同向叠加，实测加速比远低于预估，长草稿链的尾部位置几乎不被接受，草稿开销却照付。修正路径不是调参，而是三步重算：按实际采样分布逐位置重估 \\(\\alpha_j\\) 并画出衰减曲线，据边际收益截断 \\(\\gamma\\)；用目标 batch 区间的实测 \\(c\\) 替换单点值；把草稿显存计入容量方程而非视为免费。判断一个部署是否值得保留投机路径，看的是 \\(\\mathbb{E}[\\text{tokens/round}]/(1+c\\gamma)\\) 在<em>目标批大小与目标采样配置</em>下是否显著大于 1——若衰减曲线尾部已贴零、\\(c\\) 又随 batch 上翘，这个比值会趋近 1，草稿模型占住的显存就是纯代价。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>\\gamma</td><td>每轮草稿 token 数</td></tr><tr><td>\\alpha_j</td><td>第 j 个草稿位置的接受概率</td></tr><tr><td>c</td><td>草稿单步开销与目标验证单步开销之比</td></tr><tr><td>p_{\\text{draft}}</td><td>草稿分布</td></tr><tr><td>p_{\\text{target}}</td><td>目标分布</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-speculative-acceptance · 共 5 个片段</p>\n"},{"id":"th-diffusion-steps-quality","title":"扩散代码生成的步数-质量界","direction":"dir-repo-context-kv","prereq":[],"plain":"连续扩散语言模型的采样误差随步数 K 以 O(1/K) 或指数收敛，蒸馏把教师的多步轨迹压成少步学生；代码生成对语法合法性极敏感，步数不足时 token 级误差会放大为编译失败率。","definition":"连续扩散语言模型的采样误差随步数 K 以 O(1/K) 或指数收敛，蒸馏把教师的多步轨迹压成少步学生；代码生成对语法合法性极敏感，步数不足时 token 级误差会放大为编译失败率。","formula":"$$\\mathrm{TV}(p_{K},p_{\\infty})\\le C\\,\\exp\\!\\left(-\\kappa K\\right)+\\varepsilon_{\\text{distill}},\\qquad \\mathbb{E}\\!\\left[\\|x_{K}-x_{\\infty}\\|_2^2\\right]\\le\\frac{\\sigma^2}{K}\\sum_{k=1}^{K}\\eta_k^2$$","variables":[{"sym":"K","meaning":"采样步数"},{"sym":"p_K","meaning":"K 步采样分布"},{"sym":"p_{\\infty}","meaning":"极限（教师/精确）分布"},{"sym":"\\kappa","meaning":"收敛速率常数"},{"sym":"\\varepsilon_{\\text{distill}}","meaning":"蒸馏引入的分布偏差"},{"sym":"\\eta_k","meaning":"第 k 步步长"}],"derivation":"第二式 $$\\mathbb{E}[\\|x_K-x_\\infty\\|_2^2]\\le\\frac{\\sigma^2}{K}\\sum_{k=1}^{K}\\eta_k^2$$ 表明均方误差由步长平方和与噪声方差决定：步长越大误差越大，K 增大提供更多平均机会，这是 O(1/K) 界的来源。","example":"适用边界：指数收敛常数 κ 依赖得分函数光滑性，代码离散 token 嵌入空间非光滑，实际收敛常退化为多项式，公式给出的是乐观界；带 CFG/语法掩码的扩散采样会改变有效步数-质量曲线，需实测校准。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["指数收敛常数 κ 依赖得分函数的光滑性与数据分布；代码离散 token 嵌入空间非光滑，实际收敛常退化为多项式，公式给出的是乐观界","蒸馏误差 ε_distill 与步数无关，少步学生的质量天花板由教师轨迹覆盖度决定；K→1 时误差完全由蒸馏项主导，公式无法预测具体 pass@1","未刻画语法约束解码对采样轨迹的投影效应；带 CFG/语法掩码的扩散采样会改变有效步数-质量曲线，需实测校准"],"system_note":"容量决策用途：该式用于判断步数预算的边际收益——当 $$\\varepsilon_{\\text{distill}}$$ 已接近目标误差时继续加 K 无意义；蒸馏误差与步数无关，少步学生的质量天花板由教师轨迹覆盖度决定，扩容应优先投教师覆盖而非采样步数。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["直觉：连续扩散语言模型的采样误差随步数 K 以指数或 O(1/K) 收敛，蒸馏把教师多步轨迹压成少步学生；代码生成对语法合法性极敏感，步数不足时 token 级误差会放大为编译失败率。","公式 $$\\mathrm{TV}(p_K,p_\\infty)\\le C\\exp(-\\kappa K)+\\varepsilon_{\\text{distill}}$$ 中，$$\\kappa$$ 是收敛速率常数，依赖得分函数的光滑性与数据分布；$$\\varepsilon_{\\text{distill}}$$ 是与步数无关的蒸馏偏差，构成少步学生的质量天花板。","第二式 $$\\mathbb{E}[\\|x_K-x_\\infty\\|_2^2]\\le\\frac{\\sigma^2}{K}\\sum_{k=1}^{K}\\eta_k^2$$ 表明均方误差由步长平方和与噪声方差决定：步长越大误差越大，K 增大提供更多平均机会，这是 O(1/K) 界的来源。","推导关键一步是把采样误差拆成两项：随 K 指数衰减的离散化误差，加上与 K 无关的蒸馏偏差；K 到 1 时误差完全由蒸馏项主导，公式无法预测具体 pass@1。","适用边界：指数收敛常数 κ 依赖得分函数光滑性，代码离散 token 嵌入空间非光滑，实际收敛常退化为多项式，公式给出的是乐观界；带 CFG/语法掩码的扩散采样会改变有效步数-质量曲线，需实测校准。","容量决策用途：该式用于判断步数预算的边际收益——当 $$\\varepsilon_{\\text{distill}}$$ 已接近目标误差时继续加 K 无意义；蒸馏误差与步数无关，少步学生的质量天花板由教师轨迹覆盖度决定，扩容应优先投教师覆盖而非采样步数。"],"anchors":["未给出"],"pitfalls":["按指数收敛界设定步数预算，忽略代码离散嵌入空间非光滑导致的实际多项式收敛，部署后编译失败率高于预期。","只增加采样步数 K 而不改善教师轨迹覆盖度，蒸馏偏差项不降，质量天花板不变，算力被浪费。","忽略语法掩码/CFG 对采样轨迹的投影效应，用无约束公式外推带约束解码的质量-步数曲线，预测失真。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-1\">一 · 一句话直觉：误差不是被“走完”的，而是被“摊薄”的</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-2\">二 · 严格定义：两个分布、两个误差项、两个收敛口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-3\">三 · 为什么需要这个界：步数预算是容量决策，不是调参手感</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-4\">四 · 常见误解之一：把乐观界当成预测器</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-5\">五 · 常见误解之二：K=1 时公式还能预测 pass@1</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-6\">六 · 常见误解之三：把 token 级误差与编译失败率当成同一个量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-7\">七 · 步数-质量界的适用边界：公式在哪里失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-8\">八 · 第一式逐项：TV 界的三块拼图</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-9\">九 · 第二式逐项：步长方差和的 O(1/K) 来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-10\">十 · 推导关键步：误差拆成离散化项与蒸馏项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-11\">十一 · 离散化与近似落在哪里：非光滑嵌入与语法投影</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-12\">十二 · 容量决策：用界判断步数预算的边际收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-13\">十三 · 误差界的适用边界与容量决策含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-14\">十四 · 常数 κ 的依赖结构：光滑性假设在代码嵌入空间失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-15\">十五 · ε_distill 的不可约性：加 K 无法突破的天花板</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-16\">十六 · 语法约束解码的投影效应：公式未刻画的第三条路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-17\">十七 · 规模上限：K 增大时哪些量先撞墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-18\">十八 · 失效条件的清单化判定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-19\">十九 · 适用边界：κ 的光滑性假设、ε_distill 的天花板与语法投影的偏移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-20\">二十 · 把界翻译成预算：三项拆分与边际收益判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-21\">二十一 · 定批大小：用步数预算反推并发上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-22\">二十二 · 定并行度：步数预算决定切分粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-23\">二十三 · 定 KV 预算：扩散采样的中间态而非自回归缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-24\">二十四 · 定 SLO 与算例：从目标编译通过率反推资源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-25\">二十五 · 把步数-质量界折算成容量参数：可用的地方与会翻车的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-26\">二十六 · 误用一：把乐观界当成部署预算的硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-27\">二十七 · 误用二：用加 K 替代教师轨迹覆盖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-28\">二十八 · 误用三：忽略语法掩码的投影效应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-29\">二十九 · 一个反例：从公式反解 K 的部署事故链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-30\">三十 · 识别清单与工程落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-diffusion-steps-quality-sec-31\">三十一 · 误用与反例：把乐观界当预算、把步数当万能旋钮</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:556px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 556.2 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：连续扩散语言模型的采样误差随步数 K 以 O(1/K) 或指数收敛…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$\\mathrm{TV}(p_{K},p_{\\infty})\\l…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：指数收敛常数 κ 依赖得分函数的光滑性与数据分布；代码离散 tok…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-diffusion-steps-quality-sec-1\">一 · 一句话直觉：误差不是被“走完”的，而是被“摊薄”的</h3>\n<p>连续扩散语言模型的采样过程，本质上是沿一条由得分函数给出的漂移场把噪声输运回数据流形。步数 K 的作用不是“把答案一步步算出来”，而是把这段连续时间积分切成 K 段离散更新：每段都引入一份与步长成正比的离散化残差，K 越大，单段残差越小，且残差在轨迹上被更多次平均掉。于是采样分布与极限分布之间的总变差距离随 K 收缩——在得分函数足够光滑时呈指数收缩，在最粗糙的平方误差意义上呈 O(1/K) 收缩。蒸馏则换了一条路径：它不去缩小离散化残差，而是直接把教师的多步轨迹压成学生的少步映射，把“多走几步”换成“一次跳到位”。代价是引入一个与 K 无关的偏差项，它构成少步学生的质量天花板。对代码生成而言，这个天花板的含义格外尖锐：token 级分布的微小偏移在自由文本里只是措辞差异，在代码里却可能是一个括号错位、一个未定义符号，直接把样本从“可编译”推到“编译失败”。</p>\n<p>所以本系列要讨论的“步数-质量界”，不是一条“步数越多越好”的单调曲线，而是两条互相牵制的项之和：一条随 K 衰减，一条不随 K 衰减。工程判断的全部难点，在于知道自己当前卡在哪一条上。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-2\">二 · 严格定义：两个分布、两个误差项、两个收敛口径</h3>\n<p>设 p_K 为 K 步离散采样所诱导的分布，p_∞ 为极限分布（在无蒸馏时即精确教师分布，在有蒸馏时即学生所能逼近的教师轨迹覆盖下的最优分布）。步数-质量界由两个不等关系刻画：</p>\n<div class=\"formula\">$$\\mathrm{TV}(p_{K},p_{\\infty})\\le C\\,\\exp\\!\\left(-\\kappa K\\right)+\\varepsilon_{\\text{distill}},\\qquad \\mathbb{E}\\!\\left[\\|x_{K}-x_{\\infty}\\|_2^2\\right]\\le\\frac{\\sigma^2}{K}\\sum_{k=1}^{K}\\eta_k^2$$</div>\n<p>第一式是分布层面的界：总变差距离被拆成“离散化误差”与“蒸馏偏差”两项之和。C 是常数，κ 是收敛速率常数，ε_distill 是与 K 无关的蒸馏引入的分布偏差。第二式是样本层面的界：K 步轨迹终点与极限终点之间的均方误差，由噪声方差 σ² 与各步步长 η_k 的平方和共同决定。注意第二式里 K 出现在分母、步长平方和出现在分子——这正是 O(1/K) 界的来源：步长越大单步误差越大，而 K 增大提供了更多次平均的机会。</p>\n<p>两个口径不可互换。TV 界关心的是“采样分布整体离目标多远”，适合回答“这批样本里有多大比例落在合法代码流形之外”；均方误差界关心的是“单条轨迹终点偏离多远”，适合回答“给定一条轨迹，它的偏差是否已被平均掉”。代码生成关心的是前者：编译失败率是一个分布层面的比例量，不是单条轨迹的范数量。工程上若拿第二式的均方误差去外推 pass@1，会系统性乐观，因为均方误差对“少数极端偏离样本”不敏感，而恰恰是这些样本构成编译失败的主体。</p>\n<p>变量语义需要钉死：K 是采样步数；p_K 是 K 步采样分布；p_∞ 是极限（教师/精确）分布；κ 是收敛速率常数；ε_distill 是蒸馏引入的分布偏差；η_k 是第 k 步步长。这六个量里，只有 K 和 η_k 是部署时可调的，κ 由模型与数据决定，ε_distill 由蒸馏方案与教师轨迹覆盖度决定，C 与 σ² 是给定模型下的常数。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-3\">三 · 为什么需要这个界：步数预算是容量决策，不是调参手感</h3>\n<p>没有这个界，步数选择只能靠扫参：从 K=4 扫到 K=64，看 pass@1 曲线在哪里拐平。这在单卡调试时可行，在 NVL72 级别的部署里不可行——步数直接乘在解码侧的计算量上，而解码侧在 Blackwell 上受的是带宽与 TMEM 容量约束，不是纯算力约束。步数翻倍意味着每个请求要多次往返权重与激活、多次占用 SM 与 TMEM 的驻留窗口，连续批处理下的批内步数对齐会进一步放大尾延迟。步数预算因此是一个容量决策：它决定了单卡能撑多少并发、SLO 的 p99 落在哪里、以及为达到目标编译失败率需要多少张卡。</p>\n<p>这个界给出的正是决策所需的结构：边际收益。当 ε_distill 已接近目标误差时，继续加 K 的收益被指数项迅速压到零——此时扩容应投向教师轨迹覆盖度而非采样步数。反过来，当 ε_distill 远小于当前误差、误差主要由离散化项主导时，加 K 是有效手段，且第一式告诉你收益随 K 指数衰减，可以据此估算“再加多少步能换来多少失败率下降”。</p>\n<p>具体例子：一个代码补全服务的目标是把编译失败率压到某个阈值以下。若实测发现把 K 从 8 加到 32 失败率几乎不动，而换一个覆盖更广的教师重做蒸馏后失败率明显下降，那么按第一式判断，当前系统卡在 ε_distill 项上，加步数是浪费算力；反之若失败率随 K 单调下降且尚未拐平，则卡在离散化项上，此时应优先评估步数带来的显存与带宽代价是否在 SLO 预算内。这个判断不需要知道 κ 的具体数值，只需要看“加 K 有没有用”和“换教师有没有用”这两个方向的相对斜率。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-4\">四 · 常见误解之一：把乐观界当成预测器</h3>\n<p>第一式的指数项是一个上界，不是一条预测曲线。κ 依赖得分函数的光滑性与数据分布；代码的离散 token 嵌入空间是非光滑的——词表嵌入是离散点集，语法结构在嵌入空间里表现为分段、带尖角的流形，得分函数在这些边界附近梯度行为剧烈。实际收敛常退化为多项式而非指数，公式给出的是乐观界。按指数收敛界设定步数预算，会低估所需步数，部署后编译失败率高于预期，这是最典型的失效模式。</p>\n<p>工程含义是：不要用第一式的指数形状去拟合实测曲线然后外推。正确用法是把它当“形状约束”——它告诉你误差一定随 K 单调不增、且一定存在一个不随 K 下降的下限 ε_distill；它不告诉你下降有多快。实测校准必须自己做，尤其是在带语法掩码或 CFG 约束解码时：约束会把采样轨迹投影到合法子空间上，这个投影改变了有效步数-质量曲线，无约束公式无法外推带约束解码的表现。投影效应在低 K 时尤其显著——步数少时轨迹偏离大，投影会把大量样本硬拉回合法域，此时失败率的下降可能比无约束公式预测的更快或更慢，方向取决于投影是“修正”还是“截断”。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-5\">五 · 常见误解之二：K=1 时公式还能预测 pass@1</h3>\n<p>K 到 1 时，指数项 C·exp(−κ) 不再是主导，误差完全由 ε_distill 项主导。此时第一式退化为 TV ≤ C·exp(−κ) + ε_distill，其中第一项是常数、第二项是常数，整个界变成一个与 K 无关的常数上界——它对“具体 pass@1 是多少”没有任何预测力。这是公式的结构性盲区，不是精度问题。</p>\n<p>原因在于 ε_distill 的语义：它是蒸馏引入的分布偏差，其大小由教师轨迹覆盖度决定，而不是由学生步数决定。少步学生的质量天花板由教师轨迹覆盖度决定——教师没见过、没覆盖到的代码形态，学生无论怎么蒸馏都学不到。K=1 时学生做的是一个单步映射，这个映射的精度上限就是教师轨迹在数据流形上的覆盖密度所允许的精度。公式能告诉你“误差不会低于 ε_distill”，但不能告诉你 ε_distill 具体是多少，因为那取决于教师、蒸馏目标函数与数据分布三者的交互，不是解析式能给出的。</p>\n<p>工程判断：当 K 已经压到很小（少步蒸馏的典型目标区间），继续优化 pass@1 的杠杆不在步数，而在教师轨迹覆盖度与蒸馏目标的设计。此时评估扩容方向，应优先投教师覆盖——更多、更广的教师采样轨迹，而不是把 K 从 2 调到 1。后者只会把离散化项压到可忽略，而 ε_distill 纹丝不动，算力被浪费。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-6\">六 · 常见误解之三：把 token 级误差与编译失败率当成同一个量</h3>\n<p>第二式的均方误差是 token 嵌入空间里的连续量，编译失败率是离散的、非线性的比例量。两者之间没有单调的一一映射：一个均方误差很小的样本可能因为单个关键 token（如类型标注、缩进层级、括号配对）偏移而编译失败；一个均方误差较大的样本可能在语法上仍然合法。代码生成对语法合法性极敏感，步数不足时 token 级误差会放大为编译失败率——放大倍数由代码结构的刚性决定，不是常数。</p>\n<p>这意味着用第二式做步数预算时，必须把“误差下降”翻译成“失败率下降”的转换系数实测出来，而不能假设线性。具体做法：在同一批 prompt 上同时记录均方误差与编译失败率，扫 K，得到两条曲线，观察失败率曲线相对误差曲线的滞后或超前。若失败率在误差已明显下降后仍不降，说明误差集中在语法关键 token 上，此时应检查语法掩码/CFG 的投影是否在低 K 段失效，而不是继续加 K。这个转换系数是部署校准的核心产物，也是本系列后续部分要反复引用的实测锚点。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-7\">七 · 步数-质量界的适用边界：公式在哪里失效</h3>\n<p>前文给出的一句话直觉与严格定义，其工程价值不在于复述“误差随步数收敛”，而在于划清这套界能回答什么、不能回答什么。两个不等式各自刻画一种误差来源：<span class=\"formula\">$$\\mathrm{TV}(p_{K},p_{\\infty})\\le C\\,\\exp\\!\\left(-\\kappa K\\right)+\\varepsilon_{\\text{distill}}$$</span> 把总偏差拆成随 K 指数衰减的离散化项与与 K 无关的蒸馏项；<span class=\"formula\">$$\\mathbb{E}\\!\\left[\\|x_{K}-x_{\\infty}\\|_2^2\\right]\\le\\frac{\\sigma^2}{K}\\sum_{k=1}^{K}\\eta_k^2$$</span> 则说明均方误差由步长平方和与噪声方差共同决定，K 增大提供更多平均机会，这正是 O(1/K) 界的来源。两条式子共享一个前提：得分函数足够光滑，采样轨迹可被视为连续空间中的近似积分。代码生成恰恰破坏这个前提。</p>\n<p>失效条件集中在三处。其一，收敛速率常数 κ 依赖得分函数的光滑性与数据分布；代码 token 的离散嵌入空间非光滑，实际收敛常退化为多项式，指数界只是乐观上界。按指数界设定步数预算、忽略多项式退化，是典型的部署事故：离线校准显示质量达标，上线后编译失败率高于预期。其二，ε_distill 与步数无关，少步学生的质量天花板由教师轨迹覆盖度决定；K 压到 1 时误差完全由蒸馏项主导，公式无法预测具体 pass@1——此时继续加 K 毫无收益，扩容应优先投教师覆盖而非采样步数。其三，带 CFG 或语法掩码的扩散采样会对轨迹施加投影，改变有效步数-质量曲线，用无约束公式外推带约束解码必然失真，只能实测校准。</p>\n<table class=\"mini\"><thead><tr><th>误差来源</th><th>随 K 的行为</th><th>系统代价落点</th></tr></thead><tbody><tr><td>离散化误差</td><td>指数衰减（乐观界）/ 实际多项式</td><td>延迟：每步一次前向，K 线性推高单请求时延</td></tr><tr><td>蒸馏偏差 ε_distill</td><td>与 K 无关，构成质量天花板</td><td>显存与算力：教师轨迹覆盖度决定学生上限</td></tr><tr><td>语法掩码/CFG 投影</td><td>改变曲线形状，需实测</td><td>吞吐：掩码校验与重采样带来额外开销</td></tr></tbody></table>\n<p>工程判断因此要落在边际收益上：当 ε_distill 已接近目标误差，加 K 只增加延迟与功耗而不降编译失败率；当语法约束主导失败模式，先修掩码与解码投影，再谈步数预算。这套界是容量决策的筛选器，不是 pass@1 的预测器。</p>\n<h3 id=\"th-diffusion-steps-quality-sec-8\">八 · 第一式逐项：TV 界的三块拼图</h3>\n<p>$$\\mathrm{TV}(p_{K},p_{\\infty})\\le C\\,\\exp\\!\\left(-\\kappa K\\right)+\\varepsilon_{\\text{distill}}$$ 这个不等式右边只有两项，但每一项背后都藏着不同的工程含义，必须逐项拆开看。左边是 K 步采样分布与极限分布之间的全变差距离——注意它度量的是<em>分布</em>之间的距离，不是某一条采样轨迹的 token 级差异。这意味着界约束的是“从 p_K 里抽一条样本，它看起来像 p_∞ 样本的概率上界”，而不是“这条轨迹的每个 token 都对”。对代码生成而言，这个区别是致命的：一条轨迹只要有一个 token 破坏了语法，整段代码就编译失败，而 TV 界对此完全无感。</p>\n<p>常数 C 是前因子，它吸收了初始分布与极限分布之间的全部“距离预算”。C 大意味着即便 K 很大，界也松——工程上 C 由数据分布的支撑集宽度与得分函数的 Lipschitz 性质决定，代码这种离散 token 序列的嵌入空间支撑集极宽，C 天然不小。κ 是收敛速率常数，指数项的衰减速度完全由它控制；κ 依赖得分函数的光滑性，光滑性越好、κ 越大、指数项掉得越快。第三块是 ε_distill，它与 K 完全无关，是蒸馏把教师多步轨迹压成少步学生时引入的分布偏差，构成少步学生的质量天花板。</p>\n<p>代价视角：这个界告诉你步数预算的边际收益在哪里断崖。设目标误差为 δ，则需 C·exp(−κK) ≤ δ − ε_distill，即 K ≥ (1/κ)·ln(C/(δ−ε_distill))。当 ε_distill 逼近 δ 时，对数内项爆炸，K 需求趋于无穷——这正是“继续加 K 无意义”的数学表达。工程判断：先测 ε_distill 的量级，再决定是否值得扩 K；若 ε_distill 已占误差预算的大头，扩容应优先投教师轨迹覆盖度而非采样步数。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-9\">九 · 第二式逐项：步长方差和的 O(1/K) 来源</h3>\n<p>$$\\mathbb{E}\\!\\left[\\|x_{K}-x_{\\infty}\\|_2^2\\right]\\le\\frac{\\sigma^2}{K}\\sum_{k=1}^{K}\\eta_k^2$$ 这一式度量的是采样轨迹终点与极限轨迹终点的均方欧氏距离，是轨迹级的、连续空间里的误差，与第一式的分布级 TV 距离形成互补。σ² 是每步注入的噪声方差（采样器固有的随机性），η_k 是第 k 步步长。右边是“噪声方差 × 步长平方的算术平均”。</p>\n<p>为什么是 O(1/K)？关键在于求和项被 K 除。若步长取均匀 η_k = η，则右边化为 σ²η²，与 K 无关——这看似矛盾，实则因为均匀步长下总步长固定，K 增大只是把同样的总位移切成更多小段，每段噪声贡献按 η² 缩小，但段数按 K 增多，两者恰好抵消。真正产生 O(1/K) 的是<em>步长随 K 收缩</em>的情形：当 η_k ~ 1/K 时，η_k² ~ 1/K²，求和得 K·(1/K²) = 1/K，再乘 σ²/K 得 σ²/K²——比 O(1/K) 还快。而若步长不随 K 收缩（例如固定 η），界退化为常数，K 再多也无用。这就是“步长调度”在扩散采样里的核心地位：不是步数本身，而是步长如何随步数缩放，决定了误差的收敛阶。</p>\n<p>代价视角：均方误差直接映射到显存带宽与延迟预算。每步采样需一次完整的前向（得分函数评估），K 步即 K 次前向；步长平方和越大，单步位移越大，采样器越“粗”，但轨迹越偏离极限。工程上要在“K 次前向的延迟”与“步长调度带来的误差”之间做权衡：增大 K 换取更小步长，代价是线性增长的延迟与带宽占用；而步长调度不当会让 K 的收益被抵消。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-10\">十 · 推导关键步：误差拆成离散化项与蒸馏项</h3>\n<p>推导的核心动作是把总误差拆成两个来源正交的项。第一步，把 K 步采样过程视为对连续时间扩散 ODE/SDE 的离散近似，离散化误差随步长收缩而衰减——在得分函数光滑、步长按 1/K 缩放的理想条件下，该误差以指数或 O(1/K) 速率随 K 下降，这就是 C·exp(−κK) 项的来源。第二步，把“学生分布与教师分布之间的固有偏差”单独拎出：蒸馏把教师的多步轨迹压成少步学生，学生的参数化能力与教师轨迹覆盖度之间的差距不随学生采样步数 K 变化，这就是 ε_distill 项。</p>\n<p>两项相加的合法性依赖于三角不等式：TV(p_K, p_∞) ≤ TV(p_K, p_teacher) + TV(p_teacher, p_∞)。前一项是离散化误差（学生 K 步 vs 教师极限），后一项是蒸馏偏差（教师 vs 精确）。这个拆分的关键假设是：离散化误差与蒸馏偏差可以独立控制——加 K 只压前一项，不改后一项。伪代码思路：给定目标误差 δ，先固定学生参数（ε_distill 锁定），再解 K* = argmin_K {C·exp(−κK) + ε_distill ≤ δ}；若 K* 超出延迟预算，则必须回头改学生（提升教师轨迹覆盖度）而非硬堆 K。</p>\n<p>代价视角：这个拆分的工程价值在于把“加步数”和“改蒸馏”两种扩容手段解耦。加 K 的代价是线性延迟与带宽；改蒸馏的代价是教师轨迹生成与训练算力，但换来的 ε_distill 下降对所有 K 都生效。当 ε_distill 主导误差时，后者的性价比远高于前者。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-11\">十一 · 离散化与近似落在哪里：非光滑嵌入与语法投影</h3>\n<p>公式的乐观性来自两处近似。第一处是 κ 的假设：指数收敛界要求得分函数在数据分布支撑集上光滑（Lipschitz 连续），而代码的离散 token 嵌入空间本质非光滑——token 是离散的，嵌入向量之间的跳变使得分函数在 token 边界处不可微，实际收敛常退化为多项式而非指数。公式给出的 C·exp(−κK) 是乐观界，真实曲线在 K 较小时可能远高于界预测。第二处是语法约束解码的投影效应：带 CFG 或语法掩码的扩散采样，每一步都把采样轨迹投影回合法 token 集合，这个投影改变了有效步数-质量曲线——投影算子不是线性的，公式里的 η_k 和 σ² 都不再直接适用，必须实测校准。</p>\n<p>具体例子：设一个代码扩散模型在无约束采样下 K=8 时 TV 界预测误差已降到 ε_distill 量级，但加上语法掩码后，投影在每步丢弃非法 token 的同时也扭曲了步长分布，实际编译失败率在 K=8 时仍显著高于界预测。这不是公式错了，而是公式的适用域被投影算子打破。工程判断：任何带语法约束的部署，都不能用无约束公式外推质量-步数曲线，必须在目标约束下重测 K 与编译失败率的关系。</p>\n<p>代价视角：投影算子每步增加一次掩码计算与重归一化，带来额外延迟；而它改变收敛阶的副作用意味着你可能需要比公式预测更多的 K 才能达到同等质量，延迟预算被双重侵蚀。这是代码生成特有的隐性成本。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-12\">十二 · 容量决策：用界判断步数预算的边际收益</h3>\n<p>把两式合起来看，容量规划的动作是：先估 ε_distill 与目标误差 δ 的比值，再决定 K 的投入。若 ε_distill/δ 已接近 1，第一式的指数项无论怎么压都无法把总误差拉低到 δ 以下，此时加 K 的边际收益趋零，算力应转向提升教师轨迹覆盖度。若 ε_distill/δ 较小，则 K 的边际收益由 κ 决定：κ 大则少量 K 即可逼近天花板，κ 小则需大量 K，此时要评估延迟预算是否允许。</p>\n<p>第二式提供另一个维度的判断：均方误差的 O(1/K) 界依赖步长随 K 收缩。若采样器的步长调度是固定的（不随 K 缩放），第二式的界退化为常数，加 K 不改善轨迹级误差——这是许多工程实现里被忽略的细节。具体例子：某部署把 K 从 16 加到 64，但步长调度表未同步更新，结果延迟翻了四倍而编译失败率几乎不变；诊断发现步长未随 K 收缩，第二式的求和项没有获得 1/K 的收益。修复方式是让步长调度与 K 联动，而非单纯堆步数。</p>\n<p>最终落在具体机制上：步数-质量界的工程用法不是“算出一个 K 然后照做”，而是把 ε_distill 当作不可逾越的天花板、把 κ 当作逼近天花板的速率、把步长调度当作 O(1/K) 收益的开关，三者联合决定扩容投向。代码场景下还要叠加语法投影的实测校准，否则公式的乐观界会把部署引向编译失败率高于预期的陷阱。</p>\n\n\n<h3 id=\"th-diffusion-steps-quality-sec-13\">十三 · 误差界的适用边界与容量决策含义</h3>\n<p>把 <span class=\"sym\">TV</span> 界拆成 <span class=\"sym\">C·exp(−κK)</span> 与 <span class=\"sym\">ε_distill</span> 两项，工程上真正要问的是：这两项各自在什么条件下才成立、哪一项在给定预算下先饱和。第一项的前提是得分函数在数据流形上足够光滑，使得反向 SDE 的离散化误差能被 Grönwall 型论证压住；代码 token 的嵌入是离散索引查表，嵌入表在词表维度上分段常值，得分函数在 token 边界处出现跳变，κ 的有效值远低于连续图像域的经验值，实测曲线常呈 <span class=\"sym\">K^(−α)</span> 的多项式尾部而非指数尾部。这意味着按指数界反推步数预算会系统性低估所需 K：若团队按 <span class=\"sym\">exp(−κK)</span> 拟合外推，把 K 从 16 降到 8 以为误差只涨一个固定倍数，实际在非光滑嵌入上误差涨幅会超出该倍数，部署后表现为编译失败率高于离线小样本评测的预期。</p>\n<p>第二式给出的是另一条腿的代价结构：<span class=\"sym\">E[‖x_K−x_∞‖²] ≤ (σ²/K)·Ση_k²</span>。它的推导关键是把每步注入的噪声方差 σ²η_k² 视为独立增量，K 步累积后由步数做平均，于是界随 K 以 O(1/K) 收缩。这条界对步长调度极敏感——末段步长不衰减到 0 时 Ση_k² 不收敛，界本身失效；实践中把 η_k 做成余弦或线性退火，正是为了让求和项有界。系统代价上，这条界把“加步数”换算成“加 NFE（每步一次网络前向）”：K 翻倍即延迟与算力翻倍，而误差只按 1/K 收缩，边际收益递减极快。对延迟敏感的在线代码补全，K 从 32 加到 64 带来的 TTFT 增量往往吃掉整条 SLO 余量，而 TV 界的改善在 ε_distill 主导时几乎不可见。</p>\n<p>失效条件集中在三处。其一，ε_distill 与 K 无关，它由教师多步轨迹的覆盖度决定：学生在训练分布外的 prompt 上（长上下文、罕见 API 组合、领域特定 DSL）没有对应轨迹，偏差项不随采样步数下降，K→1 时误差完全由该项主导，公式对具体 pass@1 无预测力。其二，语法掩码与 CFG 约束解码在每步对采样分布做投影，投影会改变有效轨迹的测度，等价于在公式外乘一个与 K 相关的修正因子；用无约束标定的 κ 去外推带约束解码的曲线，预测会失真，必须按约束强度分层实测校准。其三，两式都假设误差可在连续空间中度量，而代码的正确性判据是离散的编译/测试通过，token 级 L2 误差与编译失败率之间不是单调映射——小误差落在标识符中间可能无害，落在括号配对处则直接致命。</p>\n<table class=\"mini\"><thead><tr><th>情形</th><th>主导项</th><th>加 K 的收益</th><th>系统代价</th></tr></thead><tbody><tr><td>教师覆盖充分、无约束</td><td>离散化项</td><td>按 1/K 或指数收缩，有效</td><td>NFE 线性增长，延迟上升</td></tr><tr><td>分布外 prompt</td><td>ε_distill</td><td>趋近于零，算力浪费</td><td>仅增延迟不增质量</td></tr><tr><td>强语法约束解码</td><td>投影修正项</td><td>曲线需实测，外推不可靠</td><td>掩码计算额外开销</td></tr></tbody></table>\n<p>由此得出容量判断：当离线标定显示 ε_distill 已接近目标误差带，继续加 K 只买到延迟；此时扩容应投向教师轨迹覆盖度（更长教师步数、更广 prompt 采样、领域数据补轨迹），而非采样步数。反过来，若 ε_distill 远低于目标而离散化项仍主导，则加 K 或改进步长调度是正确杠杆。工程上应把两式当作预算分配的不等式约束而非预测器：先测出 ε_distill 的平台值，再决定 K 的上界，最后用带约束解码的实测曲线替换理论 κ。</p>\n<h3 id=\"th-diffusion-steps-quality-sec-14\">十四 · 常数 κ 的依赖结构：光滑性假设在代码嵌入空间失效</h3>\n<p>指数收敛项 <span class=\"inline-math\">C exp(−κK)</span> 的全部预测力都压在 κ 上。推导中 κ 来自得分函数 ∇log p_t(x) 关于 x 的 Lipschitz 常数与数据分布的对数凹性：得分场越平滑、分布越接近单峰，κ 越大，误差衰减越快。这条假设在连续图像嵌入上大致成立，因为像素空间本身连续且得分网络在局部近似线性。代码不同：token 嵌入是离散词表到连续空间的查表映射，嵌入向量之间的欧氏距离与语法距离不对应，得分场在嵌入点附近存在由词表结构造成的折痕。折痕处 Lipschitz 常数发散，κ 的有效值随采样轨迹经过的 token 位置剧烈波动。工程后果是：用图像任务标定的 κ 去外推代码任务的步数预算，会系统性低估所需 K。可操作的判断是——在目标代码分布上取一小批 prompt，测 K 与编译通过率的关系曲线，若曲线在半对数坐标下不是直线，说明指数界已失效，应按多项式拟合重新定预算。</p>\n<p>更精确的表述是：κ 不是模型常数，而是轨迹依赖量。同一条采样轨迹在不同 token 位置的局部收敛速率不同，标识符、运算符附近的嵌入折痕密集，收敛慢；关键字与结构骨架附近收敛快。公式给出的是整条轨迹上的最坏情形上界，实际平均收敛速率由轨迹经过的折痕密度决定。这解释了为什么同一模型在不同代码任务上步数-质量曲线斜率不同：任务决定了轨迹落在嵌入空间的哪些区域。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-15\">十五 · ε_distill 的不可约性：加 K 无法突破的天花板</h3>\n<p>第二项 <span class=\"inline-math\">ε_distill</span> 与 K 完全解耦，这是公式最容易被误用的地方。蒸馏把教师的多步轨迹压成少步学生，学生的条件分布被约束在教师轨迹覆盖的支撑集内；教师没走过的路径，学生无论采多少步都到不了。因此总误差存在下界 <span class=\"inline-math\">lim_{K→∞} TV(p_K, p_∞) ≥ ε_distill</span>，加步数只能把第一项压到零，压不动第二项。容量决策的直接含义：当第一项已降到 ε_distill 量级以下，继续加 K 的边际收益为零，算力应转向扩大教师轨迹覆盖度——更多样的教师采样、更长的教师步数、更宽的数据分布，而不是学生侧的采样步数。</p>\n<div class=\"formula\">$$\\mathrm{TV}(p_{K},p_{\\infty})\\le \\underbrace{C\\,e^{-\\kappa K}}_{\\text{可压至零}}+\\underbrace{\\varepsilon_{\\text{distill}}}_{\\text{与 }K\\text{ 无关}}$$</div>\n<p>代价侧要看清这笔账：加 K 的代价是线性增长的采样延迟（每步一次完整去噪前向），而 ε_distill 的代价是一次性的教师轨迹构建成本。在 SLO 约束下，若解码延迟已逼近上限而编译失败率仍高于目标，说明瓶颈在 ε_distill 而非 K，此时加 K 既拖延迟又不降失败率，是纯亏损操作。K=1 的极端情形最能暴露这一点：此时第一项为 C·e^{−κ}，误差几乎完全由 ε_distill 主导，公式退化为一个常数界，对 pass@1 没有任何分辨力——它只能告诉你“不会比这个更差”，不能告诉你具体多好。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-16\">十六 · 语法约束解码的投影效应：公式未刻画的第三条路径</h3>\n<p>公式描述的是无约束扩散采样。生产环境的代码生成几乎都带语法掩码或 CFG 约束：每步采样后把不符合当前语法状态的 token 概率置零再重归一化。这是一个投影算子 P，作用在每步的采样分布上，把轨迹强行拉回合法子空间。投影改变了两件事：其一，有效步长 η_k 被重归一化后的分布改变，第二式中的步长平方和不再等于名义步长；其二，投影把轨迹推向语法边界，而边界处得分场不连续，κ 的局部值进一步下降。净效果是有效步数-质量曲线相对无约束公式整体右移且斜率变缓，用无约束公式外推带约束解码的步数预算会低估 K。</p>\n<p>工程上的处理不是修正公式，而是把公式当作上界筛选器：先用公式算出乐观步数下界，再在带约束的真实管线上实测校准系数。具体做法是在固定 prompt 集上扫 K，记录编译通过率与 TV 代理指标（如与教师轨迹的 token 级一致率），拟合出带约束的有效 κ′ 与 ε′_distill，替换公式中的名义值。这一步不能省，因为投影效应对不同语法结构（表达式嵌套深度、类型标注密度）的敏感度不同，单一校准系数不足以覆盖全部任务形态。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-17\">十七 · 规模上限：K 增大时哪些量先撞墙</h3>\n<p>公式本身不含规模变量，但三项资源会随 K 线性或超线性增长，构成实际规模上限。第一是延迟：K 步串行去噪，每步一次前向，延迟随 K 线性增长，在分离式部署中预填与解码的配比也随之改变。第二是显存带宽：每步都要读写完整的隐状态与 KV 缓存，K 增大使带宽占用按 K 倍放大，在 NVL72 这类高带宽域内尚可承受，跨节点则成为瓶颈。第三是批调度：长 K 请求占用解码槽位时间成比例延长，连续批处理下的有效并发容量下降，吞吐随 K 上升而下降。三者中先撞墙的通常是延迟，因为代码生成的 SLO 对首 token 后的完成时间敏感。</p>\n<p>规模上限的工程判断可以写成一条不等式：若目标编译失败率对应的所需 K 使得单请求解码延迟超过 SLO 上限，则公式给出的步数预算在规模上不可行，必须转向蒸馏压缩 K 或改用并行采样（一次生成多条短轨迹再筛选）。后者的代价是显存与算力换延迟，在批调度层面表现为槽位占用翻倍但单槽时间缩短，是否划算取决于当前是延迟受限还是吞吐受限。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-18\">十八 · 失效条件的清单化判定</h3>\n<p>把上述分析收敛成可执行的判定流程，避免部署后才发现公式不成立。判定按顺序进行，任一项不通过即说明公式在该场景下只配当乐观上界使用。</p>\n<ul>\n<li>光滑性检验：在目标分布上测 K-误差曲线的半对数斜率，非线性则指数界失效，改用多项式拟合定预算。</li>\n<li>天花板检验：固定教师、扫 K 至误差不再下降，该平台即 ε_distill 的实测值；若平台高于目标误差，加 K 无意义。</li>\n<li>约束检验：对比带语法掩码与无约束两条曲线的斜率差，斜率差显著则需用带约束校准的有效 κ′。</li>\n<li>规模检验：所需 K 对应的解码延迟是否越过 SLO；越过则公式预算不可行，转蒸馏或并行采样。</li>\n</ul>\n<p>这四项检验的共同代价是校准用的实测算力，但相比按乐观界部署后编译失败率超标带来的返工，这笔校准成本是必要开销。特别要注意第一项与第三项的耦合：非光滑性与投影效应叠加时，误差曲线的形状可能既非指数也非干净的多项式，此时任何解析外推都不可靠，只能靠实测曲线插值。公式在此的角色从预测工具退化为筛选工具——它告诉你哪些 K 区间值得实测，而不是直接给出答案。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-19\">十九 · 适用边界：κ 的光滑性假设、ε_distill 的天花板与语法投影的偏移</h3>\n\n<p>两式联立给出的其实是一张“误差预算表”，而不是一条可外推的定律。第一项 C·exp(−κK) 的合法性完全押在 κ 上：κ 是得分函数 ∇log p_t 在数据流形上的 Lipschitz 型常数，要求得分场随 t 平滑演化、且概率路径在嵌入空间里近似连续。代码 token 的嵌入是离散索引查表得到的向量，词表边界处得分场出现跳变，路径在 token 切换点附近不可微，κ 的有效值随上下文长度和词表使用分布漂移。工程后果是：按指数界排步数预算，会在长上下文、稀有 API 名、深嵌套语法结构上系统性低估所需 K——这些恰是编译失败率的高发区。判断方法不是信任 κ，而是在目标分布上实测 TV 或 pass@k 随 K 的衰减斜率：若 log 误差对 K 呈线性，指数界可用；若呈 log K 型，则已退化为多项式，必须把步数预算按多项式重新标定。</p>\n\n<p>第二式给出的是另一条腿的代价结构：E[‖x_K−x_∞‖²] ≤ (σ²/K)Ση_k²。它说明均方误差由步长方差与噪声方差共同决定，K 的作用只是提供更多平均机会，因此 O(1/K) 的收益是“平均”换来的，不是“精度”换来的。这条界对步长调度极敏感：η_k 若在末段不衰减，Ση_k² 随 K 线性增长，右端不降反升，加步数反而放大末段抖动。推理系统的代价体现在这里——每步一次完整的去噪前向，在 Blackwell 上是一次 tcgen05 MMA 加一次 TMEM 读写往返，K 翻倍即延迟翻倍、KV/激活驻留翻倍；当 η 调度未收敛时，这笔延迟买不到质量。可行做法是把 η_k 的衰减曲线与 K 绑定做联合标定，而不是先定 K 再调 η。</p>\n\n<p>真正决定少步学生上限的是 ε_distill，它与 K 正交。蒸馏把教师多步轨迹压成少步学生，学生能复现的分布受教师轨迹覆盖度约束：教师没走过的语法分支、没采到的长尾 token 组合，学生在少步下无从恢复。于是 K→1 时误差完全由 ε_distill 主导，公式退化为一个常数，无法预测具体 pass@1——这不是界的松弛，而是界的失效。容量决策上这意味着扩容方向的选择：若 ε_distill 已接近目标误差，继续加 K 的边际收益为零，算力应投向扩大教师轨迹覆盖（更多采样温度、更多语法变体、更长上下文），而不是采样步数。反过来说，若实测显示加 K 仍显著改善 pass@1，说明当前瓶颈在离散化项而非蒸馏项，此时压缩学生步数才是浪费。</p>\n\n<p>最后一类失效来自约束解码的投影效应。带 CFG 或语法掩码的采样在每步对 logits 做投影，等价于把采样轨迹限制在一个随 K 变化的可行域上，有效步数-质量曲线被整体改写：掩码越强，单步信息量越大，曲线在低 K 段抬升，但高 K 段的边际收益被压缩，且投影本身引入额外偏差，不与无约束公式同构。用无约束界外推带约束解码的质量是预测失真的典型来源。工程判断应落在实测校准上：对每个语法族（如 JSON、SQL、特定 DSL）单独拟合 K→编译失败率曲线，把 CFG 强度作为协变量，而不是把 κ 当作跨任务常数复用。</p>\n\n<table class=\"mini\">\n<thead><tr><th>失效来源</th><th>被破坏的假设</th><th>系统代价表现</th><th>校准手段</th></tr></thead>\n<tbody>\n<tr><td>离散嵌入非光滑</td><td>κ 为常数、指数收敛</td><td>长上下文/稀有 token 处延迟预算不足，编译失败率超预期</td><td>实测 log 误差-K 斜率，判别指数/多项式</td></tr>\n<tr><td>η_k 未衰减</td><td>Ση_k² 随 K 受控</td><td>K 翻倍延迟翻倍而误差不降，TMEM 往返浪费</td><td>η 曲线与 K 联合标定</td></tr>\n<tr><td>ε_distill 主导</td><td>K 可无限改善质量</td><td>加 K 的算力零收益，质量天花板不动</td><td>扩容转向教师轨迹覆盖度</td></tr>\n<tr><td>CFG/语法掩码</td><td>无约束采样轨迹</td><td>低 K 段虚高、高 K 段收益压缩，预测失真</td><td>按语法族分别拟合曲线</td></tr>\n</tbody>\n</table>\n<h3 id=\"th-diffusion-steps-quality-sec-20\">二十 · 把界翻译成预算：三项拆分与边际收益判据</h3>\n<p>容量决策的第一步不是解不等式，而是把 TV 界拆成可独立定价的三个预算项：离散化项 <span class=\"inline-math\">C·exp(−κK)</span>、蒸馏项 <span class=\"inline-math\">ε_distill</span>、以及语法约束带来的投影残差。前两项在公式里显式出现，第三项是公式的失效项，工程上必须单列为一项实测修正，否则所有外推都会系统性偏乐观。设目标误差为 <span class=\"inline-math\">ε_target</span>，则步数预算的下界由离散化项单独决定：</p>\n<div class=\"formula\">$$K_{\\min}=\\left\\lceil\\frac{1}{\\kappa}\\ln\\frac{C}{\\varepsilon_{\\text{target}}-\\varepsilon_{\\text{distill}}-\\varepsilon_{\\text{syntax}}}\\right\\rceil$$</div>\n<p>这个式子的工程含义比它看起来更硬：分母一旦被蒸馏项和语法项吃掉大半，对数内的比值迅速膨胀，<span class=\"inline-math\">K_min</span> 对 κ 的敏感性被放大。因此定步数预算前必须先测出 <span class=\"inline-math\">ε_distill</span> 的量级——它是少步学生的质量天花板，与 K 无关。判据很直接：当 <span class=\"inline-math\">ε_distill</span> 已经接近 <span class=\"inline-math\">ε_target</span> 时，继续加 K 的边际收益趋近于零，此时扩容应投向教师轨迹覆盖度而非采样步数。反过来，若 <span class=\"inline-math\">ε_distill</span> 远小于目标误差，则 K 是有效杠杆，但杠杆效率由 κ 决定，而 κ 在代码离散嵌入空间上会退化——这一点决定了下面批大小的定法必须留出实测校准的余量。</p>\n<p>代价侧要同时记两笔账：K 线性推高单请求延迟（每步一次完整的去噪前向），而批大小线性推高显存与功耗。二者不是独立的，因为步数预算决定了单请求占用算力的时长，进而决定了在给定 SLO 下能塞进多少并发。这就是为什么步数决策必须先于批大小决策，顺序反了会导致批大小按乐观 κ 定死、上线后被迫回退。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-21\">二十一 · 定批大小：用步数预算反推并发上限</h3>\n<p>批大小的约束来自两个方向：显存容量与延迟 SLO。步数预算通过延迟直接进入第二个约束。设单步前向的批处理时间为 <span class=\"inline-math\">\\(t_{\\text{step}}(B)\\)</span>，它随 B 增长但斜率递减（算力受限区近似常数，带宽受限区近似线性），则单请求端到端延迟为：</p>\n<div class=\"formula\">$$T_{\\text{e2e}}(B)\\approx K\\cdot t_{\\text{step}}(B)+t_{\\text{pre}}+t_{\\text{post}}$$</div>\n<p>给定 SLO 的延迟上限 <span class=\"inline-math\">\\(T_{\\text{SLO}}\\)</span>，可解出批大小的上界 <span class=\"inline-math\">\\(B\\le t_{\\text{step}}^{-1}\\!\\left((T_{\\text{SLO}}-t_{\\text{pre}}-t_{\\text{post}})/K\\right)\\)</span>。注意 K 出现在分母位置：步数预算翻倍，允许的单步时间减半，等价于把批大小压到原来的一个较小区间。这就是“步数-质量界”与“批调度”之间的耦合点——它不是两个独立旋钮，而是一个比值约束。</p>\n<p>具体机制上，扩散代码模型的采样循环是 K 次串行前向，无法像自回归解码那样用连续批处理把不同请求的步交错填充来摊薄尾延迟，因为每一步都依赖上一步的完整隐状态。因此批大小必须在“同一批请求同步推进 K 步”的框架下定，批内最慢请求决定整批节奏。工程代价是：批越大，单步时间越长，而 K 步的串行结构把这一放大效应乘以 K。一个可操作的例子：若实测 <span class=\"inline-math\">\\(t_{\\text{step}}\\)</span> 在目标批区间内近似常数，则延迟随 K 线性增长，批大小上界随 K 反比收缩；一旦进入带宽受限区，<span class=\"inline-math\">\\(t_{\\text{step}}\\)</span> 随 B 线性增长，延迟变成 <span class=\"inline-math\">K·(a+bB)</span>，此时批大小上界对 K 的敏感度更高，需要把 K 的实测校准值（而非公式乐观值）代入。</p>\n<p>显存侧则给出另一个上界：每请求的隐状态与中间激活随批大小线性增长，KV 预算在这里不是自回归意义上的 KV cache，而是扩散采样轨迹的中间态缓存。两者取小者作为最终批大小。这一步的判断必须用实测 κ 而非公式 κ，否则批大小会被高估，上线后在代码任务上表现为编译失败率超预期——这正是“按指数收敛界设定步数预算”的典型失败模式。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-22\">二十二 · 定并行度：步数预算决定切分粒度</h3>\n<p>并行度决策的核心问题是：把模型切到多卡后，单步前向的通信开销能否被 K 步的串行结构摊薄。张量并行的通信下界由每步的 all-reduce 次数与消息大小决定，而扩散采样的 K 步串行意味着通信次数随 K 线性累加。设单步通信时间为 <span class=\"inline-math\">\\(t_{\\text{comm}}(P)\\)</span>（P 为并行度），则总通信代价为 <span class=\"inline-math\">\\(K·t_{\\text{comm}}(P)\\)</span>，它与计算代价 <span class=\"inline-math\">\\(K·t_{\\text{comp}}(P)\\)</span> 同比例放大——这意味着并行效率不随 K 改变，但绝对通信开销随 K 线性增长，在 SLO 紧张时成为硬约束。</p>\n<div class=\"formula\">$$\\text{speedup}(P)=\\frac{K\\,t_{\\text{comp}}(1)}{K\\,t_{\\text{comp}}(P)+K\\,t_{\\text{comm}}(P)}=\\frac{t_{\\text{comp}}(1)}{t_{\\text{comp}}(P)+t_{\\text{comm}}(P)}$$</div>\n<p>式子表面看 K 被约掉，但工程上不能这么读：<span class=\"inline-math\">\\(t_{\\text{comm}}(P)\\)</span> 的绝对值乘以 K 后可能超过延迟预算的相当比例，尤其当 P 较大、消息被切碎时。因此定并行度的正确顺序是先用步数预算算出可容忍的单步总时间，再在该约束下选 P，而不是先选 P 再看 K 是否放得下。具体机制上，扩散模型每步都要做完整的隐状态同步，无法像自回归那样把通信与下一 token 的计算重叠，因为下一步依赖本步全部结果。代价表现为：并行度提高降低 <span class=\"inline-math\">\\(t_{\\text{comp}}\\)</span>，但 <span class=\"inline-math\">\\(t_{\\text{comm}}\\)</span> 上升，存在一个由 K 决定的最优 P——K 越大，通信项权重越高，最优 P 越小。</p>\n<p>例子：若目标 SLO 下单步预算被 K 压得很紧，则宁可减少并行度、把模型放在更少的卡上以降低通信次数，也不要用高并行度换取单步计算时间——因为 K 步串行会把通信开销累加到不可接受。这与自回归解码的直觉相反，后者常用高并行度摊薄权重读取带宽。分离式预填/解码的部署形态在这里也要重新评估：扩散采样没有“预填一次、解码多步”的结构，K 步全部是计算密集的去噪步，分离式部署的收益主要来自把长 K 请求与短 K 请求分流到不同资源池，而非计算与带宽的解耦。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-23\">二十三 · 定 KV 预算：扩散采样的中间态而非自回归缓存</h3>\n<p>扩散代码模型的显存预算结构与自回归模型不同：没有随序列长度线性增长的 KV cache，取而代之的是每步的隐状态张量 <span class=\"inline-math\">x_k</span> 与条件嵌入。设隐状态维度为 d、序列长度为 L、批大小为 B、精度字节数为 s，则单步中间态显存为 <span class=\"inline-math\">B·L·d·s</span>。关键在于：采样循环是否需要保留全部 K 步的中间态。若用二阶或更高阶采样器（如需要前两步信息的更新规则），则需保留常数个历史步；若用一阶更新，则只需当前步。这决定了显存预算是 <span class=\"inline-math\">O(B·L·d·s)</span> 还是 <span class=\"inline-math\">O(c·B·L·d·s)</span>（c 为历史步数）。</p>\n<div class=\"formula\">$$M_{\\text{traj}}\\approx c\\cdot B\\cdot L\\cdot d\\cdot s,\\qquad B_{\\max}=\\left\\lfloor\\frac{M_{\\text{budget}}-M_{\\text{weights}}-M_{\\text{cond}}}{c\\cdot L\\cdot d\\cdot s}\\right\\rfloor$$</div>\n<p>这里的容量决策要点是：K 本身不直接进入显存公式（历史步数 c 才进入），但 K 通过延迟约束间接压缩 B，从而压缩 <span class=\"inline-math\">M_traj</span>。因此“定 KV 预算”在扩散语境下应理解为定中间态预算，且它与批大小是同一个约束的两面。工程代价上，条件嵌入（语法约束、CFG 的引导信号）在每步都要参与计算，若语法掩码以稠密矩阵形式驻留显存，其占用可能超过隐状态本身——这是代码任务特有的开销，必须在预算里单列。一个具体判断：当语法掩码维度随词表增长时，掩码显存随 <span class=\"inline-math\">B·L·V</span> 增长，可能成为批大小的真正瓶颈，而非隐状态。</p>\n<p>失效条件在这里必须显式处理：带 CFG/语法掩码的扩散采样会改变有效步数-质量曲线，因为掩码把采样轨迹投影到合法子空间，等效于改变了得分函数的光滑性，从而改变 κ。用无约束公式外推带约束解码的质量-步数曲线会预测失真，表现为预算按公式算出的 K 足够、实测编译失败率仍高。正确做法是把语法投影残差 <span class=\"inline-math\">ε_syntax</span> 作为独立项实测，再回填到第一节的 <span class=\"inline-math\">K_min</span> 公式里。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-24\">二十四 · 定 SLO 与算例：从目标编译通过率反推资源</h3>\n<p>SLO 的设定不能直接写“延迟 P99 小于某值”，因为扩散代码生成的质量与延迟通过 K 耦合：压低延迟就要压 K，压 K 就抬高误差，误差在代码任务上放大为编译失败率。因此 SLO 应写成二维约束：<span class=\"inline-math\">\\((T_{\\text{SLO}}, \\text{pass@1}_{\\text{target}})\\)</span>，二者通过步数-质量界联立。求解顺序是：先由 pass@1 目标反推 <span class=\"inline-math\">ε_target</span>（定性映射，公式本身不预测具体 pass@1，K 到 1 时误差完全由蒸馏项主导），再由 <span class=\"inline-math\">ε_target</span> 反推 <span class=\"inline-math\">K_min</span>，最后由 <span class=\"inline-math\">K_min</span> 与 <span class=\"inline-math\">\\(T_{\\text{SLO}}\\)</span> 反推批大小与并行度。</p>\n<p>算例（结构性，不含编造数字）：设某代码扩散模型实测蒸馏项 <span class=\"inline-math\">ε_distill</span> 已接近目标误差的较大份额，语法投影残差 <span class=\"inline-math\">ε_syntax</span> 为另一可观份额。代入第一节公式，分母很小，对数项膨胀，<span class=\"inline-math\">K_min</span> 被推到较高区间；此时若按公式的乐观 κ 计算，会得到偏小的 K，上线后编译失败率高于预期。修正做法是用实测的多项式收敛速率替换 κ，得到更大的 <span class=\"inline-math\">K_min</span>。随后把该 K 代入第二节延迟式：<span class=\"inline-math\">\\(T_{\\text{e2e}}≈K·t_{\\text{step}}(B)\\)</span>，在 <span class=\"inline-math\">\\(T_{\\text{SLO}}\\)</span> 约束下解出 <span class=\"inline-math\">B</span> 的上界；再用第四节显存式校验 <span class=\"inline-math\">B</span> 是否被中间态与语法掩码卡住；最后用第三节判断并行度是否因 K 步通信累加而需要下调。</p>\n<p>这个算例的工程结论落在容量规划的方向上：当 <span class=\"inline-math\">ε_distill</span> 与 <span class=\"inline-math\">ε_syntax</span> 合计已占据目标误差的主要部分时，扩容的正确投向是提升教师轨迹覆盖度以压低 <span class=\"inline-math\">ε_distill</span>、以及优化语法约束解码以压低 <span class=\"inline-math\">ε_syntax</span>，而不是增加采样步数或堆并行度。因为这两项与 K 无关，加 K 只会在对数项上做无效功，同时线性推高延迟与显存，挤压批大小。反之，若两项残差都很小，则 K 是有效杠杆，但必须用实测 κ 校准，且并行度要按 K 步通信累加重新评估。最终判断落在具体机制上：把步数预算、批大小、并行度、中间态预算四者写成一组以实测 κ 与实测残差为输入的联立约束，任何一项用公式乐观值替代实测值，都会在代码任务上以编译失败率的形式暴露出来。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-25\">二十五 · 把步数-质量界折算成容量参数：可用的地方与会翻车的地方</h3>\n<p>这条界在容量决策里能用的只有一件事：判断步数预算的边际收益是否已经耗尽。把目标误差拆成离散化项与蒸馏项后，<span class=\"formula-inline\">$$\\mathrm{TV}(p_K,p_\\infty)\\le C\\exp(-\\kappa K)+\\varepsilon_{\\text{distill}}$$</span> 的导数意义很直接——当 <span class=\"formula-inline\">$$C\\kappa\\exp(-\\kappa K)$$</span> 已小于 <span class=\"formula-inline\">$$\\varepsilon_{\\text{distill}}$$</span> 的量级，再加 K 只是线性买延迟。工程上据此定批大小与并行度：设单步前向代价为 <span class=\"formula-inline\">$$t_{\\text{step}}(B)$$</span>，单请求延迟约为 <span class=\"formula-inline\">$$K\\cdot t_{\\text{step}}(B)$$</span>，吞吐约为 <span class=\"formula-inline\">$$B/(K\\cdot t_{\\text{step}}(B))$$</span>。K 翻倍而 B 不变，吞吐近似腰斩；此时若编译失败率没有同步下降，扩容就该转向教师轨迹覆盖度而不是采样步数。KV 预算同理：扩散采样的中间状态驻留显存随 K 与批内并发线性增长，把 K 压到蒸馏学生的下限，是把显存换给更大批量的唯一杠杆。</p>\n<p>失效条件必须写进容量模型，否则算出来的数是乐观界。κ 依赖得分函数的光滑性，代码的离散 token 嵌入空间非光滑，实际收敛常退化为多项式而非指数，按指数界定的步数预算会在部署后表现为编译失败率高于预期。更硬的一条是 <span class=\"formula-inline\">$$\\varepsilon_{\\text{distill}}$$</span> 与 K 无关：K 趋近 1 时误差完全由蒸馏项主导，公式给不出具体 pass@1，少步学生的质量天花板由教师轨迹覆盖度决定。带 CFG 或语法掩码的采样会对轨迹做投影，有效步数-质量曲线被改写，无约束公式外推必然失真，必须以实测曲线校准后再进 SLO 表。</p>\n<p>算例只给结构不给数字：某代码补全服务把 SLO 定在端到端 p99 与编译通过率双约束。先测出无约束下 K=8、16、32 的通过率曲线，若 16 到 32 的增益已落在蒸馏项噪声内，则锁 K=16；再按 <span class=\"formula-inline\">$$B/(K t_{\\text{step}}(B))$$</span> 反推满足 p99 的最大 B，把剩余显存投给 KV 与更大并发，而不是投给 K=64。若实测曲线在 K=16 处仍陡，说明教师覆盖不足，应扩容蒸馏数据与教师轨迹，而非加步数——这正是该界在容量规划中唯一可靠的判决：它区分“算力买精度”和“算力买不到精度”两种情形。</p>\n<table class=\"mini\"><thead><tr><th>决策项</th><th>公式给出的信号</th><th>失效时的表现</th></tr></thead><tbody><tr><td>批大小 B</td><td>K 固定后按延迟约束取最大 B</td><td>按指数界定 K 过小，失败率超 SLO</td></tr><tr><td>并行度</td><td>K 与 t_step 决定单请求占用</td><td>忽略掩码投影，实测曲线偏移</td></tr><tr><td>KV 预算</td><td>中间状态随 K·B 线性占用</td><td>蒸馏项不降，显存白花</td></tr></tbody></table>\n<h3 id=\"th-diffusion-steps-quality-sec-26\">二十六 · 误用一：把乐观界当成部署预算的硬约束</h3>\n<p>最常见的误用，是把 <span class=\"formula\">$$\\mathrm{TV}(p_K,p_\\infty)\\le C\\exp(-\\kappa K)+\\varepsilon_{\\text{distill}}$$</span> 中的指数项直接当作容量规划的输入：给定目标误差，反解出 K，然后把 K 写进推理服务的采样配置。这个做法在图像、连续嵌入空间里尚可，在代码生成上会系统性低估所需步数。原因是 κ 的推导前提是得分函数在嵌入空间上满足 Lipschitz 型光滑性；而代码 token 的离散嵌入在语法边界处（例如一个标识符从合法变为非法、一个缩进层级跳变）呈现强非光滑性，得分场在这些位置剧烈转向，实际误差衰减退化为多项式而非指数。工程后果不是“误差略大”，而是非线性放大：token 级 TV 距离的小幅上升，经过语法约束的投影后，会集中落在少数关键 token 上（括号、分号、类型标注），直接变成编译失败。</p>\n<p>识别方法有两条。其一，做 K 扫描而不是单点验证：在同一批 prompt 上取 K 的几何序列（如 4、8、16、32），记录 pass@1 与编译通过率，把误差对 K 画在 log 纵轴上。若曲线明显上凸而非直线，说明指数假设已失效，公式只能当上界参考。其二，看失败样本的分布：如果失败集中在语法结构 token 而非语义 token，基本可以判定是离散化误差主导，而非蒸馏偏差主导，此时加 K 有边际收益但收益按多项式速率递减。推理系统代价上，这意味着步数预算的延迟成本（每步一次完整的去噪前向，含 2-SM MMA 与 TMEM 往返）被低估，而吞吐侧的连续批处理又掩盖了单请求延迟的恶化，直到 SLO 违约才暴露。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-27\">二十七 · 误用二：用加 K 替代教师轨迹覆盖</h3>\n<p>第二类误用更隐蔽：团队观察到质量不达标，第一反应是把采样步数从少步学生的配置往上加，试图“用算力换质量”。但公式的第二项 <span class=\"formula\">$$\\varepsilon_{\\text{distill}}$$</span> 与 K 无关，它是少步学生分布与教师多步轨迹之间的固有偏差，天花板由教师轨迹覆盖度决定。当 K 已经接近学生训练时的步数配置，继续加 K 只会让采样轨迹偏离学生被蒸馏时见过的分布，误差不降反升——这是蒸馏模型特有的“越采样越偏”现象。具体机制是：学生在训练时只见过教师轨迹上离散的几个锚点，K 增大后采样路径落在锚点之间，学生没有对应的得分估计，输出退化为噪声。</p>\n<p>识别信号是质量随 K 的非单调性：K 从 4 加到 8 略有改善，加到 16 反而变差，或 pass@1 方差骤增。这时正确的动作是回到教师侧扩容轨迹覆盖（更多样的教师采样路径、更长的教师步数、更广的 prompt 分布），而不是在推理侧堆步数。容量决策上，这对应一条明确的判断：当实测显示 <span class=\"formula\">$$\\varepsilon_{\\text{distill}}$$</span> 已主导误差（即 K 翻倍带来的误差下降小于测量噪声），扩容预算应全部投向教师覆盖与蒸馏数据，推理侧的 K 保持学生训练配置即可。算力被浪费的形态很具体：GPU 小时花在无效的额外去噪步上，而 KV cache 与批调度容量被这些步数挤占，挤掉了本可服务的并发请求。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-28\">二十八 · 误用三：忽略语法掩码的投影效应</h3>\n<p>第三类误用出现在带约束解码的部署里。公式刻画的是无约束扩散采样的误差衰减，而生产环境的代码生成几乎总带 CFG 或语法掩码：每一步采样后把概率质量投影到合法 token 集合上。这个投影不是无害的后处理，它改变了有效步数-质量曲线。机制上，掩码在每一步把采样分布截断并重归一化，等价于在得分场上叠加一个随 K 变化的硬约束势；当 K 小、单步步长大时，投影会反复把轨迹拉回合法域，造成“步数被掩码吃掉”的现象——名义 K 步，实际有效去噪步数少于 K。反过来，K 大、步长小时，掩码的干预变温和，曲线又回到接近无约束的形态。因此用无约束公式外推带约束解码的质量，预测必然失真，且失真方向随 K 变化，不能用一个固定修正因子补偿。</p>\n<p>识别方法是做双轨实测：同一模型、同一 prompt 集，分别在开掩码与关掩码下扫 K，比较两条曲线的交点与斜率。若开掩码曲线在小 K 段显著高于关掩码（掩码救了语法），但在大 K 段反而低于关掩码（掩码阻碍了语义细化），说明投影效应已经主导，公式的 K 预算不能直接搬用。系统代价体现在延迟构成上：掩码计算本身是每步的额外开销（词表级布尔运算与重归一化），在小 batch 时占比可观；而在大 batch 连续批处理下，掩码的规则分支会造成 warp 内分歧，进一步拉低 SM 利用率。工程判断是：把掩码开销计入每步成本，再用实测曲线而非公式曲线定 K。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-29\">二十九 · 一个反例：从公式反解 K 的部署事故链</h3>\n<p>设一个团队要把扩散代码模型上线到 IDE 补全，SLO 是首 token 延迟与补全接受率。他们取公式的指数项，按目标 TV 距离反解出 K=8，理由是“指数收敛，8 步足够”。上线前的离线验证用的是无掩码、温度固定的采样，pass@1 看起来达标。上线后接入了语法掩码与 CFG，且真实 prompt 分布比离线集更偏长上下文与罕见 API。事故链如下：其一，长上下文使得分场在更多语法边界处非光滑，实际收敛退化为多项式，K=8 的有效误差高于离线估计；其二，掩码投影在小 K 下频繁干预，把部分本可细化的语义步吞掉，接受率在复杂补全上明显下滑；其三，团队按“加 K 试试”的直觉把 K 提到 16，但学生蒸馏只覆盖到 8 步锚点，轨迹偏离训练分布，输出开始出现语法正确但语义漂移的补全，接受率不升反降。最终暴露的问题不是模型能力，而是三处误用叠加：乐观界当预算、加 K 替代教师覆盖、忽略投影效应。</p>\n<p>这个反例的可迁移教训是：公式的每一项都要在部署形态下单独校准。离散化项要用带掩码的实测 K 扫描校准 κ 的有效值；蒸馏项要用学生-教师分布距离的离线测量确认天花板；投影效应要用双轨曲线确认修正方向。三者缺一，反解出的 K 就是错的。延迟侧的具体代价是每请求多出的无效步数直接叠加在去噪前向上，而吞吐侧的连续批处理会把这种单请求延迟恶化藏进平均吞吐里，直到 p99 违约。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-30\">三十 · 识别清单与工程落点</h3>\n<p>把上述误用收敛成一张可在部署前执行的检查表，每条都对应一个具体机制而非泛泛而谈。</p>\n<table class=\"mini\"><thead><tr><th>检查项</th><th>机制</th><th>失败信号</th><th>系统代价</th></tr></thead><tbody>\n<tr><td>K 扫描曲线形状</td><td>离散嵌入非光滑导致多项式收敛</td><td>log 纵轴上凸</td><td>步数预算低估，p99 延迟超标</td></tr>\n<tr><td>失败 token 分布</td><td>语法结构 token 集中误差</td><td>括号/分号类失败占比高</td><td>编译失败率放大</td></tr>\n<tr><td>质量-K 单调性</td><td>学生锚点覆盖不足</td><td>K 增大后 pass@1 反降</td><td>GPU 小时浪费在无效步</td></tr>\n<tr><td>掩码双轨曲线</td><td>投影改变有效步数</td><td>两曲线交点漂移</td><td>掩码开销与 warp 分歧</td></tr>\n<tr><td>蒸馏项主导判定</td><td>ε_distill 与 K 无关</td><td>K 翻倍误差下降小于噪声</td><td>扩容投向错误侧</td></tr>\n</tbody></table>\n<p>落点上，最关键的工程判断是区分“可加 K 改善”与“必须改教师”两种状态，并用实测而非公式判定。判定量可以写成：若 <span class=\"formula\">$$\\Delta\\mathrm{TV}/\\Delta K$$</span> 在连续两次 K 翻倍中均小于测量置信区间，则蒸馏项已主导，停止加 K。这个判据不依赖任何未给出的数字，只依赖团队自己的测量，且直接对应容量决策——把省下的步数预算换成教师轨迹覆盖的扩容，才是公式在部署形态下真正该被使用的方式。</p>\n\n<h3 id=\"th-diffusion-steps-quality-sec-31\">三十一 · 误用与反例：把乐观界当预算、把步数当万能旋钮</h3>\n<p>最常见的误用是把 $$\\mathrm{TV}(p_K,p_\\infty)\\le C\\exp(-\\kappa K)+\\varepsilon_{\\text{distill}}$$ 中的指数项当作可外推的工程承诺，直接反解出“达到目标误差所需 K”并写进容量规划。问题在于 $$\\kappa$$ 依赖得分函数的光滑性与数据分布，而代码 token 的嵌入空间是离散且非光滑的，实际收敛常退化为多项式；公式给出的是乐观界而非可达曲线。识别方法很直接：在目标模型与目标语言上实测 pass@1 与编译失败率随 K 的曲线，若在 K 翻倍后失败率下降幅度明显小于指数预测，就说明 $$\\kappa$$ 已被非光滑性压制。系统代价体现在预算错配——按指数界只留少步预算，解码阶段延迟看似达标，但编译失败率高于预期，重试与回退把端到端吞吐吃掉，且这部分代价不在单次前向的延迟账上。</p>\n<p>第二个误用是只加 K 不改教师。$$\\varepsilon_{\\text{distill}}$$ 与步数无关，少步学生的质量天花板由教师轨迹覆盖度决定；当 $$\\varepsilon_{\\text{distill}}$$ 已接近目标误差时，继续加 K 的边际收益趋零，算力被浪费在采样而非覆盖上。判别信号是：K 增大而失败率曲线出现平台，同时失败样本的分布集中在教师轨迹未覆盖的语法构造上。此时扩容应优先投教师覆盖（更长轨迹、更广语法样本），而不是采样步数。第二式 $$\\mathbb{E}[\\|x_K-x_\\infty\\|_2^2]\\le\\frac{\\sigma^2}{K}\\sum_{k=1}^{K}\\eta_k^2$$ 也提示步长 $$\\eta_k$$ 的平方和直接进入误差上界——盲目放大步长换取少步低延迟，会让误差项抬头，属于同一类误用的变体。</p>\n<p>第三个误用是忽略语法掩码与 CFG 的投影效应。带约束的扩散采样把轨迹投影到合法 token 流形上，有效步数-质量曲线被改变，用无约束公式外推必然失真；这类失真在代码场景尤其危险，因为约束解码本身会掩盖部分 token 级误差，使小 K 下的失败率看起来优于真实分布距离所预示的水平，一旦关闭掩码或换到更严的语法子集，失败率立刻暴露。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>识别信号</th><th>系统代价</th></tr></thead><tbody><tr><td>按指数界定 K</td><td>K 翻倍后失败率降幅远小于指数预测</td><td>重试与回退吞噬吞吐</td></tr><tr><td>只加 K 不改教师</td><td>失败率曲线出现平台，失败集中于未覆盖语法</td><td>采样算力空转，天花板不动</td></tr><tr><td>无约束公式外推带掩码解码</td><td>关掩码后失败率跳升</td><td>质量预测失真，SLO 违约</td></tr></tbody></table>\n<p>反例可设为一次代码补全服务的容量评审：团队用指数界把 K 压到个位数以保延迟，教师轨迹仅覆盖常见库调用，未做语法掩码的离线校准。上线后单次前向延迟达标，但编译失败率高于预期，重试把有效吞吐拉低；随后把 K 翻倍，失败率几乎不动——平台来自 $$\\varepsilon_{\\text{distill}}$$，而非离散化误差。正确动作不是继续加 K，而是先补教师覆盖并带掩码实测曲线，再决定步数预算；K 到 1 时误差完全由蒸馏项主导，公式无法预测具体 pass@1，任何“按公式算出的少步方案”都必须以实测校准为前置条件。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>K</td><td>采样步数</td></tr><tr><td>p_K</td><td>K 步采样分布</td></tr><tr><td>p_{\\infty}</td><td>极限（教师/精确）分布</td></tr><tr><td>\\kappa</td><td>收敛速率常数</td></tr><tr><td>\\varepsilon_{\\text{distill}}</td><td>蒸馏引入的分布偏差</td></tr><tr><td>\\eta_k</td><td>第 k 步步长</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-diffusion-steps-quality · 共 5 个片段</p>\n"},{"id":"th-batch-latency-model","title":"连续批调度时延模型","direction":"dir-spec-decode-code","prereq":[],"plain":"在连续批处理下，单请求完成时延约等于排队等待加自身预填与逐 token 解码时间之和，而解码步时延随批内 token 数增长，因此吞吐与时延存在可量化的权衡点。","definition":"在连续批处理下，单请求完成时延约等于排队等待加自身预填与逐 token 解码时间之和，而解码步时延随批内 token 数增长，因此吞吐与时延存在可量化的权衡点。","formula":"$$ T_{\\text{e2e}} \\approx W_q + \\frac{S_p\\,t_{\\text{prefill}}}{B} + S_o \\cdot \\max\\!\\left(t_{\\text{step}}^{\\text{base}},\\; \\frac{W + 2LHd\\,B_{\\text{eff}}}{\\text{BW}}\\right) $$","variables":[{"sym":"W_q","meaning":"排队等待时间"},{"sym":"S_p","meaning":"预填 token 数"},{"sym":"S_o","meaning":"输出 token 数"},{"sym":"t_{\\text{prefill}}","meaning":"单位预填 token 计算时间"},{"sym":"B_{\\text{eff}}","meaning":"有效批内并发序列数"},{"sym":"t_{\\text{step}}^{\\text{base}}","meaning":"固定步开销（kernel 启动等）"}],"derivation":"推导关键一步：解码每步需把权重与 KV cache 从显存读一遍，读量约 W+2LHd·B_eff，除以带宽得步时延下界；与固定开销取 max 后乘输出长度，再加排队与预填摊薄项。","example":"性能决策用途：可判断给定 SLA 下最大可接受批大小与最大输出长度，并识别解码步是带宽受限还是固定开销受限，从而决定是否值得增大批或改用投机解码降低步数。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设批内序列同步推进且无抢占；实际调度器在 prefill 与 decode 混批时会产生气泡，公式低估尾延迟","W_q 由到达率与服务率分布决定，需排队论建模；公式只给确定性近似，突发流量下不成立","未考虑 chunked prefill 对 decode 步的插入影响，长前缀预填会拉高同批其他请求的 token 间隔"],"system_note":"常见误用：用平均到达率代入 W_q 而忽略突发分布，上线后尾延迟远超模型预测；或把 B 当作可无限增大，忽视解码步时延随 B_eff 线性上升导致单请求时延恶化。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["直觉：连续批处理下单请求端到端时延≈排队等待+自身预填时间摊到批+逐 token 解码步数乘每步时延，而每步时延随批内 token 数增长，吞吐与时延存在可量化权衡点。","公式含义：$$T_{\\text{e2e}} \\approx W_q + \\frac{S_p\\,t_{\\text{prefill}}}{B} + S_o \\cdot \\max\\!\\left(t_{\\text{step}}^{\\text{base}},\\; \\frac{W + 2LHd\\,B_{\\text{eff}}}{\\text{BW}}\\right)$$ 中 W_q 为排队等待，S_p 为预填 token 数，t_prefill 为单位预填 token 计算时间，B 为批内并发，S_o 为输出 token 数，B_eff 为有效批内并发序列数，t_step^base 为 kernel 启动等固定步开销，第二项为解码步的显存带宽下界。","推导关键一步：解码每步需把权重与 KV cache 从显存读一遍，读量约 W+2LHd·B_eff，除以带宽得步时延下界；与固定开销取 max 后乘输出长度，再加排队与预填摊薄项。","适用边界：假设批内序列同步推进且无抢占；实际调度器在 prefill 与 decode 混批时产生气泡，公式低估尾延迟；W_q 需排队论建模，突发流量下确定性近似不成立；未计入 chunked prefill 对 decode 步的插入影响。","性能决策用途：可判断给定 SLA 下最大可接受批大小与最大输出长度，并识别解码步是带宽受限还是固定开销受限，从而决定是否值得增大批或改用投机解码降低步数。","常见误用：用平均到达率代入 W_q 而忽略突发分布，上线后尾延迟远超模型预测；或把 B 当作可无限增大，忽视解码步时延随 B_eff 线性上升导致单请求时延恶化。"],"anchors":["未给出"],"pitfalls":["用平均到达率估算排队等待，忽略突发流量分布，尾延迟预测严重偏低。","忽略 prefill 与 decode 混批气泡及 chunked prefill 插入，长前缀预填拉高同批其他请求 token 间隔。","把批大小当作免费吞吐杠杆，未计入解码步时延随 B_eff 线性增长对单请求时延的侵蚀。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-1\">一 · 一句话直觉与它到底在算什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-2\">二 · 为什么非要有这个模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-3\">三 · 三个常见误解及其代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-4\">四 · 适用边界与读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-5\">五 · 边界条件：这条公式在哪里开始说谎</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-6\">六 · 逐项拆解：三项各自的物理来源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-7\">七 · 推导关键步：从字节读量到步时延</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-8\">八 · 离散化与近似：公式在哪里失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-9\">九 · 用公式做工程判断：三个可算的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-10\">十 · 误用与修正：把公式用在它成立的地方</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-11\">十一 · 同步推进假设与抢占缺失：公式的第一道裂缝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-12\">十二 · 混批气泡：prefill 插入如何污染 decode 步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-13\">十三 · 排队项的分布依赖：平均到达率是陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-14\">十四 · 规模上限：B_eff 线性项与固定开销项的交叉点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-15\">十五 · 精度与硬件假设：带宽项里的隐含常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-16\">十六 · 公式的适用边界：同步推进、无抢占与带宽下界的成立条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-17\">十七 · 从公式到决策变量：四个可调旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-18\">十八 · 定批大小：解出 B 的可行区间而非单点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-19\">十九 · 定并行度：分母 BW 与分子 W 的赛跑</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-20\">二十 · 定 KV 预算：把 B_eff 从调度参数变成显存约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-21\">二十一 · 定 SLO 与算例：把四个旋钮代进同一张表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-22\">二十二 · 把时延模型当旋钮用：定批、定并行、定 KV、定 SLO 的边界与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-23\">二十三 · 误用一：用平均到达率喂 W_q，尾延迟被系统性低估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-24\">二十四 · 误用二：把 B 当成免费吞吐杠杆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-25\">二十五 · 误用三：忽略混批气泡与 chunked prefill 的插入</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-26\">二十六 · 反例：一次按均值做的容量规划如何在上线后失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-27\">二十七 · 识别清单：什么时候不该信这个公式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-batch-latency-model-sec-28\">二十八 · 误用与反例：把确定性近似当成 SLA 承诺书</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:574px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 573.7 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"491.7\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"491.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：在连续批处理下，单请求完成时延约等于排队等待加自身预填与逐 tok…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"491.7\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$ T_{\\text{e2e}} \\approx W_q + \\…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"491.7\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设批内序列同步推进且无抢占；实际调度器在 prefill 与 d…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-batch-latency-model-sec-1\">一 · 一句话直觉与它到底在算什么</h3>\n<p>连续批调度时延模型要回答的问题只有一个：给定到达流量、序列长度分布和 SLA，把批开多大、把输出放多长，单请求的端到端时延会落在哪里。它的直觉可以压缩成一句话：一个请求的完成时间，等于它在队列里等的时间，加上它自己的预填计算被摊到整个批上的那部分，再加上它每吐一个 token 就要付一次的解码步时延乘以输出长度。三段时间性质完全不同——第一段由到达率与服务率的分布决定，第二段由预填算力与批内并发分摊，第三段由解码步的显存带宽下界与固定开销决定。把三者混为一谈，是绝大多数容量规划出错的根源。</p>\n<p>严格地说，这个模型是一个确定性近似：</p>\n<div class=\"formula\">$$ T_{\\text{e2e}} \\approx W_q + \\frac{S_p\\,t_{\\text{prefill}}}{B} + S_o \\cdot \\max\\!\\left(t_{\\text{step}}^{\\text{base}},\\; \\frac{W + 2LHd\\,B_{\\text{eff}}}{\\text{BW}}\\right) $$</div>\n<p>其中 W_q 是排队等待，S_p 是预填 token 数，t_prefill 是单位预填 token 的计算时间，B 是批内并发，S_o 是输出 token 数，B_eff 是有效批内并发序列数，t_step^base 是 kernel 启动等固定步开销，BW 是显存带宽。它不是一个测量公式，而是一个结构公式：它把时延拆成三个可分别优化的项，并明确指出第三项里存在一个 max，这个 max 就是“解码步到底是带宽受限还是固定开销受限”的判据。</p>\n<p>推导的关键一步在解码项。解码每步要把权重和 KV cache 从显存读一遍，读量约为 W + 2LHd·B_eff（W 为权重字节数，L 为层数，H 为头数，d 为头维，因子 2 对应 K 与 V），除以带宽即得步时延的带宽下界。它与固定开销取 max，乘上输出长度，就得到解码总时间。这一步之所以重要，是因为它把“批越大越划算”这件事写成了一个有拐点的函数：当 B_eff 很小时，步时延被 t_step^base 压住，加批几乎不增加单步代价，吞吐白赚；当 B_eff 增大到带宽项超过固定开销后，步时延随 B_eff 线性上升，加批开始直接侵蚀单请求时延。</p>\n\n<h3 id=\"th-batch-latency-model-sec-2\">二 · 为什么非要有这个模型</h3>\n<p>没有这个模型，工程上会退化成两种粗糙做法。第一种是只看吞吐：把批尽量开大，测出一个 tokens/s 的数字就上线，结果 SLA 里的 P99 时延在真实流量下崩掉。第二种是只看单请求：一次只跑一条序列，时延好看但 GPU 利用率极低，单位 token 成本无法接受。这个模型的价值在于它把吞吐与时延放进同一个式子，让“权衡点”变成一个可以算出来的位置，而不是靠调参试出来的感觉。</p>\n<p>具体到决策用途，它至少支撑三类判断。其一，给定 SLA 下的最大可接受批大小：把目标 T_e2e 代进去，反解 B_eff 的上界，超过这个上界单请求时延就破线。其二，给定 SLA 下的最大输出长度：S_o 直接乘在步时延上，长输出请求对时延的贡献是线性的，模型让“要不要给长输出单独设队列或限流”变成算术问题。其三，识别解码步的受限类型：如果 max 取到的是 t_step^base，说明当前批太小、固定开销主导，增大批或做批内 token 打包是免费的吞吐；如果取到的是带宽项，说明已经撞上显存带宽墙，此时增大批只会恶化时延，正确动作是改用投机解码降低步数，或从权重与 KV 的字节数上做压缩。</p>\n<p>代价层面必须说清楚：这个模型本身不消耗任何运行时资源，但它的每一项都对应真实的系统代价。W_q 对应的是队列里请求占用的调度元数据与等待中的 KV 预留；预填摊薄项对应的是算力占用，预填是计算受限的，摊到批上意味着批内其他请求要等这段计算；解码项对应的是显存带宽占用，这是 Blackwell 上解码阶段最紧的资源。一个典型例子：某服务观察到解码步时延在批大小翻倍后几乎不变，于是继续加批，直到某一刻 P99 突然抬升——这正是带宽项越过固定开销的拐点，模型里那个 max 就是这条拐点的解析表达。</p>\n\n<h3 id=\"th-batch-latency-model-sec-3\">三 · 三个常见误解及其代价</h3>\n<p>第一个误解是用平均到达率代入 W_q。W_q 由到达率与服务率的分布共同决定，而不是由均值决定。用泊松均值算出的等待时间，在突发流量下会严重低估尾延迟：真实到达是成簇的，簇内请求互相排队，P99 等待可以远高于均值预测。工程后果是上线后尾延迟远超模型预测，而团队会误以为是模型错了，实际上是把一个分布问题当成了确定性问题。正确做法是把 W_q 交给排队论建模，至少用到达过程的二阶特征去校准，而不是拿一个平均 QPS 直接除。</p>\n<p>第二个误解是忽略 prefill 与 decode 混批产生的气泡。公式假设批内序列同步推进且无抢占，而真实调度器在混批时，一个长前缀预填会插进解码步之间，拉高同批其他请求的 token 间隔。chunked prefill 缓解了单次插入的冲击，但它把长预填切成多块分散到多个步里，等于持续给解码步加噪声。后果是公式系统性地低估尾延迟，尤其是当流量里混有长短差异极大的前缀时。判断方法是看同批请求的 token 间隔方差：方差大，说明气泡在起作用，此时公式给出的 T_e2e 只能当作下界读。</p>\n<p>第三个误解是把批大小当成免费的吞吐杠杆。B 在预填摊薄项里是分母，看起来越大越省，但解码项里的 B_eff 是分子，步时延随它线性上升。这两处的 B 不是同一个量：前者是分摊预填计算的并发，后者是实际参与解码步的序列数。把两者混同，就会得出“批无限大则时延无限小”的荒谬结论。真实的代价曲线是先降后升的 U 形，最低点在预填摊薄收益与解码步时延侵蚀相等的位置。工程上，这个误解的典型表现是压测时只测吞吐不测单请求时延，上线后才发现高负载下每个用户的体验都在退化。</p>\n\n<h3 id=\"th-batch-latency-model-sec-4\">四 · 适用边界与读法</h3>\n<p>这个公式只在特定假设下成立：批内序列同步推进、无抢占、到达过程可用确定性近似、且不计 chunked prefill 对解码步的插入影响。四条假设里任何一条被打破，公式的读数就要降级。突发流量下它不成立，因为 W_q 的确定性近似失效；抢占存在时它不成立，因为被抢占的请求会重新排队，实际时延高于公式；混批气泡存在时它低估尾延迟；chunked prefill 插入时它低估解码步的 token 间隔。</p>\n<p>因此正确的读法是把它当结构判据而非预测器。用它判断三件事：解码步是带宽受限还是固定开销受限；给定 SLA 下批大小的上界在哪里；输出长度对时延的线性贡献有多大。这三件事对假设的敏感性远低于绝对时延数值，所以即使公式在绝对值上偏低，它的定性结论依然可用。反过来，如果要用它做容量规划的绝对值预测，就必须先把 W_q 换成排队论模型、把气泡与 chunked prefill 的插入作为修正项加进去，否则尾延迟会被系统性低估。</p>\n<p>一个具体的工程判断落点：当观测到解码步时延与批大小近似无关时，说明 max 取的是 t_step^base，此时增大批是安全的吞吐动作，代价只是显存里多预留几份 KV；当观测到步时延随批大小近似线性上升时，说明已经进入带宽受限区，此时任何增大批的动作都在用单请求时延换吞吐，必须先用投机解码或权重压缩把每步的字节读量降下来，再谈扩批。</p>\n\n<h3 id=\"th-batch-latency-model-sec-5\">五 · 边界条件：这条公式在哪里开始说谎</h3>\n<p>这条时延公式的价值不在于“算得准”，而在于它把端到端时延拆成了三个可分别归因的项：排队等待、预填摊薄、解码步数乘步时延。工程上真正要盯的是它的失效边界——一旦越界，公式给出的不是误差，而是方向性错误的乐观。第一个边界是同步推进假设。公式默认批内所有序列在每个解码步都前进一格，但真实调度器在 prefill 与 decode 混批时，新请求的预填会挤进解码步的间隙，产生气泡；此时公式里的 <span class=\"sym\">B</span> 是一个从未真实存在的理想并发数，实际尾延迟被系统性低估。第二个边界是 <span class=\"sym\">W_q</span> 的确定性处理：排队等待由到达率与服务率的分布共同决定，用平均到达率代入只能得到均值，而 SLA 约束的是高分位，突发流量下均值与尾部分位可以相差一个数量级。第三个边界是 chunked prefill 的插入效应：长前缀预填被切块塞进解码步，会拉高同批其他请求的 token 间隔，公式完全没有这一项。</p>\n<p>把失效条件写成可检查的形式，比记住公式本身更有用。设批内序列集合为 <span class=\"sym\">S</span>，若存在任一序列在某步被抢占或未推进，则同步假设破裂，实际步数应取 <span class=\"sym\">S_o</span> 加上被抢占导致的重复步；若到达过程的服务率方差显著，则 <span class=\"sym\">W_q</span> 必须用排队论的分位数近似而非均值。一个具体的判断例子：当调度器开启 chunked prefill 且块大小相对于解码步时延不可忽略时，公式第二项（预填摊薄）与第三项（解码步）不再可加，因为预填块已经侵入了第三项的时间轴，此时应把预填块视为对解码步的周期性扰动，按最坏插入位置估算尾延迟，而不是按平均摊薄估算。</p>\n<p>系统代价必须和边界一起讲。公式中解码步的带宽下界 <span class=\"formula\">$$\\frac{W + 2LHd\\,B_{\\text{eff}}}{\\text{BW}}$$</span> 表明：增大 <span class=\"sym\">B_eff</span> 会线性抬高每步时延，吞吐上升的代价直接落在单请求时延上，这不是“批越大越划算”的免费杠杆。同时，当 <span class=\"sym\">\\(t_{\\text{step}}^{\\text{base}}\\)</span>（kernel 启动等固定开销）主导时，增大批几乎不增加步时延，此时扩容批是纯收益；一旦带宽项越过固定开销，每增加一个并发序列都在侵蚀尾延迟。这个交叉点正是决定“继续加批还是改投机解码降步数”的工程分水岭。常见误用恰恰发生在这里：把 <span class=\"sym\">B</span> 当成无上限的吞吐旋钮，忽略 <span class=\"sym\">B_eff</span> 线性上升对时延的侵蚀；或者用平均到达率估 <span class=\"sym\">W_q</span>，上线后尾延迟远超预测。公式只给确定性近似，它的正确用法是划定可行域——给定 SLA 下的最大批大小与最大输出长度——而不是预测某一次请求的真实完成时刻。</p>\n<h3 id=\"th-batch-latency-model-sec-6\">六 · 逐项拆解：三项各自的物理来源</h3>\n<p>公式写成三项相加不是数学上的随意拼接，而是把一条请求的生命周期切成三段互不重叠的时间：在等待队列里不被服务的时间、被服务但只消耗自己预填 token 的那部分时间、以及此后每生成一个 token 都要重新付一次的解码步时间。第一项 W_q 只由到达过程与服务过程共同决定，与模型结构、显存带宽、批大小都无关；它衡量的是系统“有没有空位接你”。第二项 S_p·t_prefill/B 是预填成本被批内并发摊薄后的残值：S_p 是该请求自己的前缀长度，t_prefill 是单位预填 token 的计算时间，除以 B 表达的是“预填算力被 B 条序列分享”这一事实。注意这里摊薄的是计算时间而非显存带宽时间，因为预填阶段是算力受限的 GEMM 主导，而解码阶段才是带宽受限——这正是第三项用带宽而非算力表达的原因。</p>\n<p>第三项 S_o·max(t_step^base, (W+2LHd·B_eff)/BW) 是全式最重的部分，也是唯一随输出长度线性放大的项。max 的两个候选分别对应两种截然不同的步时延形态：t_step^base 是 kernel 启动、采样、调度元数据更新等与数据量无关的固定开销，在小批或极短序列时它主导；括号内第二项是显存带宽下界，W 为权重字节数，2LHd·B_eff 为批内 B_eff 条序列在每步需读出的 KV cache 字节量（2 表示 K 与 V 两份，L 为层数，H 为头数，d 为头维），除以 BW 得到纯带宽意义上的最短步时。取 max 而非相加，是因为这两者在硬件上部分重叠：kernel 启动的间隙可以掩盖一部分 DMA 传输，反之亦然；用 max 是对重叠的理想化近似，也是公式在工程上可用的关键简化。</p>\n<p>把三项放在一起看，公式实际在说一件事：端到端时延 = 排队 + 摊薄后的预填 + 输出长度 × 每步成本，而每步成本的下界由“每步必须从显存搬多少字节”决定。这条主线把时延模型与 roofline 分析接上了，但角度不同：roofline 关心单步能达到的算力利用率上限，这里关心的是单步时间的下界如何随批内并发线性抬升，从而把吞吐增益折算成时延代价。</p>\n\n<h3 id=\"th-batch-latency-model-sec-7\">七 · 推导关键步：从字节读量到步时延</h3>\n<p>推导的起点是一个不可回避的硬件事实：自回归解码每生成一个 token，都必须把当前全部权重读一遍，并把批内所有活跃序列的 KV cache 读一遍。权重读量 W 与批大小无关，是每步的固定成本；KV cache 读量则随 B_eff 线性增长。于是每步的显存读字节数为 W + 2LHd·B_eff。把这个字节数除以可持续显存带宽 BW，得到该步在带宽维度上的最短耗时。这一步的近似在于：它假设读带宽可以被完全饱和、且没有额外的写回与中间激活流量；实际 kernel 的读效率、L2 命中率、以及 KV cache 的分页布局都会让有效带宽低于峰值，因此该式给出的是下界而非预测值。</p>\n<p>接下来与固定开销取 max。这一步的推导逻辑是：一步的时间不可能短于其数据搬运时间，也不可能短于调度与启动的固有开销，两者取较大者是对“串行依赖”的保守刻画。伪代码式的思路可以写成：</p>\n<div class=\"formula\">$$\\text{step\\_time} = \\max\\left(t_{\\text{base}},\\ \\frac{W}{BW} + \\frac{2LHd}{BW}\\cdot B_{\\text{eff}}\\right),\\quad T_{\\text{decode}} = S_o \\cdot \\text{step\\_time}$$</div>\n<p>再叠加排队与预填摊薄项即得全式。这里有一个容易被忽略的推导细节：预填项除以的是 B 而不是 B_eff。B 是批内并发序列数（调度器视角的槽位数），B_eff 是真正在解码步中贡献 KV 读量的有效序列数；两者在理想连续批处理下相等，但在有请求刚完成预填尚未进入解码、或有请求被抢占挂起时，B_eff 小于 B。公式用两个符号区分它们，正是为了在推导中保留这一差异，避免把“槽位占用”与“带宽占用”混为一谈。</p>\n<p>代价层面，这个推导直接给出一个可操作的判据：当 (W+2LHd·B_eff)/BW 远大于 t_step^base 时，解码步是带宽受限的，此时增大 B_eff 会线性拉长每步时间，吞吐上升但单请求时延同步恶化；反之当 t_step^base 主导时，增大批内并发几乎不增加步时延，是“免费”的吞吐杠杆。识别当前处于哪一侧，决定了该不该继续加批、还是该转向投机解码以减少 S_o 的有效步数。</p>\n\n<h3 id=\"th-batch-latency-model-sec-8\">八 · 离散化与近似：公式在哪里失真</h3>\n<p>公式的第一层近似是连续性假设：它把批内所有序列视为同步推进，每一步所有序列各生成一个 token，步与步之间无空洞。真实调度器做不到这一点——新请求在步边界插入、完成的请求在步边界退出，批的组成每步都在变，B_eff 是一个随步波动的量而非常数。把波动的 B_eff 替换为某个代表值（均值或峰值）代入，是公式可计算的前提，也是误差的主要来源。用峰值代入会高估步时延、低估吞吐；用均值代入会低估尾延迟，因为尾延迟恰恰发生在批最满的那几步。</p>\n<p>第二层近似在预填与解码的混批。当调度器把一条长前缀请求的预填块插入到正在解码的批中（chunked prefill），该步的算力被预填块占用，同批其他请求的 token 间隔被拉长。公式中预填项与解码项是相加关系，隐含“预填只花自己那份摊薄时间”的假设，无法表达这种插入造成的瞬时气泡。工程后果是：长前缀请求密集到达时，已在解码的短请求会观察到 token 间隔的尖峰，尾延迟显著高于公式预测。要修正，需在步时延中显式加入预填块占用项，或按 chunk 粒度做分步仿真而非闭式求值。</p>\n<p>第三层近似是 W_q 的确定性处理。公式把排队等待写成一个待定符号，本身不含到达率与服务率的关系；一旦要用它做容量规划，就必须把 W_q 替换为排队论的解。而排队论解依赖到达过程的分布假设，用平均到达率代入泊松近似在突发流量下会系统性低估尾延迟——突发到达会形成瞬时队列深度远超稳态均值，而尾延迟由队列深度的尾部分布决定，不由均值决定。这是公式最常见的失效路径：稳态算得通，上线后 P99 远超预测。</p>\n<p>第四层是 max 的重叠理想化。真实硬件上固定开销与带宽传输部分重叠但非完全重叠，取 max 相当于假设重叠率为 100%，在小批时低估步时延、在大批时高估固定开销的相对权重。这个误差量级通常小于前三层，但在极短输出（S_o 很小）的场景下，固定开销占比高，max 的乐观偏差会直接体现在端到端时延上。</p>\n\n<h3 id=\"th-batch-latency-model-sec-9\">九 · 用公式做工程判断：三个可算的边界</h3>\n<p>第一个边界是给定 SLA 下的最大批大小。把目标端到端时延 T_sla 代入，固定 S_p、S_o、W_q 的估计值，解出允许的 B_eff 上限：当解码步带宽受限时，B_eff 的可行域由 S_o·(W+2LHd·B_eff)/BW ≤ T_sla − W_q − S_p·t_prefill/B 给出，即 B_eff 与输出长度成反比。这意味着长输出请求与大批并发不可兼得，调度器若把长输出请求与大批混在一起，尾延迟必然被长输出请求拉爆。工程上对应的做法是按预测输出长度分池，而非全局一个批大小。</p>\n<p>第二个边界是最大可接受输出长度。反过来固定 B_eff，解出 S_o 的上限，就得到在当前并发下不破坏 SLA 的最长输出。这个数直接决定是否需要对超长输出请求做降级处理（如限制 max_tokens、或迁移到专用池），也决定投机解码的收益空间：投机解码降低的是有效 S_o 对应的步数，当 S_o 上限被带宽项压得很低时，减少步数比增大批更能改善时延。</p>\n<p>第三个边界是带宽受限与固定开销受限的切换点。令 (W+2LHd·B_eff)/BW = t_step^base，解出临界 B_eff*：低于它时加批几乎不损时延，高于它时每加一条序列都在线性侵蚀单请求时延。这个临界点由模型权重规模、层数头维、带宽与 kernel 启动开销共同决定，是可测量的——用两个不同批大小的实测步时延反推即可定位，无需精确知道各常数。定位之后，容量规划就有了明确的“免费区”与“付费区”之分。</p>\n<p>这三个边界的共同前提是公式的确定性近似成立。一旦流量突发性显著，W_q 的尾部会吞掉全部余量，此时任何基于均值的批大小计算都失去意义，必须改用基于到达分布尾部的排队模型，或直接以实测 P99 做闭环限流。</p>\n\n<h3 id=\"th-batch-latency-model-sec-10\">十 · 误用与修正：把公式用在它成立的地方</h3>\n<p>最常见的误用是把 B 当作免费吞吐杠杆：只看到吞吐随批增大而上升，未计入解码步时延随 B_eff 线性增长对单请求时延的侵蚀。公式的第三项已经把这条代价写死——只要处于带宽受限侧，B_eff 每增加一份，每步时间就增加 2LHd/BW 那么多，乘以 S_o 就是端到端时延的净增量。忽略这一项做的容量规划，在低负载时看似宽裕，一旦并发逼近临界点，时延会以斜率 2LHd·S_o/BW 上升，没有任何缓冲。</p>\n<p>第二个误用是用平均到达率估算 W_q。修正方式不是把公式改复杂，而是承认公式只给确定性近似，把 W_q 交给独立的排队模型或在线测量：以实测的排队时长分布替代解析解，把公式的其余两项保留为结构性下界。这样公式的角色从“预测器”转为“分解器”——它告诉你时延由哪三块构成、哪一块是带宽下界、哪一块是排队，但不负责给出精确的绝对值。</p>\n<p>第三个误用是忽略混批气泡与 chunked prefill 插入。修正的工程判断是：只要系统开启了 chunked prefill，就必须把预填块的插入视为步时延的额外项，而非预填项的摊薄。判断依据是预填块大小与解码批的带宽占用之比——预填块越大、解码批越满，插入造成的气泡越不可忽略。此时公式的应用方式应改为分步核算：对每个含预填块的步单独计算其步时延，再对纯解码步用带宽下界，最后求和，而不是用一个平均步时延乘 S_o。</p>\n<p>把公式用对的核心，是始终记住它是一个下界分解而非精确预测：第二项和第三项给出的是结构性下界，可信；W_q 与混批气泡是模型外的扰动，必须靠测量与排队论补齐。工程上真正有价值的不是公式算出的那个数，而是它强制你把时延拆成“排队、摊薄预填、带宽受限步时延”三块，并据此判断当前瓶颈在哪一侧、加批是否还有免费空间、以及是否该转向减少步数的技术路线。</p>\n<h3 id=\"th-batch-latency-model-sec-11\">十一 · 同步推进假设与抢占缺失：公式的第一道裂缝</h3>\n<p>公式把每个解码步写成所有序列齐步走一格，这在物理上要求调度器在每个 step 边界做一次全局同步。真实调度器做不到这一点：请求在不同时刻到达、在不同时刻结束，批内序列的长度参差，一个序列结束就意味着下一 step 的批形状变化。更关键的是抢占（preemption）。当 KV cache 池逼近容量上限时，调度器必须驱逐某些序列的 KV 块以腾出空间给新请求或更长的序列，被驱逐的序列要么重算预填（recompute），要么换出到主机内存再换回（swap）。这两种操作都会让该序列的 token 间隔出现一个远大于单步时延的尖峰，而公式里没有任何一项对应它。</p>\n<p>把抢占代价写进模型的最小改动是给解码项乘一个放大因子：</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx W_q + \\frac{S_p\\,t_{\\text{prefill}}}{B} + S_o \\cdot \\max\\!\\left(t_{\\text{step}}^{\\text{base}}, \\frac{W + 2LHd\\,B_{\\text{eff}}}{\\text{BW}}\\right) \\cdot \\left(1 + \\rho_{\\text{pre}}\\cdot \\frac{S_p}{S_o}\\right)$$</div>\n<p>其中 ρ_pre 是单位输出 token 上摊到的重算预填比例，它由 KV 池压力决定而非由请求本身决定。工程含义很直接：同一套公式在 KV 池宽裕时预测准确，在池子打满时系统性低估。判断阈值不在公式里，而在 KV 占用率——一旦活跃序列的 KV 块需求超过池容量的某个比例，抢占开始频繁发生，尾延迟曲线会出现拐点。这个拐点的位置取决于块大小、序列长度分布和到达率，需要用实测的驱逐计数来标定，而不是从公式推出来。</p>\n<p>代价层面：抢占重算直接把预填计算量翻倍计入关键路径，对长前缀请求尤其昂贵；换出换回则额外占用主机到设备的链路带宽，与解码步抢同一份 PCIe 或 NVLink 带宽。一个具体场景是长文档问答服务，前缀动辄数万 token，一旦发生一次重算，该请求的端到端时延增加的量级等同于一次完整预填，而同批其他请求在这一 step 内被拖慢。</p>\n\n<h3 id=\"th-batch-latency-model-sec-12\">十二 · 混批气泡：prefill 插入如何污染 decode 步</h3>\n<p>公式的第二项把预填时间除以批大小 B 做摊薄，隐含假设预填与解码在时间上完全重叠、互不干扰。实际系统里，预填和 decode 混批（mixed batching）时，一个长预填请求会占据该 step 的绝大部分计算量，decode 序列只能分到剩余的算力。结果是这一 step 的 token 间隔被拉长，而拉长的幅度与该预填的长度成正比，与批内 decode 序列数无关。这就是气泡：算力被预填吃掉，decode 序列空等。</p>\n<p>chunked prefill 是缓解手段而非消除手段。它把长预填切成若干 chunk，每个 step 插入一个 chunk，使单 step 的预填占比有上界。但插入本身仍然占用 step 时间：设 chunk 大小为 C，则每个含 chunk 的 step 的时延近似为</p>\n<div class=\"formula\">$$t_{\\text{step}}^{\\text{mixed}} \\approx \\max\\!\\left(t_{\\text{step}}^{\\text{base}},\\ \\frac{W + 2LHd\\,B_{\\text{eff}}}{\\text{BW}}\\right) + \\frac{C\\,t_{\\text{prefill}}}{B}$$</div>\n<p>只要 C 不为零，decode 序列的 token 间隔就被周期性拉长，其方差而非均值才是 SLO 的杀手。对延迟敏感的在线服务，尾延迟由最坏的那个含大 chunk 的 step 决定。工程判断：chunk 大小的选择是在预填吞吐（chunk 太小则预填请求的完成时间被拉长）与 decode 抖动（chunk 太大则同批 decode 序列被周期性打断）之间的权衡，公式给不出最优点，只能给出量级——把 C 控制到使 C·t_prefill/B 与带宽下界同阶，抖动就被压在可接受范围。</p>\n<p>代价体现在两个方向：预填请求自身的完成时延随 chunk 数线性增加（每 chunk 一次调度开销与一次 kernel 启动），而 decode 序列的 p99 token 间隔随 chunk 大小上升。这两项代价在公式里都没有位置，因此用公式做容量规划时必须对混批场景单独留出裕量。</p>\n\n<h3 id=\"th-batch-latency-model-sec-13\">十三 · 排队项的分布依赖：平均到达率是陷阱</h3>\n<p>W_q 在公式里是一个标量，但它本质上是随机变量。用平均到达率 λ 和平均服务率 μ 代入一个确定性排队近似，只在到达过程接近泊松且利用率不高时勉强可用。真实推理服务的到达过程有明显突发性：上游批处理任务集中提交、对话会话在同一时刻被多个用户触发、定时任务在同一秒内涌入。突发到达下，瞬时利用率可以远超平均值，队列长度按 Lindley 递推迅速累积，尾延迟呈指数级恶化，而基于平均值的模型完全看不到这一点。</p>\n<p>要把突发性纳入，至少需要到达过程的二阶矩。用 Kingman 近似给出等待时间的量级：</p>\n<div class=\"formula\">$$E[W_q] \\approx \\frac{\\rho}{1-\\rho}\\cdot\\frac{c_a^2+c_s^2}{2}\\cdot E[S]$$</div>\n<p>其中 ρ 为利用率，c_a 与 c_s 分别为到达间隔与服务时间的变异系数。这个式子说明：同样 70% 的利用率，到达变异系数从 1 升到 3，等待时间期望翻数倍。工程上这意味着容量规划不能只看平均 QPS，必须测到达间隔的分布形状；对突发型负载，要么按峰值到达率配置容量，要么在入口做削峰（队列+限流），把 c_a 压下来。</p>\n<p>具体例子：一个代码补全服务在早高峰出现集中请求，平均利用率看似只有六成，但瞬时到达率把队列推到数十个请求等待，p99 端到端时延远超按平均值算出的预测。这不是公式算错了，是公式的输入假设不成立。代价是显存与算力按峰值配置带来的闲置，或者按均值配置带来的 SLO 违约——两者之间的选择需要业务侧给出违约成本。</p>\n\n<h3 id=\"th-batch-latency-model-sec-14\">十四 · 规模上限：B_eff 线性项与固定开销项的交叉点</h3>\n<p>公式的解码项取 max，意味着存在一个批大小区间，步时延由带宽下界主导，超过某个点后由固定开销主导——但方向常被误读。带宽下界项 W+2LHd·B_eff 随 B_eff 线性增长，而 t_step^base 是常数。在 B_eff 较小时，带宽项低于固定开销，步时延被 kernel 启动、调度、同步等固定成本锁住，此时增大批几乎不增加步时延，吞吐线性上升，这是连续批处理的甜区。当 B_eff 增大到使带宽项超过固定开销，步时延开始随 B_eff 线性上升，单请求时延同步恶化。</p>\n<p>交叉点给出批大小的软上限：</p>\n<div class=\"formula\">$$B_{\\text{eff}}^{*} \\approx \\frac{t_{\\text{step}}^{\\text{base}}\\cdot \\text{BW} - W}{2LHd}$$</div>\n<p>这个式子的工程价值在于它把“批能开多大”从经验变成可算的量。分子里 t_step^base 与 BW 都是硬件与实现相关的常数，分母 2LHd 是每序列每 token 的 KV 读取量。模型越深、头数越多、KV 头维度越大，分母越大，软上限越低——这解释了为什么长上下文、大模型的服务在批大小上很快撞墙。超过这个点继续加批，吞吐增益被步时延上升吃掉，单请求时延恶化，SLO 先崩。</p>\n<p>代价与例子：一个 70B 级模型、长上下文服务，KV 读取量使 B_eff* 落在几十的量级；把批从 32 拉到 128，聚合吞吐可能只提升有限比例，而 p99 token 间隔翻倍。此时正确的动作不是继续加批，而是降低每步读取量——量化 KV cache、用更紧凑的 KV 布局、或改用投机解码减少步数（后者是另一条条目的主题，此处只指路）。规模上限还有第二层：B_eff 受 KV 池容量硬约束，容量公式本身是另一条条目的内容，这里只强调它与时延模型的耦合——池子满了触发抢占，回到第一节的失效模式。</p>\n\n<h3 id=\"th-batch-latency-model-sec-15\">十五 · 精度与硬件假设：带宽项里的隐含常数</h3>\n<p>带宽下界项里的 W 与 2LHd 都隐含了数据精度。W 是权重读取量，若权重以 FP8 或 NVFP4 存储，W 相应缩小；KV cache 若量化到 FP8，2LHd 项减半。公式没有显式写出精度因子，导致同一公式在 BF16 与 FP8 部署下给出不同的预测而使用者不自知。正确做法是把精度写进读取量：</p>\n<div class=\"formula\">$$R_{\\text{step}} \\approx \\alpha_w W + \\alpha_{kv}\\cdot 2LHd\\,B_{\\text{eff}}$$</div>\n<p>α_w、α_kv 为权重与 KV 的每元素字节数比值。这带来一个反直觉的结论：量化不仅省显存，还直接抬高 B_eff* 的软上限，因为分母变小。代价是量化误差对输出质量的影响，那是量化条目的主题，此处只指出时延模型必须带上精度因子，否则跨配置比较会得出错误结论。</p>\n<p>硬件侧还有一层：公式假设显存带宽是唯一瓶颈，且带宽可被充分利用。实际解码步的带宽利用率受限于 kernel 的访存模式、SM 占用与 TMEM 使用方式；在小批、短序列时，实际可达带宽低于峰值，公式低估步时延。Blackwell 上的 tcgen05 与 2-SM MMA 改变的是计算侧效率，对带宽受限的解码步帮助有限，但对预填项 t_prefill 有实质影响。因此公式在预填主导的场景（长前缀、短输出）预测偏差更大，需要单独标定 t_prefill 而非套用解码侧的带宽假设。</p>\n<p>工程判断落在最后这一点上：时延模型的适用边界不是一条线，而是三条——KV 池压力决定抢占是否发生，到达分布决定 W_q 是否可信，B_eff 与精度决定解码项是否还在带宽区。三者任一越界，公式就从定量预测退化为量级参考，此时应切换到基于实测尾延迟的闭环容量控制，而不是继续外推公式。</p>\n\n<h3 id=\"th-batch-latency-model-sec-16\">十六 · 公式的适用边界：同步推进、无抢占与带宽下界的成立条件</h3>\n<p>该时延模型成立的前提是批内序列同步推进且无抢占：每个解码步中所有活跃序列各贡献一个 token，步时延由最慢的那条决定，而没有任何请求被中途换出或插入。真实调度器在 prefill 与 decode 混批时会产生气泡——一个长前缀预填占据 SM 与带宽，同批解码序列的 token 间隔被拉长，而公式把预填项摊到 B 上、把解码项独立计算，等于假设两者互不干扰。chunked prefill 进一步打破这一假设：它把长预填切成若干块插入解码步之间，块边界处的 kernel 启动与流水排空使实际步时延高于 max 项给出的下界，长前缀请求越多，同批其他请求的 token 间隔抖动越大，公式对尾延迟系统性低估。</p>\n<p>第二项带宽下界的成立还依赖一个隐含条件：解码步确实由显存带宽支配。当 B_eff 很小或序列极短时，读量 W+2LHd·B_eff 不足以掩盖 kernel 启动、采样、调度等固定开销，此时 max 取到 t_step^base，步时延与批大小几乎无关；一旦 B_eff 增大到带宽项超过固定开销，步时延随 B_eff 线性上升，单请求时延随之恶化。判断当前处于哪一侧，决定了“加批”是免费吞吐还是时延侵蚀：</p>\n<table class=\"mini\"><thead><tr><th>区间</th><th>步时延主导项</th><th>加批的后果</th></tr></thead><tbody><tr><td>小批 / 短序列</td><td>t_step^base（固定开销）</td><td>吞吐近线性增长，单请求时延基本不变</td></tr><tr><td>大批 / 长序列</td><td>(W+2LHd·B_eff)/BW</td><td>吞吐增益递减，单请求时延线性恶化</td></tr></tbody></table>\n<p>W_q 是模型中最不可靠的一项。它由到达率与服务率的分布共同决定，公式只给出确定性近似；用平均到达率代入，等于假设流量平滑，而真实推理负载的突发性使排队长度在短时间内远超均值，上线后尾延迟远超预测——这是该模型最常见的失效方式。正确做法是把到达过程按泊松或更重尾的分布建模，用排队论求 W_q 的尾分位数而非均值，并把服务率本身视为随 B_eff 变化的随机量。当突发持续时间接近或超过单请求服务时间时，确定性近似彻底失效，此时应改用基于实测尾延迟的容量余量而非公式外推。</p>\n<div class=\"formula\">$$ T_{\\text{e2e}}^{\\text{tail}} \\gtrsim W_q^{(p)} + \\frac{S_p\\,t_{\\text{prefill}}}{B} + S_o \\cdot \\max\\!\\left(t_{\\text{step}}^{\\text{base}},\\; \\frac{W + 2LHd\\,B_{\\text{eff}}}{\\text{BW}}\\right) + \\Delta_{\\text{bubble}} $$</div>\n<p>规模上限体现在两处：B_eff 不能无限增大，因为带宽项线性上升会吃掉单请求时延预算；S_o 也不能无限长，因为步时延误差随输出长度累积。工程判断是先用公式定位解码步处于固定开销受限还是带宽受限，再决定是加批、改投机解码降步数，还是用 chunked prefill 平滑预填插入——三者对 Δ_bubble 与 B_eff 的影响方向不同，混用而不区分区间，公式给出的“最大可接受批大小”就没有意义。</p>\n<h3 id=\"th-batch-latency-model-sec-17\">十七 · 从公式到决策变量：四个可调旋钮</h3>\n<p>把 <span class=\"formula\">$$T_{\\text{e2e}} \\approx W_q + \\frac{S_p\\,t_{\\text{prefill}}}{B} + S_o \\cdot \\max\\!\\left(t_{\\text{step}}^{\\text{base}},\\; \\frac{W + 2LHd\\,B_{\\text{eff}}}{\\text{BW}}\\right)$$</span> 当作决策工具而不是解释工具，关键在于识别式子里哪些是<strong>你能拧的</strong>、哪些是<strong>你只能测的</strong>。可拧的旋钮有四个：批大小 <code>B</code>（调度器参数，决定预填摊薄与并发）、有效并发 <code>B_eff</code>（受 KV 预算与调度策略共同约束，通常小于 <code>B</code>）、并行度（切分 <code>W</code> 与 <code>2LHd</code> 在多少张卡上，直接改变分母 BW）、以及输出长度上限 <code>S_o</code>（由 <code>max_tokens</code> 与停止条件决定）。不可拧但必须测的有三个：<code>t_step^base</code>、<code>t_prefill</code>、以及 <code>W_q</code> 背后的到达过程。</p>\n<p>决策顺序应当是<strong>先定 SLO，再定 S_o 上限，再定 B_eff，最后反推并行度</strong>，而不是反过来先买卡再想能跑多少。原因在于式子的结构：<code>S_o</code> 是乘在步时延上的因子，它把任何步时延误差放大 <code>S_o</code> 倍；而 <code>B_eff</code> 只线性进入带宽项。先把 <code>S_o</code> 钉死，剩下的预算才是可以分配给批与并行的。一个具体机制：在 TensorRT-LLM 与 vLLM 中，<code>max_tokens</code> 与 <code>max_num_seqs</code> 分别是这两个旋钮的直接落点，前者写进请求模板，后者写进 scheduler 配置；二者共同决定 <code>B_eff</code> 的上界，因为 KV 预算不足时调度器会把 <code>B_eff</code> 压到低于 <code>max_num_seqs</code>。</p>\n\n<h3 id=\"th-batch-latency-model-sec-18\">十八 · 定批大小：解出 B 的可行区间而非单点</h3>\n<p>给定 SLO 上限 <code>T_slo</code>，把公式改写为对 <code>B_eff</code> 的不等式。先判断解码步处于哪个区制：若 <code>(W + 2LHd·B_eff)/BW &lt; t_step^base</code>，则步时延被固定开销钉住，此时增大批几乎免费，吞吐随 <code>B_eff</code> 线性上升而单请求时延不变——这是<strong>固定开销受限区</strong>。反之进入<strong>带宽受限区</strong>，步时延随 <code>B_eff</code> 线性上升，单请求时延被侵蚀，吞吐增益递减。</p>\n<div class=\"formula\">$$B_{\\text{eff}}^{\\max} \\approx \\frac{\\text{BW}}{2LHd}\\left(\\frac{T_{\\text{slo}} - W_q - S_p t_{\\text{prefill}}/B}{S_o} - t_{\\text{step}}^{\\text{base}}\\right)$$</div>\n<p>这个反解给出的是<strong>上限</strong>，工程上还要取一个下界：<code>B_eff</code> 太小则 <code>S_p·t_prefill/B</code> 项变大，预填摊薄失效，且 GPU 利用率塌陷。因此批大小是一个区间 <code>[B_min, B_max]</code>，而不是一个最优点。伪代码思路：对候选 <code>B_eff</code> 网格逐个代入原式，检查是否满足 <code>T_e2e ≤ T_slo</code>，同时记录该点的吞吐 <code>B_eff/S_o·t_step</code>，取满足约束的最大吞吐点。代价在于：这个网格搜索的每一格都需要一次实测 <code>t_step^base</code> 与 <code>t_prefill</code>，因为这两个量随 kernel 实现、序列长度分布、是否启用 CUDA Graph 而变，不能从规格表读出。</p>\n<p>具体例子：某在线服务 SLO 为单请求 P99 端到端 2 秒，<code>S_o</code> 上限 512，实测 <code>t_step^base</code> 为数十微秒量级而带宽项在 <code>B_eff</code> 超过某阈值后成为主导，则 <code>B_eff</code> 每翻一倍，步时延近似翻倍，512 步的输出被拉长到接近 SLO 边界。此时正确动作不是继续加 <code>max_num_seqs</code>，而是把 <code>S_o</code> 上限降到 SLO 允许的更小值，或引入投机解码压缩 <code>S_o</code> 的有效步数——后者是另一条条目的主题，此处只作为旋钮指路。</p>\n\n<h3 id=\"th-batch-latency-model-sec-19\">十九 · 定并行度：分母 BW 与分子 W 的赛跑</h3>\n<p>并行度决策的本质是问：把 <code>W</code> 与 <code>2LHd·B_eff</code> 切到 <code>N</code> 张卡上，分母 BW 变成 <code>N·BW_card</code>，但分子里的权重读量也变成 <code>W/N</code>，而 KV 读量 <code>2LHd·B_eff</code> 在张量并行下同样被切分。于是带宽受限区的步时延近似变为 <code>(W/N + 2LHd·B_eff/N)/(N·BW_card)</code>——注意这里出现 <code>N²</code> 的加速，但代价是每步都要做 all-reduce，通信量正比于激活大小，且随 <code>N</code> 增长。张量并行的通信下界是另一条条目的主题，此处只强调它对步时延的<strong>加性</strong>贡献：<code>t_step = max(带宽项, t_step^base) + t_comm(N)</code>。</p>\n<p>因此并行度不是越大越好。当 <code>B_eff</code> 很小（低负载、低并发）时，带宽项本就接近 <code>t_step^base</code>，加卡带来的分子缩小被通信开销吃掉，净收益为负；当 <code>B_eff</code> 很大时，带宽项主导，加卡收益显著。这给出一个工程判据：<strong>先测出当前工作点的区制，再决定是否扩并行度</strong>。显存侧的代价同样要计入：张量并行把 KV cache 按头切分到各卡，单卡 KV 预算下降，若 <code>B_eff</code> 受 KV 而非带宽约束，则加卡反而放宽了 <code>B_eff</code> 上限，两个效应要一起算。</p>\n<p>具体例子：一个长输出代码生成服务，<code>S_o</code> 常达数千 token，带宽项主导，此时把并行度从单卡提到多卡，步时延按 <code>N²</code> 量级下降，端到端时延中的 <code>S_o·t_step</code> 项被显著压缩；反之一个短问答服务 <code>S_o</code> 只有几十 token，固定开销主导，加卡只增加通信与功耗，SLO 不变而单位 token 成本上升。</p>\n\n<h3 id=\"th-batch-latency-model-sec-20\">二十 · 定 KV 预算：把 B_eff 从调度参数变成显存约束</h3>\n<p>公式里 <code>B_eff</code> 是\"有效批内并发序列数\"，它与调度器的 <code>max_num_seqs</code> 之间隔着一个 KV 预算。KV cache 容量公式是另一条条目的主题，此处只取它的输出：给定每 token 的 KV 字节数与可用显存，得到最大常驻序列数 <code>B_kv</code>。于是 <code>B_eff = min(max_num_seqs, B_kv, B_max)</code>，三个约束取最小。容量决策要问的是：<strong>当前 SLO 下，瓶颈是哪一个？</strong></p>\n<ul>\n<li>若 <code>B_max &lt; B_kv</code> 且 <code>B_max &lt; max_num_seqs</code>：带宽受限，加显存无用，应降 <code>S_o</code> 或提并行度。</li>\n<li>若 <code>B_kv</code> 最小：显存受限，加卡（切分 KV）或降精度存 KV 有效，但要注意 KV 量化对保真的影响是另一条条目的主题。</li>\n<li>若 <code>max_num_seqs</code> 最小：调度参数受限，纯配置问题，改配置即可，无需动硬件。</li>\n</ul>\n<p>这个三分法的工程价值在于避免\"加显存解决一切\"的惯性。显存扩容只在第二种情形下转化为吞吐；在第一种情形下它只是让 <code>B_kv</code> 更宽松，而 <code>B_eff</code> 仍被 <code>B_max</code> 钉住，吞吐不变、成本上升。代价维度上，KV 预算还影响功耗：常驻序列越多，每步读的 KV 字节越多，带宽功耗上升，这在 NVL72 整机柜的功率封顶下会成为真实约束。</p>\n\n<h3 id=\"th-batch-latency-model-sec-21\">二十一 · 定 SLO 与算例：把四个旋钮代进同一张表</h3>\n<p>算例设定（只做结构性推演，不引用具体实测数字）：某服务 <code>S_p</code> 平均 2k token，<code>S_o</code> 上限 1k token，<code>t_step^base</code> 与带宽项在同一量级，即工作点恰在区制边界附近。SLO 要求 P99 端到端不超过 <code>T_slo</code>。步骤一：用排队论而非平均到达率估 <code>W_q</code>，因为失败模式明确写着平均到达率会严重低估尾延迟；取 P99 到达间隔对应的等待时间代入。步骤二：把 <code>S_o = 1k</code> 代入，若 <code>S_o·t_step</code> 已占 <code>T_slo</code> 的大半，则说明输出长度是主要矛盾，先降 <code>max_tokens</code>。步骤三：反解 <code>B_eff^max</code>，得到带宽受限区允许的最大并发。步骤四：查 <code>B_kv</code> 与 <code>max_num_seqs</code>，取三者最小作为实际 <code>B_eff</code>。步骤五：若实际 <code>B_eff</code> 远小于 <code>B_eff^max</code>，说明瓶颈不在带宽，加卡无益；若接近，则考虑提并行度或投机解码。</p>\n<table class=\"mini\"><thead><tr><th>决策</th><th>公式中的位置</th><th>受限时的动作</th><th>代价维度</th></tr></thead><tbody>\n<tr><td>批大小</td><td><code>B</code>、<code>B_eff</code></td><td>降 <code>max_num_seqs</code> 或降 <code>S_o</code></td><td>吞吐下降、GPU 利用率塌陷</td></tr>\n<tr><td>并行度</td><td>分母 BW、分子 W</td><td>仅带宽受限区加卡有效</td><td>通信加性时延、功耗、单卡 KV 预算缩小</td></tr>\n<tr><td>KV 预算</td><td><code>B_eff</code> 上界</td><td>仅 <code>B_kv</code> 为瓶颈时扩容有效</td><td>显存、带宽功耗</td></tr>\n<tr><td>SLO / <code>S_o</code></td><td><code>S_o</code> 乘子</td><td>先钉死再分配其余预算</td><td>输出质量与任务完成度</td></tr>\n</tbody></table>\n<p>这张表的作用是把\"调参\"变成\"定位瓶颈\"。任何一次容量决策，先回答\"三个 min 里谁最小\"，再回答\"步时延在哪个区制\"，两个答案组合就唯一确定了该拧哪个旋钮。忽略这个顺序的典型后果是把批大小当免费杠杆——失败模式里明确列出：<code>B_eff</code> 线性推高步时延，单请求时延被侵蚀而吞吐增益递减，最终 SLO 破裂而吞吐并未如预期翻倍。</p>\n<p>最后落在机制上：这套用法成立的前提是<strong>公式里的量都是实测而非规格表推算</strong>。<code>t_step^base</code> 受 CUDA Graph 捕获与否影响，<code>t_prefill</code> 受 chunked prefill 切块大小影响，<code>W_q</code> 受到达分布影响——三者任一用错，反解出的 <code>B_eff^max</code> 就只是一个好看的数。工程判断因此是：把公式当<strong>约束求解器</strong>用，输入必须是本机本负载的实测值，输出必须回到实测验证一轮，否则它只是又一张纸面容量表。</p>\n\n<h3 id=\"th-batch-latency-model-sec-22\">二十二 · 把时延模型当旋钮用：定批、定并行、定 KV、定 SLO 的边界与代价</h3>\n<p>这个公式在容量决策里真正的用途不是\"预测一个数\"，而是把四个旋钮（批大小、并行度、KV 预算、SLO 目标）绑在同一条约束上做取舍。做法是反向求解：给定 SLO 的端到端上限 $T_{\\text{slo}}$ 与业务给定的输出长度 $S_o$，先由解码项解出可容忍的每步时延 $t_{\\text{step}}^{\\max}= (T_{\\text{slo}}-W_q-S_p t_{\\text{prefill}}/B)/S_o$，再判断它落在 $\\max$ 的哪一支。若 $t_{\\text{step}}^{\\max}\\le t_{\\text{step}}^{\\text{base}}$，说明该 SLO 下解码完全被固定开销支配，增大批几乎不花时延代价，此时批大小应直接顶到显存与 KV 预算允许的上限；若 $t_{\\text{step}}^{\\max}&gt;t_{\\text{step}}^{\\text{base}}$，则进入带宽受限支，反解 $B_{\\text{eff}}^{\\max}\\le \\big(t_{\\text{step}}^{\\max}\\cdot\\text{BW}-W\\big)/(2LHd)$，这就是\"给定 SLO 的最大可接受有效并发\"。注意反解出的是 $B_{\\text{eff}}$ 而非调度器里的 $B$：两者在混批、抢占、变长输出下并不相等，$B_{\\text{eff}}$ 才是真正压在带宽上的那部分序列数，把 $B$ 当免费杠杆的误用正是从这里开始的。</p>\n<p>并行度的定法要顺着同一个不等式走。张量并行把权重 $W$ 与 KV 读量按卡数切分，等效抬高了可用带宽、压低了每步的带宽项，但每层引入的集合通信把 $t_{\\text{step}}^{\\text{base}}$ 抬高——于是并行度存在一个由 $\\max$ 两支交叉点决定的最优区间：当解码步仍被带宽项支配时加卡是净收益，一旦跨过交叉点、步时延被固定开销（含 all-reduce 延迟）接管，再加卡只增加气泡与通信代价而不改善单请求时延。工程判断是：先用小批测得 $t_{\\text{step}}^{\\text{base}}$，再看目标 $B_{\\text{eff}}$ 下带宽项是否显著大于它，只有显著大于时才值得为这条链路扩并行度。KV 预算同理，$2LHd\\cdot B_{\\text{eff}}$ 既是步时延的分子也是显存占用的主体，KV 预算给得越松、可容纳的 $B_{\\text{eff}}$ 越大，但每步读的 KV 也越多，二者不是独立的两个优化目标而是一个变量的两面。</p>\n<div class=\"formula\">$$B_{\\text{eff}}^{\\max}=\\frac{t_{\\text{step}}^{\\max}\\cdot\\text{BW}-W}{2LHd},\\qquad t_{\\text{step}}^{\\max}=\\frac{T_{\\text{slo}}-W_q-S_p\\,t_{\\text{prefill}}/B}{S_o}$$</div>\n<p>算例（只做结构性推演，不代入虚构数值）：设某服务 SLO 为端到端上限 $T_{\\text{slo}}$，输出长度 $S_o$ 固定，测得固定步开销 $t_{\\text{step}}^{\\text{base}}$ 与权重读量 $W$。第一步按上式计算 $t_{\\text{step}}^{\\max}$；若它明显大于 $t_{\\text{step}}^{\\text{base}}$，则用第二式得 $B_{\\text{eff}}^{\\max}$，再与\"KV 预算能装下的序列数\"取小，得到真正可上线的批上限；若算出的 $B_{\\text{eff}}^{\\max}$ 小于 1，说明该 SLO 在单卡单副本上不可达，必须改走分离式部署、投机解码降 $S_o$ 的有效步数，或放宽 SLO。这里的关键是：投机解码之所以在这套模型里有位置，是因为它直接减少乘在步时延上的 $S_o$ 因子，而扩批只改变步时延本身，两者对 $T_{\\text{e2e}}$ 的作用路径不同，不能互相替代。</p>\n<table class=\"mini\"><thead><tr><th>决策</th><th>公式中的抓手</th><th>失效条件</th><th>系统代价</th></tr></thead><tbody><tr><td>定批大小</td><td>反解 $B_{\\text{eff}}^{\\max}$</td><td>混批气泡使实际尾延迟高于模型</td><td>步时延随 $B_{\\text{eff}}$ 线性上升，侵蚀单请求时延</td></tr><tr><td>定并行度</td><td>比较带宽项与 $t_{\\text{step}}^{\\text{base}}$</td><td>跨过交叉点后通信开销接管</td><td>集合通信抬高固定开销、增加气泡</td></tr><tr><td>定 KV 预算</td><td>$2LHd\\cdot B_{\\text{eff}}$</td><td>长前缀预填插入拉高同批 token 间隔</td><td>显存换并发，读带宽同步上升</td></tr><tr><td>定 SLO</td><td>$W_q$ 需排队论建模</td><td>用平均到达率代 $W_q$，突发下尾延迟远超预测</td><td>为尾延迟预留容量，牺牲平均吞吐</td></tr></tbody></table>\n<p>必须把边界写在决策文档里，否则这套反解会被当成精确预言。公式假设批内序列同步推进且无抢占，而真实调度器在 prefill 与 decode 混批时产生气泡，chunked prefill 又会把长前缀预填切片插入解码步，直接拉高同批其他请求的 token 间隔——这两项都让公式系统性低估尾延迟，因此反解出的 $B_{\\text{eff}}^{\\max}$ 应当作为上界而非目标值使用，实际配置要留出由气泡与插入带来的余量。更危险的是 $W_q$：它由到达率与服务率的分布共同决定，用平均到达率代入等于假设流量平滑，突发流量下确定性近似不成立，上线后尾延迟远超模型预测是这套方法最常见的翻车方式。正确的用法是把 $W_q$ 交给排队论按目标分位数（而非均值）估出，再代回反解，并把\"突发下模型失效\"作为容量规划的显式假设记录下来，让扩容决策基于分位数而非平均值。</p>\n<h3 id=\"th-batch-latency-model-sec-23\">二十三 · 误用一：用平均到达率喂 W_q，尾延迟被系统性低估</h3>\n<p>公式里 W_q 是排队等待项，但它的取值不由平均到达率单独决定。连续批处理调度器的服务时间分布是重尾的：一个 S_p 很长的预填请求会独占若干解码步的带宽预算，把同批其他请求的 token 间隔整体拉长。若用 λ 的平均值代入一个 M/M/1 式的 W_q = ρ/(μ−λ)，得到的等待时间只反映均值意义上的拥塞，而真实尾延迟由到达过程的突发性和服务时间的方差共同决定。工程上正确的做法是把 W_q 当作分布量而非标量：用到达间隔的二阶矩（或直接经验分布的 P99）进入排队模型，例如 G/G/1 的 Kingman 近似把等待时间写成 (ρ/(1−ρ))·((C_a²+C_s²)/2)·(1/μ)，其中 C_a、C_s 分别是到达与服务时间的变异系数。代价体现在容量决策上：按均值算出的最大批大小会让 P99 时延超出 SLO，而调度器为了守住 SLO 只能压低 B_eff，吞吐随之下降——这是一个被误用公式反向锁死的循环。识别方法很直接：把线上 W_q 的实测分布与模型预测的均值对比，若 P95/P50 的比值显著大于 1 而模型只给单一数值，就说明到达过程不是泊松式的，均值代入已经失效。</p>\n<p>具体例子：一个在线代码补全服务，平均每秒到达若干请求，均值负载看起来只有容量的六成，模型预测 W_q 很小。但补全请求高度同步于用户的键入节奏，短时间内成簇到达；每个请求的预填长度又因上下文差异跨度极大。结果是簇发期间 B_eff 被长预填请求占满，短请求的 W_q 实测值远超均值预测，尾延迟违约。修复不是调大 B，而是把 W_q 的输入换成簇发窗口内的瞬时到达率，并在调度侧对长预填做准入控制。</p>\n\n<h3 id=\"th-batch-latency-model-sec-24\">二十四 · 误用二：把 B 当成免费吞吐杠杆</h3>\n<p>公式第二项 max(t_step^base, (W+2LHd·B_eff)/BW) 已经写明解码步时延随 B_eff 线性上升，但实践中仍常见把批大小当作纯吞吐旋钮的用法：增大 B 提升 tokens/s，却不同步检查单请求时延项 S_o·t_step 的变化。误用的根源是把“吞吐”和“单请求时延”当成两个独立坐标，而实际上它们被同一个 B_eff 耦合。判断是否越界的工程判据是看解码步处于哪个受限区：当 (W+2LHd·B_eff)/BW 明显大于 t_step^base 时，步时延由带宽项主导，此时每增加一个并发序列，单请求的每 token 间隔就按 2LHd/BW 的斜率增加，S_o 越长，端到端时延的侵蚀越严重；反之若 t_step^base 主导，增大 B 在时延上近乎免费，这才是应当扩批的区间。代价是显存：KV cache 随 B_eff 线性增长，扩容批大小会挤压可用并发容量，这一点由 KV cache 容量公式单独约束，此处只需指路。</p>\n<p>识别信号：监控里 tokens/s 随 B 上升而单请求 P99 时延同步上升、且上升斜率与 2LHd/BW 估算吻合，就说明已经进入带宽受限区，继续扩批是在用尾延迟换吞吐。此时正确的动作不是继续加 B，而是降低 S_o 的期望（例如更早停止）、或改用投机解码压缩步数——后者降低的是 S_o 的有效值，与扩批是两条不同的杠杆。</p>\n\n<h3 id=\"th-batch-latency-model-sec-25\">二十五 · 误用三：忽略混批气泡与 chunked prefill 的插入</h3>\n<p>公式的失效条件里写明“假设批内序列同步推进且无抢占”，而真实调度器在 prefill 与 decode 混批时会产生气泡：一个长预填请求进入正在解码的批，会占掉该步的算力与带宽份额，使同批其他请求这一 token 的间隔被拉长，但它们的 S_o 计数不变，于是端到端时延被低估。chunked prefill 缓解了单步内的极端抢占，却引入了另一种插入效应：预填被切成若干 chunk 分散到多个解码步，每个 chunk 都抬高该步的 t_step，长前缀请求因此把同批所有请求的 token 间隔整体推高。代价是尾延迟：模型给出的 T_e2e 是确定性近似，而混批气泡让实际分布出现长尾，P99 与模型值的差距随预填长度方差增大而扩大。</p>\n<p>识别方法：在调度器里打点记录每个解码步的实际耗时与该步内并发序列数，若存在“步耗时显著高于同 B_eff 下的带宽下界”的步，且这些步与预填 chunk 的注入时刻对齐，即为气泡证据。工程判断是：当预填长度分布方差大时，应把预填与解码在时间上分离（分离式预填/解码，见并行与通信条目），或对预填做长度分桶以稳定 chunk 尺寸，而不是继续用统一公式做容量规划。</p>\n\n<h3 id=\"th-batch-latency-model-sec-26\">二十六 · 反例：一次按均值做的容量规划如何在上线后失效</h3>\n<p>设一个推理服务，按公式做容量规划：取平均到达率算 W_q，取目标吞吐对应的 B 作为 B_eff，取平均 S_p 与平均 S_o，代入后得到满足 SLO 的批大小，据此确定副本数与显存预算。上线后出现两类违约。第一类发生在流量簇发窗口：瞬时到达率远高于均值，W_q 实测值超出预测，尾延迟违约——这是误用一。第二类发生在长上下文请求集中出现的时段：这些请求的 S_p 大，chunked prefill 的注入使同批短请求的 token 间隔被拉高，而模型里预填项只按 S_p·t_prefill/B 摊薄，未计入插入对 decode 步的抬升——这是误用三。两类违约叠加，服务在峰值时段的 P99 时延超出 SLO，运维的第一反应是扩副本，但扩副本降低了到达率密度却未改变单副本内的混批结构，尾延迟改善有限，成本却线性上升。</p>\n<p>正确的复盘路径是把公式拆成三个可独立验证的子模型：W_q 用经验到达分布做排队仿真而非均值代入；解码步时延用实测的 t_step 对 B_eff 做回归，确认受限区并标定斜率；预填插入效应用“预填 chunk 注入时刻 vs 步耗时”的对照实验量化。三者分别标定后，容量规划才从确定性近似升级为带分布假设的模型。代价是前期投入的观测与仿真工作量，收益是避免用扩副本这种昂贵且低效的手段去补模型的洞。</p>\n\n<h3 id=\"th-batch-latency-model-sec-27\">二十七 · 识别清单：什么时候不该信这个公式</h3>\n<p>把误用收敛成可操作的判据，比记住公式本身更有用。以下情形出现任意一条，就应停止用该公式直接做容量结论：到达过程有明显簇发（到达间隔变异系数显著偏离 1）；预填长度分布方差大且与解码请求混批；B_eff 已进入带宽受限区而 S_o 期望偏长；调度器存在抢占或优先级反转。每一条都对应公式的一个失效条件，而不是公式算错了——公式在它的假设域内是准确的确定性近似，误用发生在把假设域外的输入喂进去。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>被忽略的机制</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>均值代入 W_q</td><td>到达与服务时间的分布二阶矩</td><td>尾延迟预测偏低，SLO 违约</td><td>实测 P95/P50 远大于模型单一值</td></tr><tr><td>B 当免费杠杆</td><td>解码步时延随 B_eff 线性上升</td><td>吞吐升、单请求时延恶化</td><td>tokens/s 与时延同斜率上升</td></tr><tr><td>忽略混批气泡</td><td>预填 chunk 注入抬高同批步时延</td><td>长前缀拉高全体 token 间隔</td><td>步耗时峰值与 chunk 注入时刻对齐</td></tr></tbody></table>\n<p>最后落在工程判断上：这个公式的价值不在于给出一个可抄的数字，而在于它把端到端时延分解成排队、预填摊薄、解码步三个可分别观测、分别标定的项。误用的共同结构是把其中一项的输入从分布退化成标量，或把一项的耦合关系当成独立坐标。凡是能在监控里把这三项分别打点、并用实测分布替换标量输入的服务，公式就从纸面近似变成可校准的容量工具；做不到这一点的服务，扩副本只是在为模型的盲区付费。</p>\n\n<h3 id=\"th-batch-latency-model-sec-28\">二十八 · 误用与反例：把确定性近似当成 SLA 承诺书</h3>\n<p>这套时延模型最常见的误用，是把 <span class=\"formula-inline\">$$W_q$$</span> 用一个长期平均到达率 λ 与平均服务率 μ 直接代入，得到一条平滑的排队曲线，然后拿它去签 SLO。问题在于 <span class=\"formula-inline\">$$W_q$$</span> 不是由均值决定的，而是由到达过程与服务过程的分布共同决定的：突发到达时瞬时 λ 远超均值，队列在几十毫秒内堆到远高于模型预测的长度，而模型给出的确定性近似完全看不到这个尖峰。上线后表现为 p99 尾延迟远超预测，而 p50 却与模型吻合得很好——这正是“均值对了、分布错了”的典型指纹。识别方法很直接：把线上真实到达时间戳回放进去，用排队论（如 M/G/1 或带突发的到达过程）重算 <span class=\"formula-inline\">$$W_q$$</span> 分布，若 p99 与模型偏差显著而 p50 接近，即可判定是这一条误用。</p>\n<p>第二个反例是“批大小当免费杠杆”。工程上有人看到吞吐随批增大而上升，就把 <span class=\"formula-inline\">$$B_{\\text{eff}}$$</span> 一路推高，忽略了解码步时延项 <span class=\"formula-inline\">$$\\max\\!\\left(t_{\\text{step}}^{\\text{base}},\\; \\frac{W + 2LHd\\,B_{\\text{eff}}}{\\text{BW}}\\right)$$</span> 中带宽下界随 <span class=\"formula-inline\">$$B_{\\text{eff}}$$</span> 线性上升。一旦跨过固定开销主导的区间，每步时延就由显存带宽读量决定，单请求的 token 间隔被同批其他序列“摊薄”成线性恶化。后果是总吞吐确实涨了，但单请求端到端时延以 <span class=\"formula-inline\">$$S_o$$</span> 倍放大，SLO 从达标翻成超时。识别信号：增大批后 GPU 利用率与 tokens/s 同升，而 p99 每 token 间隔（ITL）同步抬升且近似线性——此时解码步已进入带宽受限区，继续加批只换来时延侵蚀。</p>\n<p>第三个失效条件更隐蔽：模型假设批内序列同步推进、无抢占，而真实调度器在 prefill 与 decode 混批时会产生气泡，chunked prefill 的长前缀块会插进 decode 步，把同批其他请求的 token 间隔整体拉高。公式里既没有气泡项，也没有插入项，于是尾延迟被系统性低估。反例：一个长前缀请求与一批短输出请求同批，短请求的 ITL 因长预填块的插入而出现规律性尖刺，模型预测的平滑步时延无法解释。识别方式是看 ITL 的时间序列而非均值：若尖刺与 prefill 事件对齐，即为混批气泡与 chunked prefill 插入所致，此时应把预填与解码在调度层分离或限制单步预填块大小，而不是继续调公式参数。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>模型盲区</th><th>可观测指纹</th><th>系统代价</th></tr></thead><tbody><tr><td>均值代入 W_q</td><td>到达分布与突发</td><td>p50 吻合、p99 远超</td><td>尾延迟违约</td></tr><tr><td>无限增大 B</td><td>步时延随 B_eff 线性升</td><td>吞吐升、ITL 线性恶化</td><td>单请求时延侵蚀</td></tr><tr><td>忽略混批气泡</td><td>prefill/decode 抢占与插入</td><td>ITL 尖刺对齐 prefill</td><td>同批请求被拖慢</td></tr></tbody></table>\n<p>工程判断落在一条边界上：该公式只用于确定性近似下的容量下界与受限类型判别——判断解码步是固定开销受限还是带宽受限、给定 SLA 下最大可接受批与最大输出长度——而不能当作尾延迟承诺。凡涉及突发、混批、长前缀插入的场景，必须用排队论补 <span class=\"formula-inline\">$$W_q$$</span> 分布、用调度层隔离预填，否则模型越“精确”，离线上真相越远。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>W_q</td><td>排队等待时间</td></tr><tr><td>S_p</td><td>预填 token 数</td></tr><tr><td>S_o</td><td>输出 token 数</td></tr><tr><td>t_{\\text{prefill}}</td><td>单位预填 token 计算时间</td></tr><tr><td>B_{\\text{eff}}</td><td>有效批内并发序列数</td></tr><tr><td>t_{\\text{step}}^{\\text{base}}</td><td>固定步开销（kernel 启动等）</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-batch-latency-model · 共 5 个片段</p>\n"},{"id":"th-constrained-decode-rate","title":"约束解码的语法掩码开销","direction":"dir-retrieval-repo","prereq":[],"plain":"语法约束解码每步需对词表施加掩码，掩码计算与词表规模、解析器状态数成正比，当掩码无法与采样融合时会引入额外带宽与同步开销，其下界由词表大小与每 token 掩码字节数决定。","definition":"语法约束解码每步需对词表施加掩码，掩码计算与词表规模、解析器状态数成正比，当掩码无法与采样融合时会引入额外带宽与同步开销，其下界由词表大小与每 token 掩码字节数决定。","formula":"$$ t_{\\text{mask}} \\;\\ge\\; \\frac{|V| \\cdot b_{\\text{mask}}}{\\text{BW}_{\\text{HBM}}} \\cdot \\left(1 + \\kappa_{\\text{parser}}\\right) $$","variables":[{"sym":"|V|","meaning":"词表大小"},{"sym":"b_{\\text{mask}}","meaning":"每词表项掩码字节数"},{"sym":"\\kappa_{\\text{parser}}","meaning":"解析器状态维护相对开销"}],"derivation":"推导关键一步：假设掩码必须物化为每词表项 b_mask 字节的位图并写回 HBM、再被采样 kernel 读回，则单步至少搬运两倍掩码字节，取带宽倒数得时间下界；再乘以解析器状态维护的相对开销因子，得到含文法复杂度的保守估计。","example":"用途：容量决策时用它判断约束解码是否成为每 token 延迟的瓶颈——若 $$t_{\\text{mask}}$$ 与目标模型单步前向时间同量级，则需改用融合掩码或状态机方案；也可据此估算高并发下掩码读写占用的额外 HBM 带宽份额，决定是否值得为结构化输出单独部署。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["假设掩码需物化到 HBM；若在 kernel 内即时计算或使用预编译状态机可大幅降低，公式仅给物化路径下界","解析器状态数 κ_parser 随文法复杂度增长，JSON Schema 与嵌套语法差异巨大，单一常数不具普适性","未计入掩码错误导致的回退重采样成本，约束过严时有效候选集缩小会改变采样分布"],"system_note":"常见误用：把该式当作所有约束解码的固定成本，忽略即时计算路径，从而错误否决结构化输出方案；或对 JSON Schema 与深层嵌套文法套用同一 κ_parser，低估解析器状态爆炸带来的开销。后果是延迟预估偏差大、批处理容量规划失准。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["直觉：语法约束解码每一步都要把词表中不合文法的 token 屏蔽掉，掩码要么物化到显存再与 logits 逐元素作用，要么在 kernel 内即时判定；无论哪条路径，开销都随词表规模与解析器状态维护成本增长。","公式含义：$$t_{\\text{mask}} \\ge \\frac{|V| \\cdot b_{\\text{mask}}}{\\text{BW}_{\\text{HBM}}} \\cdot (1 + \\kappa_{\\text{parser}})$$ 中，$$|V|\\cdot b_{\\text{mask}}$$ 是每步需读写的掩码字节数，除以 HBM 带宽得到纯带宽下界；κ_parser 是解析器状态推进与判定相对该带宽项的附加开销系数，反映文法复杂度。","推导关键一步：假设掩码必须物化为每词表项 b_mask 字节的位图并写回 HBM、再被采样 kernel 读回，则单步至少搬运两倍掩码字节，取带宽倒数得时间下界；再乘以解析器状态维护的相对开销因子，得到含文法复杂度的保守估计。","适用边界：该下界只对“物化掩码”路径成立；若在采样 kernel 内即时计算合法性或用预编译状态机/DFA 跳过物化，实际开销可远低于此式。κ_parser 不是普适常数，JSON Schema、嵌套文法、正则与上下文无关文法的状态数差异巨大，单一系数会严重失真。","用途：容量决策时用它判断约束解码是否成为每 token 延迟的瓶颈——若 $$t_{\\text{mask}}$$ 与目标模型单步前向时间同量级，则需改用融合掩码或状态机方案；也可据此估算高并发下掩码读写占用的额外 HBM 带宽份额，决定是否值得为结构化输出单独部署。","常见误用：把该式当作所有约束解码的固定成本，忽略即时计算路径，从而错误否决结构化输出方案；或对 JSON Schema 与深层嵌套文法套用同一 κ_parser，低估解析器状态爆炸带来的开销。后果是延迟预估偏差大、批处理容量规划失准。","失效条件补充：公式未计入掩码错误导致的回退重采样成本；约束过严使有效候选集急剧缩小，会改变采样分布并可能触发重采样循环，实际每 token 代价高于带宽下界，且输出多样性下降。"],"anchors":[],"pitfalls":["把物化掩码的带宽下界当成约束解码的普遍成本，未评估 kernel 内即时判定或预编译状态机路径，导致错误放弃结构化输出。","对不同文法套用同一 κ_parser 常数，忽略 JSON Schema 与嵌套文法状态数的数量级差异，使延迟与容量预估严重偏离实测。","只计算掩码开销而忽略约束过严引发的回退重采样，有效候选集缩小时实际每 token 代价上升且采样分布被扭曲。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-1\">一 · 一句话直觉：掩码是每步都要过的“合法性闸门”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-2\">二 · 严格定义：掩码、解析器状态与合法集合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-3\">三 · 为什么需要：不是“锦上添花”，是正确性与可用性的硬约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-4\">四 · 常见误解：把下界当普适成本，把系数当常数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-5\">五 · 工程判断：先问路径，再问系数，最后问回退</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-6\">六 · 掩码成本的三条边界：物化路径、文法系数与回退重采样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-7\">七 · 逐项拆解：三个因子各自量的是什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-8\">八 · 推导关键步：为什么是“两倍搬运”与带宽倒数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-9\">九 · 离散化与近似落在哪里</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-10\">十 · 代价落点：延迟、带宽份额与容量判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-11\">十一 · 具体例子：同一公式在两种文法上的读数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-12\">十二 · 掩码下界的适用边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-13\">十三 · 物化假设：公式成立的唯一路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-14\">十四 · κ_parser 不是常数：文法复杂度的数量级差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-15\">十五 · 有效候选集收缩：公式之外的采样代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-16\">十六 · 规模上限：词表、并发与批内异构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-17\">十七 · 失效条件的工程清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-18\">十八 · 掩码下界公式的成立条件与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-19\">十九 · 把 t_mask 折算成每 token 的时间预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-20\">二十 · 定批大小：掩码带宽是批的公共分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-21\">二十一 · 定并行度：掩码不随 TP 缩小</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-22\">二十二 · 定 KV 预算：掩码开销挤压的是并发而非显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-23\">二十三 · 定 SLO：把掩码误差与回退重采样计入尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-24\">二十四 · 算例：一份结构化输出实例的容量表</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-25\">二十五 · 把掩码下界放进容量方程：批大小、并行度与 SLO 的联动</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-26\">二十六 · 误用一：把物化下界当成普遍成本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-27\">二十七 · 误用二：单一 κparser 套所有文法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-28\">二十八 · 误用三：只算掩码，不算回退重采样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-29\">二十九 · 反例：一个嵌套 Schema 的容量误判</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-30\">三十 · 识别清单与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-constrained-decode-rate-sec-31\">三十一 · 误用与反例：把物化路径的下界当成普遍成本</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:597px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 597.1 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：语法约束解码每步需对词表施加掩码，掩码计算与词表规模、解析器状态数…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$ t_{\\text{mask}} \\;\\ge\\; \\frac{…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"515.1\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：假设掩码需物化到 HBM；若在 kernel 内即时计算或使用预编…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-constrained-decode-rate-sec-1\">一 · 一句话直觉：掩码是每步都要过的“合法性闸门”</h3>\n<p>语法约束解码的直觉可以压缩成一句话：<strong>每生成一个 token，都要先把词表里不合文法的候选屏蔽掉，再在剩下的合法集合里采样。</strong>这句话里藏着两个动作，一个“判定”，一个“作用”。判定是拿当前解析器状态去问词表里每一个 token“你能不能接在这儿”；作用是把这个判定结果变成 logits 上的一个偏置，让非法 token 的概率被压到负无穷。工程上真正决定开销的不是“约束”这个概念本身，而是这两个动作被放在哪里执行：掩码要么被物化成一块与词表等长的位图写进显存、再被采样 kernel 读回来逐元素作用，要么在采样 kernel 内部即时判定合法性、根本不落盘。前一条路径的开销由词表规模和每项掩码字节数主导，后一条路径的开销由解析器状态推进的复杂度主导。两种路径的代价结构完全不同，把它们混为一谈是这一领域最常见的工程误判。</p>\n<p>需要强调的是，这里的“闸门”是<em>逐步</em>的，不是一次性的。自回归解码每吐一个 token，解析器状态就前进一步，合法集合随之改变，掩码必须重算。这意味着掩码开销是挂在每 token 延迟上的固定项，会随批内序列数线性叠加，而不是一次预计算就能摊薄的成本。对结构化输出密集的负载（JSON、函数调用参数、SQL、DSL），这一项很容易从“可忽略”变成“与模型单步前向同量级”。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-2\">二 · 严格定义：掩码、解析器状态与合法集合</h3>\n<p>把直觉形式化。设词表为 <span class=\"sym\">V</span>，大小 <span class=\"sym\">|V|</span>；设文法 <span class=\"sym\">G</span> 由一个解析器 <span class=\"sym\">P</span> 承载，<span class=\"sym\">P</span> 在读到前缀 <span class=\"sym\">s</span> 后处于状态 <span class=\"sym\">q = P(s)</span>。约束解码在步 <span class=\"sym\">t</span> 定义合法集合：</p>\n<div class=\"formula\">$$ L_t \\;=\\; \\{\\, v \\in V \\;:\\; \\delta(q_t,\\, v) \\text{ 有定义} \\,\\} $$</div>\n<p>其中 <span class=\"sym\">δ</span> 是解析器的转移函数，“有定义”意味着把 token <span class=\"sym\">v</span> 接到前缀后文法仍可继续。掩码就是 <span class=\"sym\">L_t</span> 的指示向量 <span class=\"sym\">m_t ∈ {0,1}^{|V|}</span>，采样时作用为 <span class=\"sym\">logits' = logits + (1 − m_t)·(−∞)</span>，等价于把非法项的概率置零后重新归一化。注意这里的掩码是<em>逐词表项</em>的，不是逐字符的：一个 token 可能对应多个字符（BPE 合并），判定必须对整段 token 文本做转移，这也是解析器开销随 token 长度而非 token 数增长的原因之一。</p>\n<p>把“掩码字节数”写清楚：若用位图表示，每词表项占 <span class=\"sym\">b_mask</span> 字节（典型是 1 bit 打包成字节，或直接用 1 字节布尔）。于是每步需要读写的掩码数据量为 <span class=\"sym\">|V| · b_mask</span>。这一步的纯带宽下界是：</p>\n<div class=\"formula\">$$ t_{\\text{mask}} \\;\\ge\\; \\frac{|V| \\cdot b_{\\text{mask}}}{\\text{BW}_{\\text{HBM}}} \\cdot \\left(1 + \\kappa_{\\text{parser}}\\right) $$</div>\n<p>式中 <span class=\"sym\">BW_HBM</span> 是 HBM 带宽，<span class=\"sym\">κ_parser</span> 是解析器状态推进与判定相对该带宽项的附加开销系数。这个式子的推导关键一步是：假设掩码必须物化为每词表项 <span class=\"sym\">b_mask</span> 字节的位图、写回 HBM、再被采样 kernel 读回，则单步至少搬运两倍掩码字节，取带宽倒数得时间下界，再乘上解析器维护的相对开销因子。它给出的是<strong>物化路径下的保守下界</strong>，不是约束解码的普遍成本——这一点在定义层面就必须钉死，否则后面的容量决策会全盘走偏。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-3\">三 · 为什么需要：不是“锦上添花”，是正确性与可用性的硬约束</h3>\n<p>需要掩码的理由分三层，每层的工程含义不同。第一层是<strong>正确性</strong>：函数调用、工具调用、结构化 API 输出要求模型吐出的字节流必须能被下游解析器接受，一个多余的逗号或缺失的右括号就让整条链路失败。重试一次的成本是整段前缀的重新前向，远高于每步掩码的开销。第二层是<strong>有效候选集收缩带来的采样质量</strong>：不加约束时模型可能把概率质量堆在语法非法但语义合理的 token 上，掩码把这些质量强制搬到合法项，等价于在合法子空间内重新归一化，输出更“守规矩”。第三层是<strong>可预测的延迟</strong>：结构化输出的长度和分支由文法决定，比自由文本更可控，这对 SLO 规划是利好。</p>\n<p>但第三层有个反噬：约束越严，有效候选集越小，采样分布被扭曲得越厉害。当合法集合只剩个位数 token 时，模型的偏好几乎被完全覆盖，输出多样性下降；更糟的是，若文法设计有歧义或解析器判定与模型意图错位，会出现“模型想吐的 token 全被屏蔽、只能退而求其次”的回退重采样循环，实际每 token 代价高于带宽下界。这一点公式里没有计入，属于失效条件的一部分。工程判断是：掩码开销要和“约束过严导致的回退成本”一起算，不能只算前者。</p>\n<p>具体例子：一个 JSON Schema 约束的响应，顶层是对象、字段名固定、值为枚举。解析器在读完 <span class=\"sym\">{</span> 后进入“期待键”状态，此时合法集合是若干固定键名对应的 token 序列，词表里绝大多数 token 被屏蔽。若这个 schema 嵌套三层、每层都有可选字段，解析器状态数随嵌套深度组合增长，<span class=\"sym\">κ_parser</span> 不再是常数，掩码重算的判定成本会盖过带宽项。这正是“JSON Schema 与深层嵌套文法不能套用同一系数”的由来。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-4\">四 · 常见误解：把下界当普适成本，把系数当常数</h3>\n<p>误解一：<strong>把物化掩码的带宽下界当成所有约束解码的固定成本。</strong> 这是最致命的。公式只在“掩码必须落 HBM 再读回”的路径上成立。若把合法性判定搬进采样 kernel 内部即时计算，掩码根本不物化，带宽项消失，剩下的只有解析器状态推进的算力开销；若进一步用预编译状态机或 DFA 把文法编译成转移表，判定退化成一次查表，开销可以远低于带宽下界。用物化下界去否决结构化输出方案，等于用最坏路径的估计去否定一条本可以走快路径的设计。</p>\n<p>误解二：<strong>对不同文法套用同一个 <span class=\"sym\">κ_parser</span>。</strong> 正则文法、JSON Schema、嵌套上下文无关文法的状态数差着数量级。正则的状态数与模式长度线性相关；JSON Schema 的状态数随字段数与嵌套深度组合爆炸；深层嵌套文法还要维护栈式状态。把同一个系数套到所有文法上，延迟预估会严重偏离实测，批处理容量规划随之失准。正确做法是按文法类别分别标定 <span class=\"sym\">κ_parser</span>，或在容量模型里把它当成随文法变化的输入而非常数。</p>\n<p>误解三：<strong>只算掩码开销、不算回退重采样。</strong> 约束过严使有效候选集急剧缩小，采样分布被改变，可能触发重采样循环，实际每 token 代价高于带宽下界，且输出多样性下降。容量规划若只按 <span class=\"sym\">t_mask</span> 估算，会低估高并发下结构化输出的真实延迟。</p>\n<p>误解四：<strong>把掩码当成“一次性预计算”。</strong> 掩码是逐步的，解析器状态每 token 前进一步，合法集合随之改变。批内不同序列处于不同解析器状态，掩码不能跨序列共享，只能按序列分别维护。这意味着掩码开销随批内序列数线性叠加，而不是被批处理摊薄——这是它与权重读取类开销（可被批摊薄）在代价结构上的根本区别。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-5\">五 · 工程判断：先问路径，再问系数，最后问回退</h3>\n<p>面对一个结构化输出负载，判断顺序应该是三段。第一段问路径：掩码是物化还是即时判定？物化路径下，用 <span class=\"sym\">|V|·b_mask/BW_HBM</span> 估算纯带宽项，与目标模型单步前向时间比较；若两者同量级，说明掩码已成为每 token 延迟的瓶颈，必须改用融合掩码或状态机方案。第二段问系数：文法属于哪一类，<span class=\"sym\">κ_parser</span> 是线性、组合还是栈式增长？JSON Schema 与嵌套文法要单独标定，不能借用正则的经验值。第三段问回退：约束是否过严到有效候选集只剩个位数？若是，把回退重采样成本计入每 token 代价，并重新评估输出多样性是否满足业务要求。</p>\n<p>这三段判断的产物直接喂给容量决策：若 <span class=\"sym\">t_mask</span> 与单步前向同量级，考虑为结构化输出单独部署一套融合掩码的采样 kernel，或把文法预编译成状态机以跳过物化；若掩码读写占用的额外 HBM 带宽份额在高并发下显著，考虑把约束解码与自由文本解码分流到不同实例，避免掩码开销污染自由文本的吞吐。判断的落脚点始终是同一个问题：这条路径上，掩码字节到底有没有真的被搬过 HBM。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-6\">六 · 掩码成本的三条边界：物化路径、文法系数与回退重采样</h3>\n<p>把这条下界当成“约束解码的固有价格”是最常见的越界使用。公式成立的前提是掩码必须物化为每词表项 b_mask 字节的位图、写回 HBM、再被采样 kernel 读回，于是单步至少搬运两倍掩码字节，取带宽倒数得到纯带宽项，再乘上解析器状态推进的相对开销因子。一旦这个前提被打破——在采样 kernel 内即时判定合法性，或用预编译状态机/DFA 直接跳过物化——实际开销可以远低于该式，此时公式只剩“保守上界”的意义。工程判断因此分两步：先确认当前实现落在哪条路径上，再决定是否用该式做容量估算；把即时计算路径误判为物化路径，会直接导致结构化输出方案被错误否决。</p>\n<p>第二个边界在 κ_parser。它不是普适常数：正则、JSON Schema、深层嵌套文法与上下文无关文法的状态数相差数量级，单一系数套用会严重失真。判别方法是看文法是否需要跨 token 携带栈或嵌套计数——需要，则状态维护随嵌套深度增长，κ_parser 必须按最坏嵌套实测标定；不需要，则它接近带宽项的小修正。表里给出三种典型文法的定性差异，用于决定是否值得为结构化输出单独部署：</p>\n<table class=\"mini\"><thead><tr><th>文法类型</th><th>状态维护特征</th><th>κ_parser 量级判断</th><th>对每 token 延迟的影响</th></tr></thead><tbody><tr><td>平坦正则/枚举</td><td>有限状态、无嵌套</td><td>小修正项</td><td>基本被带宽项主导</td></tr><tr><td>JSON Schema</td><td>字段级状态、浅嵌套</td><td>中等，随 schema 规模上升</td><td>与单步前向时间可比时需融合</td></tr><tr><td>深层嵌套/CFG</td><td>栈式状态、嵌套计数</td><td>可达带宽项的数倍</td><td>易成为每 token 瓶颈</td></tr></tbody></table>\n<p>第三个边界是公式完全未计入的部分：掩码错误导致的回退重采样。约束过严会使有效候选集急剧缩小，采样分布被扭曲，一旦触发重采样循环，实际每 token 代价高于带宽下界，输出多样性同时下降。这类成本不出现在 t_mask 里，却会在高并发下放大为尾延迟。因此容量决策时应把 t_mask 与目标模型单步前向时间并列比较：同量级则改用融合掩码或状态机方案；远小于前向时间则只需估算掩码读写占用的额外 HBM 带宽份额，据此判断结构化输出是否需要独立部署，而不是让整批请求共享同一份被掩码流量挤占的带宽。</p>\n<h3 id=\"th-constrained-decode-rate-sec-7\">七 · 逐项拆解：三个因子各自量的是什么</h3>\n<p>把 $$t_{\\text{mask}} \\ge \\frac{|V| \\cdot b_{\\text{mask}}}{\\text{BW}_{\\text{HBM}}} \\cdot (1 + \\kappa_{\\text{parser}})$$ 拆成三段看，每一段对应推理系统里一条独立的物理路径。第一段 $$|V| \\cdot b_{\\text{mask}}$$ 是掩码的字节体积：词表有 |V| 个条目，每个条目用 b_mask 字节表示其合法/非法状态。若用 1 bit 位图，b_mask = 1/8 字节；若用 int8 或 fp 掩码张量，b_mask = 1 或 2 字节。这个乘积不是抽象的“规模”，而是每步必须触碰的地址空间。第二段除以 BW_HBM 得到纯带宽时间：掩码字节从哪来、到哪去，决定了分母的有效性。第三段 (1 + κ_parser) 是文法复杂度的乘性放大，κ_parser 描述解析器推进状态、判定候选合法性所消耗的相对开销，它不是加性常数而是相对于带宽项的比例因子——这一点在推导中至关重要，也是误用最集中的地方。</p>\n<p>三项合起来的物理含义是：约束解码的每 token 延迟下界由“掩码体积 / 搬运速率”决定，再被文法复杂度整体抬高。注意 |V| 是模型属性、b_mask 是编码选择、κ_parser 是文法属性，三者可独立优化，因此这条式子天然是一个可分解的工程诊断工具，而不是一个只能整体接受的常数。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-8\">八 · 推导关键步：为什么是“两倍搬运”与带宽倒数</h3>\n<p>推导的起点是一个明确的物化假设：掩码先被计算并写成每词表项 b_mask 字节的位图，写入 HBM；随后采样 kernel 把它读回，与 logits 逐元素作用（非法位置置 −inf 或等价的大负数）。这条路径上，同一份掩码字节至少经历一次写、一次读，因此单步搬运量至少是 $$2|V|b_{\\text{mask}}$$。取 HBM 带宽的倒数，得到纯搬运时间下界：</p>\n<div class=\"formula\">$$t_{\\text{mem}} \\;\\ge\\; \\frac{2\\,|V|\\,b_{\\text{mask}}}{\\text{BW}_{\\text{HBM}}}$$</div>\n<p>给定公式写的是单倍体积除以带宽再乘 (1+κ_parser)，与两倍搬运并不矛盾：把因子 2 吸收进 κ_parser 的定义域，或把公式理解为“单程搬运下界 + 解析器附加项”的保守合并，二者在量级判断上等价。工程上更稳妥的做法是显式保留 2，因为写回与读回往往落在不同 kernel、不同时刻，中间还夹着一次 kernel 启动与潜在的流同步——同步开销不体现在字节数里，却实实在在落在墙钟时间上。</p>\n<p>第二步是把解析器开销乘进去。解析器每步要推进状态、对候选 token 做合法性判定，其成本与状态数、判定路径长度相关。把它写成相对带宽项的系数 (1 + κ_parser)，意味着文法越复杂，掩码路径的有效成本越高。这一步是近似的关键：κ_parser 把“状态推进的算力开销”折算成“等效带宽开销”，两者本不同量纲，折算依赖具体实现——若解析器在 CPU 上串行跑，κ_parser 可能远大于 1；若用 GPU 上的预编译 DFA 并行判定，κ_parser 可压到很小。因此这个乘性因子是推导中最软的一环，也是失效条件最集中的地方。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-9\">九 · 离散化与近似落在哪里</h3>\n<p>这条式子有三处明确的离散化/近似，识别它们比记住公式更重要。</p>\n<ul>\n<li><b>位图量化。</b>合法性本是布尔量，压到 b_mask 字节是编码选择。1 bit 位图把体积压到最小，但采样 kernel 需要位解包，解包指令开销转移到算力侧；int8 掩码省掉解包却把体积放大 8 倍。离散化在这里不是精度问题，而是“带宽 vs 算力”的兑换率问题。</li>\n<li><b>κ_parser 的常数化。</b>把随文法深度、分支数、状态数变化的状态维护成本压成单一系数，是最激进的近似。JSON Schema 的浅层键值结构与深层嵌套文法、正则与上下文无关文法，状态数量级差异巨大，单一 κ_parser 必然在某些文法上高估、在另一些上严重低估。正确用法是把它当分段常数：按文法类别分别标定，而不是全局一个数。</li>\n<li><b>带宽项的线性化。</b>公式假设搬运时间与字节数严格线性、带宽恒定可达。实际 HBM 上掩码读写会与权重读取、KV cache 读写争抢带宽，有效带宽低于峰值；高并发下这一项被放大，单请求视角的下界不再等于系统视角的每 token 成本。</li>\n</ul>\n<p>还有一处未进入公式的近似：掩码错误导致的回退重采样完全没被计入。约束过严使有效候选集急剧缩小，采样分布被扭曲，可能触发重采样循环，实际每 token 代价高于带宽下界。这一项无法用带宽语言表达，只能作为公式外的修正项单独评估。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-10\">十 · 代价落点：延迟、带宽份额与容量判断</h3>\n<p>把公式当诊断工具用时，最有价值的比较是 $$t_{\\text{mask}}$$ 与目标模型单步前向时间的关系。若两者同量级，约束解码就是每 token 延迟的瓶颈，必须改路径；若 $$t_{\\text{mask}}$$ 远小于前向时间，物化掩码可以接受，结构化输出不必单独部署。这个比较不需要精确常数，只需要量级——这正是保守下界的用途。</p>\n<p>第二个落点是带宽份额。高并发下，掩码读写占用的额外 HBM 带宽可以与 KV cache 读写相加，挤压权重流式加载的有效带宽。设并发批大小为 B，则每步掩码搬运量随 B 线性增长（每序列一份掩码），而权重读取基本与 B 无关，于是掩码在总带宽中的占比随并发上升。容量规划时应把这一项从“每 token 固定成本”改写成“随并发增长的带宽税”，据此判断是否值得为结构化输出单独部署一组实例，把掩码开销隔离到不影响主模型吞吐的资源池里。</p>\n<p>第三个落点是显存。物化掩码本身占用的是临时缓冲，规模为 |V|·b_mask 量级，单份不大，但每序列一份、加上双缓冲与流水线深度，累积起来会挤占 KV cache 的可用容量。这与 KV cache 容量公式是同一本账的两面：掩码缓冲挤掉的显存，直接换算成可容纳的并发序列数下降。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-11\">十一 · 具体例子：同一公式在两种文法上的读数</h3>\n<p>取一个中等词表规模的模型，掩码用 1 bit 位图。此时 $$|V| \\cdot b_{\\text{mask}}$$ 是词表条目数除以 8 的字节量，除以 HBM 带宽得到的是微秒量级的纯搬运下界——单看这一项，物化路径似乎便宜。但把 κ_parser 乘进去，两种文法的读数立刻分叉。</p>\n<p>例一，扁平 JSON Schema：键值对、枚举字段、浅层嵌套。解析器状态数有限，判定路径短，κ_parser 可以压得很低，物化掩码的总开销接近纯带宽项，约束解码对每 token 延迟的影响可忽略。例二，深层嵌套文法：递归结构、多层可选分支、跨字段依赖。状态数随嵌套深度组合增长，解析器每步推进的判定工作量陡增，κ_parser 显著大于 1，此时 $$t_{\\text{mask}}$$ 被整体抬高，可能与前向时间同量级。同一份公式、同一个 |V|、同一个 b_mask，结论完全相反——这说明公式的判别力几乎全部来自 κ_parser 的标定，而不是带宽项本身。</p>\n<p>工程判断由此得出：对扁平文法，物化掩码 + 采样 kernel 逐元素作用是可接受的默认路径；对深层嵌套文法，应优先评估 kernel 内即时判定或预编译状态机（DFA）跳过物化，把 κ_parser 从乘性因子降为常数级判定成本。公式在这里的作用不是给出精确数字，而是指出优化重心应放在解析器路径而非掩码体积上。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-12\">十二 · 掩码下界的适用边界与失效条件</h3>\n<p>公式 $t_{\\text{mask}} \\ge \\frac{|V| \\cdot b_{\\text{mask}}}{\\text{BW}_{\\text{HBM}}} \\cdot (1 + \\kappa_{\\text{parser}})$ 的每一项都对应一条可核查的物理路径，但它的成立前提远比表面看起来窄。$|V| \\cdot b_{\\text{mask}}$ 是每步需读写的掩码字节数：若词表规模为十万量级、每项掩码占一字节，单次掩码体量已在百 KB 级；推导的关键一步是假设掩码必须物化为位图并写回 HBM、再被采样 kernel 读回，于是单步至少搬运两倍掩码字节，取 HBM 带宽倒数即得纯带宽下界，再乘上解析器状态维护的相对开销因子 $\\kappa_{\\text{parser}}$ 得到保守估计。问题在于，这个“两倍搬运”只在物化路径下成立。若在采样 kernel 内即时判定合法性，掩码从不落盘，带宽项直接消失；若用预编译状态机或 DFA 跳过物化，每步只推进一个状态指针，开销与词表规模解耦。此时该式给出的是物化路径的下界，而非约束解码的普遍成本——把它当作固定成本去否决结构化输出方案，是容量规划中最典型的误判。</p>\n<p>$\\kappa_{\\text{parser}}$ 是整条公式里最不可靠的因子。它被定义为解析器状态推进与判定相对带宽项的附加开销系数，但文法复杂度对状态数的影响是数量级的：JSON Schema 的顶层键约束、嵌套对象、递归数组、正则与上下文无关文法，各自的状态空间可以相差几个量级。对它们套用同一常数，延迟预估会系统性偏离实测。工程上可行的做法是按文法类别分别标定：浅层 Schema 的状态推进近似常数，深层嵌套与递归文法需要实测状态爆炸后的判定开销，并把标定值写进容量模型而不是沿用默认系数。判断标准很直接——若 $t_{\\text{mask}}$ 与目标模型单步前向时间同量级，约束解码就是每 token 延迟的瓶颈，必须改用融合掩码或状态机方案；若远小于前向时间，则物化路径仍可接受，但高并发下要单独核算掩码读写占用的 HBM 带宽份额，决定是否为结构化输出独立部署。</p>\n<p>公式还漏掉了一类代价：掩码错误导致的回退重采样。约束过严时有效候选集急剧缩小，采样分布被扭曲，输出多样性下降，并可能触发重采样循环，使实际每 token 代价高于带宽下界。这类成本不在 $t_{\\text{mask}}$ 内，却会直接吃掉批处理容量规划的余量。下表把三条路径的代价结构并列，便于判断该用哪条：</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>每步主要代价</th><th>公式是否适用</th><th>失效触发点</th></tr></thead><tbody><tr><td>物化掩码到 HBM</td><td>掩码字节读写带宽 + 解析器状态推进</td><td>适用，给出下界</td><td>高并发下带宽份额挤占 KV cache 读取</td></tr><tr><td>kernel 内即时判定</td><td>逐 token 合法性判定算力</td><td>不适用，带宽项消失</td><td>判定逻辑复杂时算力成为新瓶颈</td></tr><tr><td>预编译状态机/DFA</td><td>状态指针推进，近常数</td><td>不适用</td><td>文法需动态重编译时引入编译延迟</td></tr></tbody></table>\n<p>因此该式的正确用法是作为物化路径的保守下界与路径选择的判据，而不是约束解码的成本上限。真正的工程判断落在两处：一是先确认掩码是否必须物化，能融合进采样 kernel 的绝不落盘；二是按文法类别实测 $\\kappa_{\\text{parser}}$ 并单独核算回退重采样概率，把这两项写进每 token 延迟预算，再决定结构化输出是否值得独立部署。</p>\n<h3 id=\"th-constrained-decode-rate-sec-13\">十三 · 物化假设：公式成立的唯一路径</h3>\n<p>该下界成立的前提是一条非常具体的执行路径：掩码被物化为每词表项 <em>b</em><sub>mask</sub> 字节的位图，写入 HBM，再由采样 kernel 读回并与 logits 逐元素作用。单步至少搬运两倍掩码字节——一次写、一次读——因此带宽项为 2·|<em>V</em>|·<em>b</em><sub>mask</sub>/BW<sub>HBM</sub>，公式中取带宽倒数并乘以解析器开销因子，得到的是这条路径的保守估计。一旦执行路径改变，公式立刻失去约束力。</p>\n<p>工程上要判断的第一件事是：当前框架到底走哪条路径。TensorRT-LLM 的 guided decoding 插件、vLLM 的 structured output 后端、SGLang 的 grammar 后端，各自在“预生成位图并缓存”“在采样 kernel 内即时判定”“用预编译状态机跳转”之间做了不同取舍。若掩码在 kernel 内即时计算，掩码字节根本不落 HBM，带宽项退化为寄存器与共享内存中的判定开销，公式给出的下界不再适用。此时真正的成本是判定逻辑的分支密度与状态查表的延迟，而非 HBM 流量。</p>\n<p>具体例子：一个 128K 词表的模型，若 <em>b</em><sub>mask</sub> 取 1 bit，单步掩码物化读写约 32KB；在数 TB/s 级 HBM 带宽下这一项本身并不显眼，但当 batch 内序列数上升、每步都要为每条序列各写一份掩码时，掩码流量随并发线性增长，开始与 KV cache 的读带宽争抢。这正是公式的用途所在：判断掩码是否已成为每 token 延迟的瓶颈项，而不是把它当成普遍成本。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-14\">十四 · κ_parser 不是常数：文法复杂度的数量级差异</h3>\n<p>公式把解析器状态维护折算成一个相对开销系数 κ<sub>parser</sub>，但这个系数的取值域跨越数个数量级，任何单一常数都会严重失真。正则文法对应的 DFA 状态数有限且可预编译，状态推进是一次常数时间的表查找；JSON Schema 引入嵌套对象、数组、枚举与类型联合，状态空间随 schema 深度组合增长；上下文无关文法（如完整编程语言语法）需要栈式状态，判定一个 token 是否合法可能要模拟多步归约。</p>\n<p>因此正确做法不是给 κ<sub>parser</sub> 赋一个数，而是按文法类别分层估计：对可预编译为 DFA 的文法，κ<sub>parser</sub> 接近判定指令开销与带宽项之比，量级很小；对需要运行时栈模拟的文法，κ<sub>parser</sub> 由每 token 的归约步数决定，可能远超带宽项本身，此时公式的主项从 |<em>V</em>|·<em>b</em><sub>mask</sub> 转移到解析器推进。容量规划时必须先问“这份文法属于哪一层”，再决定用哪个系数区间。</p>\n<p>代价体现为延迟结构的变化：DFA 路径下掩码开销近似与词表规模成正比、与文法深度弱相关；栈式路径下开销与文法嵌套深度强相关，同一模型在不同 schema 上的每 token 掩码时间可以差出数量级。工程判断是：把 schema 复杂度作为独立维度纳入容量表，而不是把结构化输出笼统记成一项固定开销。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-15\">十五 · 有效候选集收缩：公式之外的采样代价</h3>\n<p>公式只计掩码的搬运与判定，完全不计约束过严带来的回退重采样。当文法把有效候选集压到极小时，采样分布被实质性改变：原本概率质量分散在大量 token 上，掩码后只剩少数候选，归一化后的分布尖锐化，输出多样性下降；若约束与模型倾向冲突，模型反复给出非法 token 而被屏蔽，等价于在极小候选集上重复采样，每 token 的实际代价高于带宽下界。</p>\n<div class=\"formula\">$$ p_{\\text{eff}}(x) = \\frac{p(x)\\cdot m(x)}{\\sum_{x'} p(x')\\cdot m(x')},\\qquad |\\{x: m(x)=1\\}| \\ll |V| $$</div>\n<p>这里 <em>m</em>(<em>x</em>) 是掩码指示函数。分母是剩余候选的概率质量和，当它很小时，浮点归一化的相对误差被放大，数值精度问题（尤其在 FP8/NVFP4 采样路径上）会进一步扭曲分布。这不是带宽问题，而是数值与统计问题，公式对此完全无感。</p>\n<p>具体例子：一个要求输出严格枚举值的 schema，若枚举项恰是模型低概率 token，掩码后候选集只剩个位数，采样几乎退化为确定性选择，重采样循环的概率上升。此时每 token 延迟由“前向 + 多次掩码判定 + 回退”构成，带宽下界只是其中一小项。容量决策若只按公式估算，会低估这条路径的尾延迟。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-16\">十六 · 规模上限：词表、并发与批内异构</h3>\n<p>公式对 |<em>V</em>| 是线性的，这给出一个清晰的规模上限判断：当词表规模与并发批大小的乘积使掩码流量逼近 KV cache 读流量时，约束解码从“可忽略的附加项”变成“与注意力争带宽的主项”。在 NVL72 这类高带宽域内，单卡带宽充裕，但掩码是每序列每步独立生成的，批内序列共享同一文法时可复用位图，文法各异时则必须逐序列物化，复用率决定了实际流量。</p>\n<p>批内异构是另一个规模上限来源。连续批处理把不同请求混在同一 batch，若各请求文法不同，掩码无法在 batch 维度广播，采样 kernel 要么退化为逐序列判定，要么引入额外的掩码拼接与同步。同步开销在公式中完全没有位置，却是高并发下的实际瓶颈：每次掩码更新都要等解析器状态推进完成，形成 kernel 间的串行依赖，破坏解码步的重叠。</p>\n<p>工程判断因此分两步：先按文法分组批处理以提高位图复用率，再对无法分组的异构批评估是否值得为结构化输出单独部署实例。前者降低带宽项，后者隔离同步与解析器开销，两者都不是公式能直接回答的，但公式给出了何时必须做这两件事的触发条件——当 <em>t</em><sub>mask</sub> 与目标模型单步前向时间同量级时。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-17\">十七 · 失效条件的工程清单</h3>\n<p>把公式当作普遍成本是首要失败模式。它只描述物化路径，未覆盖即时判定与预编译状态机两条替代路径，据此否决结构化输出方案属于误判。第二条失败模式是对不同文法套用同一 κ<sub>parser</sub>，忽略 JSON Schema 与深层嵌套文法状态数的数量级差异，导致延迟与容量预估偏离实测。第三条是只算掩码不算回退，有效候选集缩小时实际每 token 代价上升且采样分布被扭曲。</p>\n<ul>\n<li>路径假设失效：掩码未落 HBM 时，带宽项不成立，应改用判定指令数与状态查表延迟建模。</li>\n<li>系数假设失效：κ<sub>parser</sub> 随文法类别跨越数量级，必须分层取值而非取常数。</li>\n<li>统计假设失效：约束过严改变采样分布并触发重采样，公式未计入这部分尾延迟。</li>\n<li>并发假设失效：批内文法异构导致位图无法复用并引入 kernel 间同步，公式无对应项。</li>\n</ul>\n<p>对应的验证手段是分层压测：固定文法、扫词表与批大小，观察掩码流量是否线性；固定词表、换文法复杂度，观察 κ<sub>parser</sub> 的实际漂移；再固定前两者、收紧候选集，观察重采样率与尾延迟。三组曲线合起来才能界定公式的适用域。</p>\n<p>最终落点是一个可操作的判据：当实测掩码路径的 HBM 流量占比低于单步前向带宽项的一个小份额，且文法可预编译为有限状态机时，公式可作为容量估算的上界使用；反之，一旦解析器推进成为主项或批内文法异构引入同步，就必须放弃该式，改用以状态机跳转次数与 kernel 串行深度为核心的模型。约束解码的语法掩码开销从来不是一条普适曲线，而是一组按执行路径与文法层级分裂的分段函数，公式只是其中物化分支的下界。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-18\">十八 · 掩码下界公式的成立条件与失效边界</h3>\n<p>前文给出的带宽下界公式并非约束解码的普遍成本，而是一条有严格前提的估计路径。它的推导依赖一个关键假设：掩码必须被物化为每词表项 b_mask 字节的位图，写回 HBM，再由采样 kernel 读回，于是单步至少搬运两倍掩码字节，取带宽倒数得到时间下界，再乘以解析器状态维护的相对开销因子。这条路径的代价结构是\"先写后读\"的显式往返，因此公式只在物化掩码成立时才有意义。一旦把合法性判定移入采样 kernel 内部即时计算，或用预编译状态机、DFA 跳过物化环节，掩码字节根本不会落到 HBM，公式给出的下界立即失去约束力——此时真实开销可能远低于该式，把它当作固定成本去否决结构化输出方案，是工程上最常见的误判之一。判断公式是否适用的第一步，不是算数值，而是确认当前实现究竟走的是物化路径还是即时判定路径。</p>\n<p>第二个失效来源是 κ_parser 被当成普适常数。该系数反映解析器状态推进与判定相对带宽项的附加开销，但解析器状态数随文法复杂度增长，JSON Schema、深层嵌套文法、正则与上下文无关文法之间的状态规模差异是数量级的，单一系数套用到所有文法会严重失真。容量规划时若用同一个 κ_parser 估算 JSON Schema 与嵌套语法，延迟预估和批处理容量都会系统性偏离实测。正确的做法是按文法类别分别标定该系数，或干脆放弃解析器开销的解析式估计，改为在目标文法上直接测量单步掩码时间，再与模型单步前向时间比较：若两者同量级，说明约束解码已成为每 token 延迟的瓶颈，应改用融合掩码或状态机方案；若掩码项只占前向时间的小份额，则物化路径仍可接受，无需为结构化输出单独部署。</p>\n<p>公式还遗漏了回退重采样成本，这是约束过严时最容易被低估的一项。当有效候选集被文法急剧压缩，采样分布本身发生改变，输出多样性下降，并可能触发重采样循环，实际每 token 代价高于带宽下界。这一项无法用掩码字节数表达，因为它取决于文法约束与模型分布之间的错配程度，而非词表规模。工程上的判别信号是候选集规模与重采样率的联合观测：候选集缩小到只剩极少数 token 且重采样频繁发生时，带宽下界已不再是主导项，此时应放宽文法或改用更粗粒度的约束层，而不是继续优化掩码读写。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>公式是否成立</th><th>系统代价表现</th></tr></thead><tbody><tr><td>掩码物化到 HBM 再读回</td><td>成立，给出保守下界</td><td>每步两倍掩码字节的 HBM 往返，高并发下占用额外带宽份额</td></tr><tr><td>kernel 内即时判定或预编译状态机</td><td>不成立，实际远低于下界</td><td>开销转为判定逻辑本身，与词表规模弱相关</td></tr><tr><td>κ_parser 按文法类别分别标定</td><td>成立但需分类</td><td>JSON Schema 与嵌套文法状态数差异导致预估分化</td></tr><tr><td>约束过严、候选集急剧缩小</td><td>不成立，遗漏重采样项</td><td>每 token 代价上升、采样分布被扭曲、多样性下降</td></tr></tbody></table>\n<p>规模上限同样来自这条公式的结构：掩码字节数与词表规模成正比，词表越大，物化路径的带宽项越重，而解析器状态维护成本随文法嵌套深度增长，两者相乘使下界在高词表、深文法组合下迅速逼近甚至超过单步前向时间。此时系统的可行域不再是\"能否约束解码\"，而是\"是否值得为结构化输出单独部署一套服务\"——把约束解码从主推理路径拆出，用独立实例承担掩码与解析器开销，避免其带宽占用侵蚀主模型的批处理容量。这一判断的依据正是公式中两项的相对量级，而非任何固定阈值。</p>\n<h3 id=\"th-constrained-decode-rate-sec-19\">十九 · 把 t_mask 折算成每 token 的时间预算</h3>\n<p>容量决策的第一步不是算总量，而是把 <span class=\"formula-inline\">t_mask</span> 与模型单步前向时间放在同一时间轴上比较。设单步前向时间为 <span class=\"formula-inline\">t_fwd</span>，则约束解码的单 token 时间下界可写成 <span class=\"formula-inline\">t_tok ≥ t_fwd + t_mask</span>；当掩码能与采样融合进同一 kernel 时，<span class=\"formula-inline\">t_mask</span> 退化为寄存器内的判定开销，可近似并入 <span class=\"formula-inline\">t_fwd</span>；当掩码必须物化，它就是独立的 HBM 往返项。工程判断的阈值很直接：若 <span class=\"formula-inline\">t_mask / t_fwd</span> 超过约一个可接受比例（例如 10%），就必须在部署前改路径，而不是靠加卡解决——加卡只摊薄 <span class=\"formula-inline\">t_fwd</span>，摊不薄物化掩码的字节搬运。用公式表达这个比值：</p>\n<div class=\"formula\">$$ \\rho_{\\text{mask}} \\;=\\; \\frac{t_{\\text{mask}}}{t_{\\text{fwd}}} \\;\\ge\\; \\frac{|V|\\, b_{\\text{mask}}}{\\text{BW}_{\\text{HBM}}\\, t_{\\text{fwd}}}\\,(1+\\kappa_{\\text{parser}}) $$</div>\n<p>这个比值是后续所有决策的主变量：批大小、并行度、KV 预算、SLO 都要围绕它展开。举例：一个词表 <span class=\"formula-inline\">|V|</span> 为十万量级的模型，若掩码以每项一字节位图物化，单步掩码字节量在百 KB 量级；相对单步前向的毫秒级时间，若 <span class=\"formula-inline\">ρ_mask</span> 落在个位数百分比，说明物化路径尚可接受；若文法复杂使 <span class=\"formula-inline\">κ_parser</span> 抬升一个数量级，比值立刻进入需要改路径的区间。注意这里不能对 JSON Schema 与深层嵌套文法套同一个 <span class=\"formula-inline\">κ_parser</span>，前者的状态推进接近线性扫描，后者状态数随嵌套深度增长，二者数量级差异会让同一份容量表得出相反结论。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-20\">二十 · 定批大小：掩码带宽是批的公共分母</h3>\n<p>连续批处理下，批内每个序列各自持有解析器状态，掩码计算量随批内活跃序列数 <span class=\"formula-inline\">B</span> 线性增长，而前向的权重读取量基本与 <span class=\"formula-inline\">B</span> 无关（权重被批内所有序列共享）。因此批越大，掩码项在总时间中的占比越高。把每步总时间写成：</p>\n<div class=\"formula\">$$ t_{\\text{step}}(B) \\;\\approx\\; t_{\\text{fwd}}(B) + B \\cdot t_{\\text{mask}} $$</div>\n<p>其中 <span class=\"formula-inline\">t_fwd(B)</span> 随批增长但边际递减（受算力或带宽饱和限制），而 <span class=\"formula-inline\">B·t_mask</span> 是严格线性的。定批大小的判据是找到使 <span class=\"formula-inline\">t_step(B)/B</span>（每 token 均摊时间）最小的 <span class=\"formula-inline\">B</span>：当 <span class=\"formula-inline\">t_fwd</span> 已饱和、<span class=\"formula-inline\">B·t_mask</span> 仍在增长时，继续加批只会推高单步延迟而不改善吞吐。工程上更常用的是反向约束：给定 SLO 的每 token 时间上限 <span class=\"formula-inline\">T_slo</span>，解出 <span class=\"formula-inline\">B_max</span>：</p>\n<div class=\"formula\">$$ B_{\\max} \\;\\le\\; \\frac{T_{\\text{slo}} - t_{\\text{fwd}}(B)}{\\,t_{\\text{mask}}\\,} $$</div>\n<p>算例：设目标模型单步前向在饱和批下耗时 <span class=\"formula-inline\">t_fwd</span>，SLO 允许每 token 时间为其 1.2 倍，则留给掩码的预算只有 0.2 倍 <span class=\"formula-inline\">t_fwd</span>；若单序列 <span class=\"formula-inline\">t_mask</span> 为 <span class=\"formula-inline\">t_fwd</span> 的 5%，则 <span class=\"formula-inline\">B_max</span> 约为 4。这个数字直接说明：物化掩码路径下，结构化输出的批大小被掩码带宽死死压住，想提高并发必须先把掩码搬进 kernel 或改用预编译状态机。若强行按无约束解码的批大小配置，单步延迟会被掩码项拖出 SLO，表现为尾延迟劣化而非吞吐下降——这是容量规划中最容易误判的形态。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-21\">二十一 · 定并行度：掩码不随 TP 缩小</h3>\n<p>张量并行把权重和激活切分到多卡，前向时间随卡数下降，但掩码的字节量 <span class=\"formula-inline\">|V|·b_mask</span> 是词表维度的全局量，除非把词表切分到各卡并让每卡只物化自己负责的片段，否则每卡都要面对完整掩码。即使做词表切分，采样时的 all-reduce 或 all-gather 又引入通信项。于是并行度 <span class=\"formula-inline\">P</span> 下的掩码相对占比变为：</p>\n<div class=\"formula\">$$ \\rho_{\\text{mask}}(P) \\;\\approx\\; \\frac{t_{\\text{mask}}}{\\,t_{\\text{fwd}}/P + t_{\\text{comm}}(P)\\,} $$</div>\n<p>分母里 <span class=\"formula-inline\">t_fwd/P</span> 随 <span class=\"formula-inline\">P</span> 缩小，而 <span class=\"formula-inline\">t_mask</span> 不变，所以 <span class=\"formula-inline\">ρ_mask</span> 随并行度单调上升——这是一个反直觉但确定的结论：加卡会让约束解码的相对开销变重。工程含义是，结构化输出密集的部署不应盲目堆 TP，而应优先把掩码路径融合掉；若必须堆 TP，则词表切分方案要与采样通信一起设计，把掩码读写限制在本地分片内。具体例子：在 NVL72 这类高带宽互联域内，<span class=\"formula-inline\">t_comm(P)</span> 增长较缓，<span class=\"formula-inline\">ρ_mask</span> 的上升主要由 <span class=\"formula-inline\">t_fwd/P</span> 缩小驱动；跨节点 TP 时通信项抬头，掩码占比反而被稀释，但整体延迟已被通信拖累，这不是可用的解法。判断并行度是否合理的标准是：在目标 <span class=\"formula-inline\">P</span> 下 <span class=\"formula-inline\">ρ_mask</span> 仍低于阈值，否则并行度收益被掩码项吃掉。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-22\">二十二 · 定 KV 预算：掩码开销挤压的是并发而非显存</h3>\n<p>掩码本身不占 KV cache，但它通过时间维度挤压并发容量。KV 预算的常规算法是按显存除以每序列 KV 字节数得到并发上限，这个上限是显存意义上的；而实际可持续并发还要受每 token 时间约束。设每序列每 token 的 KV 字节增量为 <span class=\"formula-inline\">s_kv</span>，则显存侧并发上限为 <span class=\"formula-inline\">N_mem = M_kv / (L·s_kv)</span>（<span class=\"formula-inline\">L</span> 为上下文长度，<span class=\"formula-inline\">M_kv</span> 为可用显存）。时间侧上限由第二节的 <span class=\"formula-inline\">B_max</span> 给出。真正可用的并发是二者较小值：</p>\n<div class=\"formula\">$$ N_{\\text{eff}} \\;=\\; \\min\\!\\left( \\frac{M_{\\text{kv}}}{L \\cdot s_{\\text{kv}}},\\; B_{\\max} \\right) $$</div>\n<p>约束解码的代价在于它把 <span class=\"formula-inline\">B_max</span> 压到显存上限之下，于是显存被“浪费”——KV 池还有空位，但批已经满了。这直接改变容量规划的方向：对结构化输出负载，扩容显存不一定提升吞吐，反而可能要先扩容算力或改掩码路径。算例：若显存侧 <span class=\"formula-inline\">N_mem</span> 远大于时间侧 <span class=\"formula-inline\">B_max</span>（例如前者是后者的数倍），则 KV 池的实际利用率只有 <span class=\"formula-inline\">B_max/N_mem</span>，此时为结构化输出单独部署一组实例、把 KV 预算按 <span class=\"formula-inline\">B_max</span> 而非 <span class=\"formula-inline\">N_mem</span> 来配，比在同一池里混跑更省。反之若 <span class=\"formula-inline\">N_mem</span> 才是瓶颈，掩码开销就不是容量主因，不必为它单独部署。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-23\">二十三 · 定 SLO：把掩码误差与回退重采样计入尾延迟</h3>\n<p>SLO 通常按分位数定义（如 P99 每 token 时间），而 <span class=\"formula-inline\">t_mask</span> 的下界只是均值意义上的带宽项。真正的尾延迟来自两处公式未覆盖的成本：解析器状态推进在复杂文法下的抖动，以及约束过严导致有效候选集缩小、触发回退重采样的循环。后者尤其危险——候选集被压到极小时，采样分布被扭曲，若实现层为保证输出合法性而反复重采样，每 token 的实际代价会高于带宽下界，且输出多样性下降。SLO 预算应写成：</p>\n<div class=\"formula\">$$ T_{\\text{slo}} \\;\\ge\\; t_{\\text{fwd}} + t_{\\text{mask}} + \\mathbb{E}[n_{\\text{retry}}] \\cdot t_{\\text{retry}} $$</div>\n<p>其中 <span class=\"formula-inline\">E[n_retry]</span> 是回退重采样的期望次数，它随文法约束的严格程度上升。工程判断是：对约束极严的场景（如强类型 JSON 的深层嵌套字段），不能只按带宽下界定 SLO，必须给重采样留出余量，或改用能保证候选集非空的状态机设计从源头消除重采样。具体例子：同一模型在宽松正则约束下 <span class=\"formula-inline\">t_mask</span> 可忽略，而在深层嵌套 Schema 下 <span class=\"formula-inline\">κ_parser</span> 抬升、候选集收窄，两项叠加使尾延迟显著高于均值——若 SLO 按均值定，P99 必然违约。容量规划的正确做法是对每类文法分别测 <span class=\"formula-inline\">κ_parser</span> 与重采样率，按文法类别分池部署，而不是用一个全局常数覆盖所有结构化输出。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-24\">二十四 · 算例：一份结构化输出实例的容量表</h3>\n<p>把上述四项决策串成一个可执行的算例流程。给定目标模型、目标 GPU 域、目标文法类别，按以下顺序填表：</p>\n<ul>\n<li>测 <span class=\"formula-inline\">t_fwd</span>（饱和批下）与单序列 <span class=\"formula-inline\">t_mask</span>（物化路径），算 <span class=\"formula-inline\">ρ_mask</span>；若超阈值，先改融合或状态机路径，再重测。</li>\n<li>由 SLO 的每 token 上限解出 <span class=\"formula-inline\">B_max</span>，与显存侧 <span class=\"formula-inline\">N_mem</span> 取小得 <span class=\"formula-inline\">N_eff</span>。</li>\n<li>在目标并行度 <span class=\"formula-inline\">P</span> 下复算 <span class=\"formula-inline\">ρ_mask(P)</span>，确认加卡没有把掩码占比推到阈值以上。</li>\n<li>按文法类别估 <span class=\"formula-inline\">E[n_retry]</span>，把它加进 SLO 预算；若该项不可忽略，分池部署。</li>\n</ul>\n<p>一个具体的填表结果形态：若 <span class=\"formula-inline\">ρ_mask</span> 在单卡下为个位数百分比、<span class=\"formula-inline\">B_max</span> 明显小于 <span class=\"formula-inline\">N_mem</span>，则结论是“掩码是并发瓶颈而非显存瓶颈”，容量表应把实例数按 <span class=\"formula-inline\">B_max</span> 折算，并优先投入工程改造掩码路径而非采购显存；若 <span class=\"formula-inline\">ρ_mask(P)</span> 随 <span class=\"formula-inline\">P</span> 上升越过阈值，则并行度应封顶在当前值，把剩余算力用于增加实例数而非加大单实例 TP。这套流程的价值在于把“约束解码贵不贵”从定性争论变成一张可复算的表：每个格子都对应公式里的一个变量，改文法、改路径、改并行度都能立刻反映到 <span class=\"formula-inline\">N_eff</span> 与 SLO 余量上。最终落点是一个工程判断：掩码开销的可接受性不由词表大小单独决定，而由 <span class=\"formula-inline\">ρ_mask</span> 在目标并行度与目标文法下是否仍在预算内决定——先测这个比值，再谈扩容。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-25\">二十五 · 把掩码下界放进容量方程：批大小、并行度与 SLO 的联动</h3>\n\n<p>本节的用法不是把 $$t_{\\text{mask}}$$ 当成一个待测常数，而是把它当作容量规划里的一个约束项塞进每 token 的时间预算。设目标模型单步前向时间为 $$t_{\\text{fwd}}$$，采样与通信开销为 $$t_{\\text{samp}}$$，则约束解码路径下的单 token 下界是 $$t_{\\text{step}} \\ge t_{\\text{fwd}} + t_{\\text{samp}} + t_{\\text{mask}}$$，其中 $$t_{\\text{mask}}$$ 取物化路径的下界。工程判断只有一条：当 $$t_{\\text{mask}}$$ 与 $$t_{\\text{fwd}}$$ 同量级时，掩码就是每 token 延迟的主瓶颈，此时继续加大批大小只会把 HBM 带宽份额从权重读取挤到掩码读写上，吞吐曲线提前饱和；反之若 $$t_{\\text{mask}}$$ 只占 $$t_{\\text{fwd}}$$ 的很小一份，则可以把结构化输出与普通请求混批，不必为它单独切分资源。定批大小时，把掩码字节数按批内并发序列数线性放大：批内 B 条序列各自维护解析器状态，每步掩码读写量约为 $$B \\cdot |V| \\cdot b_{\\text{mask}}$$，这直接吃掉 KV cache 之外的另一块带宽预算，因此 KV 预算的核算必须把这块“掩码带宽税”从可用 HBM 带宽里先扣掉，再谈每序列能分到多少 KV 页。</p>\n\n<p>定并行度时，掩码开销与张量并行的切分方式强耦合。若词表按 TP 切分，每条 rank 只物化自己那一段掩码，单 rank 的掩码字节数降为 $$|V|/N_{\\text{tp}} \\cdot b_{\\text{mask}}$$，带宽下界随之下降，但解析器状态必须在各 rank 间保持一致，κ_parser 项反而引入跨 rank 的同步点——这是一次典型的“用通信换带宽”。因此对文法复杂、状态推进频繁的请求，增大 TP 不一定缩短 $$t_{\\text{mask}}$$，反而可能因每步一次的状态对齐把延迟拉长；对文法简单、状态几乎不推进的场景，切分词表是有效的降本手段。下表给出决策时的定性对照，用于在架构选型会上快速分流，而不是替代实测。</p>\n\n<table class=\"mini\"><thead><tr><th>观测特征</th><th>容量决策倾向</th><th>主要代价</th></tr></thead><tbody><tr><td>$$t_{\\text{mask}}$$ 与 $$t_{\\text{fwd}}$$ 同量级</td><td>改用 kernel 内即时判定或预编译状态机，放弃物化位图</td><td>kernel 复杂度上升，采样逻辑与文法判定耦合</td></tr><tr><td>κ_parser 随文法深度急升</td><td>按文法复杂度分池部署，JSON Schema 与深层嵌套文法不共用同一 SLO</td><td>资源碎片化，池间负载不均</td></tr><tr><td>掩码带宽占 HBM 份额显著</td><td>为结构化输出单独部署，避免污染普通请求的批</td><td>额外实例的显存与功耗底噪</td></tr><tr><td>有效候选集被约束压得很小</td><td>放宽文法或引入回退预算，不按带宽下界定 SLO</td><td>回退重采样使实际每 token 代价高于下界</td></tr></tbody></table>\n\n<p>算例走一遍这条链路：某结构化输出服务，词表规模为 $$|V|$$，每词表项掩码取 $$b_{\\text{mask}}$$ 字节的位图，按物化路径单步需搬运两倍掩码字节，得 $$t_{\\text{mask}} \\ge 2|V|b_{\\text{mask}}/\\text{BW}_{\\text{HBM}} \\cdot (1+\\kappa_{\\text{parser}})$$。若实测发现该值与模型单步前向时间同量级，则无论批大小怎么调，SLO 的 p99 都会被掩码钉住，正确动作是切到即时计算路径而不是加机器；若该值只占前向时间的一小部分，则可按 $$B$$ 条序列混批，并把 $$B \\cdot |V| \\cdot b_{\\text{mask}}$$ 从 HBM 带宽预算中扣除后再分配 KV 页，避免高并发下 KV 与掩码争抢带宽导致的尾延迟抬升。这里必须强调公式的边界：它只对物化路径成立，未计入掩码判定错误导致的回退重采样；约束过严使有效候选集急剧缩小，采样分布被扭曲，实际每 token 代价会高于带宽下界，SLO 里的重试预算必须单列，不能拿这个下界去承诺 p99。</p>\n\n<p>最容易被忽略的失效条件是 κ_parser 的不可通约性。JSON Schema、正则与上下文无关文法的状态数差着数量级，把同一个 κ_parser 套到所有结构化请求上，会让延迟预估在深层嵌套文法上严重偏低、在简单正则上严重偏高，容量规划随之失准。工程上的落法是按文法族分别标定 κ_parser，并把“掩码是否物化”作为部署参数而非全局假设：同一集群里允许即时判定路径与物化路径共存，用文法族标签路由请求，才能让 $$t_{\\text{mask}}$$ 这个下界真正起到分流作用，而不是变成一刀切否决结构化输出的理由。</p>\n<h3 id=\"th-constrained-decode-rate-sec-26\">二十六 · 误用一：把物化下界当成普遍成本</h3>\n<p>最典型的误用，是把 <span class=\"formula-inline\">$$t_{\\text{mask}} \\ge \\frac{|V| \\cdot b_{\\text{mask}}}{\\text{BW}_{\\text{HBM}}} \\cdot (1 + \\kappa_{\\text{parser}})$$</span> 当作“约束解码的固有代价”，在方案评审里直接判结构化输出死刑。这个式子的推导前提非常窄：掩码必须被物化成每词表项 <em>b</em><sub>mask</sub> 字节的位图、写回 HBM、再被采样 kernel 读回，因此单步至少搬运两倍掩码字节。一旦这个前提不成立，下界就不再约束实际路径。</p>\n<p>工程上存在两条完全绕开物化的路径。其一是在采样 kernel 内即时判定合法性：把解析器状态作为 kernel 参数传入，每个线程处理一段词表区间，对候选 token 现场做文法判定，合法则保留 logits、非法则置 <code>-inf</code>，掩码从不落盘。其二是预编译状态机（DFA/下推自动机的等价状态表），把文法在离线阶段编译成状态转移表，运行时只做一次状态查表与区间屏蔽，掩码以常量或共享内存中的位图形式驻留，每步只推进状态指针。两条路径的每步代价从“读写整个词表位图”降为“一次状态推进 + 一次区间比较”，量级差异足以让原本被判死刑的方案重新可行。</p>\n<p>识别方法很直接：看采样 kernel 的签名里有没有掩码张量参数。若掩码作为独立 tensor 传入并参与逐元素运算，走的就是物化路径，下界适用；若 kernel 只接收状态索引或编译好的转移表，物化下界不适用，此时用该式估算延迟会系统性高估。后果是延迟预估偏差大、批处理容量规划失准——按物化成本算出的每 token 预算会把并发数压得过低，而实际瓶颈根本不在掩码上。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-27\">二十七 · 误用二：单一 κ<sub>parser</sub> 套所有文法</h3>\n<p>第二个误用更隐蔽：把 κ<sub>parser</sub> 当成一个可标定的普适常数，对 JSON Schema、正则、嵌套文法一视同仁。事实是解析器状态数随文法复杂度增长，JSON Schema 与深层嵌套语法的状态数差异巨大，单一系数会严重失真。一个平坦的枚举字段，状态机只有个位数状态；一个带递归 <code>$ref</code>、多层 <code>oneOf</code>、数组嵌套对象的 Schema，编译出的状态图规模可以高出若干数量级，每步的状态推进与合法性判定成本随之抬升。</p>\n<p>正确的做法是按文法分别标定 κ<sub>parser</sub>，而不是全局取一个数。标定方式是在目标硬件上跑两类微基准：固定 <em>|V|</em> 与 <em>b</em><sub>mask</sub>，只换文法，测每步掩码相关耗时；再固定文法，扫词表规模，验证带宽项是否线性。两组数据交叉后，κ<sub>parser</sub> 才能落到具体文法类别上。工程判断上，若某类 Schema 的 κ<sub>parser</sub> 使 <em>t</em><sub>mask</sub> 与目标模型单步前向时间同量级，就该改用融合掩码或预编译状态机，而不是继续在物化路径上加并发。</p>\n<p>后果体现在容量规划上：用低复杂度文法的 κ<sub>parser</sub> 去估算高嵌套 Schema 的延迟，会低估每 token 的掩码开销，进而高估可承载的并发批大小。上线后表现为尾延迟抬升、批内 token 完成时间离散度变大，而监控上又看不到显存或算力打满——瓶颈藏在解析器状态推进里。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-28\">二十八 · 误用三：只算掩码，不算回退重采样</h3>\n<p>第三个误用是公式的失效条件被忽略：该式未计入掩码错误导致的回退重采样成本。约束过严时有效候选集急剧缩小，会改变采样分布，并可能触发重采样循环。具体机制是：掩码把大量 token 置为非法后，剩余合法集合上的概率质量被重新归一化，若合法集合过小或分布过于尖锐，采样器可能反复落到被后续文法拒绝的分支上，解码器只能回退、重采样、再判定，每 token 的实际代价高于带宽下界，且输出多样性下降。</p>\n<p>识别信号有三个。其一，采样温度与 top-p 在约束下失去调节作用——调高温度仍输出近乎确定的结果，说明有效候选集已被压到极小。其二，解码循环里出现同一位置的多次重采样计数，且计数与文法嵌套深度正相关。其三，端到端吞吐低于按 <em>t</em><sub>mask</sub> 估算的吞吐，差额不随批大小线性缩放，说明存在串行的回退路径。工程上应把“有效候选集大小”作为一等指标暴露出来，在掩码生成阶段统计每步合法 token 数，低于阈值时告警，而不是等尾延迟爆掉再回头查。</p>\n<p>后果是双重的：延迟侧，回退重采样把本可并行的采样变成串行重试，批处理收益被侵蚀；质量侧，采样分布被扭曲，结构化输出的内容多样性下降，在需要生成多个候选的场景里表现为候选高度同质。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-29\">二十九 · 反例：一个嵌套 Schema 的容量误判</h3>\n<p>设一个服务要输出带递归结构的配置文档：顶层对象含若干字段，其中一个字段是数组，数组元素又是同构对象，允许嵌套若干层，另有若干 <code>oneOf</code> 分支。团队按平坦 JSON 的 κ<sub>parser</sub> 标定值估算，认为掩码开销可忽略，于是把结构化输出与普通文本解码混在同一批里，按普通解码的并发容量做规划。</p>\n<p>上线后的现象是：普通文本请求的尾延迟正常，结构化请求的尾延迟显著抬升，且抬升幅度随嵌套深度增加；批内混合时，结构化请求拖慢了同批的文本请求。排查发现采样 kernel 接收的是物化掩码张量，每步读写整个词表位图，而嵌套 Schema 编译出的状态图规模远大于平坦 Schema，κ<sub>parser</sub> 被严重低估；同时深层嵌套处有效候选集缩小，触发了回退重采样，实际每 token 代价进一步高于带宽下界。</p>\n<p>修正路径分两步。第一步把掩码从物化改为 kernel 内即时判定，掩码张量参数从采样 kernel 签名中移除，带宽项消失，<em>t</em><sub>mask</sub> 不再由 <em>|V|</em>·<em>b</em><sub>mask</sub>/BW<sub>HBM</sub> 主导。第二步按文法类别重新标定 κ<sub>parser</sub>，对深层嵌套 Schema 单独走预编译状态机路径，并把有效候选集大小纳入调度决策：候选集过小的请求不与大批混合，避免拖累同批其他请求。这个反例的教训不是“约束解码太贵”，而是“用物化下界加单一 κ<sub>parser</sub> 去规划一个文法复杂度分布很宽的服务，必然失准”。</p>\n\n<h3 id=\"th-constrained-decode-rate-sec-30\">三十 · 识别清单与工程判断</h3>\n<p>把上述误用收敛成可执行的检查项，比记住公式更有用。评审一个约束解码方案时，逐项核对：</p>\n<ul>\n<li>采样 kernel 是否接收独立掩码张量？是则物化路径，下界适用；否则需实测而非套公式。</li>\n<li>κ<sub>parser</sub> 是否按文法类别分别标定？是否存在用平坦 Schema 数据外推嵌套 Schema 的情况？</li>\n<li>是否统计每步有效候选集大小？是否有低于阈值的告警与调度隔离？</li>\n<li>是否观测到回退重采样计数？该计数是否随文法深度增长？</li>\n<li>容量规划里的并发数，是按 <em>t</em><sub>mask</sub> 与单步前向时间同量级来判断瓶颈，还是直接假设掩码可忽略？</li>\n</ul>\n<p>判断规则可以写得很硬：若 <em>t</em><sub>mask</sub> 与目标模型单步前向时间同量级，掩码就是每 token 延迟的瓶颈，必须改用融合掩码或状态机方案，而不是加并发；若掩码读写占用的额外 HBM 带宽份额在高并发下显著，就值得为结构化输出单独部署一组实例，把文法复杂度隔离在专用池里，避免污染普通解码的批。反过来，若实测显示即时判定路径下掩码开销远低于前向时间，那么此前基于物化下界的否决结论应当撤回——这正是最常见的误用所要防的那类错误决策。</p>\n<p>最后落到一个具体机制上：把文法编译产物（状态转移表、区间屏蔽位图）在服务启动时一次性生成并常驻，运行时采样 kernel 只做状态查表与区间比较，掩码字节不再进出 HBM，κ<sub>parser</sub> 退化为一次查表的常数开销。此时约束解码的每 token 代价由前向计算主导，结构化输出不再需要单独的容量折扣——是否走这条路，取决于文法是否可预编译、以及有效候选集是否被压到触发回退重采样的程度，这两点是工程判断的落脚处。</p>\n\n\n<h3 id=\"th-constrained-decode-rate-sec-31\">三十一 · 误用与反例：把物化路径的下界当成普遍成本</h3>\n<p>最常见的误用，是把 $$t_{\\text{mask}} \\ge \\frac{|V| \\cdot b_{\\text{mask}}}{\\text{BW}_{\\text{HBM}}} \\cdot (1 + \\kappa_{\\text{parser}})$$ 当作“约束解码的固定成本”，据此在容量规划阶段直接否决结构化输出方案。这个不等式只在掩码必须物化为每词表项 b_mask 字节的位图、写回 HBM 再被采样 kernel 读回的路径下成立，单步至少搬运两倍掩码字节。一旦在采样 kernel 内即时判定合法性，或用预编译状态机/DFA 跳过物化，实际开销可远低于该式给出的下界。反例很典型：某服务要在每 token 上输出严格 JSON，工程师按物化位图估算，得出掩码读写与单步前向同量级，于是判定结构化输出不可行，转而用后处理正则修补自由文本；结果修补逻辑本身要回退重采样，端到端延迟反而更高，且输出字段缺失率上升。识别方法很直接——先问掩码是否真的落盘到 HBM，再看采样 kernel 是否与掩码融合；若两者皆否，这个下界就不适用于该实现。</p>\n<p>第二个误用是对 JSON Schema 与深层嵌套文法套用同一个 κ_parser。解析器状态数随文法复杂度增长，JSON Schema 的字段组合、嵌套深度与上下文无关文法的状态空间不在一个量级，单一常数会严重失真。后果是延迟预估偏差大、批处理容量规划失准：按浅层文法标定的系数去排布连续批处理，遇到深层嵌套请求时每 token 的解析器推进成本被低估，批次内最慢序列拖住整个 step，吞吐骤降而调度器无从察觉。工程上应把 κ_parser 视为按文法族分档的经验量，而不是全局常数；识别信号是同一批次内不同 schema 的 token 间延迟分布出现双峰。</p>\n<p>第三个失效条件藏在公式之外：约束过严使有效候选集急剧缩小，会改变采样分布并可能触发回退重采样循环。此时实际每 token 代价高于带宽下界，输出多样性同时下降。设原始分布为 p、约束后有效集为 A，重归一化分布为</p>\n<div class=\"formula\">$$ p'(x) = \\frac{p(x)\\,\\mathbf{1}[x \\in A]}{\\sum_{y \\in A} p(y)} $$</div>\n<p>当 $$\\sum_{y \\in A} p(y)$$ 很小时，被保留的 token 在原始分布下概率极低，采样结果偏离模型意图，温度与 top-p 的语义也被扭曲；若实现再叠加“非法即重采样”，每步期望尝试次数上升，掩码开销之外又多出一层前向或采样代价。识别方式是监控有效候选集占比与重采样率，两者同时走低即是约束过紧的信号。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>把物化下界当普遍成本</td><td>错误否决结构化输出，退回后处理修补</td><td>掩码未落 HBM 却仍按带宽项估算</td></tr><tr><td>单一 κ_parser 通用于所有文法</td><td>延迟与容量预估偏离实测</td><td>同批不同 schema 的 token 间延迟双峰</td></tr><tr><td>忽略约束过严的回退重采样</td><td>每 token 代价上升、多样性下降</td><td>有效候选集占比与重采样率同降</td></tr></tbody></table>\n<p>工程判断落在路径选择上：容量决策时先用该式判断掩码是否与目标模型单步前向同量级，同量级则必须改用融合掩码或预编译状态机，而不是放弃结构化输出；同时按文法族分别标定 κ_parser，并把有效候选集占比纳入 SLO 监控，避免约束过严把带宽下界之外的重采样成本悄悄计入每 token 延迟。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>|V|</td><td>词表大小</td></tr><tr><td>b_{\\text{mask}}</td><td>每词表项掩码字节数</td></tr><tr><td>\\kappa_{\\text{parser}}</td><td>解析器状态维护相对开销</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-constrained-decode-rate · 共 5 个片段</p>\n"},{"id":"th-prefix-cache-hit-bound","title":"前缀缓存命中率与预填节省界","direction":"dir-structured-decode","prereq":[],"plain":"仓库级上下文复用能否省下预填算力，取决于命中 token 占输入的比例；命中率低于临界值时，维护缓存的显存与查找开销反而吃掉收益。","definition":"仓库级上下文复用能否省下预填算力，取决于命中 token 占输入的比例；命中率低于临界值时，维护缓存的显存与查找开销反而吃掉收益。","formula":"$$T_{\\text{prefill}}^{\\text{cached}} = \\frac{2 P N_{\\text{in}} (1-h)}{\\eta_{\\text{MFU}} C} + \\frac{M_{\\text{cache}}}{B_{\\text{HBM}}},\\qquad h^{*} = 1-\\frac{\\eta_{\\text{MFU}} C\\, M_{\\text{cache}}}{2 P N_{\\text{in}} B_{\\text{HBM}}}$$","variables":[{"sym":"$h$","meaning":"前缀缓存命中 token 占输入 token 的比例"},{"sym":"$N_{\\text{in}}$","meaning":"单请求输入 token 数（仓库上下文长度）"},{"sym":"$P$","meaning":"模型参数量"},{"sym":"$M_{\\text{cache}}$","meaning":"为前缀缓存预留的显存字节数"},{"sym":"$B_{\\text{HBM}}$","meaning":"HBM 有效带宽"}],"derivation":"推导关键一步：令缓存版预填时间对命中率求零收益条件，即未命中重算节省的时间恰好等于缓存读取开销，解出 $$h^{*} = 1-\\frac{\\eta_{\\text{MFU}} C\\, M_{\\text{cache}}}{2 P N_{\\text{in}} B_{\\text{HBM}}}$$，它把“命中率阈值”写成算力、带宽、显存三者的比值。","example":"容量决策用途：给定 $M_{\\text{cache}}$ 预算与实测 $h$，可直接判断该仓库是否值得开前缀缓存；也可反解出为达到目标 $h^{*}$ 所需的最小 $N_{\text{in}}$，用于决定哪些仓库纳入缓存池、哪些走冷预填。","pseudocode":"输入数据与超参\n 计算目标函数与梯度\n 更新参数并记录诊断量\n 返回可复用的配方","limits":["前缀必须逐 token 完全一致才能命中，仓库上下文中插入一行注释即导致整段失效","缓存块按固定粒度（如 16 token）对齐，短公共前缀的命中收益被块内浪费抵消"],"system_note":"常见误用：把 token 级命中率当作块级命中率。缓存块按固定粒度（如 16 token）对齐，短公共前缀的命中收益被块内浪费抵消，实际有效 $h$ 低于统计值，导致按公式算出的收益在部署中不出现。","papers":["paper-a-lightweight-framework-for-adaptive-2024"],"facts":["直觉：仓库级上下文复用的预填节省不是线性的，命中率 h 决定剩余重算量 (1-h)，而缓存本身要占显存并消耗一次 HBM 读带宽，二者相抵后存在盈亏平衡点。","公式第一项 $$\\frac{2 P N_{\\text{in}} (1-h)}{\\eta_{\\text{MFU}} C}$$ 中，$2P$ 是每 token 前向的浮点运算量（乘加各计一次），$N_{\\text{in}}(1-h)$ 是未命中、必须重算的 token 数，除以 $\\eta_{\\text{MFU}} C$ 得到以秒计的预填时间；第二项 $M_{\\text{cache}}/B_{\\text{HBM}}$ 是把缓存块从 HBM 读回的时间代价。","推导关键一步：令缓存版预填时间对命中率求零收益条件，即未命中重算节省的时间恰好等于缓存读取开销，解出 $$h^{*} = 1-\\frac{\\eta_{\\text{MFU}} C\\, M_{\\text{cache}}}{2 P N_{\\text{in}} B_{\\text{HBM}}}$$，它把“命中率阈值”写成算力、带宽、显存三者的比值。","适用边界：$h^{*}$ 随 $N_{\\text{in}}$ 增大而下降，说明长仓库上下文更容易跨过盈亏点；反之短输入（如单文件补全）的 $N_{\\text{in}}$ 小，$h^{*}$ 可能接近或超过 1，缓存永远不划算。失效条件还包括前缀必须逐 token 完全一致，插入一行注释即整段失效。","容量决策用途：给定 $M_{\\text{cache}}$ 预算与实测 $h$，可直接判断该仓库是否值得开前缀缓存；也可反解出为达到目标 $h^{*}$ 所需的最小 $N_{\text{in}}$，用于决定哪些仓库纳入缓存池、哪些走冷预填。","常见误用：把 token 级命中率当作块级命中率。缓存块按固定粒度（如 16 token）对齐，短公共前缀的命中收益被块内浪费抵消，实际有效 $h$ 低于统计值，导致按公式算出的收益在部署中不出现。"],"anchors":["16 token"],"pitfalls":["按 token 统计命中率却忽略块对齐粒度，短公共前缀（不足一个缓存块）被计为命中，实际零收益，容量规划高估节省。","只优化 $h$ 而忽略 $M_{\\text{cache}}$ 的显存挤占：缓存池扩大后 KV 可用空间减少，批大小下降，吞吐反而低于不开缓存的基线。","假设仓库上下文稳定不变，但 agent 循环每轮改写文件头部或插入注释，前缀逐 token 失配，命中率骤降而调度器仍按旧 $h$ 预留缓存。"],"long_html":"<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-1\">一 · 一句话直觉与严格定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-2\">二 · 为什么需要这个界：容量决策不能靠感觉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-3\">三 · 失效条件之一：逐 token 完全一致</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-4\">四 · 失效条件之二：块对齐粒度吞掉短前缀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-5\">五 · 常见误解：只优化 $h$，忽略 $M_{\\text{cache}}$ 的挤占</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-6\">六 · 盈亏平衡点：命中率阈值与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-7\">七 · 盈亏平衡点：命中率阈值与它的三个失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-8\">八 · 两项时间各自度量什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-9\">九 · 零收益条件的推导关键步</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-10\">十 · $h^{*}$ 随 $N_{\\text{in}}$ 单调下降的含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-11\">十一 · 离散化发生在块粒度上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-12\">十二 · 逐 token 一致性与公式的适用域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-13\">十三 · 反解 $N_{\\text{in}}$ 与容量决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-14\">十四 · 盈亏点推导的边界：块对齐、显存挤占与仓库漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-15\">十五 · 公式成立的前提假设</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-16\">十六 · 逐 token 一致性与块对齐的双重失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-17\">十七 · 规模上限：$N_{\\text{in}}$ 的两端都不安全</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-18\">十八 · 动态上下文下的命中率漂移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-19\">十九 · 何时该放弃公式，改用实测</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-20\">二十 · 盈亏点之外的三个断崖：逐 token 一致性、块对齐与显存挤占</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-21\">二十一 · 从阈值到决策变量：反解批大小与并行度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-22\">二十二 · KV 预算：缓存池与 KV 池的零和分配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-23\">二十三 · SLO 反解：把 $h^{*}$ 变成准入判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-24\">二十四 · 算例：一个仓库上下文的完整决策链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-25\">二十五 · 动态 $h$ 估计与缓存池回收</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-26\">二十六 · 把盈亏平衡式嵌进调度器：批大小、并行度、KV 预算与 SLO 的联合定标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-27\">二十七 · 误用一：把 token 级命中率当块级命中率</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-28\">二十八 · 误用二：只优化 $h$，无视 $M_{\\text{cache}}$ 的显存挤占</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-29\">二十九 · 误用三：假设仓库上下文稳定，忽略逐 token 失配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-30\">三十 · 反例复盘：一次“命中率很高但收益为零”的容量决策</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-31\">三十一 · 误用与反例：命中率统计口径、缓存挤占与失效前缀</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"th-prefix-cache-hit-bound-sec-32\">三十二 · 命中率阈值之外的三种典型误用</button></li></ol></nav><figure class=\"diagram\" data-fig=\"theory-map\"><svg style=\"max-width:556px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 556.2 281\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">前置：无（入口卡）</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">定义：仓库级上下文复用能否省下预填算力，取决于命中 token 占输入的…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">公式：$$T_{\\text{prefill}}^{\\text{cache…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"474.2\" height=\"44.8\" rx=\"8\" fill=\"#fdecec\" stroke=\"#f3caca\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#b91c1c\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">失效：前缀必须逐 token 完全一致才能命中，仓库上下文中插入一行注释…</text></svg><figcaption><b>先修与边界</b> · 这张卡从哪来、核心公式是什么、在哪里失效；先修关系与正文一致。</figcaption></figure>\n<h3 id=\"th-prefix-cache-hit-bound-sec-1\">一 · 一句话直觉与严格定义</h3>\n<p>前缀缓存的收益不是“命中多少就省多少”，而是一场<b>重算算力</b>与<b>缓存读带宽</b>之间的对冲：命中率 $h$ 只决定还剩多少 token 需要重算，而缓存本身必须占用显存、并在复用时被完整读回一次 HBM。把这两件事写进同一个时间表达式，盈亏平衡点就自然浮现。</p>\n<p>严格定义如下。设单请求输入 token 数为 $N_{\\text{in}}$（即仓库上下文长度），模型参数量为 $P$，前缀缓存命中 token 占输入 token 的比例为 $h$，为前缀缓存预留的显存字节数为 $M_{\\text{cache}}$，HBM 有效带宽为 $B_{\\text{HBM}}$，硬件算力为 $C$、预填算子达到的算力利用率为 $\\eta_{\\text{MFU}}$。则开启缓存后的预填时间为：</p>\n<div class=\"formula\">$$T_{\\text{prefill}}^{\\text{cached}} = \\frac{2 P N_{\\text{in}} (1-h)}{\\eta_{\\text{MFU}} C} + \\frac{M_{\\text{cache}}}{B_{\\text{HBM}}}$$</div>\n<p>第一项中 $2P$ 是每 token 前向的浮点运算量（乘加各计一次），$N_{\\text{in}}(1-h)$ 是未命中、必须重算的 token 数，除以 $\\eta_{\\text{MFU}} C$ 得到以秒计的预填时间；第二项是把缓存块从 HBM 读回的时间代价。注意这里没有把“查找/比对前缀”的 CPU 侧开销写进公式——它是常数级但不可忽略的调度代价，在后续部分单独处理。定义本身要强调的是：$h$ 是<b>token 级</b>比例，而 $M_{\\text{cache}}$ 是<b>字节级</b>预算，两者量纲不同，这正是误解的温床。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-2\">二 · 为什么需要这个界：容量决策不能靠感觉</h3>\n<p>工程上最常见的争论是“这个仓库值不值得开前缀缓存”。没有界，回答只能靠试跑；有了界，回答变成一个可反解的不等式。令缓存版预填时间相对冷预填的节省归零，即未命中重算省下的时间恰好被缓存读取开销吃掉，解出临界命中率：</p>\n<div class=\"formula\">$$h^{*} = 1-\\frac{\\eta_{\\text{MFU}} C\\, M_{\\text{cache}}}{2 P N_{\\text{in}} B_{\\text{HBM}}}$$</div>\n<p>它把“命中率阈值”写成算力、带宽、显存三者的比值。这个式子的工程价值在于三个方向都可解：给定 $M_{\\text{cache}}$ 预算与实测 $h$，直接判断该仓库是否值得开缓存；给定目标 $h^{*}$，反解出所需的最小 $N_{\\text{in}}$，从而决定哪些仓库纳入缓存池、哪些走冷预填；给定 $N_{\\text{in}}$ 与 $h$，反解可承受的 $M_{\\text{cache}}$ 上限，避免缓存池无限膨胀。</p>\n<p>适用边界很清晰：$h^{*}$ 随 $N_{\\text{in}}$ 增大而下降，长仓库上下文更容易跨过盈亏点；反之短输入（如单文件补全）的 $N_{\\text{in}}$ 小，$h^{*}$ 可能接近或超过 1，缓存永远不划算。举例：一个仓库级 agent 请求携带数万 token 的上下文，$N_{\\text{in}}$ 大，$h^{*}$ 被压得很低，只要跨轮次复用稳定，缓存几乎必然划算；而一个只带几百 token 的单文件补全请求，分母 $2PN_{\\text{in}}$ 很小，$h^{*}$ 被推到接近 1，即便命中率看起来不错，读回缓存的带宽代价也吞掉了全部收益。这里的代价是显性可算的：预填延迟、HBM 带宽占用、以及被缓存池挤占的 KV 可用显存。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-3\">三 · 失效条件之一：逐 token 完全一致</h3>\n<p>前缀命中不是“语义相似”而是“逐 token 完全一致”。仓库上下文中插入一行注释、改写文件头部、调整 import 顺序，都会让从改动点开始的所有后续 token 失配，整段缓存失效。这不是精度问题，是<b>精确匹配</b>的硬约束：缓存键是 token 序列本身，任何一位不同即视为不同前缀。</p>\n<p>伪代码层面的判定逻辑可以写成：对候选前缀逐块比较 token id，遇到首个不等位置即截断命中长度，返回 $h \\cdot N_{\\text{in}}$ 的有效命中量。工程上这意味着 agent 循环中“每轮改写文件头部”的行为会让实测 $h$ 骤降，而调度器若仍按旧 $h$ 预留缓存，就会出现缓存池被占满、命中却极低的错配。代价体现在两方面：显存被无效缓存块长期占用，KV 可用空间减少导致批大小下降；同时每次请求仍要走一遍查找比对，白白消耗调度周期。</p>\n<p>具体例子：一个多轮代码修复 agent，第一轮读入整个仓库上下文建立缓存，第二轮在文件顶部插入一行 license 注释——从该行起全部 token 失配，$h$ 从高位跌至接近零，但缓存池仍按上一轮的 $h$ 扩容，结果是吞吐低于不开缓存的基线。工程判断是：把“前缀稳定性”作为是否纳入缓存池的前置条件，而不是只看历史命中率。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-4\">四 · 失效条件之二：块对齐粒度吞掉短前缀</h3>\n<p>缓存块按固定粒度对齐（如 16 token）。一个不足一个缓存块的公共前缀，在 token 级统计里被计为命中，但在块级分配里根本无法形成可复用的缓存块，实际收益为零。这是“统计命中率”与“有效命中率”之间最典型的缺口。</p>\n<p>把有效命中率写成块级形式：设块大小为 $g$（如 16 token），则有效命中 token 数为 $\\lfloor h N_{\\text{in}} / g \\rfloor \\cdot g$，块内余数被浪费。当 $h N_{\\text{in}} &lt; g$ 时有效命中为零。代入前面的时间公式，第一项中的 $(1-h)$ 应替换为 $(1 - h_{\\text{eff}})$，其中 $h_{\\text{eff}} = \\lfloor h N_{\\text{in}} / g \\rfloor g / N_{\\text{in}}$。代价是直接的：容量规划按 token 级 $h$ 估算节省，部署中却观察不到，因为块内浪费把收益吃掉了。</p>\n<p>具体例子：多个短请求共享一段不足 16 token 的系统提示前缀，token 级统计显示每个请求都“命中”，但块对齐后没有任何一个完整缓存块被复用，$M_{\\text{cache}}$ 却为这些碎片预留了空间。工程判断是：容量规划必须用块级有效 $h$，而不是日志里的 token 级命中率；对短公共前缀，宁可走冷预填，也不要把碎片塞进缓存池。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-5\">五 · 常见误解：只优化 $h$，忽略 $M_{\\text{cache}}$ 的挤占</h3>\n<p>最危险的误用是把命中率当成唯一目标函数。缓存池扩大后，KV 可用显存减少，批大小下降，吞吐反而可能低于不开缓存的基线。公式里 $M_{\\text{cache}}$ 同时出现在分子（读回时间）和隐性约束（挤占 KV 容量）中，只盯 $h$ 会看不见后者的代价。</p>\n<p>把挤占代价写成约束：设总显存为 $M_{\\text{HBM}}$，KV 可用空间为 $M_{\\text{HBM}} - M_{\\text{cache}}$，批大小 $b$ 与该空间成正比。当 $M_{\\text{cache}}$ 增大使 $b$ 下降时，吞吐 $\\propto b / T_{\\text{prefill}}^{\\text{cached}}$ 可能不升反降。这给出一个双向判据：扩大缓存池的边际收益必须同时覆盖读回时间与批大小损失。</p>\n<p>具体例子：一个高并发推理服务为提升 $h$ 把缓存池扩到占显存较大比例，单请求预填确实变快，但并发批大小被压缩，整体吞吐低于基线——这正是“只优化 $h$”的典型失败。工程判断是：把 $M_{\\text{cache}}$ 当作与批大小共享的稀缺资源，用 $h^{*}$ 反解出的上限约束缓存池，而不是让命中率指标单独驱动扩容。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-6\">六 · 盈亏平衡点：命中率阈值与失效边界</h3>\n\n<p>前缀缓存的收益不是单调的“开了就省”。把预填时间写成命中率 $h$ 的函数，收益结构立刻显形：<div class=\"formula\">$$T_{\\text{prefill}}^{\\text{cached}} = \\frac{2 P N_{\\text{in}} (1-h)}{\\eta_{\\text{MFU}} C} + \\frac{M_{\\text{cache}}}{B_{\\text{HBM}}}$$</div>第一项是剩余重算代价——$2P$ 为每 token 前向的浮点运算量（乘加各计一次），$N_{\\text{in}}(1-h)$ 是未命中、必须重新预填的 token 数，除以 $\\eta_{\\text{MFU}} C$ 折算为秒；第二项是把缓存块从 HBM 读回的时间。注意第二项与 $h$ 无关：只要缓存池存在，读取开销就按预留显存规模计入，命中率再高也压不掉它。令两项相抵解出零收益条件，得到阈值<div class=\"formula\">$$h^{*} = 1-\\frac{\\eta_{\\text{MFU}} C\\, M_{\\text{cache}}}{2 P N_{\\text{in}} B_{\\text{HBM}}}$$</div>它把“命中率够不够”写成算力、带宽、显存三者的比值。$h &lt; h^{*}$ 时，维护缓存的开销吃掉全部节省，系统比不开缓存更慢。这个阈值是容量决策的第一道闸门：给定 $M_{\\text{cache}}$ 预算与实测 $h$，可直接判断某仓库是否值得纳入缓存池；也可反解出达标所需的最小 $N_{\\text{in}}$，把长仓库上下文纳入、短输入走冷预填。</p>\n\n<p>$h^{*}$ 随 $N_{\\text{in}}$ 增大而下降，这是该方案最重要的边界性质：仓库上下文越长，未命中重算的绝对代价越大，越容易跨过盈亏点；反之单文件补全这类短输入 $N_{\\text{in}}$ 小，$h^{*}$ 可能逼近甚至超过 1，缓存永远不划算。工程上不能对所有请求统一开缓存，而应按 $N_{\\text{in}}$ 分层：长上下文请求进缓存池，短请求直接冷预填。第二个失效条件是前缀必须逐 token 完全一致。仓库上下文中插入一行注释、改动文件头部，都会让该位置之后的所有 token 失配，整段缓存作废，命中率骤降。这在 agent 循环里尤其致命——每轮改写文件头部是常态，而调度器若仍按旧的 $h$ 预留缓存容量，就会持续为一个已经失效的池子付显存与带宽。第三个失效条件是块对齐：缓存块按固定粒度（如 16 token）切分，短公共前缀不足一个块时被整块浪费，命中收益归零。</p>\n\n<p>最常见的误用是把 token 级命中率当作块级命中率。统计口径按 token 计数，短公共前缀（不足一个缓存块）被计为命中，实际有效 $h$ 为零；按公式算出的收益在部署中不出现，容量规划系统性高估节省。修正方式是统计时先把命中区间按 16 token 粒度向下取整，再累加有效命中 token 数，用这个“块级有效 $h$”代入阈值公式。另一类误用只优化 $h$ 而忽略 $M_{\\text{cache}}$ 的显存挤占：缓存池扩大后 KV 可用空间减少，可容纳的批大小下降，连续批处理的吞吐反而低于不开缓存的基线。此时预填时间确实缩短了，但解码阶段的并发度损失更大，端到端吞吐倒退。判断依据仍是那条公式——$M_{\\text{cache}}$ 同时出现在读取开销项和阈值分母里，扩大缓存池会同时抬高两项成本，收益窗口被双向压缩。</p>\n\n<table class=\"mini\"><thead><tr><th>条件</th><th>对 $h^{*}$ 的影响</th><th>工程后果</th></tr></thead><tbody><tr><td>$N_{\\text{in}}$ 增大（长仓库上下文）</td><td>下降</td><td>更易跨过盈亏点，值得开缓存</td></tr><tr><td>$M_{\\text{cache}}$ 扩大</td><td>上升</td><td>读取开销与显存挤占同时增加</td></tr><tr><td>前缀逐 token 失配（插入注释）</td><td>实际 $h$ 骤降</td><td>整段缓存作废，预留容量被浪费</td></tr><tr><td>公共前缀不足 16 token</td><td>有效 $h$ 归零</td><td>统计命中但零收益</td></tr></tbody></table>\n\n<p>把这三条失效条件合起来看，前缀缓存的适用域是一个窄带：长输入、前缀稳定、公共段足够长且块对齐良好。任何一条不满足，公式给出的节省都会被第二项或显存挤占吞掉。因此部署时的正确动作不是“默认开启”，而是先用块级有效 $h$ 与实测 $M_{\\text{cache}}$ 算出 $h^{*}$，再决定哪些仓库进池、池子预留多大——阈值公式在这里不是理论装饰，而是容量规划的直接输入。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-7\">七 · 盈亏平衡点：命中率阈值与它的三个失效面</h3>\n<p>前缀缓存的收益从来不是线性的：命中率 $h$ 只决定剩余重算量 $(1-h)$，而缓存本身要占用显存、并在复用时消耗一次 HBM 读带宽。把这两项放进同一个预填时间表达式，才有可判定的边界：</p>\n<div class=\"formula\">$$T_{\\text{prefill}}^{\\text{cached}} = \\frac{2 P N_{\\text{in}} (1-h)}{\\eta_{\\text{MFU}} C} + \\frac{M_{\\text{cache}}}{B_{\\text{HBM}}},\\qquad h^{*} = 1-\\frac{\\eta_{\\text{MFU}} C\\, M_{\\text{cache}}}{2 P N_{\\text{in}} B_{\\text{HBM}}}$$</div>\n<p>第一项里 $2P$ 是每 token 前向的浮点运算量，$N_{\\text{in}}(1-h)$ 是必须重算的 token 数，除以 $\\eta_{\\text{MFU}} C$ 得秒级预填时间；第二项是把缓存块从 HBM 读回的时间代价。令未命中重算节省的时间恰好等于缓存读取开销，解出的 $h^{*}$ 把“命中率阈值”写成算力、带宽、显存三者的比值——它不是经验常数，而是随部署形态漂移的量。$N_{\\text{in}}$ 越大 $h^{*}$ 越低，长仓库上下文容易跨过盈亏点；单文件补全这类短输入 $N_{\\text{in}}$ 小，$h^{*}$ 可能逼近甚至超过 1，缓存永远不划算。这一条直接支撑容量决策：给定 $M_{\\text{cache}}$ 预算与实测 $h$，判断某仓库是否值得开缓存；也可反解出达到目标 $h^{*}$ 所需的最小 $N_{\\text{in}}$，决定哪些仓库进缓存池、哪些走冷预填。</p>\n<p>第一个失效面是粒度错配。缓存块按固定粒度对齐（16 token），短公共前缀不足一块时被计为命中却实际零收益，token 级统计的 $h$ 系统性高于块级有效 $h$，按公式算出的节省在部署中不出现。第二个失效面在显存侧：只盯 $h$ 而放大 $M_{\\text{cache}}$，KV 可用空间被挤占、批大小下降，吞吐反而低于不开缓存的基线——公式第二项只算了读回时间，没算这笔机会成本。第三个失效面是前缀的逐 token 完全一致性：仓库上下文中插入一行注释即导致整段失效，而 agent 循环每轮改写文件头部时，调度器仍按旧 $h$ 预留缓存，命中率骤降与容量错配同时发生。工程判断因此落在两处：以块级有效命中率而非 token 统计值代入 $h^{*}$，并把 $M_{\\text{cache}}$ 的挤占代价计入基线对比。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>机制</th><th>系统代价</th></tr></thead><tbody><tr><td>块对齐浪费</td><td>短前缀不足 16 token 块</td><td>有效 $h$ 低于统计值，预填节省不兑现</td></tr><tr><td>缓存池挤占</td><td>$M_{\\text{cache}}$ 扩大压缩 KV 空间</td><td>批大小下降，吞吐低于无缓存基线</td></tr><tr><td>前缀逐 token 失配</td><td>插入注释或改写文件头部</td><td>命中率骤降，按旧 $h$ 预留的缓存空转</td></tr></tbody></table>\n<h3 id=\"th-prefix-cache-hit-bound-sec-8\">八 · 两项时间各自度量什么</h3>\n<p>缓存版预填时间写成两项相加，是把两种完全不同的物理过程并置。第一项 $\\frac{2PN_{\\text{in}}(1-h)}{\\eta_{\\text{MFU}}C}$ 度量的是<strong>算力时间</strong>：$2P$ 是每 token 前向的浮点运算量（乘与加各计一次），$N_{\\text{in}}(1-h)$ 是未命中、必须重新走一遍前向的 token 数，两者相乘得到剩余重算的 FLOPs，再除以 $\\eta_{\\text{MFU}}C$——有效算力，即峰值算力 $C$ 乘上实际可达的 MFU——才落到秒。分母里 $\\eta_{\\text{MFU}}$ 不是装饰：预填是算力受限的稠密矩阵乘阶段，MFU 决定了同一张 B200 上名义算力与实际吞吐的差距，把它从分母拿掉就等于假设硬件满负荷，公式立刻失去预测力。</p>\n<p>第二项 $\\frac{M_{\\text{cache}}}{B_{\\text{HBM}}}$ 度量的是<strong>带宽时间</strong>：$M_{\\text{cache}}$ 是为该请求前缀预留的缓存字节数，$B_{\\text{HBM}}$ 是 HBM 有效带宽，相除得到把这些 KV 块从 HBM 搬回片上所需的时间。注意这一项与 $h$ 无关——只要决定复用缓存，读回动作就要发生，读回量与命中多少无关，因为缓存块是按预留容量整体驻留的。这正是公式非线性的来源：节省项随 $h$ 线性下降，代价项是常数。</p>\n<p>两项相加隐含一个假设：读回与重算不重叠。工程上它们其实可以部分重叠——未命中部分的重算在 tensor core 上跑，命中部分的 KV 读回走 HBM，两者争用的是不同资源。公式取串行相加是保守下界，实际收益会比公式预测的略好；但在做容量决策时用保守界更安全，因为一旦按乐观值预留缓存池，显存挤占的副作用（见后文）不会被公式捕捉。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-9\">九 · 零收益条件的推导关键步</h3>\n<p>把“开缓存是否划算”形式化为：缓存带来的时间节省必须为正。不开缓存时预填时间为 $\\frac{2PN_{\\text{in}}}{\\eta_{\\text{MFU}}C}$，开缓存后为上式。两者相减，节省量为</p>\n<div class=\"formula\">$$\\Delta T = \\frac{2PN_{\\text{in}}h}{\\eta_{\\text{MFU}}C} - \\frac{M_{\\text{cache}}}{B_{\\text{HBM}}}$$</div>\n<p>令 $\\Delta T = 0$，即命中省下的算力时间恰好被读回带宽时间吃掉，解出临界命中率：</p>\n<div class=\"formula\">$$h^{*} = 1-\\frac{\\eta_{\\text{MFU}}C\\,M_{\\text{cache}}}{2PN_{\\text{in}}B_{\\text{HBM}}}$$</div>\n<p>推导中唯一非平凡的步骤是把 $M_{\\text{cache}}$ 从“容量”转成“时间”。这一步的合法性依赖一个前提：缓存池的驻留量与该请求的读回量成正比。真实系统里缓存池是全局共享的，$M_{\\text{cache}}$ 是池子总容量而非单请求占用，因此严格说第二项应写成单请求摊到的读回字节除以带宽。公式把 $M_{\\text{cache}}$ 当作单请求可归属的份额，是一种<strong>均摊近似</strong>——在请求长度同构、命中分布均匀时成立；仓库级负载往往长尾严重，少数超长仓库占据大部分缓存，均摊会把它们的读回代价低估。工程上应按仓库分桶计算 $h^{*}$，而不是全局一个阈值。</p>\n<p>另一个近似在 $2P$ 上：它假设前向是纯稠密 GEMM、每 token 计算量与上下文长度无关。实际预填中注意力部分的计算随 $N_{\\text{in}}$ 二次增长，$2P$ 只覆盖了线性部分。对长仓库上下文（$N_{\\text{in}}$ 达到数万 token），注意力项不可忽略，公式会系统性高估重算节省，从而把 $h^{*}$ 算低——即过于乐观地认为缓存划算。修正方式是把 $2P$ 换成 $2P + c\\cdot N_{\\text{in}}$ 形式的有效每 token 代价，但那样 $h^{*}$ 就不再是闭式，只能数值求解。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-10\">十 · $h^{*}$ 随 $N_{\\text{in}}$ 单调下降的含义</h3>\n<p>观察 $h^{*}$ 的表达式，$N_{\\text{in}}$ 只出现在分母，因此 $h^{*}$ 随输入长度增大而单调下降。这不是数学巧合，而是物理直觉的形式化：输入越长，单个未命中 token 的重算代价（相对固定的缓存读回开销）越大，于是越少比例的命中就足以回本。长仓库上下文天然站在盈亏点有利一侧。</p>\n<p>反向情形同样重要。单文件补全类请求 $N_{\\text{in}}$ 小，分母缩小，$h^{*}$ 可能被推到接近 1 甚至超过 1。$h^{*}&gt;1$ 在数学上意味着即使 100% 命中也不划算——因为读回整个缓存的时间超过了重算全部 token 的时间。这在短输入上是真实存在的：重算几十个 token 的算力时间可能只有微秒级，而读回一个 16 token 对齐的缓存块加上查找开销已与之相当。此时正确决策是不开缓存，走冷预填。</p>\n<p>工程含义是缓存策略必须<strong>按输入长度分档</strong>。同一套 $M_{\\text{cache}}$ 预算下，长上下文仓库应优先纳入缓存池，短请求应直接排除。若调度器对所有请求一视同仁地查缓存，短请求会稳定亏本，把长请求挣来的收益稀释掉。一个可操作的判据是：对每个仓库实测 $N_{\\text{in}}$ 分布，代入 $h^{*}$ 算出该仓库的准入阈值，只对实测 $h$ 高于阈值的仓库开缓存。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-11\">十一 · 离散化发生在块粒度上</h3>\n<p>公式里的 $h$ 是连续比例，但真实系统的命中是离散的。缓存块按固定粒度对齐，给定事实中的锚点是 16 token。这意味着一个前缀要么整块命中，要么整块不命中；不足一块的公共前缀在统计上会被计入命中，在物理上却零收益——因为块内未满部分无法复用，仍要重算。</p>\n<p>把连续 $h$ 换成块级有效命中率，需要一次向下取整式的离散化：设公共前缀长度为 $L$，块大小为 $b=16$，则有效命中 token 数为 $\\lfloor L/b \\rfloor \\cdot b$，有效命中率为</p>\n<div class=\"formula\">$$h_{\\text{eff}} = \\frac{\\lfloor L/b \\rfloor \\cdot b}{N_{\\text{in}}} \\le h_{\\text{stat}}$$</div>\n<p>差值 $h_{\\text{stat}} - h_{\\text{eff}}$ 就是块内浪费。当 $L$ 远大于 $b$ 时浪费可忽略；当 $L$ 只有几十 token、$b=16$ 时，浪费比例可达百分之几十。这正是“按 token 统计命中率却忽略块对齐”这一失败模式的数学根源：容量规划用 $h_{\\text{stat}}$ 代入公式，算出正收益，部署中却观察到收益消失，因为真实起作用的是 $h_{\\text{eff}}$。</p>\n<p>离散化还影响第二项。读回是按块进行的，命中 $k$ 块就读 $k$ 块，读回时间应为 $k \\cdot b \\cdot s_{\\text{kv}} / B_{\\text{HBM}}$（$s_{\\text{kv}}$ 为每 token KV 字节数），而非连续公式里的 $M_{\\text{cache}}/B_{\\text{HBM}}$。当 $M_{\\text{cache}}$ 是池子总容量时，这两者的差异被均摊近似掩盖；当按单请求精确计算时，块粒度会让读回时间呈阶梯状，$h^{*}$ 也随之变成阶梯函数而非光滑曲线。做精细容量规划时应按阶梯求解，而不是解连续方程后四舍五入。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-12\">十二 · 逐 token 一致性与公式的适用域</h3>\n<p>公式默认 $h$ 是一个可测的稳定量，但前缀缓存的命中前提是逐 token 完全一致。仓库上下文中插入一行注释，就会让该行之后的所有 token 位置错位，整段前缀失效，$h$ 从高位骤降到接近零。这不是公式算错了，而是公式的输入假设被打破——$h$ 不再是稳态参数，而是一个随仓库编辑历史剧烈波动的随机变量。</p>\n<p>在 agent 循环场景下这一点尤其致命。若每轮改写文件头部或插入注释，前缀逐 token 失配，实测 $h$ 会远低于历史统计值，而调度器仍按旧 $h$ 预留缓存池。结果是：缓存占着显存却不产生命中，$M_{\\text{cache}}$ 的挤占效应全额兑现，节省项却归零——公式预测的正收益变成实打实的负收益。这是三种失败模式里最难在监控上发现的，因为缓存命中计数器可能仍显示“有命中”（旧块尚未淘汰），但新请求的前缀已经对不上。</p>\n<p>因此公式的适用域应明确标注：它适用于<strong>前缀稳定</strong>的仓库上下文——即文件内容在多次请求间不发生头部插入、行序调整、注释注入的仓库。对编辑频繁的仓库，正确做法是把 $h$ 当作时变量，用滑动窗口估计近期 $h$，并设置一个失配检测：当前缀哈希与缓存索引不匹配时立即收缩该仓库的缓存配额，而不是继续按公式预留。公式给的是稳态判据，工程系统需要在其外围加一层失配触发的降级逻辑。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-13\">十三 · 反解 $N_{\\text{in}}$ 与容量决策</h3>\n<p>公式的实用价值不止于判断“是否划算”，还在于反解。给定 $M_{\\text{cache}}$ 预算与目标命中率 $h^{*}$，可解出为跨过盈亏点所需的最小输入长度：</p>\n<div class=\"formula\">$$N_{\\text{in}}^{\\min} = \\frac{\\eta_{\\text{MFU}}C\\,M_{\\text{cache}}}{2P(1-h^{*})B_{\\text{HBM}}}$$</div>\n<p>这个反解直接支撑仓库准入决策：算出每个仓库的 $N_{\\text{in}}^{\\min}$，把实测平均输入长度低于该值的仓库排除出缓存池，只让长仓库占用 $M_{\\text{cache}}$。这样做的收益是双重的——既避免了短仓库的亏本缓存，又因为缓存池只服务长仓库而提高了池子的有效利用率。</p>\n<p>但反解不能脱离显存挤占的约束单独使用。扩大 $M_{\\text{cache}}$ 会压缩 KV 可用空间，批大小随之下降，吞吐可能低于不开缓存的基线。公式里没有批大小这一项，它只比较单请求的预填时间，看不见并发维度的损失。工程判断应是：先用公式筛出值得缓存的仓库集合，再用 KV 容量模型（本卷其他部分讨论）验证扩大缓存池后批大小是否仍能维持 SLO。两个约束同时满足才开缓存；只满足公式约束而突破显存约束，就是“只优化 $h$ 忽略 $M_{\\text{cache}}$ 挤占”这一失败模式的完整路径。</p>\n<p>最后落在机制上：$h^{*}$ 的本质是把算力、带宽、显存三个物理量压成一个无量纲比值，它的预测力完全取决于代入的是 $h_{\\text{eff}}$ 而非 $h_{\\text{stat}}$、是分桶的 $M_{\\text{cache}}$ 而非全局均摊、是稳定前缀而非编辑中的仓库。三者任一失真，公式就会给出“划算”的错误信号，而部署中的代价由显存和批大小来付。</p>\n\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-14\">十四 · 盈亏点推导的边界：块对齐、显存挤占与仓库漂移</h3>\n<p>阈值 $h^{*}=1-\\eta_{\\text{MFU}}CM_{\\text{cache}}/(2PN_{\\text{in}}B_{\\text{HBM}})$ 的推导只做了一次离散化近似：把“缓存读取”压缩成 $M_{\\text{cache}}/B_{\\text{HBM}}$ 这一项连续时间，默认缓存块一经命中即整块可用。真实路径上，命中判定发生在固定粒度（如 16 token）的块边界，未命中块内的剩余 token 仍要整块重算。于是公式里的 $(1-h)$ 必须替换为块级未命中率 $1-h_b$，而 $h_b \\le h$：一段不足 16 token 的公共前缀在 token 统计里算命中，在块统计里收益为零。工程后果是容量规划系统性高估节省——按 token 级 $h$ 反解出的 $M_{\\text{cache}}$ 预算，在部署中对应的实际节省低于预期，短前缀密集的仓库（单文件补全、小函数复用）最先暴露这一偏差。</p>\n<p>第二个失效条件藏在 $M_{\\text{cache}}$ 的语义里。公式把缓存占用的显存当作一次性读取代价，却未计入它对 KV 可用空间的挤占：缓存池扩大后，同一张卡上可容纳的并发序列变少，批大小下降，解码阶段的吞吐随之走低。当 $h$ 只略高于 $h^{*}$ 时，预填省下的时间可能被批大小收缩带来的解码延迟抵消，系统整体吞吐反而低于不开缓存的基线。判断依据不是 $h&gt;h^{*}$ 本身，而是“预填节省 × 请求到达率”与“批大小损失 × 解码时间”两项的相对大小；前者随 $N_{\\text{in}}$ 增长，后者随并发度增长，二者在中等长度仓库、高并发场景下最容易反转。</p>\n<p>第三个失效条件是前缀的逐 token 稳定性假设。$h$ 在推导中是静态参数，但 agent 循环每轮改写文件头部、插入一行注释，就会让整段前缀失配，命中率骤降；而调度器仍按旧 $h$ 预留缓存块，形成“预留了显存却读不到命中”的空转。此时公式第二项照常付出，第一项的 $(1-h)$ 却回到 1，实际预填时间高于冷预填基线。可操作的判据是把 $h$ 当作滑动统计量而非常量：当观测到的块级命中率连续低于 $h^{*}$ 时，应收缩缓存池而非继续扩容，把显存还给 KV。</p>\n<table class=\"mini\"><thead><tr><th>失效源</th><th>公式中被破坏的项</th><th>系统代价</th></tr></thead><tbody><tr><td>块对齐浪费</td><td>$(1-h)\\to(1-h_b)$，$h_b&lt;h$</td><td>预填节省被高估，容量规划偏大</td></tr><tr><td>显存挤占</td><td>$M_{\\text{cache}}$ 未计入 KV 缩减</td><td>批大小下降，解码吞吐反降</td></tr><tr><td>前缀漂移</td><td>$h$ 静态化，实际趋近 0</td><td>缓存读取开销照付，预填无节省</td></tr></tbody></table>\n<h3 id=\"th-prefix-cache-hit-bound-sec-15\">十五 · 公式成立的前提假设</h3>\n<p>缓存版预填时间公式 <span class=\"formula\">$$T_{\\text{prefill}}^{\\text{cached}} = \\frac{2 P N_{\\text{in}} (1-h)}{\\eta_{\\text{MFU}} C} + \\frac{M_{\\text{cache}}}{B_{\\text{HBM}}}$$</span> 的推导隐含了四个假设，任何一个被打破，$h^{*}$ 就失去指导意义。第一，假设未命中 token 的重算代价与命中 token 的读取代价可以线性叠加——即预填阶段是算力受限的，HBM 读取不占用同一时间窗口。第二，假设 $M_{\\text{cache}}$ 是常量，缓存池大小不随请求动态变化；实际部署中缓存块按 LRU 淘汰，$M_{\\text{cache}}$ 在稳态下才近似恒定。第三，假设 $h$ 是请求级稳定量，同一仓库的连续请求命中率不随时间漂移。第四，假设缓存读取的带宽 $B_{\\text{HBM}}$ 与预填计算的带宽需求不冲突——而 tcgen05 MMA 在 SM100 上运行时同样要喂数据，二者共享 HBM 通道。</p>\n<p>工程上最容易被忽视的是第一条。当 $h$ 很高（接近 1）时，第一项趋近于零，预填时间几乎全部由 $M_{\\text{cache}}/B_{\\text{HBM}}$ 决定，此时系统从算力受限转为带宽受限。这意味着公式在 $h \\to 1$ 的极限下给出的“节省”是虚假的：你并没有省掉时间，只是把时间从 MMA 流水线搬到了 HBM 读取路径上。对于 B200 这类算力/带宽比极高的芯片，这个转换点来得比预期早——$2P$ 越大，第一项随 $(1-h)$ 收缩得越快，第二项的相对权重越高。</p>\n<p>具体例子：一个 $P$ 较大的模型处理 $N_{\\text{in}}$ 较长的仓库上下文，当 $h$ 从 0.5 升到 0.9 时，第一项缩小到原来的五分之一，但第二项不变；若 $M_{\\text{cache}}$ 预留了几个 GB，读取时间在毫秒量级，而剩余重算时间可能已降到同一量级，两项相加后总时间不再随 $h$ 显著下降。此时继续扩大缓存池只增加显存挤占，不换来延迟收益。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-16\">十六 · 逐 token 一致性与块对齐的双重失效</h3>\n<p>前缀缓存的命中判定是逐 token 完全一致，这是比公式中任何连续变量都更硬的约束。仓库上下文中插入一行注释、调整 import 顺序、格式化工具重排空白，都会让该位置之后的所有 token 失配。命中率不是从 $h$ 平滑下降到某个中间值，而是从失配点开始断崖式归零。这与公式把 $h$ 当作连续可调参数的处理形成张力：$h$ 在两次请求之间可以剧烈跳变，而调度器若按历史 $h$ 预留 $M_{\\text{cache}}$，就会在失配发生时既占着显存又拿不到命中收益。</p>\n<p>第二重失效来自块粒度。缓存块按固定粒度（如 16 token）对齐，命中以块为单位生效。一段长度不足一个块的公共前缀，在 token 级统计中计入命中，但在块级分配中根本不产生可复用的缓存块，实际有效 $h$ 为零。更普遍的情形是公共前缀长度为块粒度的非整数倍：末尾不足一块的部分被浪费，有效命中率被系统性高估。设块粒度为 $g$，真实可复用 token 数为 $\\lfloor N_{\\text{shared}}/g \\rfloor \\cdot g$，则有效命中率</p>\n<div class=\"formula\">$$h_{\\text{eff}} = \\frac{\\lfloor N_{\\text{shared}}/g \\rfloor \\cdot g}{N_{\\text{in}}} \\le h$$</div>\n<p>当 $N_{\\text{shared}}$ 接近 $g$ 的整数倍时两者接近；当 $N_{\\text{shared}}$ 远小于 $g$ 时，$h_{\\text{eff}}$ 可以低到统计值的零头。短公共前缀（如共享的系统提示词只有几个 token）是这一失效的典型场景：按 token 统计命中率可观，按块计算收益为零，容量规划据此高估节省，部署后收益不出现。</p>\n<p>代价落在显存与吞吐两侧：为这些“统计上命中、实际上无效”的前缀预留的缓存块仍占着 $M_{\\text{cache}}$，挤占 KV cache 空间，批大小下降；而调度器以为命中率高、预填便宜，放大了并发，实际每个请求仍在做接近全量的冷预填，预填队列堆积，首 token 延迟上升。这是块对齐误用最直接的工程后果——不是算错了节省，而是算错了容量。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-17\">十七 · 规模上限：$N_{\\text{in}}$ 的两端都不安全</h3>\n<p>$h^{*}$ 随 $N_{\\text{in}}$ 增大而下降，这常被读作“长上下文更适合前缀缓存”。这个读法只对了一半。$N_{\\text{in}}$ 增大确实压低阈值，但同一方向上 $M_{\\text{cache}}$ 也在增大——长仓库上下文对应的缓存块数量线性增长，而 HBM 容量固定。当缓存池大到挤占 KV cache 时，公式第二项的 $M_{\\text{cache}}$ 不再是可自由设定的常量，而是被显存预算硬约束的上限。此时反解 $h^{*}$ 得到的阈值是在“缓存池已满”的前提下算出的，继续增大 $N_{\\text{in}}$ 不再改善盈亏点，反而因 KV 空间压缩导致批大小下降、吞吐走低。</p>\n<p>另一端，短输入（单文件补全、单函数生成）的 $N_{\\text{in}}$ 小，$h^{*}$ 可能接近或超过 1，意味着无论命中率多高，缓存读取开销都盖过重算节省。这不是说短输入不能缓存，而是说缓存的经济性必须靠跨请求摊销——单请求内算不过来，只有同一前缀被反复复用时，$M_{\\text{cache}}/B_{\\text{HBM}}$ 才被多次分摊。公式本身没有刻画复用次数，这是它在短输入场景下的结构性盲区：它把一次读取代价与一次重算节省对比，而真实系统里读取代价被 $k$ 次命中分摊，重算节省也被 $k$ 次请求累加。复用次数 $k$ 足够大时，即使单次不划算也能转正；$k$ 小则相反。</p>\n<p>具体判断：给定 $M_{\\text{cache}}$ 预算与实测 $h$，可反解出为达到目标 $h^{*}$ 所需的最小 $N_{\\text{in}}$，据此决定哪些仓库纳入缓存池、哪些走冷预填。但反解结果只在 $M_{\\text{cache}}$ 未被显存预算封顶时有效；一旦缓存池触及上限，$N_{\\text{in}}$ 的增大不再带来阈值下降，规模上限由此显现。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-18\">十八 · 动态上下文下的命中率漂移</h3>\n<p>agent 循环是前缀缓存最容易被高估的场景。每一轮工具调用后，模型可能改写文件头部、插入注释、重排结构，前缀逐 token 失配，命中率骤降。而调度器通常按上一轮的 $h$ 预留缓存、规划批大小，形成滞后：预留的缓存块在新一轮全部失效，显存被占，命中却归零。公式把 $h$ 当作静态参数，无法表达这种轮间跳变；把它当作滑动平均又会平滑掉断崖，导致容量决策在失配发生后的若干轮内持续高估收益。</p>\n<p>工程上的处理不是修正公式，而是给公式加一层失效检测：按块粒度实测有效命中率，与调度器预留的 $h$ 做偏差比较，偏差超过阈值时收缩缓存池、回退到冷预填路径。代价是检测本身要读缓存元数据、比对块哈希，这部分开销计入查找成本，在 $h$ 本就接近 $h^{*}$ 的仓库上可能直接把系统推过盈亏点。换言之，失效检测在临界区附近是有代价的，不能无条件开启。</p>\n<p>另一个漂移源是并发请求的前缀分叉：同一仓库的不同请求在某个位置走向不同分支，公共前缀在分叉点截断。分叉点之前的块可共享，之后的块各自独立。若调度器按整段前缀预留缓存，分叉后的块被重复占用，$M_{\\text{cache}}$ 的实际有效利用率低于名义值。这同样是公式未刻画的：它假设缓存块全部有效，而分叉使一部分块只被单请求使用，读取代价无法被复用分摊。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-19\">十九 · 何时该放弃公式，改用实测</h3>\n<p>公式的适用边界可以压缩成三条判据。其一，$h$ 在请求间稳定且块级有效命中率与 token 级统计偏差小——否则 $h^{*}$ 的输入本身就是错的。其二，$M_{\\text{cache}}$ 未被显存预算封顶，缓存池大小可调——否则反解出的阈值不构成可执行决策。其三，预填确实处于算力受限区间，HBM 读取不与之争夺同一瓶颈——否则两项叠加的线性假设不成立，$h \\to 1$ 时的“节省”是账面数字。</p>\n<p>三条中任一不满足，就应放弃解析阈值，改用块级实测命中率与端到端首 token 延迟做容量决策：直接测开缓存与不开缓存的吞吐差，按仓库维度决定是否纳入缓存池，而不是按公式算出的 $h^{*}$ 一刀切。这不是否定公式，而是承认它的推导前提在动态仓库、块对齐、显存封顶三类场景下被系统性破坏，此时解析解给出的是方向而非数值。</p>\n<p>一个可操作的工程判断：把 $h_{\\text{eff}}$（块级）而非 $h$（token 级）代入 $h^{*}$ 的比较，若 $h_{\\text{eff}}$ 与 $h$ 的差距超过块粒度带来的理论上限，说明该仓库的公共前缀碎片化严重，缓存池应缩小而非扩大；若两者接近且 $M_{\\text{cache}}$ 未触顶，公式的阈值可以直接用于纳入决策。这条判断把公式从“算节省”降级为“筛仓库”，恰好落在它前提成立的区间内。</p>\n\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-20\">二十 · 盈亏点之外的三个断崖：逐 token 一致性、块对齐与显存挤占</h3>\n\n<p>把 $h^{*}$ 当作一张“命中率及格线”来用，前提是公式里的每一项都还在它假设的工况内。第一个假设最脆弱：前缀必须逐 token 完全一致。仓库上下文不是静态语料，agent 循环每轮都可能改写文件头部、插入一行注释、调整 import 顺序，而这些改动落在序列最前端，会让其后所有 token 的位置整体位移，缓存块逐块失配。此时实测 $h$ 从高位骤降，而调度器仍按上一轮的 $h$ 预留 $M_{\\text{cache}}$，形成“缓存占着显存、命中却归零”的双重浪费——预填时间回到冷启动水平，同时批大小被压缩。工程上的判断是：把 $h$ 当作随会话演化的状态量而非仓库的固有属性，缓存池按最近窗口的实测命中率动态收缩，而不是按历史峰值静态分配。</p>\n\n<p>第二个断崖来自块粒度。缓存按固定粒度（如 16 token）对齐，命中判定发生在块边界上，因此长度不足一个块的公共前缀在统计口径里被记为命中，在物理上却零收益。设公共前缀长度为 $L$、块粒度为 $g$，则有效命中率近似为 $\\lfloor L/g \\rfloor g / L$，当 $L&lt;g$ 时该式恒为零。单文件补全、函数级问答这类场景的公共前缀往往只有几个 token 的系统提示加少量上下文，统计报表上的 $h$ 好看，部署中却看不到任何预填节省。容量规划若直接用 token 级 $h$ 代入 $h^{*}$ 判据，就会把一批本应走冷预填的仓库错误纳入缓存池，白白占用显存并增加查找开销。</p>\n\n<p>第三个断崖是 $M_{\\text{cache}}$ 对 KV 空间的挤占，这一点公式只用一项 $M_{\\text{cache}}/B_{\\text{HBM}}$ 表达了读回代价，却没有表达它对并发度的侵蚀。缓存池扩大后 KV 可用显存减少，可驻留的批大小下降，decode 阶段的吞吐随之走低；当批大小跌破某个水平，即便预填确实省了时间，端到端吞吐仍可能低于不开缓存的基线。换言之，$h^{*}$ 只回答了“预填这一项划不划算”，没有回答“整机划不划算”。因此容量决策应做双约束：既要求实测 $h&gt;h^{*}$，也要求扩大缓存后 decode 批大小不低于吞吐拐点。反解最小 $N_{\\text{in}}$ 时同样要带上这个约束——长仓库上下文因 $N_{\\text{in}}$ 大而天然容易跨过盈亏点，短输入则可能永远不划算，这正是把仓库分池、冷热分流的依据。</p>\n\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>公式中的表现</th><th>系统代价</th></tr></thead><tbody><tr><td>前缀逐 token 失配</td><td>实测 $h$ 骤降，$h^{*}$ 判据失效</td><td>预填回到冷启动，缓存显存空占</td></tr><tr><td>短前缀被块对齐吞掉</td><td>有效 $h$ 低于统计 $h$</td><td>查找与读回开销照付，节省为零</td></tr><tr><td>缓存池挤占 KV</td><td>$M_{\\text{cache}}$ 上升未反映在公式收益里</td><td>批大小下降，decode 吞吐低于基线</td></tr></tbody></table>\n<h3 id=\"th-prefix-cache-hit-bound-sec-21\">二十一 · 从阈值到决策变量：反解批大小与并行度</h3>\n<p>$h^{*}$ 的价值不在于它是一个被动的判据，而在于它是三个可调量的函数：算力 $\\eta_{\\text{MFU}} C$、带宽 $B_{\\text{HBM}}$、显存 $M_{\\text{cache}}$。工程上真正要问的是：给定一个仓库的实测 $h$ 与 $N_{\\text{in}}$，我应该把 $M_{\\text{cache}}$ 压到多少、把批大小放到多少，才能让缓存版预填时间严格小于冷预填时间。把公式第二项移项，可得缓存可用的显存上界：</p>\n<div class=\"formula\">$$M_{\\text{cache}}^{\\max} = \\frac{2 P N_{\\text{in}} (1-h) B_{\\text{HBM}}}{\\eta_{\\text{MFU}} C}$$</div>\n<p>这个式子的读法是：命中率越高，允许的缓存池越小——因为剩余重算量已经很小，再大的缓存读回开销就会反超节省。反过来，若某仓库 $h$ 只有 0.3 而 $N_{\\text{in}}$ 又不大，$M_{\\text{cache}}^{\\max}$ 会被压到很小，意味着你只能给这个仓库分配极有限的缓存块，否则读回时间吃掉全部收益。批大小的耦合在于：批内多个请求共享同一前缀时，$M_{\\text{cache}}$ 是每批只读一次还是每请求各读一次，直接改变第二项的系数。若调度器能把同前缀请求聚成一批，读回代价被摊薄，等效于把 $B_{\\text{HBM}}$ 放大；若做不到，第二项按请求数线性增长，$h^{*}$ 随之抬升。因此定批大小的正确顺序是：先按前缀聚类确定可摊薄的读回次数，再反解 $M_{\\text{cache}}^{\\max}$，最后用剩余显存除以单请求 KV 占用得到批上界。并行度同理——TP 扩大后每卡 $B_{\\text{HBM}}$ 与 $C$ 同步缩放，$h^{*}$ 中的比值近似不变，但 $M_{\\text{cache}}$ 被切分到更多卡上，单卡缓存池变小，块对齐浪费的相对比例上升，这是 TP 决策里容易被忽略的一项。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-22\">二十二 · KV 预算：缓存池与 KV 池的零和分配</h3>\n<p>前缀缓存池与 KV 池共享同一块 HBM，这不是比喻而是硬约束。设总可用显存为 $M_{\\text{HBM}}$，权重占 $M_{W}$，则 $M_{\\text{cache}} + M_{\\text{KV}} = M_{\\text{HBM}} - M_{W}$。缓存池每扩大一字节，KV 池就少一字节，而 KV 池决定并发批大小。于是存在一个显式的吞吐最优点：把 $M_{\\text{cache}}$ 从 0 开始增大，预填时间按第一项下降、按第二项上升，同时解码吞吐因批大小下降而线性下滑。写成吞吐表达式：</p>\n<div class=\"formula\">$$\\text{Throughput}(M_{\\text{cache}}) \\approx \\frac{B_{\\text{batch}}(M_{\\text{cache}})}{T_{\\text{prefill}}^{\\text{cached}} + T_{\\text{decode}}}$$</div>\n<p>其中 $B_{\\text{batch}}$ 随 $M_{\\text{cache}}$ 增大而单调下降。这个式子没有闭式解，但给了明确的搜索方向：对每个候选 $M_{\\text{cache}}$ 采样实测 $h$ 与 $T_{\\text{prefill}}$，取吞吐最大点。工程判断是——当 $h$ 接近 $h^{*}$ 时，第一项的边际收益已经很小，而 $B_{\\text{batch}}$ 的边际损失是线性的，最优点必然落在 $h$ 明显高于 $h^{*}$ 的区域，而不是恰好等于阈值处。这就是“只优化 $h$ 而忽略 $M_{\\text{cache}}$ 挤占”这一失败模式的数学根源：调度器按旧 $h$ 预留了过大的缓存池，KV 池被挤压后批大小下降，吞吐反而低于不开缓存的基线。具体例子：一个 agent 循环每轮改写文件头部，前缀逐 token 失配，实测 $h$ 骤降，但缓存池仍按历史 $h$ 预留，此时 $M_{\\text{cache}}^{\\max}$ 已经小于实际预留量，系统处于纯亏损区，必须由调度器按滑动窗口的 $h$ 估计动态回收缓存块。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-23\">二十三 · SLO 反解：把 $h^{*}$ 变成准入判据</h3>\n<p>SLO 通常写成首 token 时延（TTFT）的上界。预填时间就是 TTFT 的主体，因此可以直接把 $T_{\\text{prefill}}^{\\text{cached}} \\le \\text{TTFT}_{\\text{SLO}}$ 当作准入不等式，反解出该请求必须达到的最小命中率：</p>\n<div class=\"formula\">$$h_{\\min} = 1 - \\frac{\\eta_{\\text{MFU}} C}{2 P N_{\\text{in}}}\\left(\\text{TTFT}_{\\text{SLO}} - \\frac{M_{\\text{cache}}}{B_{\\text{HBM}}}\\right)$$</div>\n<p>这个式子的工程含义是：SLO 越紧，$h_{\\min}}$ 越高；$N_{\\text{in}}$ 越长，同样的 SLO 下 $h_{\\min}}$ 越低，因为长上下文给了更多可命中的 token。于是路由层可以据此做准入：对每个进站请求先查前缀树得到预估 $h$，若 $h &lt; h_{\\min}}$ 则不走缓存路径、直接冷预填并跳过缓存查找（省掉查找开销），若 $h \\ge h_{\\min}}$ 则走缓存路径。这比“有缓存就用”的朴素策略更稳，因为它在 SLO 层面做了显式取舍。注意 $M_{\\text{cache}}/B_{\\text{HBM}}$ 这一项在 SLO 紧时会显著抬高 $h_{\\min}}$——读回时间本身不可压缩，缓存池越大读回越慢，所以紧 SLO 场景下应当优先缩小缓存块粒度而非扩大池子。具体例子：单文件补全类请求 $N_{\\text{in}}$ 小，$h_{\\min}}$ 可能被推到接近 1，此时任何缓存查找都是纯开销，路由应直接判定为冷预填，这也解释了为什么短输入场景下前缀缓存常常“开了但没用”。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-24\">二十四 · 算例：一个仓库上下文的完整决策链</h3>\n<p>设某仓库上下文 $N_{\\text{in}} = 32\\text{K}$ token，模型参数量 $P$ 给定，$\\eta_{\\text{MFU}}$ 与 $C$ 由硬件决定，$B_{\\text{HBM}}$ 取有效带宽。实测该仓库跨请求的 token 级命中率 $h = 0.6$，但缓存块粒度为 16 token，公共前缀多为不足一块的短片段，块级有效命中率低于统计值——按失败模式，容量规划若直接用 0.6 会高估节省。决策链如下：第一步，用块级有效 $h$ 重算 $M_{\\text{cache}}^{\\max}$，得到该仓库可分配的缓存显存上界；第二步，用 $M_{\\text{HBM}} - M_{W} - M_{\\text{cache}}^{\\max}$ 得到 KV 池，除以单请求 KV 占用得批上界；第三步，用 $h_{\\min}}$ 检查该仓库在目标 TTFT SLO 下是否准入；第四步，若准入，把该仓库纳入缓存池并按前缀聚类调度，若不准入则标记为冷预填仓库。算例的关键判断在于：$N_{\\text{in}} = 32\\text{K}$ 使 $h^{*}$ 相对较低，长上下文天然容易跨过盈亏点，所以这个仓库大概率值得开缓存；但块对齐浪费会把有效 $h$ 从 0.6 拉低，若拉低后仍高于 $h^{*}$ 则收益成立，若低于则应当缩小缓存块粒度或放弃该仓库。反过来，若同一系统里还有 $N_{\\text{in}} = 2\\text{K}$ 的单文件补全流量，其 $h^{*}$ 接近或超过 1，必须走冷预填路径，不能与仓库流量共用同一缓存池预算——共用会导致仓库流量的 $M_{\\text{cache}}$ 被短请求的无效查找稀释。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-25\">二十五 · 动态 $h$ 估计与缓存池回收</h3>\n<p>上述所有决策都依赖 $h$ 的准确估计，而 $h$ 不是静态量。agent 循环每轮改写文件头部或插入注释，前缀逐 token 失配，命中率骤降；调度器若仍按旧 $h$ 预留缓存，就落入纯亏损区。工程上必须把 $h$ 做成滑动窗口统计，并让 $M_{\\text{cache}}$ 随之下调。具体机制是：为每个仓库维护一个按请求计数的命中率估计 $\\hat{h}$，当 $\\hat{h}$ 跌破 $h^{*}$ 时触发缓存块回收，把释放的显存归还 KV 池以恢复批大小；当 $\\hat{h}$ 回升时再逐步扩池。回收粒度应与缓存块粒度对齐（16 token 的整数倍），避免回收本身产生碎片。代价方面，滑动窗口估计引入估计滞后，滞后期间系统可能处于次优区，因此窗口长度要按请求到达率选取——到达率高则窗口短、响应快但方差大，到达率低则窗口长、稳定但滞后明显。另一个必须处理的细节是：块级有效 $h$ 与 token 级 $h$ 的偏差应作为独立指标监控，二者差距扩大意味着公共前缀正在碎片化，此时扩大缓存池无益，应转向提示词结构化（把稳定前缀前置、把易变内容后置）来恢复块级命中。这一条落在具体机制上：前缀的物理布局决定块对齐效率，而块对齐效率决定公式里的 $h$ 是否可信。</p>\n\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-26\">二十六 · 把盈亏平衡式嵌进调度器：批大小、并行度、KV 预算与 SLO 的联合定标</h3>\n\n<p>前文给出的 $h^{*}$ 不是一个事后审计指标，而是一个可以写进调度器决策环的约束。工程上真正要做的，是把 $h^{*}$ 与批大小 $B$、张量并行度 $T$、KV 预算 $M_{\\text{KV}}$ 和 SLO 里的首 token 时延预算 $t_{\\text{TTFT}}$ 放在同一张表里联立。核心判断只有一条：前缀缓存池 $M_{\\text{cache}}$ 与 KV 池 $M_{\\text{KV}}$ 共享同一块 HBM，前者每扩大一字节，后者就少一字节，而后者直接决定稳态批大小。于是容量决策可以写成一个带约束的极值问题——在 $\\sum_i M_{\\text{cache},i} + M_{\\text{KV}} \\le M_{\\text{HBM}}$ 下，最大化满足 $T_{\\text{prefill}}^{\\text{cached}} \\le t_{\\text{TTFT}}$ 的并发请求数。这里的关键量是缓存版预填时间的第一项 $\\frac{2 P N_{\\text{in}}(1-h)}{\\eta_{\\text{MFU}} C}$：它随 $h$ 线性下降，而第二项 $M_{\\text{cache}}/B_{\\text{HBM}}$ 随缓存池线性上升，两者斜率符号相反，交点就是该仓库、该并行度下的最优缓存配额。批大小不是独立变量——它由剩余 KV 空间反解，因此“先定批大小再定缓存”的顺序在仓库级复用场景下是错的，必须先定缓存配额，再让批大小吃剩余空间。</p>\n\n<p>具体机制上，调度器应当对每个仓库维护一个滑动窗口的实测 $h$（按块对齐后的有效命中率，而非 token 统计值），并用它反解两个决策量。第一，判断是否纳入缓存池：给定当前 $M_{\\text{cache}}$ 配额，若实测 $h &lt; h^{*}$，则该仓库走冷预填，缓存池腾出的显存回流给 KV，批大小上升，吞吐改善；若 $h &gt; h^{*}$，则保留缓存并考虑扩容。第二，反解最小可缓存输入长度 $N_{\\text{in}}^{\\min}$：由 $h^{*}=1-\\frac{\\eta_{\\text{MFU}} C M_{\\text{cache}}}{2 P N_{\\text{in}} B_{\\text{HBM}}}$ 移项得 $N_{\\text{in}}^{\\min}=\\frac{\\eta_{\\text{MFU}} C M_{\\text{cache}}}{2 P B_{\\text{HBM}}(1-h)}$，它给出“多长的仓库上下文才配得上这份缓存配额”的下界。短输入的单文件补全类请求 $N_{\\text{in}}$ 小，$N_{\\text{in}}^{\\min}$ 往往高于其实际长度，公式直接判定不划算，无需实测即可排除。并行度 $T$ 通过 $\\eta_{\\text{MFU}}$ 与 $C$ 的有效利用率间接进入：$T$ 增大时单卡有效算力占比变化，$\\eta_{\\text{MFU}}$ 随之漂移，$h^{*}$ 的分母 $2 P N_{\\text{in}} B_{\\text{HBM}}$ 不变而分子里的 $\\eta_{\\text{MFU}} C$ 改变，因此同一仓库在不同 TP 配置下的盈亏点并不相同，缓存池配额必须按并行度分组标定，不能全局一刀切。</p>\n\n<p>算例。设某仓库上下文 $N_{\\text{in}}$ 为长上下文量级，模型参数 $P$ 固定，HBM 有效带宽 $B_{\\text{HBM}}$ 与峰值算力 $C$ 取该卡实测有效值，$\\eta_{\\text{MFU}}$ 取预填阶段的实测利用率。给定缓存配额 $M_{\\text{cache}}$，代入 $h^{*}$ 表达式得到一个阈值；若该仓库实测块级有效命中率高于此阈值，则保留缓存，此时预填时间第一项按 $(1-h)$ 缩减，第二项为固定的缓存回读开销，二者相加仍低于冷预填的 $\\frac{2 P N_{\\text{in}}}{\\eta_{\\text{MFU}} C}$，SLO 中的 TTFT 预算得以守住；若低于阈值，则把该仓库踢出缓存池，$M_{\\text{cache}}$ 释放给 KV，批大小按释放量等比上升，吞吐回到基线以上。注意这里不引入任何未给定的具体数值——算例的结论是定性的：阈值两侧的决策方向由公式符号决定，而具体倍数取决于实测的 $\\eta_{\\text{MFU}}$、$B_{\\text{HBM}}$ 与 $h$，这三者必须在目标硬件与目标框架上实测，不能从规格表推算。</p>\n\n<table class=\"mini\">\n<thead><tr><th>决策量</th><th>由公式导出的判据</th><th>系统代价</th></tr></thead>\n<tbody>\n<tr><td>批大小 $B$</td><td>缓存配额确定后，KV 剩余空间反解 $B$</td><td>缓存挤占 KV 导致 $B$ 下降，吞吐反低于基线</td></tr>\n<tr><td>并行度 $T$</td><td>按 $\\eta_{\\text{MFU}}$ 分组标定 $h^{*}$，不跨组复用配额</td><td>TP 改变使阈值漂移，旧配额失准</td></tr>\n<tr><td>KV 预算</td><td>$M_{\\text{KV}} = M_{\\text{HBM}} - \\sum M_{\\text{cache},i}$</td><td>缓存池扩大直接压缩 KV，长上下文并发受限</td></tr>\n<tr><td>SLO（TTFT）</td><td>$T_{\\text{prefill}}^{\\text{cached}} \\le t_{\\text{TTFT}}$</td><td>缓存回读项 $M_{\\text{cache}}/B_{\\text{HBM}}$ 是硬性下限</td></tr>\n</tbody>\n</table>\n\n<p>边界与失效条件必须写进调度器的保护逻辑，否则公式会被误用成“开了缓存就一定省”。第一，前缀必须逐 token 完全一致才命中，agent 循环每轮改写文件头部或插入一行注释，整段前缀失配，$h$ 骤降，而调度器若仍按旧 $h$ 预留 $M_{\\text{cache}}$，就会出现缓存占着显存却零收益的双重损失——保护逻辑应检测连续多轮 $h$ 跌破 $h^{*}$ 即触发配额回收。第二，块对齐粒度（16 token）意味着短公共前缀的命中被块内浪费抵消，按 token 统计的 $h$ 系统性高于块级有效 $h$，容量规划会高估节省；调度器必须只采信块级命中计数，token 级统计仅作参考。第三，只优化 $h$ 而忽略 $M_{\\text{cache}}$ 的显存挤占是典型误用：缓存池扩大后 KV 可用空间减少、批大小下降，吞吐反而低于不开缓存的基线，这正是公式第二项存在的意义——它把缓存回读的带宽代价显式计入，防止决策者只盯第一项的缩减。第四，$h^{*}$ 随 $N_{\\text{in}}$ 增大而下降，说明长仓库上下文更容易跨过盈亏点，但这也意味着短输入场景下 $h^{*}$ 可能接近或超过 1，缓存永远不划算，此类请求应在入口处直接路由到冷预填路径，不进入缓存池的准入判断。最终落在工程判断上：把 $h^{*}$ 当作每个（仓库 × 并行度 × 缓存配额）三元组的准入阈值，用块级实测 $h$ 驱动准入与回收，用释放的显存反解批大小，才是这套公式在容量决策中的正确用法。</p>\n<h3 id=\"th-prefix-cache-hit-bound-sec-27\">二十七 · 误用一：把 token 级命中率当块级命中率</h3>\n<p>这是部署中最普遍、也最隐蔽的误用。前缀缓存的存储与查找单位不是 token，而是固定粒度的缓存块，典型粒度为 16 token。调度器在做容量规划时若直接拿监控面板上的 token 级命中率 $h$ 代入公式，就会系统性高估收益。原因在于：一段不足一个块的公共前缀（例如 8 个 token 的系统提示尾巴、一段短函数签名）在 token 统计里被计为命中，但在块对齐的缓存索引里根本构不成一个可复用的块，实际收益为零。</p>\n<p>机制上，缓存键是块哈希链：第 $k$ 个块的键由前 $k-1$ 个块的哈希与本块 16 个 token 的内容共同决定。只有整块 16 个 token 逐字节一致，该块才进入可命中集合；不足一块的尾部只能走重算。于是有效命中率应写成块级口径：</p>\n<div class=\"formula\">$$h_{\\text{eff}} = \\frac{16 \\cdot \\lfloor N_{\\text{hit}}/16 \\rfloor}{N_{\\text{in}}} \\le h$$</div>\n<p>两者差值就是块内浪费，量级为每段公共前缀最多 15 个 token。当 $N_{\\text{in}}$ 很大（长仓库上下文）时这点浪费可忽略；但当输入本身只有几百 token、公共前缀又短时，$h_{\\text{eff}}$ 可能只有统计值的一半甚至更低，此时用 $h$ 反解出的 $h^{*}$ 判断“值得开缓存”就是错的。</p>\n<p>系统代价落在容量与吞吐两侧：按虚高的 $h$ 预留 $M_{\\text{cache}}$，会挤占 KV 可用显存，压低并发批大小；而实际省下的预填时间远小于预期，端到端吞吐可能低于不开缓存的基线。识别方法很直接——在监控里同时打点 token 级命中数与块级命中数，二者比值持续偏离 1 即说明块对齐在吃收益；再对若干真实请求抽样，把公共前缀长度对 16 取模，看余数分布是否集中在 1–15。举例：某代码补全服务把系统提示压缩到 12 个 token 以“提高命中率”，token 面板显示 $h$ 接近 0.9，但块级命中为零，预填时间没有任何下降。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-28\">二十八 · 误用二：只优化 $h$，无视 $M_{\\text{cache}}$ 的显存挤占</h3>\n<p>公式里 $h$ 与 $M_{\\text{cache}}$ 不是独立变量：缓存池扩大，KV 可用空间就缩小，二者争夺同一块 HBM。很多团队把“提高命中率”当成唯一目标，不断加大缓存池、延长缓存保留时间，结果 $h$ 上去了，批大小却掉下来。这正是 $h^{*}$ 表达式所刻画的权衡——阈值本身随 $M_{\\text{cache}}$ 上升而上升，意味着缓存越大，需要的命中率越高才划算。</p>\n<p>把挤占效应写成约束更清楚。设总显存为 $M_{\\text{HBM}}$，KV 每 token 占用 $m_{\\text{kv}}$，则最大并发请求数近似为</p>\n<div class=\"formula\">$$B_{\\max} \\approx \\frac{M_{\\text{HBM}} - M_{\\text{cache}} - M_{\\text{weight}}}{m_{\\text{kv}} \\cdot N_{\\text{ctx}}}$$</div>\n<p>$M_{\\text{cache}}$ 每增加一份，$B_{\\max}$ 线性下降。在解码阶段受显存带宽约束的负载下，吞吐近似正比于批大小，因此缓存挤占的代价可以直接换算成吞吐损失。判断是否越界，要看“缓存省下的预填时间”是否大于“批大小下降带来的解码吞吐损失”，而不是只看预填一项。</p>\n<p>识别信号有三：其一，开启缓存后 GPU 显存利用率长期贴顶、调度器频繁因显存不足拒绝新请求；其二，$h$ 上升的同时 token/s 下降；其三，缓存池的淘汰率很低（说明大量块长期占位却极少被复用）。反例：一个多租户推理服务为提升仓库级复用，把缓存池设为显存的四成，$h$ 从 0.4 提到 0.7，但批大小从 48 掉到 22，解码吞吐反而低于关闭缓存的基线——省下的预填算力抵不过解码并发的塌陷。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-29\">二十九 · 误用三：假设仓库上下文稳定，忽略逐 token 失配</h3>\n<p>前缀命中要求逐 token 完全一致，这是硬约束而非近似。仓库上下文恰恰是最不稳定的输入：agent 循环每轮改写文件头部、插入一行注释、调整 import 顺序，都会让从改动点开始的所有后续块哈希全部改变，整段缓存失效。更糟的是调度器仍按历史 $h$ 预留缓存、按旧命中率做容量规划，形成“缓存占着显存但命中率骤降”的双重损失。</p>\n<p>机制上，块哈希链是前缀敏感的：第 $k$ 块的键依赖前 $k-1$ 块，因此任意位置的一行插入会让其后所有块失配，失配范围是“改动点之后的全长”，而不是“改动的那一行”。有效命中率因此退化为改动点之前的前缀占比：</p>\n<div class=\"formula\">$$h_{\\text{eff}} \\approx \\frac{N_{\\text{prefix}}}{N_{\\text{in}}},\\quad N_{\\text{prefix}} = \\text{改动点之前的 token 数}$$</div>\n<p>若 agent 每轮都在文件头部附近改动，$N_{\\text{prefix}}$ 极小，$h_{\\text{eff}}$ 趋近于零，而 $M_{\\text{cache}}$ 仍被占着。系统代价是双向的：预填没有节省，显存却被无效块占用，批大小与解码吞吐同时受损。识别方法是按“改动位置分布”而非“命中率均值”做统计——把每个请求的失配起点位置画成直方图，若大量样本的失配起点落在上下文的头 10%，说明缓存策略对该工作负载根本不成立。</p>\n<p>反例：一个代码 agent 每轮在仓库上下文顶部插入时间戳注释以做审计，缓存池按上一周的 $h=0.6$ 预留了三成显存。上线后每轮前缀从第一个块起就失配，实际 $h_{\\text{eff}}$ 接近零，预填时间与不开缓存持平，但可用 KV 显存少了三成，长对话请求开始排队。修复不是调大缓存，而是把易变内容移出前缀（时间戳放到后缀或元数据字段），让稳定部分留在前缀，$h_{\\text{eff}}$ 才回到可用区间。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-30\">三十 · 反例复盘：一次“命中率很高但收益为零”的容量决策</h3>\n<p>把三个误用叠在一个具体场景里看后果。某仓库级问答服务，输入 $N_{\\text{in}}$ 约数千 token，团队在压测中观察到 token 级 $h$ 达 0.8，遂按公式反解 $h^{*}$ 判定“远高于盈亏点”，把缓存池扩到显存的三分之一并纳入全部仓库。上线一周后三项指标同时恶化：预填时间几乎没降、批大小下降、尾延迟上升。</p>\n<p>逐项归因：其一，公共前缀多为短小的文件头与许可证声明，长度常不足 16 token，token 级命中被块对齐吞掉，块级 $h$ 远低于 0.8；其二，缓存池扩大挤占 KV，$B_{\\max}$ 下降，解码吞吐受损；其三，部分仓库由 agent 持续改写，前缀逐 token 失配，历史 $h$ 不再代表当下。三者叠加，使“按公式算出的收益”在部署中完全没有出现——公式没错，错在代入公式的 $h$ 与 $M_{\\text{cache}}$ 不是部署口径下的真实值。</p>\n<p>工程判断应落在口径统一上：容量决策必须用块级有效命中率、按当前工作负载的改动位置分布加权，并把 $M_{\\text{cache}}$ 的挤占代价计入同一本账。具体做法是给每个仓库维护“块级命中率 + 失配起点分布 + 缓存块复用频次”三元组，只有三元组同时达标才纳入缓存池；对短公共前缀的仓库走冷预填，对高频改写的仓库把易变段移出前缀。这样 $h^{*}$ 才是可执行的判据，而不是一个被统计口径污染的漂亮数字。</p>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-31\">三十一 · 误用与反例：命中率统计口径、缓存挤占与失效前缀</h3>\n<p>最常见的误用是把 token 级命中率直接当成块级命中率代入盈亏公式。前缀缓存按固定粒度对齐，例如 16 token 一块，命中判定以整块为单位：一个公共前缀若只有 12 个 token 与缓存块相同，剩余 4 个 token 落在块内不同位置，这一整块就无法复用，实际有效 $h$ 为零，而统计脚本仍把它记为 12 个命中 token。这类短公共前缀在仓库场景里极多——同一份 license 头、同一段 import 块、同一组常量定义，长度往往不足一个块。后果是容量规划按统计 $h$ 算出的预填节省在部署中根本不出现，调度器却已经按这个乐观值削减了预填资源。识别方法很直接：不要用 token 计数算 $h$，改为统计“被真正复用的缓存块数 × 块大小 ÷ $N_{\\text{in}}$”，并与 token 级统计并列打印；两者差距越大，说明块内浪费越严重。工程上的对策是把公共前缀补齐到块边界，或对短前缀直接放弃缓存、走冷预填，避免为几个 token 的命中付出一次块查找与索引维护的开销。</p>\n<p>第二种误用只优化 $h$，无视 $M_{\\text{cache}}$ 对显存的挤占。公式第二项 $M_{\\text{cache}}/B_{\\text{HBM}}$ 只刻画了把缓存块读回的时间，却没有刻画缓存池扩大后 KV 可用空间的收缩：缓存与在飞请求的 KV 共享同一块 HBM，$M_{\\text{cache}}$ 每增加一份，可容纳的并发序列就少一份，批大小下降直接压低吞吐。于是出现一个反直觉的结果——命中率确实上去了，端到端吞吐却低于不开缓存的基线。判断这类失效不能只看 $h$，要把缓存池大小作为独立变量做扫描：固定 $N_{\\text{in}}$ 与请求到达率，逐档增大 $M_{\\text{cache}}$，观察吞吐曲线的拐点。拐点之前缓存是净收益，拐点之后每多留一字节缓存都在用批大小换命中率。容量决策应在这个拐点上取 $M_{\\text{cache}}$，而不是把显存能留多少就留多少。</p>\n<p>第三个失效条件是前缀必须逐 token 完全一致，而 agent 循环恰恰在破坏这一点。多轮 agent 每轮都会改写文件头部、插入一行注释、调整 import 顺序，哪怕只动一个字符，从该位置起的整段前缀全部失配，命中率骤降；但调度器仍按上一轮实测的旧 $h$ 预留缓存与预填资源，形成“缓存占着显存、命中却归零”的双重浪费。反例可以这样构造：一个仓库级上下文复用服务，首轮实测 $h$ 很高，运维据此把 $M_{\\text{cache}}$ 调大、把预填并发调小；随后 agent 开始在每轮开头插入时间戳注释，前缀从第一个 token 起就不再一致，$h$ 跌到接近零，而未命中重算量 $(1-h)$ 回到满值，预填时间按第一项 $\\frac{2PN_{\\text{in}}(1-h)}{\\eta_{\\text{MFU}}C}$ 全额付出，同时缓存读取项照付，系统同时承担了两份代价。识别信号是“缓存块命中数/查找次数”这个比值：查找次数不降而命中数塌陷，就说明前缀在被持续改写。工程判断是给缓存键加内容指纹并周期性重算 $h$，一旦实测 $h$ 低于由 $h^{*}=1-\\frac{\\eta_{\\text{MFU}}C\\,M_{\\text{cache}}}{2PN_{\\text{in}}B_{\\text{HBM}}}$ 给出的阈值，就应主动收缩缓存池、把显存还给 KV，而不是继续按历史命中率运行。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>机制后果</th><th>识别信号</th></tr></thead><tbody><tr><td>token 级命中率当块级用</td><td>短前缀被计为命中，实际零收益，节省高估</td><td>token 级 $h$ 与块级 $h$ 差距大</td></tr><tr><td>只追 $h$ 不顾 $M_{\\text{cache}}$</td><td>KV 空间收缩、批大小下降，吞吐低于基线</td><td>$M_{\\text{cache}}$ 扫描曲线出现拐点</td></tr><tr><td>假设前缀稳定</td><td>逐 token 失配，命中归零而缓存仍占显存</td><td>查找次数不降、命中数塌陷</td></tr></tbody></table>\n\n<h3 id=\"th-prefix-cache-hit-bound-sec-32\">三十二 · 命中率阈值之外的三种典型误用</h3>\n<p>公式里的 $h^{*}$ 是盈亏平衡点，不是“开了缓存就一定赚”的许可证。最常见的误用是把 token 级命中率直接代入公式，而缓存块按固定粒度（如 16 token）对齐：一段不足一个块的公共前缀在统计上被记为命中，实际却无法复用，有效 $h$ 低于报表值。识别方法很简单——把命中统计改成按块计数，若块级 $h$ 与 token 级 $h$ 差距明显，说明短公共前缀正在虚增收益，容量规划会系统性高估节省。另一个误用是只盯 $h$ 而不约束 $M_{\\text{cache}}$：缓存池扩大后 KV 可用空间被挤占，可容纳的批大小下降，吞吐可能反而低于不开缓存的基线。此时 $h$ 再高也救不回来，因为第二项 $M_{\\text{cache}}/B_{\\text{HBM}}$ 之外还多了一笔隐性的并发损失。</p>\n<p>反例落在 agent 循环上：某仓库级上下文被反复复用，调度器按历史 $h$ 预留了大块缓存并据此排批。但 agent 每轮会改写文件头部或插入一行注释，前缀必须逐 token 完全一致才能命中，这一行改动就让整段缓存失效，$h$ 骤降而预留不变，结果是缓存占着显存、预填却按冷路径重算，延迟与显存两头受损。识别信号是“命中率随轮次单调下滑而缓存占用不降”，此时应把缓存键绑定到内容哈希而非会话 ID，并对改写频繁的仓库回退到冷预填。</p>\n<table class=\"mini\"><thead><tr><th>误用</th><th>后果</th><th>识别信号</th></tr></thead><tbody><tr><td>token 级命中当块级</td><td>有效 $h$ 虚高，节省不出现</td><td>块级与 token 级命中率差距大</td></tr><tr><td>扩池不约束 $M_{\\text{cache}}$</td><td>批大小下降，吞吐低于基线</td><td>缓存占用升、并发降</td></tr><tr><td>假设上下文不变</td><td>前缀失配，$h$ 骤降</td><td>命中率随轮次下滑</td></tr></tbody></table>\n<p>工程判断落在容量决策上：给定 $M_{\\text{cache}}$ 预算与实测块级 $h$，用 $h^{*}$ 判断该仓库是否值得开缓存；短输入（如单文件补全）的 $N_{\\text{in}}$ 小，$h^{*}$ 可能接近或超过 1，缓存永远不划算，应直接走冷预填而不占缓存池。</p>\n<table class=\"mini\" data-fig=\"theory-sym\"><caption>符号表：公式里每个字母的含义</caption><thead><tr><th>符号</th><th>含义</th></tr></thead><tbody><tr><td>$h$</td><td>前缀缓存命中 token 占输入 token 的比例</td></tr><tr><td>$N_{\\text{in}}$</td><td>单请求输入 token 数（仓库上下文长度）</td></tr><tr><td>$P$</td><td>模型参数量</td></tr><tr><td>$M_{\\text{cache}}$</td><td>为前缀缓存预留的显存字节数</td></tr><tr><td>$B_{\\text{HBM}}$</td><td>HBM 有效带宽</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：theory/th-prefix-cache-hit-bound · 共 5 个片段</p>\n"}];})();
